function t(key, defaultValue) {
  var dict = I18N[window.currentLang] || I18N.en;
  return dict[key] || defaultValue || key;
}

function _getVerifyBadgeHtml(isVerified, size) {
  var sz = size || 16;
  var color = isVerified ? '#1d9bf0' : '#f59e0b';
  var title = isVerified ? 'Verified Student' : 'Student';
  return '<span class="vbadge' + (isVerified ? ' verified' : '') + '" title="' + title + '" style="display:inline-flex !important;align-items:center !important;justify-content:center !important;width:' + sz + 'px !important;height:' + sz + 'px !important;min-width:' + sz + 'px !important;min-height:' + sz + 'px !important;border-radius:50% !important;background:' + color + ' !important;flex-shrink:0 !important;vertical-align:middle !important;margin-left:4px !important;">' +
    '<svg viewBox="0 0 24 24" width="' + Math.round(sz * 0.55) + '" height="' + Math.round(sz * 0.55) + '" fill="none" stroke="#ffffff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>' +
  '</span>';
}

function _getPartnerVerifiedStatus(partner, displayName, curChatId) {
  var handle = (partner && partner.handle) ? partner.handle.toLowerCase().replace('@','') : String(displayName || '').toLowerCase().replace('@','');
  if (handle === 'miiguelean' || handle === 'miguel') return true;
  if (partner) {
    if (partner.isVerified === true || partner.verified === true || partner.isVerifiedStudent === true) return true;
    if (partner.profile && (partner.profile.isVerified === true || partner.profile.verified === true)) return true;
    if (partner.isVerified === false || (partner.profile && partner.profile.isVerified === false)) return false;
  }
  if (typeof crushDataAll !== 'undefined' && crushDataAll) {
    for (var i = 0; i < crushDataAll.length; i++) {
      var c = crushDataAll[i];
      var cH = (c.handle || c.name || '').toLowerCase().replace('@','');
      if (cH === handle || c.id === curChatId) {
        if (c.isVerified === true || c.verified === true) return true;
        if (c.isVerified === false) return false;
      }
    }
  }
  return false;
}

function applyLanguageTranslations(){
  var dict = I18N[window.currentLang] || I18N.en;
  for (var key in dict) {
    var el = document.getElementById(key);
    if (el) {
      if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
        var placeholderKey = key + '-placeholder';
        if (dict[placeholderKey]) {
          el.placeholder = dict[placeholderKey];
        } else if (key === 'li-email') {
          el.placeholder = dict['li-email-placeholder'];
        } else if (key === 'li-pass') {
          el.placeholder = dict['li-password-placeholder'];
        }
      } else {
        el.innerHTML = dict[key];
      }
    }
  }
  var setHeaders = document.querySelectorAll('#settings-modal .set-h');
  var setHTitles = [
    dict['set-h-account'],
    dict['set-h-campus'],
    dict['set-h-appearance'],      // App Theme: Undrgradz / University colours
    // La tarjeta de estadisticas se quito; su entrada sale de aqui o los
    // titulos siguientes se corren uno.
    dict['set-h-preferences'],     // toggles card → "Preferences"
    dict['set-h-notifications'],
    dict['set-h-personalization'],
    dict['set-h-support']
  ];
  setHeaders.forEach(function(h, idx){
    if(setHTitles[idx]) h.textContent = setHTitles[idx];
  });
  var setModalTitle = document.querySelector('#settings-modal .msheet .mtitle, #settings-modal .msheet div[style*="font-family:var(--font-serif)"]');
  if (setModalTitle && setModalTitle.textContent.indexOf('Logo') === -1) {
    setModalTitle.textContent = dict['set-title'];
  }
  var navLabels = {
    'Hangouts': dict['nav-hangouts'],
    'Crush': dict['nav-crush'],
    'Chats': dict['nav-chats'],
    'Profile': dict['nav-profile']
  };
  document.querySelectorAll('.navbar .nl').forEach(function(lbl){
    var txt = lbl.textContent.trim();
    if(navLabels[txt]) lbl.textContent = navLabels[txt];
  });
  var evChips = {
    'Nightlife': dict['cat-nightlife'],
    'Study': dict['cat-study'],
    'Sports': dict['cat-sports'],
    'Dorm': dict['cat-dorm'],
    'Greek Life': dict['cat-greek'],
    'Abroad': dict['cat-abroad'],
    'Campus': dict['cat-campus'],
    'Networking': dict['cat-networking']
  };
  document.querySelectorAll('#ev-section-row .evsec-chip').forEach(function(chip){
    var svg = chip.querySelector('svg');
    var txt = chip.textContent.trim();
    if (!txt) return;
    for (var k in evChips) {
      if (txt.indexOf(k) > -1 || k.indexOf(txt) > -1) {
        if (svg) {
          var raw = evChips[k];
          var firstLetterIdx = raw.search(/[a-zA-ZáéíóúüñíóúñíóúñíóúñÁÉÍÓÚÑü]/);
          var cleanText = (firstLetterIdx > -1) ? raw.substring(firstLetterIdx).trim() : raw;
          chip.innerHTML = '';
          chip.appendChild(svg);
          chip.appendChild(document.createTextNode(' ' + cleanText));
        } else {
          chip.innerHTML = evChips[k];
        }
      }
    }
  });
  var filterOptions = {
    'compat': window.currentLang === 'es' ? 'Compatibilidad máxima' : 'Most compatible with you',
    'trending': window.currentLang === 'es' ? 'Tendencias' : 'Top trending',
    'newest': window.currentLang === 'es' ? 'Más recientes' : 'Newest',
    'spots': window.currentLang === 'es' ? 'Más cupos libres' : 'Most spots open',
    'soon': window.currentLang === 'es' ? 'Pronto a ocurrir' : 'Happening soon',
    'near': window.currentLang === 'es' ? 'Cerca de ti' : 'Nearby'
  };
  var filterSel = document.getElementById('ev-filter-sel');
  if (filterSel) {
    Array.prototype.forEach.call(filterSel.options, function(opt){
      if(filterOptions[opt.value]) opt.textContent = filterOptions[opt.value];
    });
  }
}
