function getUniversityCity(uniName) {
  if (!uniName) return '';
  if (universityCityMap[uniName]) return universityCityMap[uniName];
  for (var key in universityCityMap) {
    if (uniName.toLowerCase().indexOf(key.toLowerCase()) !== -1 || key.toLowerCase().indexOf(uniName.toLowerCase()) !== -1) {
      return universityCityMap[key];
    }
  }
  var atMatch = uniName.match(/at\s+([A-Z][a-zA-Z\s]+)/i);
  if (atMatch) return atMatch[1].trim();
  var campusMatch = uniName.match(/Campus\s+([A-Z][a-zA-Z\s]+)/i);
  if (campusMatch) return campusMatch[1].trim();
  var commaMatch = uniName.match(/,\s*([A-Z][a-zA-Z\s]+)/i);
  if (commaMatch) return commaMatch[1].trim();
  return uniName;
}

