function icon(name,size,opts){
  size=size||18;opts=opts||{};
  var inner=ICONS[name]||ICONS.dot;
  var sw=opts.fill?'0':(opts.sw||2);
  var fill=opts.fill?'currentColor':'none';
  var extra=(opts.cls?(' '+opts.cls):'')+(opts.style?('" style="'+opts.style):'');
  return '<svg class="ico'+extra+'" width="'+size+'" height="'+size+'" viewBox="0 0 24 24" fill="'+fill+'" stroke="currentColor" stroke-width="'+sw+'" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+inner+'</svg>';
}
// Bridge for static HTML: <span data-ico="camera" data-ico-size="18"></span> → rendered icon
function _hydrateIcons(root){(root||document).querySelectorAll('[data-ico]').forEach(function(el){if(el._icoDone)return;el._icoDone=true;el.innerHTML=icon(el.getAttribute('data-ico'),parseInt(el.getAttribute('data-ico-size'),10)||18);el.style.display='inline-flex';el.style.verticalAlign='middle';});}
document.addEventListener('DOMContentLoaded',function(){try{_hydrateIcons(document);}catch(e){}});

