// ══════════════════════════════════════════════════════
// UNDRGRADZ — GLOBAL CUSTOM MODAL SYSTEM (ugzModal)
// ══════════════════════════════════════════════════════
window.ugzModal = (function() {
  function _getOrCreateDOM() {
    var overlay = document.getElementById('ugz-modal-overlay');
    if (!overlay) {
      overlay = document.createElement('div');
      overlay.id = 'ugz-modal-overlay';
      overlay.className = 'ugz-modal-overlay';
      overlay.setAttribute('aria-modal', 'true');
      overlay.setAttribute('role', 'dialog');
      overlay.innerHTML = 
        '<div class="ugz-modal-card" id="ugz-modal-card">' +
          '<div class="ugz-modal-badge" id="ugz-modal-badge"><span id="ugz-modal-icon">ⓘ</span></div>' +
          '<div class="ugz-modal-title" id="ugz-modal-title">Title</div>' +
          '<div class="ugz-modal-message" id="ugz-modal-message">Message</div>' +
          '<div class="ugz-modal-input-wrap" id="ugz-modal-input-wrap" style="display:none;">' +
            '<input type="text" id="ugz-modal-input" class="ugz-modal-input" autocomplete="off" />' +
          '</div>' +
          '<div class="ugz-modal-actions" id="ugz-modal-actions">' +
            '<button type="button" class="ugz-modal-btn ugz-btn-cancel" id="ugz-modal-cancel-btn">Cancel</button>' +
            '<button type="button" class="ugz-modal-btn ugz-btn-confirm" id="ugz-modal-confirm-btn">Confirm</button>' +
          '</div>' +
        '</div>';
      document.body.appendChild(overlay);

      window.addEventListener('keydown', function(e) {
        var ov = document.getElementById('ugz-modal-overlay');
        if (!ov || !ov.classList.contains('ugz-open')) return;
        if (e.key === 'Escape') {
          var cancelBtn = document.getElementById('ugz-modal-cancel-btn');
          if (cancelBtn && cancelBtn.style.display !== 'none') {
            cancelBtn.click();
          } else {
            var confirmBtn = document.getElementById('ugz-modal-confirm-btn');
            if (confirmBtn) confirmBtn.click();
          }
        } else if (e.key === 'Enter') {
          var confirmBtn = document.getElementById('ugz-modal-confirm-btn');
          if (confirmBtn) confirmBtn.click();
        }
      });

      overlay.addEventListener('click', function(e) {
        if (e.target === overlay && overlay.dataset.allowBackdropClose === 'true') {
          var cancelBtn = document.getElementById('ugz-modal-cancel-btn');
          if (cancelBtn && cancelBtn.style.display !== 'none') {
            cancelBtn.click();
          } else {
            var confirmBtn = document.getElementById('ugz-modal-confirm-btn');
            if (confirmBtn) confirmBtn.click();
          }
        }
      });
    }
    return overlay;
  }

  function _translateMsg(msg) {
    if (!msg) return '';
    msg = String(msg);
    if (window.currentLang === 'es' && typeof ALERT_MAP_ES !== 'undefined') {
      if (ALERT_MAP_ES[msg]) return ALERT_MAP_ES[msg];
      for (var key in ALERT_MAP_ES) {
        if (msg.startsWith(key)) {
          msg = msg.replace(key, ALERT_MAP_ES[key]);
          break;
        }
      }
      if (msg.indexOf('Failed to login:') === 0) {
        msg = msg.replace('Failed to login:', 'Error al iniciar sesión:');
      } else if (msg.indexOf('Failed to upload photo:') === 0) {
        msg = msg.replace('Failed to upload photo:', 'Error al subir la foto:');
      } else if (msg.indexOf('Failed to join event:') === 0) {
        msg = msg.replace('Failed to join event:', 'Error al unirse al evento:');
      } else if (msg.indexOf('Failed to leave event:') === 0) {
        msg = msg.replace('Failed to leave event:', 'Error al salir del evento:');
      } else if (msg.indexOf('You joined "') === 0) {
        msg = msg.replace('You joined "', 'Te uniste a "').replace('" 🎉\nA group chat was added to your Chats.', '" 🎉\nSe añadió un chat grupal a tus Chats.');
      }
    }
    return msg;
  }

  function show(opts) {
    opts = opts || {};
    var type = opts.type || 'info';
    var title = opts.title || '';
    var message = _translateMsg(opts.message || opts.msg || '');
    var confirmText = opts.confirmText || opts.okText || 'OK';
    var cancelText = opts.cancelText || 'Cancel';
    var defaultValue = opts.defaultValue || '';
    var placeholder = opts.placeholder || '';
    var onConfirm = opts.onConfirm;
    var onCancel = opts.onCancel;
    var allowBackdropClose = (type === 'info' || type === 'success');

    var icon = 'info';
    if (type === 'info') {
      icon = 'info';
      title = title || (window.currentLang === 'es' ? 'Información' : 'Information');
      confirmText = opts.confirmText || 'OK';
    } else if (type === 'success') {
      icon = 'checkCircle';
      title = title || (window.currentLang === 'es' ? '¡Éxito!' : 'Success!');
      confirmText = opts.confirmText || (window.currentLang === 'es' ? 'Listo' : 'Done');
    } else if (type === 'error') {
      icon = 'alert';
      title = title || (window.currentLang === 'es' ? 'Algo salió mal' : 'Something went wrong');
      confirmText = opts.confirmText || 'OK';
    } else if (type === 'warning') {
      icon = 'alert';
      title = title || (window.currentLang === 'es' ? 'Advertencia' : 'Warning');
      confirmText = opts.confirmText || (window.currentLang === 'es' ? 'Continuar' : 'Continue');
      cancelText = opts.cancelText || (window.currentLang === 'es' ? 'Cancelar' : 'Cancel');
    } else if (type === 'confirm') {
      icon = 'help';
      title = title || (window.currentLang === 'es' ? '¿Estás seguro?' : 'Are you sure?');
      confirmText = opts.confirmText || (window.currentLang === 'es' ? 'Confirmar' : 'Confirm');
      cancelText = opts.cancelText || (window.currentLang === 'es' ? 'Cancelar' : 'Cancel');
    } else if (type === 'prompt') {
      icon = 'edit';
      title = title || (window.currentLang === 'es' ? 'Ingresa la información' : 'Input required');
      confirmText = opts.confirmText || (window.currentLang === 'es' ? 'Aceptar' : 'Submit');
      cancelText = opts.cancelText || (window.currentLang === 'es' ? 'Cancelar' : 'Cancel');
    } else if (type === 'premium') {
      icon = 'lock';
      if (!window.PLANS_ENABLED) {
        // Plans/A+ hidden pre-launch: keep the gate, drop all A+ branding/CTA.
        title = window.currentLang === 'es' ? 'Función no disponible' : 'Feature Not Available';
        message = window.currentLang === 'es' ? 'Esta función no está disponible por el momento.' : "This feature isn't available right now.";
        confirmText = window.currentLang === 'es' ? 'Entendido' : 'Got it';
        cancelText = window.currentLang === 'es' ? 'Cerrar' : 'Close';
      } else {
        title = title || (window.currentLang === 'es' ? 'Plan A+ Student Requerido' : 'A+ Student Plan Required');
        message = message || (window.currentLang === 'es' ? 'Esta función requiere el plan A+ Student ($19.99/año).\n\nActualiza tu plan para desbloquear esta función.' : 'This feature requires the A+ Student plan ($19.99/yr).\n\nUpgrade your plan to unlock this feature.');
        confirmText = opts.confirmText || (window.currentLang === 'es' ? 'Ver Planes' : 'Go to Plans');
        cancelText = opts.cancelText || (window.currentLang === 'es' ? 'Ahora no' : 'Not Now');
      }
    } else if (type === 'cheat') {
      icon = 'lock';
      title = title || (window.currentLang === 'es' ? 'Cheats Requeridos' : 'Cheats Required');
      message = message || (window.currentLang === 'es' ? 'Esta función requiere Cheats.\n\nCompra un cheat para desbloquear esta función.' : 'This feature requires Cheats.\n\nPurchase a cheat to unlock this feature.');
      confirmText = opts.confirmText || (window.currentLang === 'es' ? 'Ver Cheats' : 'Go to Cheats');
      cancelText = opts.cancelText || (window.currentLang === 'es' ? 'Ahora no' : 'Not Now');
    } else if (type === 'subscribed') {
      // Post-purchase celebration — title/message are always passed in by the
      // caller (they carry the specific plan name + renewal date), so there is
      // no generic copy to fall back to here.
      icon = 'crown';
      title = title || (window.currentLang === 'es' ? '¡Ya eres A+!' : "You're A+ now!");
      confirmText = opts.confirmText || (window.currentLang === 'es' ? '¡Vamos!' : "Let's go!");
      allowBackdropClose = true;
    }

    var overlay = _getOrCreateDOM();
    overlay.dataset.allowBackdropClose = allowBackdropClose ? 'true' : 'false';

    var card = document.getElementById('ugz-modal-card');
    card.className = 'ugz-modal-card type-' + type;

    var iconEl = document.getElementById('ugz-modal-icon');
    if (iconEl) iconEl.innerHTML = (typeof window.icon==='function') ? window.icon(icon,26) : icon;

    var titleEl = document.getElementById('ugz-modal-title');
    if (titleEl) titleEl.textContent = title;

    var msgEl = document.getElementById('ugz-modal-message');
    if (msgEl) msgEl.textContent = message;

    var inputWrap = document.getElementById('ugz-modal-input-wrap');
    var inputEl = document.getElementById('ugz-modal-input');
    if (type === 'prompt') {
      if (inputWrap) inputWrap.style.display = 'block';
      if (inputEl) {
        inputEl.value = defaultValue;
        inputEl.placeholder = placeholder;
      }
    } else {
      if (inputWrap) inputWrap.style.display = 'none';
    }

    var cancelBtn = document.getElementById('ugz-modal-cancel-btn');
    var isSingleBtn = (type === 'info' || type === 'success' || type === 'error' || type === 'subscribed');
    if (cancelBtn) {
      cancelBtn.style.display = isSingleBtn ? 'none' : 'inline-flex';
      cancelBtn.textContent = cancelText;
    }

    var confirmBtn = document.getElementById('ugz-modal-confirm-btn');
    if (confirmBtn) {
      confirmBtn.textContent = confirmText;
    }

    // Confetti burst for the post-purchase celebration only — cleared on every
    // show() so a rapid re-open never stacks pieces from the previous one.
    var existingConfetti = card.querySelector('.ugz-confetti');
    if (existingConfetti) existingConfetti.remove();
    if (type === 'subscribed') {
      var confettiColors = ['#f59e0b', '#dc2626', '#3d7bff', '#22c55e', '#a855f7', '#fbbf24'];
      var confetti = document.createElement('div');
      confetti.className = 'ugz-confetti';
      var piecesHtml = '';
      for (var ci = 0; ci < 16; ci++) {
        var left = Math.round(Math.random() * 100);
        var delay = (Math.random() * 0.5).toFixed(2);
        var duration = (1.6 + Math.random() * 0.9).toFixed(2);
        var color = confettiColors[ci % confettiColors.length];
        var drift = Math.round((Math.random() - 0.5) * 60);
        piecesHtml += '<span class="ugz-confetti-piece" style="left:' + left + '%;background:' + color +
          ';animation-delay:' + delay + 's;animation-duration:' + duration + 's;--drift:' + drift + 'px;"></span>';
      }
      confetti.innerHTML = piecesHtml;
      card.appendChild(confetti);
    }

    overlay.style.display = 'flex';
    requestAnimationFrame(function() {
      overlay.classList.add('ugz-open');
    });

    if (type === 'prompt' && inputEl) {
      setTimeout(function() { inputEl.focus(); }, 80);
    } else if (confirmBtn) {
      setTimeout(function() { confirmBtn.focus(); }, 80);
    }

    return new Promise(function(resolve) {
      function close(resValue) {
        overlay.classList.remove('ugz-open');
        setTimeout(function() {
          overlay.style.display = 'none';
          var c = card.querySelector('.ugz-confetti');
          if (c) c.remove();
        }, 220);

        confirmBtn.onclick = null;
        if (cancelBtn) cancelBtn.onclick = null;

        resolve(resValue);
      }

      confirmBtn.onclick = function() {
        var val = (type === 'prompt') ? (inputEl ? inputEl.value : '') : true;
        if (typeof onConfirm === 'function') {
          onConfirm(val);
        }
        close(val);
      };

      if (cancelBtn) {
        cancelBtn.onclick = function() {
          var val = (type === 'prompt') ? null : false;
          if (typeof onCancel === 'function') {
            onCancel(val);
          }
          close(val);
        };
      }
    });
  }

  return {
    show: show,
    alert: function(msg, titleOrOpts) {
      var opts = (typeof titleOrOpts === 'object') ? titleOrOpts : { title: titleOrOpts };
      opts.type = opts.type || 'info';
      opts.message = msg;
      return show(opts);
    },
    confirm: function(msgOrOpts, titleOrOpts) {
      var opts = {};
      if (typeof msgOrOpts === 'object' && msgOrOpts !== null) {
        opts = Object.assign({}, msgOrOpts);
      } else if (typeof titleOrOpts === 'object' && titleOrOpts !== null) {
        opts = Object.assign({}, titleOrOpts);
        opts.message = typeof msgOrOpts === 'string' ? msgOrOpts : opts.message;
      } else {
        opts = {
          message: typeof msgOrOpts === 'string' ? msgOrOpts : '',
          title: typeof titleOrOpts === 'string' ? titleOrOpts : undefined
        };
      }
      opts.type = 'confirm';
      return show(opts);
    },
    prompt: function(msg, defaultVal) {
      return show({
        type: 'prompt',
        message: msg,
        defaultValue: defaultVal || ''
      });
    },
    premium: function(msg, onConfirm) {
      return show({
        type: 'premium',
        message: msg,
        onConfirm: onConfirm || function() {
          if (typeof sw === 'function') sw('premium', 'Plans');
        }
      });
    },
    subscribed: function(opts) {
      opts = opts || {};
      return show({
        type: 'subscribed',
        title: opts.title,
        message: opts.message,
        confirmText: opts.confirmText,
        onConfirm: opts.onConfirm
      });
    }
  };
})();

// Global Window Expose & Overrides
window.ugzAlert = window.ugzModal.alert;
window.ugzConfirm = window.ugzModal.confirm;
window.ugzPrompt = window.ugzModal.prompt;
window.showAlert = window.ugzModal.show;
window.showConfirm = window.ugzModal.confirm;
window.showPrompt = window.ugzModal.prompt;
window.showPremModal = window.ugzModal.premium;

window._prettyAlert = function(msg) {
  return window.ugzModal.alert(msg);
};

window.premAlert = function(msg) {
  return window.ugzModal.premium(msg, function() {
    if (typeof sw === 'function') sw('premium', 'Plans');
  });
};

try {
  window.alert = function(msg) { return window.ugzModal.alert(msg); };
  window.confirm = function(msg) { return window.ugzModal.confirm(msg); };
  window.prompt = function(msg, defaultVal) { return window.ugzModal.prompt(msg, defaultVal); };
} catch(e) {}

// ══════════════════════════════════════════════════════
// SUSPENSION/BAN APPEAL SCREEN
// Reuses the exact same visual language as the login screen (.auth-main-card,
// .field/.gi.auth-input-field, .gbtn.auth-submit-btn from styles.css) so the
// experience feels continuous instead of dropping into a generic dialog.
//
// There is no active token at this point (a rejected login never issues one,
// and a forceLogout-kicked session is about to lose its), so the account is
// identified by email alone — the backend resolves it the same way login()
// does (matches @handle or full email). The password field is shown
// pre-filled and locked purely for visual continuity with the login form; it
// is NEVER read or sent anywhere.
//
// `opts.email` must be the resolved, real institutional email — callers are
// responsible for passing that, not whatever raw text the user may have
// typed (which could be a handle). Since we don't need a password to check
// or submit anymore, the pending-appeal pre-check always runs up front.
// ══════════════════════════════════════════════════════
window.openAppealForm = function(opts) {
  opts = opts || {};
  var email = opts.email || '';
  var displayPassword = opts.password || '';
  var isEs = window.currentLang === 'es';
  var t = function(es, en) { return isEs ? es : en; };

  var existing = document.getElementById('ugz-appeal-overlay');
  if (existing) existing.remove();

  var overlay = document.createElement('div');
  overlay.id = 'ugz-appeal-overlay';
  overlay.style.cssText = 'position:fixed; inset:0; z-index:10000; display:flex; align-items:center; justify-content:center; padding:20px; background:rgba(5,8,16,0.78); backdrop-filter:blur(6px); opacity:0; transition:opacity 0.2s;';
  overlay.innerHTML =
    '<div class="auth-main-card" id="ugz-appeal-card" style="max-width:420px; max-height:92vh; overflow-y:auto;"></div>';
  document.body.appendChild(overlay);
  requestAnimationFrame(function() { overlay.style.opacity = '1'; });

  var card = document.getElementById('ugz-appeal-card');

  function closeForm() {
    overlay.style.opacity = '0';
    setTimeout(function() { overlay.remove(); }, 200);
  }

  function renderLoading() {
    card.innerHTML =
      '<div style="text-align:center; padding:30px 0; color:rgba(255,255,255,0.7);">' + t('Cargando...', 'Loading...') + '</div>';
  }

  function renderPendingStatus(pendingAppeal) {
    card.innerHTML =
      '<div class="auth-logo-text" style="font-size:22px; margin-bottom:6px;">' + t('Apelación en revisión', 'Appeal under review') + '</div>' +
      '<div style="color:rgba(255,255,255,0.75); font-size:var(--fs-base); line-height:1.5; margin-bottom:18px;">' +
        t('Ya tienes una apelación en revisión para esta sanción. Un administrador la evaluará; te avisaremos en cuanto sea resuelta.', 'You already have an appeal under review for this sanction. An admin will evaluate it; we\'ll let you know as soon as it\'s resolved.') +
      '</div>' +
      '<div class="field" style="background:rgba(255,255,255,0.06); border-radius:var(--rad-lg); padding:14px; margin-bottom:20px;">' +
        '<div style="font-size:var(--fs-2xs); font-weight:600; color:var(--fg2); text-transform:uppercase; letter-spacing:0.9px; margin-bottom:6px;">' + t('Tu mensaje', 'Your message') + '</div>' +
        '<div style="color:#fff; font-size:var(--fs-sm); white-space:pre-wrap;">' + escapeHtmlForAppeal(pendingAppeal.message) + '</div>' +
        '<div style="color:rgba(255,255,255,0.5); font-size:var(--fs-2xs); margin-top:10px;">' + new Date(pendingAppeal.createdAt).toLocaleString() + '</div>' +
      '</div>' +
      '<button type="button" class="gbtn auth-submit-btn" id="ugz-appeal-close-btn">' + t('Cerrar', 'Close') + '</button>';

    document.getElementById('ugz-appeal-close-btn').onclick = function() {
      closeForm();
      if (typeof opts.onClose === 'function') opts.onClose();
    };
  }

  function renderForm() {
    var MIN_LEN = 20, MAX_LEN = 1000;
    var passwordFieldHtml = displayPassword
      ? '<div class="field">' +
          '<label>' + t('Contraseña', 'Password') + '</label>' +
          '<input class="gi auth-input-field" type="password" value="' + displayPassword.replace(/"/g, '&quot;') + '" readonly disabled style="opacity:0.65;"/>' +
        '</div>'
      : '';

    card.innerHTML =
      '<div class="auth-logo-text" style="font-size:22px; margin-bottom:6px;">' + t('Apelar sanción', 'Appeal your sanction') + '</div>' +
      '<div style="color:rgba(255,255,255,0.75); font-size:var(--fs-base); line-height:1.5; margin-bottom:18px;">' +
        t('Cuéntanos por qué crees que esta decisión debe revisarse. Un administrador la evaluará.', 'Tell us why you think this decision should be reviewed. An admin will evaluate it.') +
      '</div>' +
      '<div class="field">' +
        '<label>' + t('Correo', 'Email') + '</label>' +
        '<input class="gi auth-input-field" type="email" value="' + email.replace(/"/g, '&quot;') + '" readonly disabled style="opacity:0.65;"/>' +
      '</div>' +
      passwordFieldHtml +
      '<div class="field">' +
        '<label>' + t('Motivo de la apelación', 'Reason for appeal') + '</label>' +
        '<textarea class="gi auth-input-field" id="ugz-appeal-message" rows="5" style="height:auto; min-height:110px; resize:vertical; padding-top:12px;" placeholder="' + t('Explica por qué debería revisarse tu sanción...', 'Explain why your sanction should be reviewed...') + '"></textarea>' +
        '<div id="ugz-appeal-counter" style="font-size:var(--fs-2xs); opacity:0.7; text-align:right; margin-top:4px;">0 / ' + MAX_LEN + '</div>' +
      '</div>' +
      '<div id="ugz-appeal-error" style="display:none; color:#f87171; font-size:var(--fs-sm); margin:-4px 0 14px;"></div>' +
      '<button type="button" class="gbtn auth-submit-btn" id="ugz-appeal-submit-btn">' + t('Enviar apelación', 'Submit appeal') + '</button>' +
      '<div style="text-align:center; font-size:var(--fs-base); color:rgba(255,255,255,0.6); margin-top:14px; cursor:pointer;" id="ugz-appeal-cancel-btn">' + t('Cancelar', 'Cancel') + '</div>';

    var msgEl = document.getElementById('ugz-appeal-message');
    var counterEl = document.getElementById('ugz-appeal-counter');
    var errorEl = document.getElementById('ugz-appeal-error');

    function updateCounter() {
      var len = msgEl.value.length;
      counterEl.textContent = len + ' / ' + MAX_LEN;
      counterEl.style.color = (len < MIN_LEN || len > MAX_LEN) ? '#f87171' : '';
    }
    msgEl.addEventListener('input', updateCounter);
    updateCounter();

    function showError(text) {
      errorEl.textContent = text;
      errorEl.style.display = 'block';
    }

    document.getElementById('ugz-appeal-cancel-btn').onclick = function() {
      closeForm();
      if (typeof opts.onClose === 'function') opts.onClose();
    };

    document.getElementById('ugz-appeal-submit-btn').onclick = function() {
      errorEl.style.display = 'none';
      var message = msgEl.value.trim();

      if (message.length < MIN_LEN) { showError(t('Tu apelación debe tener al menos 20 caracteres.', 'Your appeal must be at least 20 characters.')); return; }
      if (message.length > MAX_LEN) { showError(t('Tu apelación no puede superar los 1000 caracteres.', 'Your appeal cannot exceed 1000 characters.')); return; }

      var submitBtn = document.getElementById('ugz-appeal-submit-btn');
      submitBtn.disabled = true;

      apiClient.submitAppeal(email, message).then(function() {
        closeForm();
        window.ugzModal.alert(t('Tu apelación fue enviada. Un administrador la revisará pronto.', 'Your appeal was submitted. An admin will review it soon.'), { type: 'success' }).then(function() {
          if (typeof opts.onClose === 'function') opts.onClose();
        });
      }).catch(function(err) {
        submitBtn.disabled = false;
        if (err && err.status === 409) {
          showError(t('Ya tienes una apelación en revisión para esta sanción.', 'You already have an appeal under review for this sanction.'));
        } else {
          showError((err && err.message) || t('No se pudo enviar la apelación.', 'Could not submit the appeal.'));
        }
      });
    };
  }

  // No password needed anymore to check — always try the pending-appeal
  // pre-check first so an existing appeal shows its status instead of a
  // blank form, regardless of which screen triggered this one.
  renderLoading();
  apiClient.checkAppealStatus(email).then(function(data) {
    if (data && data.pendingAppeal) {
      renderPendingStatus(data.pendingAppeal);
    } else {
      renderForm();
    }
  }).catch(function() {
    renderForm();
  });
};

function escapeHtmlForAppeal(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

