var GREEK_PAIRS=[
  ['ΣΧ Sigma Chi','ΔΓ Delta Gamma'],['ΣΑΕ Sigma Alpha Epsilon','ΚΑΘ Kappa Alpha Theta'],
  ['ΠΚΑ Pi Kappa Alpha','ΠΒΦ Pi Beta Phi'],['ΚΣ Kappa Sigma','ΚΔ Kappa Delta'],
  ['ΛΧΑ Lambda Chi Alpha','ΑΧΩ Alpha Chi Omega'],['ΒΘΠ Beta Theta Pi','ΚΚΓ Kappa Kappa Gamma'],
  ['ΦΔΘ Phi Delta Theta','ΔΔΔ Delta Delta Delta'],['ΣΝ Sigma Nu','ΓΦΒ Gamma Phi Beta'],
  ['ΤΚΕ Tau Kappa Epsilon','ΑΦ Alpha Phi'],['ΘΧ Theta Chi','ΖΤΑ Zeta Tau Alpha'],
  ['ΑΦΑ Alpha Phi Alpha','ΑΚΑ Alpha Kappa Alpha'],['ΚΑΨ Kappa Alpha Psi','ΔΣΘ Delta Sigma Theta'],
  ['ΩΨΦ Omega Psi Phi','ΖΦΒ Zeta Phi Beta'],['ΦΒΣ Phi Beta Sigma','ΣΓΡ Sigma Gamma Rho']
];
function _greekPartner(org){if(!org)return null;for(var i=0;i<GREEK_PAIRS.length;i++){if(GREEK_PAIRS[i][0]===org)return GREEK_PAIRS[i][1];if(GREEK_PAIRS[i][1]===org)return GREEK_PAIRS[i][0];}return null;}
function _greekCircle(org){var c=[];if(org){c.push(org);var pn=_greekPartner(org);if(pn)c.push(pn);}return c;}
// relation of a profile's org to MY org: 'same' | 'paired' | null
function _greekRelation(p){var myOrg=userPro&&userPro.org;if(!myOrg||!p||!p.org)return null;if(p.org===myOrg)return 'same';if(_greekPartner(myOrg)===p.org)return 'paired';return null;}
function _populateFilterChips(){
  var mk=function(label){return '<div class="yr-chip" style="font-size:var(--fs-2xs);" onclick="crushFilterChip(this)">'+label+'</div>';};
  var unis=Object.keys(UNI).map(function(d){return UNI[d].name;});
  var set=function(id,html){var el=document.getElementById(id);if(el)el.innerHTML=html;};
  // Major filters removed; Greek filters are now static Fraternity/Sorority/Rushing/None chips (in markup)
  _uniRender('crush');
  // Hangouts University choose-list — unified to match the Crush filter
  _uniRender('ev');
  /* uni state selects are now country-scoped via _uniCountryChange */
  // Free toggle filters (green flags, love language, workout, diet)
  var mkFree=function(label){return '<div class="yr-chip" style="font-size:var(--fs-2xs);" onclick="this.classList.toggle(\'on\')">'+label+'</div>';};
  if(typeof GREEN_FLAGS!=='undefined')set('crush-greenflag-chips',GREEN_FLAGS.map(mkFree).join(''));
  if(typeof LOVE_LANGS!=='undefined')set('crush-lovelang-chips',LOVE_LANGS.map(mkFree).join(''));
  if(typeof WORKOUTS!=='undefined')set('crush-workout-chips',WORKOUTS.map(mkFree).join(''));
  if(typeof DIETS!=='undefined')set('crush-diet-chips',DIETS.map(mkFree).join(''));
  if(typeof LIVING!=='undefined')set('crush-living-chips',LIVING.map(mkFree).join(''));
  // Alumni already graduated — "Living Situation" (dorm/off-campus/etc.) doesn't apply.
  var _livingSection=document.getElementById('crush-living-section');
  if(_livingSection){
    if((obMode||userMode)==='alumni'){
      _livingSection.style.display='none';
    }else{
      // Don't unconditionally reveal it — _populateFilterChips() can run (e.g. from
      // the async uni-fetch callback) after _collapseCrushFilters() has already
      // hidden every .love-filter-section and shown the "Filters applied" pill.
      // Blindly resetting display here popped Living Situation back into view
      // while every other section stayed collapsed, making it look rendered
      // outside its card. Only reveal it if the panel isn't currently collapsed.
      var _pill=document.getElementById('crush-filters-applied');
      var _isCollapsed=_pill&&_pill.style.display!=='none';
      _livingSection.style.display=_isCollapsed?'none':'';
    }
  }
  if(typeof DRINK_OPTS!=='undefined')set('crush-drink-chips',DRINK_OPTS.map(mkFree).join(''));
  if(typeof SMOKE_OPTS!=='undefined')set('crush-smoke-chips',SMOKE_OPTS.map(mkFree).join(''));
  if(typeof POLITICS_OPTS!=='undefined')set('crush-politics-chips',POLITICS_OPTS.map(mkFree).join(''));

  var langsP4List = [
    { code: 'us', name: 'English' }, { code: 'gb', name: 'English' }, { code: 'ca', name: 'English' }, { code: 'au', name: 'English' },
    { code: 'mx', name: 'Spanish' }, { code: 'es', name: 'Spanish' }, { code: 'ar', name: 'Spanish' }, { code: 'co', name: 'Spanish' },
    { code: 'fr', name: 'French' }, { code: 'ca', name: 'French (Québécois)' }, { code: 'de', name: 'German' }, { code: 'it', name: 'Italian' },
    { code: 'br', name: 'Portuguese' }, { code: 'pt', name: 'Portuguese' }, { code: 'cn', name: 'Mandarin' }, { code: 'hk', name: 'Cantonese' },
    { code: 'jp', name: 'Japanese' }, { code: 'kr', name: 'Korean' }, { code: 'vn', name: 'Vietnamese' }, { code: 'sa', name: 'Arabic' },
    { code: 'ru', name: 'Russian' }, { code: 'ua', name: 'Ukrainian' }, { code: 'tr', name: 'Turkish' }, { code: 'gr', name: 'Greek' },
    { code: 'in', name: 'Hindi' }, { code: 'pk', name: 'Urdu' }, { code: 'bd', name: 'Bengali' }, { code: 'nl', name: 'Dutch' },
    { code: 'se', name: 'Swedish' }, { code: 'no', name: 'Norwegian' }, { code: 'dk', name: 'Danish' }, { code: 'fi', name: 'Finnish' },
    { code: 'pl', name: 'Polish' }, { code: 'cz', name: 'Czech' }, { code: 'ph', name: 'Tagalog' }, { code: 'id', name: 'Indonesian' },
    { code: 'my', name: 'Malay' }, { code: 'th', name: 'Thai' }, { code: 'il', name: 'Hebrew' }, { code: 'ir', name: 'Persian' },
    { flag: '🧏', name: 'ASL (Sign Language)' }
  ];
  set('crush-lang-chips', langsP4List.map(function(item){
    var flagIco = item.flag ? ('<span style="font-size:13px;margin-right:4px;">' + item.flag + '</span>') : '<img src="https://flagcdn.com/w40/' + item.code + '.png" style="width:18px;height:12px;object-fit:cover;border-radius:2px;vertical-align:middle;margin-right:4px;display:inline-block;box-shadow:var(--el-1);"/>';
    return '<div class="yr-chip" style="font-size:var(--fs-2xs);display:inline-flex;align-items:center;" onclick="this.classList.toggle(\'on\')">' + flagIco + ' ' + item.name + '</div>';
  }).join(''));

  var ethnicitiesP4 = ['White', 'Latino / Hispanic', 'Black / African American', 'Asian', 'Middle Eastern', 'Native American', 'Pacific Islander', 'Mixed / Biracial', 'Other'];
  set('crush-ethnicity-chips', ethnicitiesP4.map(mkFree).join(''));

  var religionsP4 = ['Atheist', 'Agnostic', 'Christian', 'Catholic', 'Jewish', 'Muslim', 'Hindu', 'Buddhist', 'Spiritual', 'Other'];
  set('crush-religion-chips', religionsP4.map(mkFree).join(''));

  var greekP4 = ['Fraternity', 'Sorority', 'Rushing', 'None'];
  set('crush-frat-chips', greekP4.map(mkFree).join(''));

  if(typeof _renderGreekFilterSection==='function')_renderGreekFilterSection();
  if(typeof FAITH_LEVELS!=='undefined')set('crush-faith-chips',FAITH_LEVELS.map(mkFree).join(''));
  // Marks the Filters panel as populated so boot-time filter restoration
  // (which runs before the user ever opens the tab) knows not to collapse
  // sections/place the "Filters applied" pill against an empty panel.
  window._filtersPanelInitialized = true;
  if(typeof _setFiltersDirty==='function')_setFiltersDirty(false);
}
function _updateHeightLbl(v){var lbl=document.getElementById('crush-height-lbl');if(lbl)lbl.textContent=(parseInt(v)<=58)?'Any':(_fmtHeight(parseInt(v))+'+');}

var BANNED = ['fuck','shit','asshole','bitch','dick','cock','pussy','nigga','nigger','cunt','whore','slut','retard','faggot','kike','spic','chink','tranny','wetback'];
function censor(t){
  if(!t)return t;
  var out=String(t);
  BANNED.forEach(function(w){
    var re=new RegExp(w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi');
    out=out.replace(re,function(m){return m.charAt(0)+'*'.repeat(Math.max(1,m.length-1));});
  });
  return out;
}
function hasBanned(t){if(!t)return false;var s=String(t).toLowerCase();return BANNED.some(function(w){return s.indexOf(w)>-1;});}

