// ── SESSION RESTORE (localStorage — no database) — keeps you signed in across refreshes ──
function _restoreSession(){
  try{
    var raw=localStorage.getItem('ugz_snap_v3')||sessionStorage.getItem('ugz_snap');
    if(!raw)return false;
    var snap=JSON.parse(raw);
    if(!snap||!snap.userPro||!snap.userPro.handle||snap.userPro.handle==='@user')return false;
    userPro=snap.userPro;
    if(snap.userMode)userMode=snap.userMode;
    if(snap.obMode)obMode=snap.obMode;
    if(snap.curPlan)curPlan=snap.curPlan;
    if(snap.curPlanPeriod)curPlanPeriod=snap.curPlanPeriod;
    if(snap.curPlanEnds)curPlanEnds=new Date(snap.curPlanEnds);
    if(typeof snap.curPlanWillRenew!=='undefined')curPlanWillRenew=snap.curPlanWillRenew;
    if(snap.uni)uni=snap.uni;
    if(typeof snap.verified!=='undefined')verified=snap.verified;
    if(snap.selectedHobbies)selectedHobbies=snap.selectedHobbies;
    if(snap.selectedFlags)selectedFlags=snap.selectedFlags;
    if(snap.selectedClubs&&typeof selectedClubs!=='undefined')selectedClubs=snap.selectedClubs;
    if(snap.selectedPrompts&&typeof selectedPrompts!=='undefined')selectedPrompts=snap.selectedPrompts;
    if(snap.userGender)userGender=snap.userGender;
    if(snap.suData)suData=snap.suData;
    if(typeof snap.politicsPicked!=='undefined'&&typeof _politicsPicked!=='undefined')_politicsPicked=snap.politicsPicked;
    if(snap.crushGenderPref&&typeof crushGenderPref!=='undefined')crushGenderPref=snap.crushGenderPref;
    return true;
  }catch(e){return false;}
}
function _bootRestoredApp(){
  var _ls=null,_ll=null;
  try{
    _ls=sessionStorage.getItem('ugz_last_screen') || localStorage.getItem('ugz_last_screen');
    _ll=sessionStorage.getItem('ugz_last_label') || localStorage.getItem('ugz_last_label');
  }catch(e){}
  if (typeof userPro !== 'undefined' && userPro) {
    var liveUni = _resolveUserUniversity(userPro.email || userPro.universityDomain || userPro.university);
    if (liveUni) {
      uni = liveUni;
      userPro.university = liveUni.name;
      userPro.universityDomain = liveUni.domain;
    }
  }
  try{applyColors();}catch(e){}
  try{if(typeof _applyLogoColors==='function')_applyLogoColors();}catch(e){}
  try{if(typeof applySeasonalSkin==='function')applySeasonalSkin();}catch(e){}
  try{updateProfileUI();}catch(e){}
  try{buildNav();}catch(e){}
  // Restore saved discover/search filters (age range, chips, gender pref)
  // after a page reload — the login path already does this, but a reload
  // goes through _bootRestoredApp() instead and previously skipped it.
  try{if(typeof _presetsLoad==='function')_presetsLoad();}catch(e){}
  try{if(userPro&&userPro.customization&&userPro.customization.activeFilters&&typeof _applyFilterState==='function')_applyFilterState(userPro.customization.activeFilters);}catch(e){}
  try{if(typeof loadCrushFeed==='function'){loadCrushFeed();}else{renderCrush();}}catch(e){}
  try{renderHangouts();}catch(e){}
  try{if(typeof conectarChatEnVivo==='function')conectarChatEnVivo();}catch(e){}
  try{if(typeof fetchAndRenderChats==='function')fetchAndRenderChats();}catch(e){}
  try{filterChatBySection();}catch(e){}
  try{if(typeof renderCrushPreview==='function')renderCrushPreview();}catch(e){}
  if(_ls&&_ls!=='premium'){try{sw(_ls,_ll||_ls);}catch(e){}}
  try{if(typeof _saveSessionState==='function')_saveSessionState();}catch(e){}
  try{setTimeout(function(){if(typeof _showEntryPoll==='function')_showEntryPoll();},700);}catch(e){}
}
// ── SPLASH / APP INIT ──
function _hideNativeSplashScreen(options) {
  try {
    if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.SplashScreen) {
      var fadeDuration = (options && typeof options.fadeOutDuration === 'number') ? options.fadeOutDuration : 400;
      window.Capacitor.Plugins.SplashScreen.hide({ fadeOutDuration: fadeDuration });
    }
  } catch(e) {
    console.warn("Could not hide native splash screen:", e);
  }
}

function setActiveRootScreen(screenId) {
  var screens = ['authscreen', 'onboarding', 'app'];
  screens.forEach(function(id) {
    var el = document.getElementById(id);
    if (el) {
      if (id === screenId) {
        el.classList.add('active');
        el.style.display = 'flex';
        el.style.pointerEvents = 'auto';
        el.style.visibility = 'visible';
      } else {
        el.classList.remove('active');
        el.style.display = 'none';
        el.style.pointerEvents = 'none';
        el.style.visibility = 'hidden';
      }
    }
  });
}



window.addEventListener('load', function() {
  var initStart = Date.now();
  console.log(`[STARTUP] APP_INIT_START at ${initStart}`);

  try{if(typeof applyLanguageTranslations==='function')applyLanguageTranslations();}catch(e){}
  try{_logoColorsLoad();_applyLogoColors();}catch(e){}

  // Add auth_session_expired listener to automatically log out on expiration
  window.addEventListener('auth_session_expired', function() {
    console.warn("Session expired. Logging out...");
    if (typeof _logOut === 'function') {
      _logOut(true);
    }
  });

  // Failsafe safety net: Ensure native splash hides even if network or JS encounters an unhandled error (max 4000ms)
  var failsafeTimer = setTimeout(function() {
    console.warn("[STARTUP] Failsafe timer (4000ms) triggered _hideNativeSplashScreen");
    _hideNativeSplashScreen({ fadeOutDuration: 400 });
  }, 4000);

  // Upfront session validity check
  console.log("[STARTUP] SESSION_CHECK_START");
  var checkStart = Date.now();
  var sessionCheckPromise = Promise.resolve(null);
  if (typeof apiClient !== 'undefined' && apiClient.getAccessToken()) {
    sessionCheckPromise = Promise.race([
      apiClient.getMe(),
      new Promise(function(_, reject) { setTimeout(function() { reject(new Error('Timeout 1500ms')); }, 1500); })
    ]).then(function(res) {
      console.log(`[STARTUP] SESSION_CHECK_END (success in ${Date.now() - checkStart}ms)`);
      return res;
    }).catch(function(err) {
      console.warn(`[STARTUP] SESSION_CHECK_END (failed/timeout in ${Date.now() - checkStart}ms: ${err.message})`);
      return null;
    });
  }

  // Restore session from localStorage if available
  var savedUserPro = null;
  try {
    var stored = localStorage.getItem('userPro');
    if (stored) {
      savedUserPro = JSON.parse(stored);
    }
  } catch(e) {}

  sessionCheckPromise.then(function(user) {
    var activeUser = user || savedUserPro;
    
    // --- CRITICAL TASK 1: Set Root Screen & Prepare Critical DOM ---
    if (activeUser) {
      if (user) {
        try {
          userPro.id = user.id;
          userPro.name = user.firstName + ' ' + (user.lastName || '');
          userPro.handle = user.handle ? (user.handle.startsWith('@') ? user.handle : '@' + user.handle) : '@you';
          userPro.email = user.email;
          userPro.phone = user.phone || '';
          
          var profile = user.profile || {};
          userPro.bio = profile.bio || '';
          userPro.university = profile.university || '';
          userPro.major = profile.major || '';
          userPro.grad = profile.grad || '';
          userPro.crossover = profile.crossover || false;
          userPro.isGhostMode = profile.isGhostMode || false;
          userPro.subscriptionTier = profile.subscriptionTier || 'FREE';
          // These three drove the "Tu plan activo · renueva el ..." Plans-screen
          // label and every curPlan==='aplus' gate in the app — on a plain
          // reload (as opposed to a fresh doLoginAuth()) they were never set,
          // so a paid subscription looked like it had vanished after F5.
          curPlan = profile.subscriptionTier ? profile.subscriptionTier.toLowerCase() : 'free';
          curPlanPeriod = profile.subscriptionPeriod || '';
          curPlanEnds = profile.subscriptionEnds ? new Date(profile.subscriptionEnds) : null;
          curPlanWillRenew = profile.subscriptionWillRenew !== false;
          // userMode/obMode (alumni vs student) were never restored on a plain
          // reload at all — only doLoginAuth() set them, and only in-memory —
          // so every F5 silently reverted an alumni account back to 'student'
          // defaults (e.g. the Living Situation filter would reappear).
          var _acctType=(profile.academic && profile.academic.accountType) || '';
          userMode = (_acctType==='alumni' || (!_acctType && profile.grad && typeof _yearInSchoolFromGrad==='function' && _yearInSchoolFromGrad(profile.grad)==='Alumni')) ? 'alumni' : 'student';
          obMode = userMode;
          window._regAlumni = (userMode==='alumni');
          if (profile.gender) {
            userPro.gender = profile.gender === 'WOMAN' ? 'female' : profile.gender === 'MAN' ? 'male' : 'other';
            userGender = userPro.gender;
          }
          if (profile.interestedIn) {
            userPro.interestedIn = profile.interestedIn === 'WOMAN' ? 'female' : profile.interestedIn === 'MAN' ? 'male' : 'any';
            crushGenderPref = userPro.interestedIn;
          }
          userPro.interests = profile.interests || [];
          userPro.prompts = profile.prompts || [];
          userPro.identityTags = profile.identityTags || [];
          userPro.lookingForTags = profile.lookingForTags || [];
          
          if (profile.lifestyle) Object.assign(userPro, profile.lifestyle);
          if (profile.academic) Object.assign(userPro, profile.academic);
          if (profile.background) Object.assign(userPro, profile.background);
          if (profile.customization) {
            userPro.customization = profile.customization;
            Object.assign(userPro, profile.customization);
          }
          if (profile.socials) Object.assign(userPro, profile.socials);
          
          userPro.customization = profile.customization || {};
          userPro.isVerified = !!(user.isVerified || (profile && profile.isVerified));
          if (userPro.isVerified) verified = true;
          // Involvement verification badges (Student Government / Creator / Athlete)
          userPro.isCreatorVerified = !!user.isCreatorVerified;
          userPro.isAthleteVerified = !!user.isAthleteVerified;
          userPro.isGovtVerified = !!user.isGovtVerified;
          userPro.verifiedSports = Array.isArray(profile.verifiedSports) ? profile.verifiedSports : [];
          
          if (userPro.university) {
            uni = _resolveUserUniversity(userPro.university);
            if (typeof applyColors === 'function') try { applyColors(); } catch(e){}
          }
          try { localStorage.setItem('userPro', JSON.stringify(userPro)); } catch(sErr){}
        } catch (mapErr) {
          console.error("Error syncing profile on restore:", mapErr);
        }
      }
      setActiveRootScreen('app');
      console.log("[STARTUP] ROOT_SCREEN_READY -> 'app'");
    } else {
      if (typeof apiClient !== 'undefined' && apiClient.clearTokens) {
        apiClient.clearTokens();
      }
      setActiveRootScreen('authscreen');
      if (typeof switchAuthTab === 'function') switchAuthTab('login');
      console.log("[STARTUP] ROOT_SCREEN_READY -> 'authscreen'");
    }

    // Force layout reflow behind splash screen so WKWebView paints the frame
    try { void document.body.offsetHeight; } catch(e){}
    console.log("[STARTUP] CRITICAL_UI_READY");

    // --- TIMING CALCULATIONS ---
    var elapsed = Date.now() - initStart;
    var minSplashTime = 1500; // Minimum 1500ms visual splash
    var remainingDelay = Math.max(0, minSplashTime - elapsed);

    console.log(`[STARTUP] SPLASH_HIDE_START (elapsed: ${elapsed}ms, remainingDelay: ${remainingDelay}ms)`);

    setTimeout(function() {
      clearTimeout(failsafeTimer);
      // Pintar el contenido de la sección visible ANTES de ocultar el splash,
      // para que la app no aparezca 1s vacía (tabs + dropdown sin cards). Render
      // local, idempotente; _bootRestoredApp luego refresca con datos frescos.
      if (activeUser) {
        try { if (typeof buildNav === 'function') buildNav(); } catch(e){}
        try { if (typeof renderHangouts === 'function') renderHangouts(); } catch(e){}
        try { if (typeof filterChatBySection === 'function') filterChatBySection(); } catch(e){}
      }
      _hideNativeSplashScreen({ fadeOutDuration: 400 });
      console.log(`[STARTUP] SPLASH_HIDE_END (splash hidden at +${Date.now() - initStart}ms)`);

      // --- SECONDARY TASKS (Run non-blocking AFTER Splash is fully hidden) ---
      setTimeout(function() {
        console.log(`[STARTUP] SECONDARY_TASKS_START at +${Date.now() - initStart}ms`);
        
        // 1. Deferred Photo Grid Rendering
        if (activeUser && user && user.photos) {
          try {
            var grid = document.getElementById('prof-photos');
            if (grid) {
              grid.querySelectorAll('.pgcell:not(.add)').forEach(function(c){c.remove();});
              const dbPhotos = user.photos || [];
              dbPhotos.sort((a,b) => (a.order || 0) - (b.order || 0));
              dbPhotos.forEach(p => {
                if (typeof crushPhotoCell === 'function') {
                  var d = crushPhotoCell(p.url, 'center');
                  d.dataset.photoId = p.id;
                  grid.insertBefore(d, grid.lastChild);
                }
              });
              _profilePicUrl = dbPhotos.length > 0 ? dbPhotos[0].url : '';
              if (typeof _syncFirstCrushPhoto === 'function') _syncFirstCrushPhoto();
            }
          } catch(photoErr) {
            console.error("Secondary photo render error:", photoErr);
          }
        }

        // 2. Deferred Socket & Network Connections
        if (activeUser && typeof _bootRestoredApp === 'function') {
          try { _bootRestoredApp(); } catch(bootErr) { console.error("Secondary boot error:", bootErr); }
        }
      }, 450); // Executed 450ms AFTER splash hide command completes!
    }, remainingDelay);

  }).catch(function(e) {
    console.error("Initialization error:", e);
    setActiveRootScreen('authscreen');
    if (typeof switchAuthTab === 'function') switchAuthTab('login');
    clearTimeout(failsafeTimer);
    _hideNativeSplashScreen({ fadeOutDuration: 400 });
  });
});

// ── AUTH ──
function switchAuthTab(tab){
  // Visual: los tabs ahora son subrayado neón (CSS .auth-tab-btn.active::after).
  // Solo se alternan clases; los estilos inline viejos peleaban con el CSS.
  var su=document.getElementById('auth-signup-panel'),li=document.getElementById('auth-login-panel');
  var tsu=document.getElementById('auth-tab-su-btn'),tli=document.getElementById('auth-tab-li-btn');
  var on=function(b){if(b){b.classList.add('active');b.style.cssText='';}};
  var off=function(b){if(b){b.classList.remove('active');b.style.cssText='';}};
  if(tab==='signup'){
    if(su)su.style.display='block';if(li)li.style.display='none';
    on(tsu);off(tli);
  }else{
    if(su)su.style.display='none';if(li)li.style.display='block';
    on(tli);off(tsu);
  }
}

function setSignupMode(mode){
  signupMode=mode;userMode=mode;obMode=mode;
  document.querySelectorAll('[id^="amc-"]').forEach(function(c){c.classList.remove('on');});
  var el=document.getElementById('amc-'+mode+'-btn');if(el)el.classList.add('on');
  var df=document.getElementById('su-dob-field');if(df)df.style.display=(mode==='student'||mode==='alumni')?'block':'none';
}

function setLoginMode(mode){
  userMode=mode;obMode=mode;
  document.querySelectorAll('[id^="limc-"]').forEach(function(c){c.classList.remove('on');});
  var el=document.getElementById('limc-'+mode+'-btn');if(el)el.classList.add('on');
  var lbl=document.getElementById('li-email-label');if(lbl){if(mode==='business')lbl.textContent='Business email';else if(mode==='institution')lbl.textContent='Faculty email (.edu)';else lbl.textContent='School email (.edu)';}
  var inp=document.getElementById('li-email');if(inp)inp.placeholder=(mode==='business')?'you@company.com':'you@university.edu';
}


// ♌ ZODIAC — derived from birth month/day
var ZODIAC_SIGNS=[['Capricorn','♑'],['Aquarius','♒'],['Pisces','♓'],['Aries','♈'],['Taurus','♉'],['Gemini','♊'],['Cancer','♋'],['Leo','♌'],['Virgo','♍'],['Libra','♎'],['Scorpio','♏'],['Sagittarius','♐']];
var ZODIAC_LASTDAY=[19,18,20,19,20,20,22,22,21,22,21,21];
var ZODIAC_ELEM={Aries:'fire',Leo:'fire',Sagittarius:'fire',Taurus:'earth',Virgo:'earth',Capricorn:'earth',Gemini:'air',Libra:'air',Aquarius:'air',Cancer:'water',Scorpio:'water',Pisces:'water'};
function _zodiacFromMD(month,day){if(!month||!day)return null;var idx=(day>ZODIAC_LASTDAY[month-1])?month%12:month-1;return {s:ZODIAC_SIGNS[idx][0],e:ZODIAC_SIGNS[idx][1]};}
// returns 0..1 elemental compatibility; same element / complementary (fire-air, earth-water) score high
function _zodiacCompat(a,b){
  if(!a||!b)return null;
  if(a===b)return 0.95;
  var ea=ZODIAC_ELEM[a],eb=ZODIAC_ELEM[b];if(!ea||!eb)return 0.5;
  if(ea===eb)return 0.85;
  var comp=((ea==='fire'&&eb==='air')||(ea==='air'&&eb==='fire')||(ea==='earth'&&eb==='water')||(ea==='water'&&eb==='earth'));
  return comp?0.8:0.45;
}
function calcDobAge(){
  var m=parseInt(document.getElementById('su-dob-month')&&document.getElementById('su-dob-month').value)||0;
  var d=parseInt(document.getElementById('su-dob-day')&&document.getElementById('su-dob-day').value)||0;
  var y=parseInt(document.getElementById('su-dob-year')&&document.getElementById('su-dob-year').value)||0;
  var msg=document.getElementById('dob-msg');if(!msg)return;
  // zodiac shows as soon as month+day are valid (year not required)
  var zr=document.getElementById('dob-zodiac-row'),zl=document.getElementById('dob-zodiac-label');
  var z=_zodiacFromMD(m,d);
  if(zr&&zl){if(z){zl.textContent=z.e+' '+z.s;zr.style.display='flex';}else{zr.style.display='none';}}
  if(!m||!d||!y||y<1900||y>2015){msg.textContent='';return;}
  var now=new Date();
  var age=now.getFullYear()-y-((now.getMonth()+1>m||(now.getMonth()+1===m&&now.getDate()>=d))?0:1);
  if(age<0||age>100){msg.textContent='';return;}
  msg.textContent=age+' years old';msg.style.color=age<17?'#dc2626':'#4ade80';
}

// Password must be ≥6 chars with at least one number and one special character
function _passwordValid(p){p=p||'';return p.length>=1;}
function checkPassMatch(){
  var p1=document.getElementById('su-pass'),p2=document.getElementById('su-pass2'),msg=document.getElementById('pass-match-msg');
  if(!msg)return;
  var v1=p1?p1.value:'';
  // First show whether the password meets the strength rules
  if(v1&&!_passwordValid(v1)){
    var needs=[];if(v1.length<6)needs.push('6+ chars');if(!/[0-9]/.test(v1))needs.push('a number');if(!/[^A-Za-z0-9]/.test(v1))needs.push('a special character');
    msg.textContent='✗ Add '+needs.join(', ');msg.style.color='#dc2626';return;
  }
  if(!p2||!p2.value){msg.textContent='';return;}
  if(p1&&p1.value===p2.value){msg.textContent='✓ Passwords match';msg.style.color='#4ade80';}
  else{msg.textContent='✗ Passwords do not match';msg.style.color='#dc2626';}
}

function togglePwVis(inputId,eyeId){
  var inp=document.getElementById(inputId),eye=document.getElementById(eyeId);
  if(!inp)return;var h=inp.type==='password';inp.type=h?'text':'password';if(eye)eye.textContent=h?'🙈':'👁';
}

function doSignupAuth(){
  var fname=((document.getElementById('su-fname')&&document.getElementById('su-fname').value)||'').trim();
  var lname=((document.getElementById('su-lname')&&document.getElementById('su-lname').value)||'').trim();
  var mname=((document.getElementById('su-mname')&&document.getElementById('su-mname').value)||'').trim();
  var pass=((document.getElementById('su-pass')&&document.getElementById('su-pass').value)||'');
  var pass2=((document.getElementById('su-pass2')&&document.getElementById('su-pass2').value)||'');
  if(!fname||!lname){alert('Please enter your first and last name.');return;}
  if(!_passwordValid(pass)){alert('Please enter a password.');var pe=document.getElementById('su-pass');if(pe)pe.focus();return;}
  if(pass!==pass2){alert('Passwords do not match.');return;}
  var calcAge=99;
  if(signupMode==='student'){
    var m=parseInt(document.getElementById('su-dob-month')&&document.getElementById('su-dob-month').value)||0;
    var d=parseInt(document.getElementById('su-dob-day')&&document.getElementById('su-dob-day').value)||0;
    var y=parseInt(document.getElementById('su-dob-year')&&document.getElementById('su-dob-year').value)||0;
    if(!m||!d||!y){alert('Students must enter a full date of birth.');return;}
    var now2=new Date();
    calcAge=now2.getFullYear()-y-((now2.getMonth()+1>m||(now2.getMonth()+1===m&&now2.getDate()>=d))?0:1);
    if(calcAge<17){var am=document.getElementById('age-block-modal');if(am)am.classList.add('open');return;}
  }
  if(hasBanned(fname)||hasBanned(lname)||hasBanned(mname)){alert('⚠️ Your name contains restricted language. Please correct it.');return;}
  var _z=(signupMode==='student')?_zodiacFromMD(parseInt(document.getElementById('su-dob-month')&&document.getElementById('su-dob-month').value)||0,parseInt(document.getElementById('su-dob-day')&&document.getElementById('su-dob-day').value)||0):null;
  var _showZ=document.getElementById('su-show-zodiac');
  var _bm=parseInt(document.getElementById('su-dob-month')&&document.getElementById('su-dob-month').value)||0;
  var _bd=parseInt(document.getElementById('su-dob-day')&&document.getElementById('su-dob-day').value)||0;
  suData={fname:fname,mname:mname,lname:lname,pass:pass,age:calcAge,zodiac:_z?_z.s:null,zodiacEmoji:_z?_z.e:null,zodiacShow:_showZ?_showZ.checked:true,bMonth:_bm,bDay:_bd};
  userPro.name=fname+(mname?(' '+mname):'')+' '+lname;userPro.fname=fname;userPro.mname=mname;userPro.lname=lname;userMode=signupMode;obMode=signupMode;
  var auth=document.getElementById('authscreen');if(auth)auth.classList.remove('active');
  var onb=document.getElementById('onboarding');if(onb)onb.classList.add('active');
  obStep=1;
  if(signupMode==='student'){window._regAlumni=false;_ob4Start(false);return;}
  else if(signupMode==='alumni'){window._regAlumni=true;_ob4Start(true);return;}
  else if(signupMode==='business'){obTotalSteps=3;buildBusinessOb();}
  else{obTotalSteps=2;buildInstOb();}
  updateObProg();
}

