function sendFeuCode(){
  var phone=(document.getElementById('feu-phone')&&document.getElementById('feu-phone').value||'').trim();
  if(!phone){alert('Enter a phone number.');return;}
  _feuCode=String(Math.floor(100000+Math.random()*900000));
  var row=document.getElementById('feu-otp-row');if(row)row.style.display='block';
  var container=document.getElementById('feu-otp-inputs');
  if(container){container.innerHTML='';for(var i=0;i<6;i++){var inp=document.createElement('input');inp.className='ci';inp.type='text';inp.maxLength=1;inp.style.cssText='width:36px;height:42px;';inp.addEventListener('input',function(){otpNext(this);checkFeuCode();});container.appendChild(inp);}}
  var msg=document.getElementById('feu-otp-msg');if(msg)msg.textContent='Code sent (demo: '+_feuCode+')';
}
function checkFeuCode(){
  var container=document.getElementById('feu-otp-inputs');if(!container)return;
  var digits=Array.from(container.querySelectorAll('input')).map(function(i){return i.value;}).join('');
  if(digits.length<6)return;
  if(digits===_feuCode){
    var result=document.getElementById('feu-result');
    var txt=document.getElementById('feu-result-txt');
    // Look up saved profile by phone (demo: show current user's email if available)
    var foundEmail='';var foundHandle='';
    try{for(var k in localStorage){if(k.startsWith('ugz_')){var d=JSON.parse(localStorage[k]);if(d&&d.handle){foundEmail=k.replace('ugz_','');foundHandle=d.handle;break;}}}}catch(e){}
    if(txt)txt.innerHTML='Email: <strong>'+(foundEmail||'No account found for this phone')+'</strong>'+(foundHandle?'<br>Username: <strong>'+foundHandle+'</strong>':'');
    if(result)result.style.display='block';
    var msg=document.getElementById('feu-otp-msg');if(msg){msg.textContent='✅ Verified!';msg.style.color='#4ade80';}
  }else if(digits.length===6){
    var msg2=document.getElementById('feu-otp-msg');if(msg2){msg2.textContent='Incorrect code. Try again.';msg2.style.color='#dc2626';}
  }
}

// ── FORGOT PASSWORD ──
var _fpCode='';var _fpEmail='';
function forgotPassword(){
  var modal=document.createElement('div');modal.id='fp-modal';modal.className='mov open';modal.style.zIndex='9999';
  modal.innerHTML='<div class="msheet"><div class="mhnd"></div>'+
    '<div class="mtitle">Reset Password</div>'+
    '<div id="fp-step1">'+
      '<div style="font-size:var(--fs-base);color:var(--fg2);line-height:1.6;margin-bottom:14px;">Enter your school email. We\'ll send a verification code to reset your password.</div>'+
      '<div class="field"><label>School Email</label>'+
        '<div style="display:flex;gap:8px;">'+
          '<input class="gi" type="email" id="fp-email" placeholder="you@university.edu" style="flex:1;"/>'+
          '<button onclick="sendFpCode()" style="padding:10px 12px;border-radius:var(--rx);border:none;background:var(--p);color:#fff;font-family:var(--font);font-size:var(--fs-xs);font-weight:600;cursor:pointer;white-space:nowrap;">Send Code</button>'+
        '</div>'+
      '</div>'+
      '<div id="fp-otp-row" style="display:none;margin-top:8px;">'+
        '<div style="font-size:var(--fs-2xs);font-weight:600;color:var(--fg2);text-transform:uppercase;letter-spacing:0.7px;margin-bottom:6px;">Enter 6-digit code</div>'+
        '<div style="display:flex;gap:6px;justify-content:center;" id="fp-otp-inputs"></div>'+
        '<div id="fp-otp-msg" style="font-size:var(--fs-sm);font-weight:500;text-align:center;margin-top:8px;color:var(--fg3);"></div>'+
      '</div>'+
    '</div>'+
    '<div id="fp-step2" style="display:none;">'+
      '<div style="font-size:var(--fs-base);color:#4ade80;font-weight:500;margin-bottom:12px;">✅ Identity confirmed! Set your new password.</div>'+
      '<div class="field"><label>New Password</label>'+
        '<div style="position:relative;"><input class="gi" type="password" id="fp-new-pass" placeholder="New password"/></div>'+
      '</div>'+
      '<div class="field"><label>Confirm Password</label>'+
        '<div style="position:relative;"><input class="gi" type="password" id="fp-confirm-pass" placeholder="Confirm password"/></div>'+
      '</div>'+
      '<div id="fp-pass-err" style="font-size:var(--fs-sm);color:#dc2626;font-weight:500;margin-bottom:8px;display:none;"></div>'+
      '<button class="gbtn" style="background:var(--p);" onclick="doResetPassword()">Change Password →</button>'+
    '</div>'+
    '<button class="gbtn-ghost" style="margin-top:10px;" onclick="document.getElementById(\'fp-modal\').remove()">Cancel</button>'+
  '</div>';
  document.body.appendChild(modal);
}
function sendFpCode(){
  var email=(document.getElementById('fp-email')&&document.getElementById('fp-email').value||'').trim().toLowerCase();
  if(!email){alert('Enter your email.');return;}
  _fpEmail=email;
  _fpCode=String(Math.floor(100000+Math.random()*900000));
  var row=document.getElementById('fp-otp-row');if(row)row.style.display='block';
  var container=document.getElementById('fp-otp-inputs');
  if(container){container.innerHTML='';for(var i=0;i<6;i++){var inp=document.createElement('input');inp.className='ci';inp.type='text';inp.maxLength=1;inp.style.cssText='width:36px;height:42px;';inp.addEventListener('input',function(){otpNext(this);checkFpCode();});container.appendChild(inp);}}
  var msg=document.getElementById('fp-otp-msg');if(msg)msg.textContent='Code sent to '+email+' (demo: '+_fpCode+')';
}
function checkFpCode(){
  var container=document.getElementById('fp-otp-inputs');if(!container)return;
  var digits=Array.from(container.querySelectorAll('input')).map(function(i){return i.value;}).join('');
  if(digits.length<6)return;
  if(digits===_fpCode){
    document.getElementById('fp-step1').style.display='none';
    document.getElementById('fp-step2').style.display='block';
  }else if(digits.length===6){
    var msg=document.getElementById('fp-otp-msg');if(msg){msg.textContent='Incorrect code. Try again.';msg.style.color='#dc2626';}
  }
}
function doResetPassword(){
  var np=(document.getElementById('fp-new-pass')&&document.getElementById('fp-new-pass').value)||'';
  var cp=(document.getElementById('fp-confirm-pass')&&document.getElementById('fp-confirm-pass').value)||'';
  var errEl=document.getElementById('fp-pass-err');
  if(!_passwordValid(np)){if(errEl){errEl.textContent='Please enter a password.';errEl.style.display='block';}return;}
  if(np!==cp){if(errEl){errEl.textContent='Passwords do not match.';errEl.style.display='block';}return;}
  // Check against old password
  try{var saved=JSON.parse(localStorage.getItem('ugz_'+_fpEmail)||'{}');
    if(saved&&saved.pass&&saved.pass===np){if(errEl){errEl.textContent='New password cannot be old password.';errEl.style.display='block';}return;}
    saved.pass=np;localStorage.setItem('ugz_'+_fpEmail,JSON.stringify(saved));
  }catch(e){}
  if(errEl)errEl.style.display='none';
  alert('✅ Password changed successfully! You can now log in.');
  document.getElementById('fp-modal').remove();
}

async function doLoginAuth(){
  var emailOrUsername=((document.getElementById('li-email')&&document.getElementById('li-email').value)||'').trim();
  var pass=((document.getElementById('li-pass')&&document.getElementById('li-pass').value)||'');
  if(!emailOrUsername){alert('Enter your school email or username.');return;}
  if(!pass){alert('Enter your password.');return;}

  try {
    // 1. Authenticate with backend API
    const loginData = await apiClient.login(emailOrUsername, pass);
    console.log("Logged in successfully to backend:", loginData);

    if (loginData && loginData.notice) {
      window.ugzModal.alert(loginData.notice.message, { title: loginData.notice.title, type: 'info' });
    }

    // 2. Fetch full profile details
    const dbProfile = await apiClient.getMe();
    console.log("Loaded full database profile:", dbProfile);

    // 3. Map backend fields back to userPro global object so frontend UI works!
    userPro.id = dbProfile.id;
    userPro.name = dbProfile.firstName + ' ' + (dbProfile.lastName || '');
    userPro.handle = dbProfile.handle ? (dbProfile.handle.startsWith('@') ? dbProfile.handle : '@' + dbProfile.handle) : '@you';
    userPro.email = dbProfile.email;
    userPro.phone = dbProfile.phone || '';
    userPro.age = dbProfile.birthDate ? Math.floor((new Date() - new Date(dbProfile.birthDate)) / (365.25 * 24 * 60 * 60 * 1000)) : 20;
    userPro.isVerified = !!dbProfile.isVerified;
    verified = !!dbProfile.isVerified;
    window.verified = verified;
    // Involvement verification badges (Student Government / Creator / Athlete)
    userPro.isCreatorVerified = !!dbProfile.isCreatorVerified;
    userPro.isAthleteVerified = !!dbProfile.isAthleteVerified;
    userPro.isGovtVerified = !!dbProfile.isGovtVerified;

    const profile = dbProfile.profile || {};
    userPro.verifiedSports = Array.isArray(profile.verifiedSports) ? profile.verifiedSports : [];
    userPro.bio = profile.bio || '';
    userPro.university = profile.university || (userPro.email ? userPro.email.split('@')[1] : '');
    userPro.major = profile.major || '';
    userPro.grad = profile.grad || '';
    userPro.crossover = profile.crossover || false;
    userPro.isGhostMode = profile.isGhostMode || false;
    userPro.subscriptionTier = profile.subscriptionTier || 'FREE';
    userPro.gender = profile.gender === 'WOMAN' ? 'female' : profile.gender === 'MAN' ? 'male' : 'other';
    userGender = userPro.gender;
    userPro.interestedIn = profile.interestedIn === 'WOMAN' ? 'female' : profile.interestedIn === 'MAN' ? 'male' : 'any';
    crushGenderPref = userPro.interestedIn;

    // Map rich JSON structures back
    userPro.interests = profile.interests || [];
    userPro.prompts = profile.prompts || [];
    userPro.identityTags = profile.identityTags || [];
    userPro.lookingForTags = profile.lookingForTags || [];
    
    if (profile.lifestyle) Object.assign(userPro, profile.lifestyle);
    if (profile.academic) Object.assign(userPro, profile.academic);
    if (profile.background) Object.assign(userPro, profile.background);

    // Explicitly sync language properties on userPro
    const loadedLangs = (profile.background && (profile.background.languages || profile.background.langs)) || profile.languages || profile.langs || userPro.languages || userPro.langs || ['English'];
    userPro.languages = loadedLangs;
    userPro.langs = loadedLangs;
    userPro.flags = loadedLangs;
    selectedFlags = loadedLangs.slice();

    if (profile.customization) {
      userPro.customization = profile.customization;
      Object.assign(userPro, profile.customization);
      if (profile.customization.chatBackgrounds) {
        userPro.chatBackgrounds = profile.customization.chatBackgrounds;
      }
    }
    if (profile.socials) Object.assign(userPro, profile.socials);

    // 4. Map & render database photos in UI grid
    var grid=document.getElementById('prof-photos');
    if(grid){
      // Remove any existing cells except the ".add" button
      grid.querySelectorAll('.pgcell:not(.add)').forEach(function(c){c.remove();});
      
      const dbPhotos = dbProfile.photos || [];
      dbPhotos.sort((a,b) => (a.order || 0) - (b.order || 0));
      userPro.photos = dbPhotos.map(p => p.url);
      window.userDatingPhotos = dbPhotos.map(p => p.url);
      
      dbPhotos.forEach(p => {
        if (typeof crushPhotoCell === 'function') {
          var d=crushPhotoCell(p.url, 'center');
          d.dataset.photoId = p.id;
          grid.insertBefore(d, grid.lastChild);
        }
      });
      
      if(dbPhotos.length > 0) {
        _profilePicUrl = dbPhotos[0].url;
      } else {
        _profilePicUrl = '';
      }
      
      if (typeof _syncFirstCrushPhoto === 'function') {
        _syncFirstCrushPhoto();
      }
    }

    // Set university colors
    uni = _resolveUserUniversity(userPro.university || userPro.email);
    if (uni && uni.name) {
      userPro.university = uni.name;
    }
    if (typeof applyColors === 'function') try { applyColors(); } catch(e){}

    // Update global variables
    // accountType is the persisted alumni/student flag (see saveProfile()'s
    // academic.accountType). Older accounts saved before this field existed
    // fall back to inferring alumni status from their graduation date.
    var _acctType=(profile.academic && profile.academic.accountType) || userPro.accountType || '';
    userMode = (_acctType==='alumni' || (!_acctType && profile.grad && typeof _yearInSchoolFromGrad==='function' && _yearInSchoolFromGrad(profile.grad)==='Alumni')) ? 'alumni' : 'student';
    obMode = userMode;
    curPlan = profile.subscriptionTier ? profile.subscriptionTier.toLowerCase() : 'free';
    curPlanPeriod = profile.subscriptionPeriod || '';
    curPlanEnds = profile.subscriptionEnds ? new Date(profile.subscriptionEnds) : null;
    curPlanWillRenew = profile.subscriptionWillRenew !== false;
    verified = dbProfile.isEmailVerified;

    // Connect WebSockets
    if (typeof conectarChatEnVivo === 'function') {
      conectarChatEnVivo();
    }

    setActiveRootScreen('app');
    setTimeout(function(){
      applyColors();
      if(typeof applySeasonalSkin==='function')applySeasonalSkin();
      try{userPro.activityLog = userPro.activityLog || []; renderActivityLog();}catch(e){}
      try{_presetsLoad(); renderFilterPresets();}catch(e){}
      try{if (userPro.customization && userPro.customization.activeFilters) { _applyFilterState(userPro.customization.activeFilters); }}catch(e){}
      updateProfileUI();
      if(typeof fetchAndRenderHangouts==='function')fetchAndRenderHangouts();
      if(typeof fetchAndRenderChats==='function')fetchAndRenderChats();
      buildNav();
      if(typeof loadCrushFeed==='function'){loadCrushFeed();}else{renderCrush();}
      _saveSessionState();
      var _ls=sessionStorage.getItem('ugz_last_screen')||localStorage.getItem('ugz_last_screen');var _ll=sessionStorage.getItem('ugz_last_label')||localStorage.getItem('ugz_last_label');if(_ls&&_ls!=='premium')sw(_ls,_ll||_ls);
    },30);

  } catch (error) {
    if (error.status === 403) {
      var isEs = window.currentLang === 'es';
      // The backend resolves the real institutional email server-side (the
      // login field may hold a @handle instead) and echoes it back on this
      // specific error so the appeal screen is never mis-filled.
      var resolvedEmail = (error.data && error.data.email) || emailOrUsername;
      window.ugzModal.show({
        type: 'warning',
        message: error.message,
        confirmText: isEs ? 'Apelar' : 'Appeal',
        cancelText: isEs ? 'Cerrar' : 'Close',
        onConfirm: function() { window.openAppealForm({ email: resolvedEmail, password: pass }); }
      });
    } else {
      alert('Failed to login: ' + error.message);
    }
  }
}

// ── ONBOARDING ──
function sdots(cur,tot){var h='<div style="display:flex;gap:5px;justify-content:center;margin-bottom:14px;">';for(var i=1;i<=tot;i++){var cls=i<cur?'sdot done':i===cur?'sdot on':'sdot';h+='<div class="'+cls+'"></div>';}return h+'</div>';}
function goOb(n){for(var i=1;i<=8;i++){var e=document.getElementById('obs'+i);if(e)e.style.display=(i===n)?'block':'none';}obStep=n;updateObProg();if(typeof renderObCrushPreview==='function'&&document.getElementById('ob-crush-preview'))setTimeout(renderObCrushPreview,0);if(typeof _obSyncYearInSchool==='function'&&document.getElementById('ob-year'))setTimeout(_obSyncYearInSchool,0);}
// Year in School is derived from the graduation term + year (Dec 2026 / May 2027 → Senior, etc.)
function _obSyncYearInSchool(){
  var term=document.getElementById('ob-grad-term'),yr=document.getElementById('ob-grad-year'),ys=document.getElementById('ob-year');
  if(!term||!yr||!ys)return;
  var grad=term.value+" '"+String(yr.value).slice(-2);
  var yis=_yearInSchoolFromGrad(grad);
  if(yis==='Alumni'||!yis)yis='Senior';// a registering student can't be alumni
  if(ys.options&&ys.options.length){for(var i=0;i<ys.options.length;i++){if(ys.options[i].text===yis){ys.selectedIndex=i;break;}}}
  else{ys.textContent=yis;}
}
function updateObProg(){var p=document.getElementById('ob-prog');if(p)p.style.width=Math.round((obStep/obTotalSteps)*100)+'%';}
function obBack(){if(obStep>1)goOb(obStep-1);else{var onb=document.getElementById('onboarding'),auth=document.getElementById('authscreen');if(onb)onb.classList.remove('active');if(auth)auth.classList.add('active');}}

