  var vfOptional     = isES?'Opcional — puedes subirlo después desde tu perfil.':'Optional — you can upload it later from your profile.';
  var vfFormats      = isES?'PDF, JPG, JPEG o PNG · máx. 8 MB':'PDF, JPG, JPEG or PNG · max 8 MB';
