  var yNow=new Date().getFullYear();var gyOpt='<option value="">'+gradYrSelectDefault+'</option>';for(var y=yNow;y<yNow+6;y++)gyOpt+='<option'+(String(y)===String(st.gradyr)?' selected':'')+'>'+y+'</option>';
