    return '<div class="id-box" style="margin-bottom:0;" onclick="_ob4PickVerifDoc(\''+kind+'\',\''+(sport||'')+'\')">📄 '+label+'</div>'+
           '<div style="font-size:var(--fs-2xs);color:var(--fg3);margin-top:6px;text-align:center;">'+vfFormats+'</div>';
