function _ob4Gender(el,v){window.userGender=v;var box=el.parentElement;if(box)box.querySelectorAll('.ob4-chip').forEach(function(c){c.classList.toggle('on',c===el);});if(typeof _ob4ValidateAll3==='function')_ob4ValidateAll3();}
function _ob4Pref(el,v){window.crushGenderPref=v;var box=el.parentElement;if(box)box.querySelectorAll('.ob4-chip').forEach(function(c){c.classList.toggle('on',c===el);});if(typeof _ob4ValidateAll3==='function')_ob4ValidateAll3();}
function _ob4ValidateAll3(){
  var g=window.userGender||'';
  var pr=window.crushGenderPref||'';
  var h=window.selectedHobbies||[];
  var btn=document.getElementById('ob4-continue-btn-p3');
  if(btn){
    var isValid = !!(g && pr && h && h.length === 10);
    if(isValid){
      btn.removeAttribute('disabled');
      btn.style.opacity='1';
    }else{
      btn.setAttribute('disabled','true');
      btn.style.opacity='0.45';
    }
  }
}
function _ob4Next3(){
  var g=window.userGender||'';
  var pr=window.crushGenderPref||'';
  var h=window.selectedHobbies||[];
  if(!g||!pr||h.length!==10){
    alert('Please select your gender, preferences, and exactly 10 interests to continue.');
    return;
  }
  _ob4Go(4);
}

