function _ob4GetZodiac(month, day){
  if(!month||!day)return '';
  var signs=[
    {s:'Capricorn',e:'♑'},{s:'Aquarius',e:'♒'},{s:'Pisces',e:'♓'},{s:'Aries',e:'♈'},
    {s:'Taurus',e:'♉'},{s:'Gemini',e:'♊'},{s:'Cancer',e:'♋'},{s:'Leo',e:'♌'},
    {s:'Virgo',e:'♍'},{s:'Libra',e:'♎'},{s:'Scorpio',e:'♏'},{s:'Sagittarius',e:'♐'},
    {s:'Capricorn',e:'♑'}
  ];
  var cutoffs=[20,19,20,20,21,21,22,23,23,23,22,22,20];
  var idx=(day<=cutoffs[month-1])?month-1:month;
  if(idx>12)idx=0;
  return signs[idx].e+' '+signs[idx].s;
}
