window._evCustomCoverDataUrl = window._evCustomCoverDataUrl || null;

function _evTriggerCustomUpload(){
  var inp = document.getElementById('ev-custom-cover-input');
  if (inp) inp.click();
}

function _evHandleCustomCover(input){
  if (!input || !input.files || !input.files[0]) return;
  var file = input.files[0];
  var reader = new FileReader();
  reader.onload = function(e){
    var dataUrl = e.target.result;
    window._evCustomCoverDataUrl = dataUrl;
    window._evThumb = dataUrl;
    window._evCoverPicked = true;
    window._evEmoji = '📸';
    
    var prev = document.getElementById('ev-prev-thumb');
    if (prev) {
      prev.style.backgroundImage = 'url("' + dataUrl + '")';
      prev.style.backgroundSize = 'cover';
      prev.style.backgroundPosition = 'center';
      prev.textContent = '';
    }
    
    var sec = (document.getElementById('ev-section') && document.getElementById('ev-section').value) || 'nightlife';
    renderEventStockPickerGrid(sec);
  };
  reader.readAsDataURL(file);
}

function _evSelectCustomCoverPhoto() {
  if (!window._evCustomCoverDataUrl) return;
  window._evThumb = window._evCustomCoverDataUrl;
  window._evCoverPicked = true;
  window._evEmoji = '📸';
  var prev = document.getElementById('ev-prev-thumb');
  if (prev) {
    prev.style.backgroundImage = 'url("' + window._evCustomCoverDataUrl + '")';
    prev.style.backgroundSize = 'cover';
    prev.style.backgroundPosition = 'center';
    prev.textContent = '';
  }
  var sec = (document.getElementById('ev-section') && document.getElementById('ev-section').value) || 'nightlife';
  renderEventStockPickerGrid(sec);
}

function renderEventStockPickerGrid(sec) {
  var grid = document.getElementById('ev-stock-picker-grid');
  if (!grid) return;
  var secVal = sec || (document.getElementById('ev-section') && document.getElementById('ev-section').value) || 'nightlife';
  var photos = EVENT_STOCK_PHOTOS[secVal] || EVENT_STOCK_PHOTOS.nightlife;
  var activePhoto = window._evThumb || '';

  var hasPhoto = photos.some(function(p) { return p.url === activePhoto; });
  if (!hasPhoto && !window._evCustomCoverDataUrl && photos.length) {
    activePhoto = photos[0].url;
    window._evThumb = photos[0].url;
    window._evEmoji = photos[0].emoji;
    var prev = document.getElementById('ev-prev-thumb');
    if (prev) {
      prev.style.backgroundImage = 'url("' + photos[0].url + '")';
      prev.style.backgroundSize = 'cover';
      prev.style.backgroundPosition = 'center';
      prev.textContent = '';
    }
  }

  // 1. Upload custom tile (always FIRST choice before stock photos)
  var uploadTile = '<div class="ev-stock-choice upload-choice" onclick="_evTriggerCustomUpload()" style="position:relative;flex:0 0 110px;aspect-ratio:1;border-radius:var(--rad-md);overflow:hidden;cursor:pointer;border:2px dashed #dc2626;background:linear-gradient(145deg, rgba(240,62,90,0.25), rgba(61,123,255,0.18));display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;transition:all 0.2s;flex-shrink:0;">' +
    '<span style="font-size:var(--fs-xl);">'+icon('camera',16)+'</span>' +
    '<span style="font-size:var(--fs-2xs);font-weight:700;color:#fff;text-align:center;line-height:1.2;">+ Subir foto</span>' +
  '</div>';

  // 2. Custom preview tile if user uploaded a photo
  var customTile = '';
  if (window._evCustomCoverDataUrl) {
    var isCustomSel = (activePhoto === window._evCustomCoverDataUrl);
    customTile = '<div class="ev-stock-choice' + (isCustomSel ? ' selected' : '') + '" onclick="_evSelectCustomCoverPhoto()" style="position:relative;flex:0 0 110px;aspect-ratio:1;border-radius:var(--rad-md);overflow:hidden;cursor:pointer;border:2.5px solid ' + (isCustomSel ? '#dc2626' : 'rgba(255,255,255,0.12)') + ';background-image:url(\'' + window._evCustomCoverDataUrl + '\');background-size:cover;background-position:center;transition:all 0.2s;flex-shrink:0;">' +
      '<div style="position:absolute;bottom:0;left:0;right:0;background:rgba(0,0,0,0.85);padding:4px 6px;font-size:var(--fs-2xs);font-weight:700;color:#fff;text-align:center;">Tu foto 🌟</div>' +
      '<div style="position:absolute;inset:0;background:rgba(61,123,255,0.3);display:flex;align-items:center;justify-content:center;opacity:' + (isCustomSel ? '1' : '0') + ';transition:opacity 0.2s;">' +
        '<span style="font-size:var(--fs-xl);color:#fff;font-weight:900;">✓</span>' +
      '</div>' +
    '</div>';
  }

  // 3. Stock photo choices
  var html = photos.map(function(item) {
    var isSelected = (!window._evCustomCoverDataUrl || activePhoto !== window._evCustomCoverDataUrl) && (item.url === activePhoto);
    return '<div class="ev-stock-choice' + (isSelected ? ' selected' : '') + '" onclick="_evSelectStockGridPhoto(\'' + item.url + '\',\'' + item.emoji + '\',\'' + secVal + '\')" style="position:relative;flex:0 0 110px;aspect-ratio:1;border-radius:var(--rad-md);overflow:hidden;cursor:pointer;border:2.5px solid ' + (isSelected ? 'var(--p)' : 'rgba(255,255,255,0.12)') + ';background-image:url(\'' + item.url + '\');background-size:cover;background-position:center;box-shadow:var(--el-2);transition:all 0.2s;flex-shrink:0;">' +
      '<div style="position:absolute;bottom:0;left:0;right:0;background:linear-gradient(transparent, rgba(0,0,0,0.85));padding:6px 8px;font-size:var(--fs-2xs);font-weight:600;color:#fff;text-shadow:0 1px 2px rgba(0,0,0,0.8);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' +
        item.label +
      '</div>' +
      '<div style="position:absolute;inset:0;background:rgba(43,95,217,0.3);display:flex;align-items:center;justify-content:center;opacity:' + (isSelected ? '1' : '0') + ';transition:opacity 0.2s;">' +
        '<span style="font-size:var(--fs-xl);color:#fff;text-shadow:0 2px 5px rgba(0,0,0,0.6);font-weight:900;">✓</span>' +
      '</div>' +
    '</div>';
  }).join('');

  grid.innerHTML = uploadTile + customTile + html;
}

function _evSelectStockGridPhoto(url, emoji, sec) {
  window._evCustomCoverDataUrl = null;
  window._evThumb = url;
  window._evCoverPicked = true;
  window._evEmoji = emoji;
  
  var prev = document.getElementById('ev-prev-thumb');
  if (prev) {
    prev.style.backgroundImage = 'url("' + url + '")';
    prev.style.backgroundSize = 'cover';
    prev.style.backgroundPosition = 'center';
    prev.textContent = '';
  }
  
  renderEventStockPickerGrid(sec);
}

function _evPickThumb(){
  // The picker lives in step 7, which is collapsed by default. scrollIntoView on
  // a display:none element is a silent no-op, so the button looked dead — open
  // the step first, then scroll to the card rather than to the hidden grid.
  if (typeof _ehOpenStep === 'function') _ehOpenStep(7);
  var grid = document.getElementById('ev-stock-picker-grid');
  if (grid) {
    grid.style.outline = '2.5px solid var(--p)';
    setTimeout(function() {
      grid.style.outline = '';
    }, 800);
  }
}

function _evSetThumb(type,val,emoji){
  var t=document.getElementById('ev-prev-thumb');
  if(t){
    if(type==='grad'){
      t.style.background=val;t.style.backgroundImage='';t.textContent=emoji;
      window._evThumb='';
      window._evEmoji=emoji;
    }else{
      t.style.backgroundImage='url('+val+')';t.style.backgroundSize='cover';t.style.backgroundPosition='center';t.textContent='';
      window._evThumb=val;
      window._evEmoji=emoji;
    }
  }
  var m=document.getElementById('ev-thumb-modal');
  if(m)m.remove();
}

function _evThumbFile(inp){}

