  var photos=[],positions=[];var grid=document.getElementById('prof-photos');
  if(grid&&grid.querySelectorAll){Array.prototype.forEach.call(grid.querySelectorAll('.pgcell:not(.add)'),function(c){var img=c.querySelector('img');if(img&&img.src){photos.push(img.src);positions.push(img.style.objectPosition||'center');}});}
