function _cardStudioSave(){if(typeof _vibeSave==='function')try{_vibeSave();}catch(e){}if(typeof renderCrushPreview==='function')try{renderCrushPreview();}catch(e){}var m=document.getElementById('cardstudio-modal');if(m)m.remove();alert('🎨 Your card is saved!');}
// ── 💬 STATUS / MOOD — a short "currently…" that shows on your card & chats (auto-expires 24h) ──
var STATUS_PRESETS=[{e:'📚',t:'finals szn'},{e:'🎉',t:'out tonight'},{e:'☕',t:'free for coffee'},{e:'😴',t:'recharging'},{e:'🎧',t:'in my own world'},{e:'🏋️',t:'gym then food'},{e:'🍿',t:'movie night'},{e:'📖',t:'library grind'},{e:'🌮',t:'taco run?'},{e:'🥳',t:'down to hang'}];
var STATUS_EMOJIS=['💬','📚','🎉','☕','😴','🎧','🏋️','🍿','✈️','📖','🌮','🔥','💻','🎮','🥳','🙏'];
function _statusActive(s){return !!(s&&s.text&&s.ts&&(Date.now()-s.ts)<86400000);}
function _myStatus(){return _statusActive(userPro&&userPro.status)?userPro.status:null;}
function _profileStatus(p){if(!p)return null;if(p===userPro||p.isSelf)return _myStatus();if(p._st!==undefined)return p._st;var h=_strHash((p.name||'')+'status');if(h%3!==0){p._st=null;return null;}var s=STATUS_PRESETS[h%STATUS_PRESETS.length];p._st={emoji:s.e,text:s.t};return p._st;}
function openStatusEditor(){var cur=_myStatus();window._statusDraft={emoji:(cur&&cur.emoji)||'💬',text:(cur&&cur.text)||''};_renderStatusEditor();}
function _renderStatusEditor(){
  var d=window._statusDraft;
  var m=document.getElementById('status-modal');if(m)m.remove();
  m=document.createElement('div');m.id='status-modal';m.className='mov open';m.style.zIndex='10003';
  var presets=STATUS_PRESETS.map(function(s){var on=d.emoji===s.e&&d.text===s.t;return '<div onclick="_statusPreset(\''+s.e+'\',\''+s.t.replace(/'/g,"\\'")+'\')" style="cursor:pointer;font-size:var(--fs-sm);font-weight:500;padding:7px 11px;border-radius:var(--rad-lg);border:1px solid '+(on?'var(--p)':'var(--gbdl)')+';background:'+(on?'rgba(61,123,255,0.1)':'rgba(255,255,255,0.04)')+';color:#fff;">'+s.e+' '+s.t+'</div>';}).join('');
  var emojis=STATUS_EMOJIS.map(function(e){var on=d.emoji===e;return '<button onclick="_statusSetEmoji(\''+e+'\')" style="width:38px;height:38px;border-radius:var(--rad-sm);border:1.5px solid '+(on?'var(--p)':'var(--gbdl)')+';background:'+(on?'rgba(61,123,255,0.12)':'rgba(255,255,255,0.04)')+';font-size:var(--fs-lg);cursor:pointer;">'+e+'</button>';}).join('');
  m.innerHTML='<div class="msheet" style="max-width:380px;max-height:88vh;overflow-y:auto;"><div class="mhnd"></div>'+
    '<div style="text-align:center;margin-bottom:12px;"><div style="font-size:30px;">'+icon('chat',16)+'</div><div class="t-title">Set your status</div><div class="t-sub">Shows on your card & chats · clears after 24h</div></div>'+
    '<div style="font-size:var(--fs-xs);font-weight:600;color:var(--fg2);text-transform:uppercase;letter-spacing:0.6px;margin-bottom:7px;">Quick picks</div><div class="t-chip-row">'+presets+'</div>'+
    '<div style="font-size:var(--fs-xs);font-weight:600;color:var(--fg2);text-transform:uppercase;letter-spacing:0.6px;margin-bottom:7px;">Or make your own</div>'+
    '<div style="display:flex;gap:8px;align-items:center;margin-bottom:10px;"><div style="font-size:var(--fs-xl);width:44px;height:44px;border-radius:var(--rad-sm);background:rgba(255,255,255,0.06);border:1px solid var(--gbdl);display:flex;align-items:center;justify-content:center;" id="status-emoji-preview">'+d.emoji+'</div><input id="status-text" maxlength="24" value="'+d.text.replace(/"/g,'&quot;')+'" oninput="window._statusDraft.text=this.value;" placeholder="currently…" style="flex:1;box-sizing:border-box;background:rgba(255,255,255,0.05);border:1px solid var(--gbdl);border-radius:var(--rad-sm);color:#fff;font-size:var(--fs-base);padding:11px 12px;"/></div>'+
    '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px;">'+emojis+'</div>'+
    '<button class="gbtn" style="background:var(--p);margin-bottom:8px;" onclick="_statusSave()">Set status</button>'+
    (_myStatus()?'<button class="gbtn-ghost" style="color:#dc2626;margin-bottom:8px;" onclick="_statusClear()">Clear status</button>':'')+
    '<button class="gbtn-ghost" onclick="document.getElementById(\'status-modal\').remove()">Cancel</button></div>';
  document.body.appendChild(m);
}
function _statusPreset(e,t){window._statusDraft={emoji:e,text:t};_renderStatusEditor();}
function _statusSetEmoji(e){window._statusDraft.emoji=e;_renderStatusEditor();}
function _statusSave(){var d=window._statusDraft;var txt=(d.text||'').trim();if(!txt){alert('Add a few words for your status.');return;}userPro.status={emoji:d.emoji||'💬',text:txt.slice(0,24),ts:Date.now()};if(typeof _vibeSave==='function')try{_vibeSave();}catch(e){}_statusAfter();}
function _statusClear(){userPro.status=null;if(typeof _vibeSave==='function')try{_vibeSave();}catch(e){}_statusAfter();}
function _statusAfter(){var m=document.getElementById('status-modal');if(m)m.remove();if(typeof updateProfileUI==='function')try{updateProfileUI();}catch(e){}if(typeof renderCrushPreview==='function')try{renderCrushPreview();}catch(e){}}
// ══════════ 🍂 SEASONAL SKINS — auto by date, additive (never overrides your theme) ══════════
// months are 0-indexed: Aug=7 … Dec=11, Jan=0 … May=4
var SEASONS=[
  {k:'welcome',label:'🎉 Welcome Week',e:'🎉',banner:'🎉 Welcome week — go meet your people!',particle:'confetti',start:[7,15],end:[8,5]},
  {k:'homecoming',label:'🏈 Homecoming',e:'🏈',banner:'🏈 Homecoming week is here!',particle:'confetti',start:[9,1],end:[9,14]},
  {k:'halloween',label:'🎃 Halloween',e:'🎃',banner:'🎃 Spooky season on campus',particle:'leaf',start:[9,20],end:[9,31]},
  {k:'fall',label:'🍂 Fall',e:'🍂',banner:'🍂 Fall vibes around campus',particle:'leaf',start:[10,1],end:[10,30]},
  {k:'finalsF',label:'📚 Finals',e:'📚',banner:'📚 Finals season — you\'ve got this',particle:'none',start:[11,1],end:[11,18]},
  {k:'winter',label:'❄️ Winter',e:'❄️',banner:'❄️ Happy holidays!',particle:'snow',start:[11,19],end:[11,31]},
  {k:'newyear',label:'🎆 New Year',e:'🎆',banner:'🎆 New year, new semester',particle:'confetti',start:[0,1],end:[0,5]},
  {k:'valentines',label:'💘 Valentine\'s',e:'💘',banner:'💘 Cuffing season is here',particle:'none',start:[1,8],end:[1,15]},
  {k:'spring',label:'🌴 Spring Break',e:'🌴',banner:'🌴 Spring break!',particle:'none',start:[2,8],end:[2,22]},
  {k:'finalsS',label:'📚 Finals',e:'📚',banner:'📚 Finals season — almost there',particle:'none',start:[4,1],end:[4,15]},
  {k:'grad',label:'🎓 Graduation',e:'🎓',banner:'🎓 Congrats, grads!',particle:'confetti',start:[4,16],end:[4,31]}
];
function _currentSeason(){
  // Seasonal skins removed from the app per user request — no auto seasonal theming.
  return null;
}
function applySeasonalSkin(){
  var s=_currentSeason();
  var pc=document.getElementById('season-particles');
  if(!pc){pc=document.createElement('div');pc.id='season-particles';document.body.appendChild(pc);}
  if(s&&s.particle&&s.particle!=='none'){
    var glyphs=s.particle==='confetti'?['🎉','✨','🎊','💫']:s.particle==='snow'?['❄️','❅','✦']:['🍂','🍁','🌿'];
    var html='';for(var i=0;i<16;i++){var g=glyphs[i%glyphs.length];var left=((i*61)%100);var dur=6+(i%6);var delay=((i*7)%10)*0.6;var size=14+(i%4)*6;html+='<span style="position:absolute;left:'+left+'%;top:-12vh;font-size:'+size+'px;opacity:0.5;animation:season-fall '+dur+'s linear '+delay.toFixed(1)+'s infinite;">'+g+'</span>';}
    pc.innerHTML=html;pc.style.display='block';
  }else{pc.innerHTML='';pc.style.display='none';}
  if(typeof renderSeasonBanner==='function')renderSeasonBanner();
}
function renderSeasonBanner(){
  var box=document.getElementById('season-banner');if(!box)return;
  var s=_currentSeason();
  if(!s){box.innerHTML='';return;}
  box.innerHTML='<div style="margin:8px var(--s) 4px;padding:11px 14px;border-radius:var(--rad-md);background:linear-gradient(135deg,rgba(43,95,217,0.14),rgba(240,62,90,0.1));border:1px solid var(--gbdl);display:flex;align-items:center;gap:10px;"><div style="font-size:var(--fs-xl);">'+s.e+'</div><div style="flex:1;font-size:var(--fs-base);font-weight:600;color:#fff;">'+s.banner+'</div></div>';
}
function _seasonSetOff(off){try{localStorage.setItem('ugz_season_off',off?'1':'0');}catch(e){}if(off)window._seasonForce=null;applySeasonalSkin();if(typeof openSettings==='function')try{openSettings();}catch(e){}}
function _seasonForceSet(k){try{localStorage.setItem('ugz_season_off','0');}catch(e){}window._seasonForce=(window._seasonForce===k)?null:k;applySeasonalSkin();if(typeof renderSeasonPicker==='function')renderSeasonPicker();}
function renderSeasonPicker(){
  var box=document.getElementById('season-picker');if(!box)return;
  var off=false;try{off=localStorage.getItem('ugz_season_off')==='1';}catch(e){}
  var chips=SEASONS.map(function(s){var on=window._seasonForce===s.k;return '<button onclick="_seasonForceSet(\''+s.k+'\')" style="flex-shrink:0;padding:7px 11px;border-radius:var(--rad-lg);border:1.5px solid '+(on?'var(--p)':'var(--gbdl)')+';background:'+(on?'rgba(61,123,255,0.12)':'rgba(255,255,255,0.04)')+';color:#fff;font-family:var(--font);font-size:var(--fs-xs);font-weight:600;cursor:pointer;white-space:nowrap;">'+s.label+'</button>';}).join('');
  box.innerHTML='<div class="settings-row" style="align-items:center;"><div><div class="settings-label">🍂 Seasonal skins</div><div class="settings-sub">Auto homecoming / finals / holiday flair</div></div><div class="sw'+(off?'':' on')+'" id="sw-season" onclick="_seasonSetOff(this.classList.contains(\'on\'))"></div></div>'+
    (off?'':'<div style="font-size:var(--fs-2xs);font-weight:600;color:var(--fg2);text-transform:uppercase;letter-spacing:0.6px;margin:4px 0 7px;">Preview a skin</div><div style="display:flex;gap:6px;overflow-x:auto;-webkit-overflow-scrolling:touch;padding-bottom:4px;">'+chips+'</div>'+(window._seasonForce?'<div style="font-size:var(--fs-2xs);color:#a9c4ff;margin-top:5px;">Previewing a skin · tap it again for auto-by-date.</div>':''));
}
function renderStatusCard(){
  var box=document.getElementById('status-card');if(!box)return;
  var s=_myStatus();
  box.innerHTML='<div onclick="openStatusEditor()" style="cursor:pointer;display:flex;align-items:center;gap:12px;padding:13px;background:rgba(240,62,90,0.07);border:1px solid rgba(240,62,90,0.3);border-radius:var(--rs);">'+
    '<div style="font-size:var(--fs-2xl);">'+(s?s.emoji:''+icon('chat',16)+'')+'</div>'+
    '<div style="flex:1;"><div style="font-size:var(--fs-base);font-weight:600;color:#fff;">Status</div><div style="font-size:var(--fs-xs);color:var(--fg2);">'+(s?'"'+s.text+'" · tap to change':'Set a "currently…" — shows on your card')+'</div></div>'+
    '<div style="font-size:var(--fs-lg);color:var(--fg2);">›</div></div>';
}
function renderThemePicker(){
  var box=document.getElementById('theme-picker');if(!box)return;
  if(typeof userPro!=='undefined')userPro.customPalettes=userPro.customPalettes||[];
  var cur=(uni&&uni.p||'').toLowerCase();var sc=_schoolColors();
  // My-school palette always reflects the school's real colors; fall back to uni colors if not in the UNI list
  var schoolPal=sc||((uni&&uni.p)?{p:uni.p,p2:(uni.p2||uni.p)}:null);
  var swatch=function(name,p,p2,onclick,extra){
    var on=(p||'').toLowerCase()===cur;
    return '<div onclick="'+onclick+'" style="cursor:pointer;flex-shrink:0;width:72px;text-align:center;position:relative;">'+
      '<div style="height:52px;border-radius:var(--rad-sm);background:linear-gradient(135deg,'+p+','+p2+');border:2.5px solid '+(on?'#fff':'transparent')+';box-shadow:var(--el-1);position:relative;">'+(on?'<div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:var(--fs-lg);color:#fff;text-shadow:0 1px 3px rgba(0,0,0,0.6);">✓</div>':'')+(extra||'')+'</div>'+
      '<div style="font-size:var(--fs-2xs);font-weight:500;color:'+(on?'#fff':'var(--fg2)')+';margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+name+'</div></div>';
  };
  var html='';
  if(schoolPal)html+=swatch('🎓 My school',schoolPal.p,schoolPal.p2,'applySchoolTheme()');
  (userPro.customPalettes||[]).forEach(function(pal,i){
    html+=swatch('Palette '+(i+1),pal.p,pal.p2,'applyTheme(\''+pal.p+'\',\''+pal.p2+'\')','<span onclick="event.stopPropagation();_paletteRemove('+i+')" style="position:absolute;top:-6px;right:-6px;background:#000000;border:1px solid var(--gbdl);border-radius:50%;width:18px;height:18px;font-size:var(--fs-2xs);display:flex;align-items:center;justify-content:center;color:var(--fg2);">✕</span>');
  });
  if((userPro.customPalettes||[]).length<2)html+='<div onclick="_paletteCreate()" style="cursor:pointer;flex-shrink:0;width:72px;text-align:center;"><div style="height:52px;border-radius:var(--rad-sm);border:1.5px dashed var(--gbdl);display:flex;align-items:center;justify-content:center;font-size:var(--fs-xl);color:var(--fg2);">＋</div><div style="font-size:var(--fs-2xs);font-weight:500;color:var(--fg2);margin-top:5px;">Create</div></div>';
  box.innerHTML='<div style="padding:13px;background:rgba(255,255,255,0.04);border:1px solid var(--gbdl);border-radius:var(--rs);">'+
    '<div style="font-size:var(--fs-base);font-weight:700;color:#fff;margin-bottom:4px;">🎨 Theme</div>'+
    '<div style="font-size:var(--fs-xs);color:var(--fg3);margin-bottom:11px;">Your school colors, plus up to 2 palettes you create.</div>'+
    '<div style="display:flex;gap:12px;overflow-x:auto;-webkit-overflow-scrolling:touch;padding-bottom:2px;">'+html+'</div>'+
  '</div>';
}
function _paletteCreate(){
  userPro.customPalettes=userPro.customPalettes||[];
  if(userPro.customPalettes.length>=2){alert('You can save up to 2 custom palettes.');return;}
  window._palDraft={p:(uni&&uni.p)||'#3d7bff',p2:(uni&&uni.p2)||'#002868'};
  var m=document.getElementById('palette-modal');if(m)m.remove();
  m=document.createElement('div');m.id='palette-modal';m.className='mov open';m.style.zIndex='10003';
  m.innerHTML='<div class="msheet" style="max-width:340px;"><div class="mhnd"></div>'+
    '<div style="text-align:center;margin-bottom:14px;"><div style="color:var(--uni-accent,var(--p));">'+icon('palette',26)+'</div><div style="font-size:var(--fs-lg);font-weight:900;color:#fff;">Create a palette</div></div>'+
    '<div id="pal-preview" style="height:60px;border-radius:var(--rad-md);margin-bottom:14px;background:linear-gradient(135deg,'+window._palDraft.p+','+window._palDraft.p2+');"></div>'+
    '<div style="display:flex;gap:12px;margin-bottom:16px;"><label style="flex:1;font-size:var(--fs-sm);font-weight:600;color:var(--fg2);">Primary<br><input type="color" value="'+window._palDraft.p+'" oninput="_palSet(\'p\',this.value)" style="width:100%;height:42px;border:none;background:none;cursor:pointer;margin-top:5px;"/></label><label style="flex:1;font-size:var(--fs-sm);font-weight:600;color:var(--fg2);">Secondary<br><input type="color" value="'+window._palDraft.p2+'" oninput="_palSet(\'p2\',this.value)" style="width:100%;height:42px;border:none;background:none;cursor:pointer;margin-top:5px;"/></label></div>'+
    '<button class="gbtn" style="background:var(--p);margin-bottom:8px;" onclick="_paletteSave()">Save palette</button>'+
    '<button class="gbtn-ghost" onclick="document.getElementById(\'palette-modal\').remove()">Cancel</button></div>';
  document.body.appendChild(m);
}
function _palSet(k,v){window._palDraft[k]=v;var pv=document.getElementById('pal-preview');if(pv)pv.style.background='linear-gradient(135deg,'+window._palDraft.p+','+window._palDraft.p2+')';}
function _paletteSave(){userPro.customPalettes=userPro.customPalettes||[];if(userPro.customPalettes.length>=2)return;userPro.customPalettes.push({p:window._palDraft.p,p2:window._palDraft.p2});if(typeof _vibeSave==='function')try{_vibeSave();}catch(e){}var m=document.getElementById('palette-modal');if(m)m.remove();applyTheme(window._palDraft.p,window._palDraft.p2);}
function _paletteRemove(i){userPro.customPalettes=userPro.customPalettes||[];userPro.customPalettes.splice(i,1);if(typeof _vibeSave==='function')try{_vibeSave();}catch(e){}renderThemePicker();}

// ── NAV ──
function buildNav(){
  var nav=document.getElementById('bot-inner');if(!nav)return;nav.innerHTML='';
  var mode=obMode||userMode||'student';
  var items=mode==='institution'?NAV_INST:mode==='business'?NAV_BUSINESS:mode==='alumni'?NAV_ALUMNI:NAV_STUDENT;
  var _ls=null,_ll=null;
  try{
    _ls=sessionStorage.getItem('ugz_last_screen') || localStorage.getItem('ugz_last_screen');
    _ll=sessionStorage.getItem('ugz_last_label') || localStorage.getItem('ugz_last_label');
  }catch(e){}

  var defIdx=-1;for(var _di=0;_di<items.length;_di++){if(items[_di].id==='discover'){defIdx=_di;break;}}
  if(defIdx<0)defIdx=Math.floor(items.length/2);
  var targetId = (_ls && _ls !== 'premium') ? _ls : items[defIdx].id;

  items.forEach(function(item,i){
    var isCurrentActive = (item.id === targetId);
    var btn=document.createElement('button');btn.className='np'+(isCurrentActive?' active':'');btn.id='np-'+item.id;
    var lblText = item.lbl;
    if (window.currentLang === 'es') {
      if (item.id === 'hangouts') lblText = 'Planes';
      else if (item.id === 'unicrush') lblText = 'Crush';
      else if (item.id === 'search') lblText = 'Buscar';
      else if (item.id === 'discover') lblText = 'Campus';
      else if (item.id === 'alumnihub') lblText = 'Red';
      else if (item.id === 'chats') lblText = 'Chats';
      else if (item.id === 'profile') lblText = 'Mi Perfil';
    }
    btn.innerHTML='<span class="ni">'+item.icon+'</span><span class="nl">'+lblText+'</span>'+'<div class="nbadge" id="nbadge-'+item.id+'" style="display:'+(item.b?'flex':'none')+'">'+(item.b||'')+'</div>';
    btn.onclick=(function(id,lbl){return function(){sw(id,lbl);};})(item.id,lblText);nav.appendChild(btn);
  });
  var targetItem = items.find(function(it){return it.id === targetId;}) || items[defIdx];
  // _ll is only trustworthy when we're actually restoring the screen it was
  // saved for (targetId === _ls). When targetId got overridden back to the
  // default tab (e.g. the saved screen was 'premium', which is excluded above),
  // using the stale _ll left the title bar reading "Plans" while Campus was
  // the section actually shown.
  var targetLbl = (targetId === _ls && _ll) ? _ll : targetItem.lbl;
  if (window.currentLang === 'es' && targetItem) {
    if (targetItem.id === 'hangouts') targetLbl = 'Planes';
    else if (targetItem.id === 'unicrush') targetLbl = 'Crush';
    else if (targetItem.id === 'search') targetLbl = 'Buscar';
    else if (targetItem.id === 'discover') targetLbl = 'Campus';
    else if (targetItem.id === 'alumnihub') targetLbl = 'Red';
    else if (targetItem.id === 'chats') targetLbl = 'Chats';
    else if (targetItem.id === 'profile') targetLbl = 'Mi Perfil';
  }
  sw(targetId,targetLbl);
  var tbAv=document.getElementById('tb-av');if(tbAv)tbAv.style.display=(mode==='business')?'none':'flex';

  var totalUnread = 0;
  if (window._unreadMessageCounts) {
    for (var mId in window._unreadMessageCounts) {
      totalUnread += window._unreadMessageCounts[mId] || 0;
    }
  }
  var chatsBadge = document.getElementById('nbadge-chats');
  if (chatsBadge) {
    if (totalUnread > 0) {
      chatsBadge.style.display = 'flex';
      chatsBadge.textContent = totalUnread > 9 ? '+9' : totalUnread;
    } else {
      chatsBadge.style.display = 'none';
    }
  }
}

// The .section wrapper carries an entrance transform, which makes it the
// containing block for position:fixed children — a FAB parked inside it floats
// mid-screen instead of sticking to the viewport. Reparent to <body> once.
function _detachFabs(){
  ['hangouts-fab'].forEach(function(fid){
    var f=document.getElementById(fid);
    if(f&&f.parentElement!==document.body)document.body.appendChild(f);
  });
  var cf=document.querySelector('.chat-fab');
  if(cf&&cf.parentElement!==document.body)document.body.appendChild(cf);
}
// Fixed FABs live outside their section now, so visibility is driven by screen.
function _syncFabs(screen){
  // FABs only belong inside the app — never over the Sign Up / Log In screen.
  var appEl=document.getElementById('app');
  var appOn=!!(appEl && appEl.classList.contains('active'));
  var hf=document.getElementById('hangouts-fab');
  if(hf){
    var onCreate=(document.getElementById('evp-create')||{}).classList &&
                 document.getElementById('evp-create').classList.contains('active');
    hf.style.display=(appOn&&screen==='hangouts'&&!onCreate)?'':'none';
  }
  var cf=document.querySelector('.chat-fab');
  if(cf)cf.style.display=(appOn&&screen==='chats')?'':'none';
}
document.addEventListener('DOMContentLoaded',function(){
  _detachFabs();
  try{_syncFabs(sessionStorage.getItem('ugz_last_screen')||'hangouts');}catch(e){_syncFabs('hangouts');}
});


// Deck bootstrap. These used to hang off sw('unicrush'); now Crush is a tab,
// so they run when that tab is opened instead. Guarded so repeated tab
// switches do not re-run the one-shot skeleton.
function _initCrushDeck(){
  if(!window._ucSkelShown){window._ucSkelShown=true;var _cc=document.getElementById('crush-card');if(_cc&&typeof _swipeSkelHtml==='function'){_cc.innerHTML=_swipeSkelHtml();setTimeout(function(){if(typeof renderCrush==='function')renderCrush();},520);}}
  if(typeof renderMoments==='function')renderMoments();
  if(typeof renderSeniorSendoff==='function')renderSeniorSendoff();
  if(typeof renderSpotlight==='function')renderSpotlight();
  if(true){var _ssb=document.getElementById('single-sex-banner');if(_ssb)_ssb.innerHTML=(typeof _singleSexBanner==='function')?_singleSexBanner():'';}
  if(typeof renderCrushCategories==='function')renderCrushCategories();
  if(typeof renderMatchOfDay==='function')renderMatchOfDay();
  if(typeof renderDailyPicks==='function')renderDailyPicks();
  if(typeof _roseLoad==='function')_roseLoad();
}

function sw(id,label,opts){
  if(id==='premium'&&!window.PLANS_ENABLED)return;
  if(id==='unicrush'){
    id='discover'; label='Campus';
    try{
      sessionStorage.setItem('ugz_last_crush_tab','swipe');
      localStorage.setItem('ugz_last_crush_tab','swipe');
    }catch(e){}
  }
  if(window.NavigationManager){
    if(!label){
      label = window.NavigationManager.getSectionLabel(id);
    }
    if(!opts || !opts.fromBack){
      window.NavigationManager.pushSectionHistory(id, label);
    }
  }
  _detachFabs();
  _syncFabs(id);
  try{
    sessionStorage.setItem('ugz_last_screen',id);
    sessionStorage.setItem('ugz_last_label',label||'');
    localStorage.setItem('ugz_last_screen',id);
    localStorage.setItem('ugz_last_label',label||'');
  }catch(e){}
  document.querySelectorAll('.section').forEach(function(s){s.classList.remove('active');});
  document.querySelectorAll('.np').forEach(function(n){n.classList.remove('active');});
  // Handle biz-profile as special case
  var secId = id==='biz-profile'?'biz-profile':id;
  var sec=document.getElementById('sec-'+secId);if(sec)sec.classList.add('active');
  var np=document.getElementById('np-'+id);if(np)np.classList.add('active');
  var tbt=document.getElementById('tb-title');if(tbt){if(!label||label==='undrgradz'){tbt.innerHTML='<span class="tb-logo-undr">Undr</span><span class="tb-logo-gradz">gradz</span>';}else{tbt.textContent=label;}}
  var micons={student:'grad',alumni:'grad',business:'briefcase',institution:'landmark'};
  var mi=document.getElementById('tb-mode-icon');if(mi)mi.innerHTML=icon(micons[obMode||userMode]||'grad',18);
  var scr=document.getElementById('app-scroll');if(scr)scr.scrollTop=0;
  // Hide group chat button for business
  var grpBtn=document.querySelector('#sec-chats button[onclick="openGrpModal()"]');if(grpBtn)grpBtn.style.display=(obMode==='business'||userMode==='business')?'none':'block';
  if(id==='premium')showPremiumForMode();
  if(id==='alumnihub'&&typeof _alumniHubList==='function')_alumniHubList();
  if((id==='uchats'||id==='chats')&&typeof fetchAndRenderChats==='function')fetchAndRenderChats();
  if(id==='hangouts'&&typeof fetchAndRenderHangouts==='function')fetchAndRenderHangouts();
  if(id==='profile'){
    if(typeof renderBadges==='function')renderBadges();
    if(typeof syncVerificationStatus==='function')syncVerificationStatus();
    if(typeof apiClient!=='undefined'&&apiClient.getAccessToken()){
      apiClient.getMe().then(function(dbProfile){
        userPro.friendsCount=dbProfile.friendsCount||0;
        userPro.matchesCount=dbProfile.matchesCount||0;
        userPro.eventsJoinedCount=dbProfile.eventsJoinedCount||0;
        if(typeof updateProfileUI==='function')try{updateProfileUI();}catch(err){}
      }).catch(function(e){
        console.error("Failed to refresh profile stats:",e);
      });
    }
  }
  if(id==='profile'&&typeof renderReferralCard==='function')renderReferralCard();
  if(typeof _applyPlanLocks==='function')_applyPlanLocks();
  if(id==='profile'){setTimeout(function(){if(typeof renderCrushPreview==='function')renderCrushPreview();if(typeof onUcMilesChange==='function')onUcMilesChange(typeof _crushMiles!=='undefined'?_crushMiles:10);_updateAddCellVis();if(typeof _initFilterAccordion==='function')_initFilterAccordion();},50);}
}
function _updateAddCellVis(){
  var grid=document.getElementById('prof-photos');if(!grid)return;
  var photos=grid.querySelectorAll('.pgcell:not(.add)').length;
  var add=grid.querySelector('.pgcell.add');if(add)add.style.display=(photos>=6)?'none':'';
}


// ── PROFILE ──
// One hue per profile tab — the section repaints itself when you switch tabs.
var PROF_TAB_ACCENT={crush:'#dc2626',activity:'#fbbf24',safety:'#34d399',filters:'#60a5fa'};
function _profAccent(){
  var sec=document.getElementById('sec-profile');
  var v=sec&&sec.style.getPropertyValue('--prof-accent').trim();
  return v||PROF_TAB_ACCENT.crush;
}
function _profileCompleteness(){if(typeof userPro==='undefined'||!userPro)return {pct:100};var items=[!!(userPro.bio&&userPro.bio.trim()),!!(userPro.major&&String(userPro.major).trim()),!!(userPro.interests&&userPro.interests.length>=3),!!(userPro.prompts&&userPro.prompts.length>=1),!!((userPro.greenFlags&&userPro.greenFlags.length)||(userPro.tot&&Object.keys(userPro.tot).length)||userPro.loveLanguage),!!(userPro.anthem||userPro.workout||userPro.diet||userPro.height),!!(userPro.pronouns&&userPro.pronouns.length)];var done=items.filter(Boolean).length;return {done:done,total:items.length,pct:Math.round(done/items.length*100)};}
// Likes multiplier shown on the completeness card. Scales 1.0x -> 3.5x with how
// much of the profile is filled in, so the figure moves as you complete it
// instead of promising a flat 3.5x from an empty profile.
function _profileLikeBoost(pct){
  var p=Math.max(0,Math.min(100,pct||0));
  return (1 + (p/100)*2.5).toFixed(1);
}
function _renderCompleteness(){
  var el=document.getElementById('prof-completeness');if(!el||typeof userPro==='undefined'||!userPro)return;
  var c=_profileCompleteness();if(c.pct>=100){el.style.display='none';return;}
  var tip=!(userPro.bio&&userPro.bio.trim())?'Add a bio':((!userPro.prompts||!userPro.prompts.length)?'Add a prompt':((!userPro.interests||userPro.interests.length<3)?'Add interests':'Complete your vibe'));
  el.style.display='block';
  var A=_profAccent();
  el.innerHTML='<div onclick="openEdit()" style="cursor:pointer;background:linear-gradient(135deg,color-mix(in srgb,'+A+' 14%,transparent),rgba(255,255,255,0.03));border:1.5px solid color-mix(in srgb,'+A+' 50%,transparent);border-radius:var(--rad-lg);padding:14px 16px;'+A+' 22%,transparent);backdrop-filter:blur(10px);">'+
    '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:8px;">'+
      '<span style="font-size:var(--fs-base);font-weight:700;color:#ffffff;display:flex;align-items:center;gap:6px;white-space:nowrap;">'+icon('zap',15)+' Profile <span style="color:'+A+';text-shadow:0 0 10px color-mix(in srgb,'+A+' 80%,transparent);">'+c.pct+'%</span> complete</span>'+
      ''+
    '</div>'+
    // The likes multiplier used to be a separate pill. It now lives in the
    // sentence and scales with how complete the profile is — 1.0x at nothing
    // filled in, up to 3.5x at 100% — so the number is a reason to keep going
    // rather than a fixed promise.
    '<div style="font-size:var(--fs-xs);color:rgba(255,255,255,0.72);margin-bottom:9px;font-weight:500;">'+tip+' to get <b style="color:#fde68a;font-weight:800;">'+_profileLikeBoost(c.pct)+'x more Likes</b> and climb your university Top Rank</div>'+
    '<div style="height:8px;border-radius:var(--rad-xs);background:rgba(0,0,0,0.8);overflow:hidden;border:1px solid rgba(255,255,255,0.1);">'+
      '<div style="height:100%;width:'+c.pct+'%;background:linear-gradient(90deg,color-mix(in srgb,'+A+' 45%,#06b6d4),'+A+');border-radius:var(--rad-xs);'+A+' 80%,transparent);"></div>'+
    '</div>'+
  '</div>';
}
function updateProfileUI(){
  if(typeof _initProfileEditor==='function')try{_initProfileEditor();}catch(e){}
  try{_renderCompleteness();}catch(e){}
  try{_applyVbadge();}catch(e){}
  if(typeof renderThemePicker==='function')try{renderThemePicker();}catch(e){}
  if(typeof renderStatusCard==='function')try{renderStatusCard();}catch(e){}
  try{var _se=document.getElementById('prof-status-el');var _ms=(typeof _myStatus==='function')?_myStatus():null;if(_se){if(_ms){_se.textContent=_ms.emoji+' '+_ms.text;_se.style.display='inline-block';}else{_se.style.display='none';}}}catch(e){}
  if(suData&&suData.fname){var n=(suData.fname+' '+(suData.lname||'')).trim();if(n)userPro.name=n;}
  if(!userPro.name||userPro.name.trim()==='')userPro.name=userPro.handle.replace('@','');
  var color=uni?uni.p:'var(--p)';var init=userPro.name.charAt(0).toUpperCase();
  var avTb=document.getElementById('tb-av');if(avTb){if(_profilePicUrl){avTb.textContent='';avTb.style.backgroundImage='url('+_profilePicUrl+')';avTb.style.backgroundSize='cover';avTb.style.backgroundPosition='center';}else{avTb.textContent=init;avTb.style.backgroundImage='';avTb.style.background=color;}}
  var avPic=document.getElementById('prof-pic-txt');if(avPic)avPic.textContent=init;
  var avImg=document.getElementById('prof-avatar-img');
  var pt2=document.getElementById('prof-pic-txt');
  if(_profilePicUrl){
    if(avImg){avImg.src=_profilePicUrl;avImg.style.display='block';}
    if(pt2)pt2.style.display='none';
  }else{
    if(avImg){avImg.style.display='none';avImg.removeAttribute('src');}
    if(pt2)pt2.style.display='';
  }
  var hb=document.getElementById('prof-handle-big');if(hb)hb.textContent=userPro.handle;
  var vb=document.getElementById('vbadge');
  if(vb){
    var isBlue = !!((typeof verified !== 'undefined' && verified) || (typeof userPro !== 'undefined' && userPro && (userPro.isVerified || userPro.badgeColor === '#1d9bf0')));
    if (isBlue) {
      vb.style.display = 'inline-flex';
      vb.style.background = '#1d9bf0';
      vb.title = 'ID Verified (Blue Badge 💙)';
    } else {
      vb.style.display = 'none';
    }
  }
  var hn=document.getElementById('prof-name-el');if(hn){hn.textContent=(typeof _shortName==='function'?_shortName():userPro.name);hn.style.display='block';}
  var hd=document.getElementById('prof-handle-el');if(hd)hd.textContent=userPro.handle;
  var gr=document.getElementById('pgrad');if(gr){var gradVal=userPro.grad||'—';var yrMatch=gradVal.match(/\d{2}$/);gr.textContent=yrMatch?yrMatch[0]:gradVal;}
  var ag=document.getElementById('page');if(ag)ag.textContent=userPro.age?userPro.age:'—';
  var mj=document.getElementById('pmajor-el');if(mj)mj.textContent=[userPro.major,userPro.minor].filter(Boolean).join(' · ');
  var bi=document.getElementById('prof-bio-el');if(bi){bi.textContent=userPro.bio||'';bi.style.display=userPro.bio?'block':'none';}
  var intr=document.getElementById('prof-interests');
  if(intr&&userPro.interests&&userPro.interests.length)intr.innerHTML=userPro.interests.map(function(i){return '<div class="cpill on">'+i+'</div>';}).join('');
  var flr=document.getElementById('prof-flags-row');
  if(flr){
    var pieces=[];
    // Approved involvement verifications. Only APPROVED requests ever reach
    // these flags, so pending/rejected ones are never shown publicly.
    pieces=pieces.concat(_getVerifiedInvolvementPills());
    var userLangs = (userPro && (userPro.languages || userPro.langs || userPro.flags || (userPro.background && userPro.background.languages))) || [];
    if(userLangs && userLangs.length){
      pieces=pieces.concat(userLangs.slice(0,8).map(function(l){var flagIco = _getLangFlag(l); return '<div class="cpill">'+flagIco+' '+_langLabel(l)+'</div>';}));
    }
    flr.innerHTML=pieces.join('');
  }
  var orgNm=document.getElementById('prof-org-nm');var orgTp=document.getElementById('prof-org-tp');
  if(orgNm)orgNm.textContent=userPro.org||'None';
  if(orgTp){orgTp.textContent=userPro.org?'Frat / Sorority':'';orgTp.style.display=userPro.org?'':'none';}
  // Clubs
  var clubsWrap=document.getElementById('prof-clubs-wrap');var clubsRow=document.getElementById('prof-clubs-row');
  if(clubsWrap&&clubsRow){
    var clubs=(userPro&&userPro.clubs)||[];
    if(clubs.length){clubsWrap.style.display='block';clubsRow.innerHTML=clubs.map(function(c){return '<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:var(--rad-md);background:rgba(255,255,255,0.07);border:1px solid var(--gbdl);font-size:var(--fs-sm);font-weight:500;color:#fff;">'+icon('clubShield',13)+c+'</span>';}).join('');}
    else{clubsWrap.style.display='none';}
  }
  
  // Set profile cover/background photo dynamically
  var coverEl = document.getElementById('prof-cover');
  if (coverEl) {
    var coverUrl = 'images/unidad-deportiva-uadec.jpg'; // default fallback
    if (userPro && userPro.coverPhoto) {
      coverUrl = userPro.coverPhoto;
    } else {
      var currentUni = _getCurrentUni();
      if (currentUni && currentUni.coverPhotos && currentUni.coverPhotos.length) {
        coverUrl = currentUni.coverPhotos[0];
      }
    }
    coverEl.style.backgroundImage = 'linear-gradient(rgba(0,0,0,0.55),rgba(0,0,0,0.75)), url("' + coverUrl + '")';
  }
  var statFriends = document.getElementById('prof-stat-friends');
  var statMatches = document.getElementById('prof-stat-matches');
  var statEvents = document.getElementById('prof-stat-events');
  if(statFriends) statFriends.textContent = userPro.friendsCount || 0;
  if(statMatches) statMatches.textContent = userPro.matchesCount || 0;
  if(statEvents) statEvents.textContent = userPro.eventsJoinedCount || 0;

  var pun = document.getElementById('prof-uni-nm');
  if (pun) {
    var resolvedUni = _resolveUserUniversity((userPro && (userPro.university || userPro.email)) || '');
    if (resolvedUni) uni = resolvedUni;
    var uObj = (typeof uni !== 'undefined' && uni && uni.name) ? uni : resolvedUni;
    pun.textContent = uObj ? uObj.name : ((userPro && userPro.university) || 'University');
  }
}
function switchProfTab(tab){
  if(tab==='posts')tab='crush';
  // #match-filters-wrap no longer moves between panels: it is declared inside
  // #ptab-panel-filters and stays there. Shuttling it into #ptab-panel-crush for
  // every non-filters tab is what made the filters reappear on My Card.
  ['crush','activity','safety','filters'].forEach(function(t){
    var btn=document.getElementById('ptab-'+t);
    var panel=document.getElementById('ptab-panel-'+t);
    if(btn)btn.classList.toggle('active',t===tab);
    if(panel)panel.style.display=(t===tab)?'block':'none';
  });
  // Tint the whole Profile section with the active tab's hue
  var _sec=document.getElementById('sec-profile');
  if(_sec)_sec.style.setProperty('--prof-accent',PROF_TAB_ACCENT[tab]||PROF_TAB_ACCENT.crush);
  if(typeof _renderCompleteness==='function')try{_renderCompleteness();}catch(e){}
  if(tab==='filters'&&typeof _initFilterAccordion==='function')try{_initFilterAccordion();}catch(e){}
  if(tab==='crush'){
    if(typeof _initProfileEditor==='function')_initProfileEditor();
    if(typeof _initFilterAccordion==='function')_initFilterAccordion();
  }
  if(tab==='safety'&&typeof renderSafetyPanel==='function')renderSafetyPanel();
  if(tab==='activity'&&typeof renderActivityLog==='function')renderActivityLog();
}
// Collapse the Match Filters into tappable accordion sections (only the first stays open by default)
function _updateFilterBadge(sec){
  var title=sec.querySelector('.love-filter-title');if(!title)return;
  var n=sec.querySelectorAll?sec.querySelectorAll('.yr-chip.on, .b5c.on').length:0;
  var badge=title.querySelector('.acc-badge');
  if(n>0){if(!badge){badge=document.createElement('span');badge.className='acc-badge';var car=title.querySelector('.acc-caret');if(car)title.insertBefore(badge,car);else title.appendChild(badge);}badge.textContent=' · '+n;}
  else if(badge){badge.remove();}
}
// Jump from the Crush swipe page straight to the Match Filters (which live in Profile → Crush)
function openMatchFilters(){
  if(typeof sw==='function')sw('profile');
  if(typeof switchProfTab==='function')switchProfTab('filters');
  setTimeout(function(){
    var panel=document.getElementById('ptab-panel-filters');if(!panel)return;
    var divs=panel.querySelectorAll?panel.querySelectorAll('div'):[];var title=null;
    for(var i=0;i<divs.length;i++){if(divs[i].textContent&&divs[i].textContent.trim()==='Match Filters'&&divs[i].children.length===0){title=divs[i];break;}}
    if(title&&title.scrollIntoView)title.scrollIntoView({behavior:'smooth',block:'start'});
  },250);
}
function _initFilterAccordion(){
  // The filter sections live in #ptab-panel-filters (they were moved out of the
  // crush/My-Card panel). Querying the old panel left the accordion dead, so the
  // whole tab rendered fully expanded.
  var panel=document.getElementById('ptab-panel-filters')||document.getElementById('ptab-panel-crush');if(!panel)return;
  var secs=panel.querySelectorAll('.love-filter-section');
  Array.prototype.forEach.call(secs,function(sec,i){
    var title=sec.querySelector('.love-filter-title');if(!title)return;
    if(!sec.dataset.acc){
      sec.dataset.acc='1';
      var car=document.createElement('span');car.className='acc-caret';
      title.appendChild(car);
      title.style.cursor='pointer';
      title.addEventListener('click',function(){
        sec.classList.toggle('collapsed');
        var c=title.querySelector('.acc-caret');if(c)c.textContent=sec.classList.contains('collapsed')?'▸':'▾';
        _updateFilterBadge(sec);
      });
    }
    // Always re-collapse all but the first section each time Profile → filters is opened
    if(i>0)sec.classList.add('collapsed');else sec.classList.remove('collapsed');
    var car=title.querySelector('.acc-caret');if(car)car.textContent=sec.classList.contains('collapsed')?'▸':'▾';
    _updateFilterBadge(sec);
  });
  // Premium gating was a dead end — the dimmed A+ sections opened nothing. Make
  // the gold "A+ Student" tag tappable so it routes to the paywall.
  Array.prototype.forEach.call(panel.querySelectorAll('.love-filter-section .tag.gold'),function(tag){
    if(tag.__paywall)return;tag.__paywall=1;
    tag.style.cursor='pointer';
    tag.addEventListener('click',function(e){e.stopPropagation();if(typeof premAlert==='function')premAlert();});
  });
}
