function saveEdit(){var get=function(id){var el=document.getElementById(id);return el?el.value.trim():'';};var nameInp=document.getElementById('ed-name');if(nameInp&&nameInp.value.trim())userPro.name=nameInp.value.trim();var handleInp=document.getElementById('ed-handle');if(handleInp&&handleInp.value.trim()){var h=handleInp.value.trim();userPro.handle=h.startsWith('@')?h:'@'+h;}userPro.bio=get('ed-bio');var _ig=document.getElementById('ed-ig');if(_ig)userPro.ig=_ig.value.trim();var mode=obMode||userMode||'student';if(mode==='business'){userPro.bizCat=get('ed-biz-cat');userPro.website=get('ed-website');userPro.otherlink=get('ed-otherlink');var catEl=document.getElementById('biz-prof-cat');if(catEl&&userPro.bizCat)catEl.textContent=userPro.bizCat;var webEl=document.getElementById('biz-web-link');if(webEl&&userPro.website)webEl.innerHTML='<a href="'+userPro.website+'" target="_blank" style="color:var(--fg);font-size:var(--fs-base);text-decoration:none;">'+userPro.website.replace('https://','')+'</a>';}else{userPro.major=get('ed-major');userPro.minor=get('ed-minor');userPro.gradSemester=get('ed-gradsem');}var m=document.getElementById('edit-modal');if(m)m.classList.remove('open');if(typeof saveProfile==='function')saveProfile();updateProfileUI();}
// ── IMAGE POSITION PICKER ──
var _bannerUrl='',_profilePicUrl='';
var _ipX=0,_ipY=0,_ipDW=0,_ipDH=0,_ipFW=0,_ipFH=0,_ipBaseScale=1,_ipZoom=1;
var _ipDragging=false,_ipSX=0,_ipSY=0,_ipSDX=0,_ipSDY=0;
var _ipPinchDist=0,_ipNatW=0,_ipNatH=0;
function openImagePositioner(url,type,onSave){
  if(type==='banner'){_ipFW=300;_ipFH=120;}
  else {_ipFW=210;_ipFH=280;}
  _ipZoom=1;
  var radius=type==='banner'?'14px':'20px';
  var title=type==='banner'?icon('image',15)+' Position Banner':icon('camera',15)+' Position Portrait Photo';
  var prev=document.getElementById('imgpos-modal');if(prev)prev.remove();
  var modal=document.createElement('div');modal.id='imgpos-modal';modal.className='mov open';modal.style.zIndex='9999';
  var frameBorderStyle = type==='banner' ? 'border:2px solid var(--uni-p, #dc2626);' : 'border:2.5px solid var(--uni-p, #dc2626);';
  modal.innerHTML='<div class="msheet" style="text-align:center;padding-bottom:24px;">'+
    '<div class="mhnd"></div>'+
    '<div class="mtitle">'+title+'</div>'+
    '<div style="font-size:var(--fs-xs);color:var(--fg3);margin-bottom:10px;">Drag · pinch to zoom · use buttons</div>'+
    '<div id="ipframe" style="width:'+_ipFW+'px;height:'+_ipFH+'px;border-radius:'+radius+';overflow:hidden;position:relative;margin:0 auto 10px;'+frameBorderStyle+'cursor:grab;touch-action:none;background:#111;">'+
    '<img id="ipimg" src="'+url+'" style="position:absolute;max-width:none;user-select:none;-webkit-user-drag:none;" draggable="false"/>'+
    '</div>'+
    '<div style="display:flex;justify-content:center;gap:8px;margin-bottom:14px;">'+
      '<button onclick="ipZoomBtn(-0.15)" style="width:36px;height:36px;border-radius:50%;border:1px solid var(--gbdl);background:rgba(255,255,255,0.08);color:#fff;font-size:var(--fs-lg);cursor:pointer;display:flex;align-items:center;justify-content:center;">−</button>'+
      '<div style="font-size:var(--fs-xs);color:var(--fg3);display:flex;align-items:center;padding:0 6px;" id="ip-zoom-lbl">100%</div>'+
      '<button onclick="ipZoomBtn(0.15)" style="width:36px;height:36px;border-radius:50%;border:1px solid var(--gbdl);background:rgba(255,255,255,0.08);color:#fff;font-size:var(--fs-lg);cursor:pointer;display:flex;align-items:center;justify-content:center;">+</button>'+
    '</div>'+
    '<div style="display:flex;gap:8px;justify-content:center;margin-top:4px;">'+
      '<button class="gbtn-ghost" style="flex:1;max-width:170px;margin:0;" onclick="document.getElementById(\'imgpos-modal\').remove()">Cancel</button>'+
      '<button class="gbtn" style="background:var(--p);flex:1;max-width:170px;margin:0;" id="ipbtn-save">Use Photo ✓</button>'+
    '</div>';
  document.body.appendChild(modal);
  var img=document.getElementById('ipimg');
  var frame=document.getElementById('ipframe');
  img.onload=function(){
    _ipNatW=img.naturalWidth;_ipNatH=img.naturalHeight;
    _ipBaseScale=Math.max(_ipFW/_ipNatW,_ipFH/_ipNatH);
    function applyZoom(z,cx,cy){
      // Min zoom = 1 (cover fit) so a horizontal photo can't shrink below the frame and leave dark space.
      z=Math.max(1,Math.min(5,z));
      if(cx===undefined)cx=_ipFW/2;if(cy===undefined)cy=_ipFH/2;
      var oldDW=_ipDW,oldDH=_ipDH;
      _ipZoom=z;
      _ipDW=Math.ceil(_ipNatW*_ipBaseScale*_ipZoom);
      _ipDH=Math.ceil(_ipNatH*_ipBaseScale*_ipZoom);
      if(oldDW>0){_ipX=cx-(cx-_ipX)*(_ipDW/oldDW);}
      if(oldDH>0){_ipY=cy-(cy-_ipY)*(_ipDH/oldDH);}
      clamp();
      img.style.width=_ipDW+'px';img.style.height=_ipDH+'px';
      img.style.left=_ipX+'px';img.style.top=_ipY+'px';
      var lbl=document.getElementById('ip-zoom-lbl');if(lbl)lbl.textContent=Math.round(z*100)+'%';
    }
    window.ipZoomBtn=function(delta){applyZoom(_ipZoom+delta);};
    _ipDW=Math.ceil(_ipNatW*_ipBaseScale);_ipDH=Math.ceil(_ipNatH*_ipBaseScale);
    img.style.width=_ipDW+'px';img.style.height=_ipDH+'px';
    _ipX=Math.round((_ipFW-_ipDW)/2);_ipY=Math.round((_ipFH-_ipDH)/2);
    img.style.left=_ipX+'px';img.style.top=_ipY+'px';
    function clamp(){
      // Prevent panning to dark space — image must always fully cover the frame
      if(_ipDW>=_ipFW){_ipX=Math.min(0,Math.max(_ipFW-_ipDW,_ipX));}
      else{_ipX=Math.round((_ipFW-_ipDW)/2);}
      if(_ipDH>=_ipFH){_ipY=Math.min(0,Math.max(_ipFH-_ipDH,_ipY));}
      else{_ipY=Math.round((_ipFH-_ipDH)/2);}
    }
    function onDown(ex,ey){_ipDragging=true;_ipSX=ex;_ipSY=ey;_ipSDX=_ipX;_ipSDY=_ipY;frame.style.cursor='grabbing';}
    function onMove(ex,ey){if(!_ipDragging)return;_ipX=_ipSDX+(ex-_ipSX);_ipY=_ipSDY+(ey-_ipSY);clamp();img.style.left=_ipX+'px';img.style.top=_ipY+'px';}
    function onUp(){_ipDragging=false;frame.style.cursor='grab';}
    frame.addEventListener('mousedown',function(e){e.preventDefault();onDown(e.clientX,e.clientY);});
    document.addEventListener('mousemove',function(e){onMove(e.clientX,e.clientY);});
    document.addEventListener('mouseup',onUp);
    frame.addEventListener('touchstart',function(e){
      e.preventDefault();
      if(e.touches.length===2){_ipDragging=false;_ipPinchDist=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);}
      else{onDown(e.touches[0].clientX,e.touches[0].clientY);}
    },{passive:false});
    frame.addEventListener('touchmove',function(e){
      e.preventDefault();
      if(e.touches.length===2){
        var d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);
        var cx=(e.touches[0].clientX+e.touches[1].clientX)/2-frame.getBoundingClientRect().left;
        var cy=(e.touches[0].clientY+e.touches[1].clientY)/2-frame.getBoundingClientRect().top;
        if(_ipPinchDist>0)applyZoom(_ipZoom*(d/_ipPinchDist),cx,cy);
        _ipPinchDist=d;
      }else{onMove(e.touches[0].clientX,e.touches[0].clientY);}
    },{passive:false});
    frame.addEventListener('touchend',function(e){_ipPinchDist=0;onUp();});
  };
  document.getElementById('ipbtn-save').onclick=function(){
    // Bake the framed crop (pan + zoom) into a new image so what you positioned is exactly what's used
    try{
      var im=document.getElementById('ipimg');
      var scaleX=_ipNatW/_ipDW,scaleY=_ipNatH/_ipDH;
      var sx=(-_ipX)*scaleX,sy=(-_ipY)*scaleY;
      var sw=_ipFW*scaleX,sh=_ipFH*scaleY;
      sx=Math.max(0,Math.min(sx,_ipNatW-sw));sy=Math.max(0,Math.min(sy,_ipNatH-sh));
      var outScale=2,cw=Math.round(_ipFW*outScale),ch=Math.round(_ipFH*outScale);
      var cv=document.createElement('canvas');cv.width=cw;cv.height=ch;
      cv.getContext('2d').drawImage(im,sx,sy,sw,sh,0,0,cw,ch);
      var out=cv.toDataURL('image/jpeg',0.9);
      if(onSave)onSave(out,'50% 50%');
    }catch(err){
      var bgX=_ipDW>_ipFW?Math.max(0,Math.min(100,Math.round(_ipX/(_ipFW-_ipDW)*100))):50;
      var bgY=_ipDH>_ipFH?Math.max(0,Math.min(100,Math.round(_ipY/(_ipFH-_ipDH)*100))):50;
      if(onSave)onSave(url,bgX+'% '+bgY+'%');
    }
    document.getElementById('imgpos-modal').remove();
  };
}
function pickPic(){
  var inp=document.getElementById('prof-pic-file');
  if(!inp){inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.id='prof-pic-file';inp.style.display='none';document.body.appendChild(inp);}
  inp.onchange=function(){if(!inp.files[0])return;window._profilePicFile=inp.files[0];var url=URL.createObjectURL(inp.files[0]);inp.value='';openImagePositioner(url,'profile',function(u,pos){_applyProfilePic(u,pos);});};
  inp.click();
}
function _applyProfilePic(u,pos){
  _profilePicUrl=u;
  var pp=document.getElementById('prof-pic');
  if(pp){pp.style.backgroundImage='url('+u+')';pp.style.backgroundSize='cover';pp.style.backgroundPosition=pos||'center';}
  var pt=document.getElementById('prof-pic-txt');if(pt)pt.style.display='none';
  var img=document.getElementById('prof-avatar-img');
  if(img){img.src=u;img.style.display='block';img.style.objectPosition=pos||'center';}
  var ac=document.getElementById('prof-avatar-circle');
  if(ac){ac.style.background='transparent';ac.style.borderColor='rgba(255,255,255,0.5)';}
}
function _getCurrentUni() {
  if (typeof uni !== 'undefined' && uni) {
    if (uni.coverPhotos && uni.coverPhotos.length) return uni;
    // Try lookup by name in loaded UNI database
    if (typeof UNI !== 'undefined' && uni.name) {
      for (var d in UNI) {
        if (UNI[d] && UNI[d].name === uni.name) {
          if (UNI[d].coverPhotos && UNI[d].coverPhotos.length) {
            return UNI[d];
          }
        }
      }
    }
    // Fallback: lookup by domain from email
    var domain = '';
    if (typeof userPro !== 'undefined' && userPro && userPro.email) {
      domain = userPro.email.split('@')[1];
    }
    if (!domain && typeof _ob4State !== 'undefined' && _ob4State && _ob4State.email) {
      domain = _ob4State.email.split('@')[1];
    }
    if (domain) {
      var resolved = _resolveUniDomain(domain);
      if (resolved && typeof UNI !== 'undefined' && UNI[resolved]) {
        return UNI[resolved];
      }
    }
  }
  return uni || null;
}

