function switchEvTab(tab){
  ['nearby','my','create','joined'].forEach(function(t){
    var tb=document.getElementById('evtab-'+t);
    var p=document.getElementById('evp-'+t);
    if(tb){
      var on=(t===tab);
      tb.classList.toggle('active',on);
      tb.style.background=on?(uni?uni.p:'var(--p)'):'';
      tb.style.color=on?'#fff':'';
    }
    if(p)p.classList.toggle('active',t===tab);
  });
  if (tab === 'create' || tab === 'my' || tab === 'joined') {
    _tbBackIcon(function(){ switchEvTab('nearby'); }, 'Volver');
  } else {
    _tbModeIcon('group3');
  }
  // The FAB is a shortcut *to* Create — pointless while you're already on it
  var _fab=document.getElementById('hangouts-fab');
  if(_fab)_fab.style.display=(tab==='create')?'none':'';
  if(_fab&&_fab.parentElement!==document.body)_detachFabs();

  if(tab==='nearby')renderHangouts();
  if(tab==='my')renderMyHangouts();
  if(tab==='joined')renderJoinedHangouts();
  if(tab==='create'){
    if(typeof renderEventStockPickerGrid==='function'){
      var _sec=(document.getElementById('ev-section')&&document.getElementById('ev-section').value)||'nightlife';
      renderEventStockPickerGrid(_sec);
    }
    setTimeout(function(){if(typeof _evReviewSync==='function')_evReviewSync();},30);
    var _no=document.getElementById('ev-opt-networking');
    if(_no)_no.style.display=((obMode||userMode)==='alumni')?'':'none';
    var _sel=document.getElementById('ev-section');
    if(_sel&&_sel.value==='networking'&&(obMode||userMode)!=='alumni')_sel.value='nightlife';
    buildUniInviteSection();
    renderEvGenderRatio();
    if(typeof _populateFilterChips==='function')_populateFilterChips();
    // Paint Publish with the section the form opens on, not just on change.
    if(typeof onEvSectionChange==='function'){
      var _sEl=document.getElementById('ev-section');
      onEvSectionChange((_sEl&&_sEl.value)||'nightlife');
    }
    if(typeof _applyPlanLocks==='function')_applyPlanLocks();
    if(typeof _renderEvGreekCohost==='function')_renderEvGreekCohost();
  }
}
