// Per-event-type free spot caps (A+ Student unlocks up to 150)
var _EV_SECTION_CAP={nightlife:15,gaming:10,study:10,sports:10,dorm:10,greek:20,abroad:10,exclusive:10,networking:30,campus:15};
function _evMaxCap(sec){var freeCap=_EV_SECTION_CAP[sec]||10;return (typeof curPlan!=='undefined'&&curPlan!=='free')?150:freeCap;}

function _clampEvCap(el){
  var sec=(document.getElementById('ev-section')&&document.getElementById('ev-section').value)||'nightlife';
  var freeCap=_EV_SECTION_CAP[sec]||10;var max=_evMaxCap(sec);
  var v=parseInt(el.value);
  if(isNaN(v)||v<2){el.value=2;v=2;}
  if(v>max){
    el.value=max;
    if(typeof curPlan==='undefined'||curPlan==='free'){
      if(window.PLANS_ENABLED){
        if(typeof _prettyAlert==='function')_prettyAlert('¿Quieres más espacio? Suscríbete al plan A+ Student para alojar hasta 150 personas 🚀');
        else alert('¿Quieres más espacio? Suscríbete al plan A+ Student para alojar hasta 150 personas 🚀');
      }
      if(typeof premAlert==='function')premAlert();
    }
  }
  var ec=document.getElementById('ev-cap-echo');if(ec)ec.textContent=el.value;
  if(typeof renderEvGenderRatio==='function')renderEvGenderRatio();
}

window._evMajors=window._evMajors||[];
function _evRenderMajorChips(){var box=document.getElementById('ev-major-chips');if(!box)return;box.innerHTML=(window._evMajors||[]).map(function(m,i){return '<span class="cpill on" style="cursor:pointer;" onclick="_evRemoveMajor('+i+')">'+m+' \u2715</span>';}).join('');}
function _evRemoveMajor(i){window._evMajors.splice(i,1);_evRenderMajorChips();}
function _evAddMajor(m){if(!m)return;var sel=document.getElementById('ev-major-pick');if(sel)sel.value='';if(window._evMajors.indexOf(m)>-1)return;if(window._evMajors.length>=1&&(typeof curPlan==='undefined'||curPlan!=='aplus')){if(typeof premAlert==='function')premAlert();return;}window._evMajors.push(m);_evRenderMajorChips();}

function _evCapStep(d){
  var c=document.getElementById('ev-cap');if(!c)return;
  var curr=(parseInt(c.value)||2);
  var sec=(document.getElementById('ev-section')&&document.getElementById('ev-section').value)||'nightlife';
  var freeCap=_EV_SECTION_CAP[sec]||10;
  var isFree=(typeof curPlan==='undefined'||curPlan==='free');
  var mx=isFree?freeCap:(parseInt(c.max)||150);

  if(d<0 && curr<=2){
    if(typeof _prettyAlert==='function')_prettyAlert('Un evento requiere mínimo 2 personas para poder crearse.');
    else alert('Un evento requiere mínimo 2 personas para poder crearse.');
    c.value=2;
    if(typeof _clampEvCap==='function')_clampEvCap(c);
    return;
  }

  if(d>0 && curr>=mx && isFree){
    if(window.PLANS_ENABLED){
      if(typeof _prettyAlert==='function')_prettyAlert('🚀 ¿Quieres más espacio? Suscríbete al plan A+ Student para alojar hasta 150 personas.');
      else alert('🚀 ¿Quieres más espacio? Suscríbete al plan A+ Student para alojar hasta 150 personas.');
    }
    if(typeof premAlert==='function')premAlert();
    return;
  }

  var v=curr+d;
  if(v<2)v=2;
  if(v>mx)v=mx;
  c.value=v;
  if(typeof _clampEvCap==='function')_clampEvCap(c);
  if(typeof _evReviewSync==='function')_evReviewSync();
}

