  var w=document.getElementById('ev-prev-when');if(w)w.textContent='\uD83D\uDCC5 '+((cl&&cl!=='Select a date')?cl:'Pick a date')+((h)?(' \u00b7 '+h+':'+(mi||'00')+' '+ap):'');
  var ad=(document.getElementById('ev-addr')||{}).value||'';var wh=document.getElementById('ev-prev-where');if(wh)wh.textContent='\uD83D\uDCCD '+(ad.trim()||'Add a location');
  var cp=document.getElementById('ev-prev-cap');if(cp)cp.textContent=(document.getElementById('ev-cap')||{}).value||'10';
