function onEvSectionChange(sec){
  // Publish takes the chosen section's colour, so the button that creates the
  // event matches the category it will land in. Same _secColor the cards, the
  // detail modal and the section chips already use.
  try{
    var pb=document.getElementById('ev-publish-btn');
    if(pb&&typeof _secColor==='function')pb.style.setProperty('--pub-hue',_secColor(sec));
  }catch(e){}
  var extras=document.getElementById('ev-study-extras');
  if(extras)extras.style.display=(sec==='study')?'block':'none';
  var abroadExtras=document.getElementById('ev-abroad-extras');
  if(abroadExtras)abroadExtras.style.display=(sec==='abroad')?'block':'none';
  var netEx=document.getElementById('ev-networking-extras');if(netEx){netEx.style.display=(sec==='networking')?'block':'none';if(sec==='networking'){var mp=document.getElementById('ev-major-pick');if(mp&&mp.children.length<=1&&typeof MAJORS!=='undefined')mp.innerHTML='<option value="">Add a major…</option>'+MAJORS.map(function(m){return '<option>'+m+'</option>';}).join('');}}
  
  // Online location toggle is ONLY allowed for Study and Gaming!
  var onlineBtn=document.getElementById('ehtog-online');
  var inpersonBtn=document.getElementById('ehtog-inperson');
  if(onlineBtn){
    if(sec==='study'||sec==='gaming'){
      onlineBtn.style.display='inline-flex';
    }else{
      onlineBtn.style.display='none';
      if(inpersonBtn)_evLocMode(inpersonBtn,'inperson');
    }
  }

  var freeCap=_EV_SECTION_CAP[sec]||10;var maxCap=_evMaxCap(sec);
  var capEl=document.getElementById('ev-cap');if(capEl){capEl.max=maxCap;if(parseInt(capEl.value)>maxCap){capEl.value=maxCap;var ec=document.getElementById('ev-cap-echo');if(ec)ec.textContent=maxCap;}}
  var hint=document.getElementById('ev-cap-hint');if(hint)hint.textContent=window.PLANS_ENABLED?('Free: max '+freeCap+' · A+ Student: up to 150'):('Max '+freeCap);
  var exExtras=document.getElementById('ev-exclusive-extras');
  if(exExtras)exExtras.style.display=(sec==='exclusive')?'block':'none';
  var lock=document.getElementById('ev-exclusive-lock');
  if(lock)lock.style.display=(sec==='exclusive'&&curPlan!=='aplus')?'block':'none';
  var pubBtn=document.getElementById('ev-publish-btn');
  if(pubBtn){
    if(sec==='exclusive'&&curPlan!=='aplus'){pubBtn.textContent=window.PLANS_ENABLED?'🔒 Unlock A+ Student to create Exclusive':'🔒 Locked';pubBtn.style.background='linear-gradient(135deg,#f59e0b,#d97706)';}
    else{pubBtn.textContent='Publish Event 🎉';pubBtn.style.background='var(--p)';}
  }

  // Update stock photos grid when section changes
  if (typeof renderEventStockPickerGrid === 'function') {
    renderEventStockPickerGrid(sec);
  }
}

