var currentChatSection='all';var _chatSubMode='all';
function _chatSub(el,m){_chatSubMode=m;var box=el.parentElement;if(box)box.querySelectorAll('.cst').forEach(function(c){c.classList.toggle('on',c===el);});if(typeof filterChatBySection==='function')filterChatBySection();}
var CHAT_SECTION_LABEL = {
  all: 'All Messages',
  friends: 'Friends',
  individuals: 'Friends',
  matches: 'Matches ❤️',
  events: 'Events 🎉'
};

function _getChatCategory(item) {
  var csec = (item.getAttribute('data-csec') || '').toLowerCase();
  var id = (item.id || '').toLowerCase();
  var onclick = (item.getAttribute('onclick') || '').toLowerCase();

  if (csec === 'friends' || csec === 'individuals' || id.indexOf('chat_friend_') === 0 || id === 'clist-ana' || id === 'clist-miguel') {
    return 'friends';
  } else if (csec === 'matches' || id.indexOf('chat_match_') === 0 || onclick.indexOf('match') > -1) {
    return 'matches';
  } else {
    return 'events';
  }
}

// ── MATCHES BANNER ──
// Tapping ✕ hides it for good. It only comes back once you've picked up another 20
// matches since that dismissal — and dismissing again restarts the same 20-match wait.
var _MATCH_BANNER_STEP = 20;

function _matchBannerDismissedAt() {
  try {
    var v = localStorage.getItem('ugz_matchbanner_dismissed');
    return v === null ? null : (parseInt(v, 10) || 0);
  } catch (_) { return null; }
}

function _countWaitingMatches() {
  var n = 0;
  var uc = document.getElementById('uc-chat-list');
  if (uc) n += uc.querySelectorAll('.citem').length;
  var list = document.getElementById('chat-list');
  if (list) {
    Array.prototype.forEach.call(list.querySelectorAll('.citem'), function(it) {
      if (_getChatCategory(it) === 'matches') n++;
    });
  }
  // Offline/demo fallback — the static banner ships with a seed count
  if (!n) {
    var b = document.getElementById('chats-match-banner');
    if (b && b.dataset.seedCount) n = parseInt(b.dataset.seedCount, 10) || 0;
  }
  return n;
}

function _syncMatchBanner() {
  var b = document.getElementById('chats-match-banner');
  if (!b) return;
  var n = _countWaitingMatches();
  var dismissedAt = _matchBannerDismissedAt();
  var show = n > 0 && (dismissedAt === null || n >= dismissedAt + _MATCH_BANNER_STEP);
  b.style.display = show ? 'flex' : 'none';
  if (show) {
    var c = document.getElementById('match-banner-count');
    if (c) c.textContent = n + ' Match' + (n === 1 ? '' : 'es') + ' waiting for your message';
  }
}

function dismissMatchBanner() {
  try { localStorage.setItem('ugz_matchbanner_dismissed', String(_countWaitingMatches())); } catch (_) {}
  _syncMatchBanner();
}

// A fresh Crush match becomes a row in #chat-list tagged 'matches', so it shows up
// under All + Matches the moment you match — and never under Friends.
function _addMatchChatRow(chatId, p) {
  var container = document.getElementById('chat-dm-container') || document.getElementById('chat-list');
  if (!container || !p) return;
  if (document.getElementById('uc-match-' + chatId)) return;
  var dupe = Array.prototype.slice.call(container.querySelectorAll('.cnm')).some(function(el) {
    return el.textContent.replace(/\s*💘\s*$/, '').trim() === p.name;
  });
  if (dupe) return;

  var item = document.createElement('div');
  item.className = 'citem';
  item.id = 'uc-match-' + chatId;
  item.setAttribute('data-csec', 'matches');
  item.onclick = function() { openChat(chatId, p.name + ' 💘', p.bg, p.init, false, [], false); };
  item.innerHTML =
    '<div class="cav" style="background:'+p.bg+';"><span>'+p.init+'</span></div>' +
    '<div class="cmeta"><div class="cnm">'+p.name+' 💘</div><div class="cpre" style="color:#fbbf24;">'+icon('hourglass',16)+' Expires in 24h — say hi!</div></div>' +
    '<div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;"><div class="ctm">Now</div><div class="cunrd" style="background:#e91e63;">1</div></div>';
  container.insertBefore(item, container.firstChild);

  if (typeof filterChatBySection === 'function') filterChatBySection();
}

function _ensureEventChats() {
  var list = document.getElementById('chat-list');
  if (!list) return;

  var events = (typeof HANGOUT_EVENTS !== 'undefined') ? HANGOUT_EVENTS : [];
  events.forEach(function(e) {
    var key = (e.section || '') + '|' + (e.name || '');
    var isJoined = !!joinedHangouts[key] || (userPro && (e.creatorId === userPro.id || (e.creator && e.creator.id === userPro.id)));
    if (isJoined) {
      var emoji = e.emoji || (e.section==='nightlife'?'🌙':e.section==='study'?'📚':e.section==='dorm'?'🏠':e.section==='sports'?'⚽':e.section==='greek'?'🏛️':e.section==='campus'?'🎓':e.section==='networking'?'🤝':e.section==='exclusive'?'✨':'🎉');
      if (typeof addEventGroupChat === 'function' && !_hangoutChatIds[key]) {
        _hangoutChatIds[key] = addEventGroupChat(e.name, e.section, emoji);
      }
    }
  });
}

function setChatSection(sec) {
  if (sec === 'greek' && typeof _ensureGreekChat === 'function') _ensureGreekChat();
  if (sec === 'clubs' && typeof _ensureClubChats === 'function') _ensureClubChats();
  if ((sec === 'all' || sec === 'events') && typeof _ensureEventChats === 'function') _ensureEventChats();
  currentChatSection = sec;
  var _uc = document.getElementById('cpanel-uchats');
  var _cl = document.getElementById('chat-list');
  // Matches render inside #chat-list like every other chat — the old separate
  // panel only produced a duplicate list stacked under an empty state.
  if (_uc) _uc.style.display = 'none';
  if (_cl) _cl.style.display = 'block';

  document.querySelectorAll('.chatsec-chip').forEach(function(c) {
    var s = c.getAttribute('data-sec');
    c.classList.toggle('on', s === sec || (sec === 'friends' && s === 'individuals'));
  });

  var lbl = document.getElementById('chat-section-label');
  if (lbl) lbl.textContent = CHAT_SECTION_LABEL[sec] || 'Messages';
  var _cs = document.getElementById('chat-search');
  if (_cs) _cs.placeholder = (sec === 'study') ? '🔍 Search classes — code, name, days, time, professor…' : '🔍 Search chats, events or users…';
  filterChatBySection();
}

function _chatRecent(){try{var a=JSON.parse(localStorage.getItem('ugz_chatrecent'));if(Array.isArray(a))return a;}catch(e){}return ['FIFA Tournament','Ana M.','Calculus Group','Rooftop Party'];}
function _chatRecentSave(a){try{localStorage.setItem('ugz_chatrecent',JSON.stringify(a.slice(0,8)));}catch(e){}}
function _chatRecentDel(t){_chatRecentSave(_chatRecent().filter(function(x){return x!==t;}));_chatSearchFocus();}
function _chatRecentClear(){_chatRecentSave([]);_chatSearchFocus();}
function _chatSearchBlur(){var d=document.getElementById('chat-search-results-drop');if(d)d.style.display='none';}
function _chatSearchInput(v){if(v&&v.trim()){if(typeof liveChatSearch==='function')liveChatSearch(v);}else{_chatSearchFocus();}}
var _CHAT_SUGG=[
  {ic:'⚽',grad:'linear-gradient(150deg,#16a34a,#052e16)',t:'FIFA Tournament',s:'Event · 18 participants',act:"openChat('gfifa','FIFA Tournament ⚽','#22c55e','⚽',true,['Luis: See you guys at 7pm!'],true)"},
  {portrait:'women/65',t:'Ana M.',s:"Friend · TCU '27",act:"openChat('ana','Ana M.','#e91e63','A',false,['Ready for FIFA night?'],true)"},
  {ic:'📗',grad:'linear-gradient(150deg,#3b82f6,#1e3a8a)',t:'Calculus Study Group',s:'Study Group · 8 members',act:"openChat('gcalc','Calculus Study Group 📗','#3b82f6','📗',true,['Daniel: Chapter 6 is tough'],true)"}
];
function _chatPickSugg(i){var g=_CHAT_SUGG[i];if(!g)return;var d=document.getElementById('chat-search-results-drop');if(d)d.style.display='none';var inp=document.getElementById('chat-search');if(inp)inp.blur();var r=_chatRecent();if(r.indexOf(g.t)===-1){r.unshift(g.t);_chatRecentSave(r);}try{eval(g.act);}catch(e){}}
function _chatSearchFocus(){
  var d=document.getElementById('chat-search-results-drop');if(!d)return;
  
  if (typeof apiClient !== 'undefined' && apiClient.getAccessToken() && !window._myFriendsCache) {
    apiClient.getFriends().then(function(friends) {
      window._myFriendsCache = friends;
    }).catch(function(err) {
      console.error("Error prefetching friends for chat search:", err);
    });
  }

  var rec=_chatRecent();
  var chips=rec.length?rec.map(function(t){var e=t.replace(/'/g,"");return '<div style="display:inline-flex;align-items:center;gap:6px;background:rgba(255,255,255,0.06);border:1px solid var(--gbdl);border-radius:var(--rad-md);padding:5px 10px;font-size:var(--fs-sm);font-weight:500;color:#fff;">'+t+'<span onpointerdown="event.preventDefault();_chatRecentDel(\''+e+'\')" style="cursor:pointer;color:var(--fg3);font-weight:700;touch-action:manipulation;">×</span></div>';}).join(''):'<div style="font-size:var(--fs-sm);color:var(--fg3);padding:2px 0;">No recent searches</div>';
  var sugg=_CHAT_SUGG.map(function(g,i){
    var av=g.portrait?('<img src="https://randomuser.me/api/portraits/'+g.portrait+'.jpg" style="width:38px;height:38px;border-radius:50%;object-fit:cover;flex-shrink:0;"/>'):('<div style="width:38px;height:38px;border-radius:var(--rad-sm);background:'+g.grad+';display:flex;align-items:center;justify-content:center;font-size:var(--fs-lg);flex-shrink:0;">'+g.ic+'</div>');
    return '<div onpointerdown="event.preventDefault();_chatPickSugg('+i+')" style="display:flex;align-items:center;gap:11px;padding:9px 14px;cursor:pointer;touch-action:manipulation;">'+av+'<div style="flex:1;min-width:0;"><div style="font-size:var(--fs-base);font-weight:600;color:#fff;">'+g.t+'</div><div style="font-size:var(--fs-xs);color:var(--fg2);">'+g.s+'</div></div></div>';
  }).join('');
  d.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between;padding:11px 14px 7px;"><div style="font-size:var(--fs-2xs);font-weight:700;color:var(--fg3);letter-spacing:.7px;">RECENT SEARCHES</div>'+(rec.length?'<span onpointerdown="event.preventDefault();_chatRecentClear()" style="font-size:var(--fs-xs);font-weight:600;color:#3d7bff;cursor:pointer;touch-action:manipulation;">Clear</span>':'')+'</div>'+
    '<div style="display:flex;flex-wrap:wrap;gap:7px;padding:0 14px 12px;">'+chips+'</div>'+
    '<div style="font-size:var(--fs-2xs);font-weight:700;color:var(--fg3);letter-spacing:.7px;padding:2px 14px 4px;border-top:1px solid var(--gbdl);">SUGGESTIONS</div>'+sugg;
  d.style.display='block';
}

function filterChatBySection() {
  var list = document.getElementById('chat-list');
  if (!list) return;

  var dmContainer = document.getElementById('chat-dm-container');
  var sec = currentChatSection || 'all';
  if ((sec === 'all' || sec === 'events') && typeof _ensureEventChats === 'function') {
    var hasEvs = Array.prototype.slice.call(list.querySelectorAll('.citem')).some(function(it) {
      return _getChatCategory(it) === 'events';
    });
    if (!hasEvs) _ensureEventChats();
  }

  var items = Array.prototype.slice.call(list.querySelectorAll('.citem'));
  var sub = (typeof _chatSubMode !== 'undefined') ? _chatSubMode : 'all';
  var sec = currentChatSection || 'all';

  // Deduplicate items in DOM by ID or (Category + Name)
  var seenIds = {};
  var seenKeys = {};
  items = items.filter(function(it) {
    if (it.id && seenIds[it.id]) {
      it.remove();
      return false;
    }
    if (it.id) seenIds[it.id] = true;

    var nameEl = it.querySelector('.cnm');
    var nameKey = nameEl ? nameEl.textContent.trim() : '';
    var cat = _getChatCategory(it);
    var key = cat + '::' + nameKey;
    if (nameKey && seenKeys[key]) {
      it.remove();
      return false;
    }
    if (nameKey) seenKeys[key] = true;
    return true;
  });

  // Sort items when viewing 'all': Friends (1) -> Matches (2) -> Events (3)
  if (sec === 'all') {
    items.sort(function(a, b) {
      var catMap = { 'friends': 1, 'matches': 2, 'events': 3 };
      var catA = catMap[_getChatCategory(a)] || 3;
      var catB = catMap[_getChatCategory(b)] || 3;
      return catA - catB;
    });

    items.forEach(function(it) {
      var cat = _getChatCategory(it);
      if (dmContainer && (cat === 'friends' || cat === 'matches')) {
        dmContainer.appendChild(it);
      } else {
        list.appendChild(it);
      }
    });
  }

  // Hide old category headers
  list.querySelectorAll('.chat-grp-hdr').forEach(function(h) {
    h.style.display = 'none';
  });

  var anyVisible = false;
  items.forEach(function(it) {
    var itemCat = _getChatCategory(it);
    var show = false;

    if (sec === 'all') {
      show = true;
    } else if (sec === 'friends' || sec === 'individuals') {
      show = (itemCat === 'friends');
    } else if (sec === 'matches') {
      show = (itemCat === 'matches');
    } else if (sec === 'events') {
      show = (itemCat === 'events');
    } else {
      var rawSec = (it.getAttribute('data-csec') || '').toLowerCase();
      show = (rawSec === sec.toLowerCase());
    }

    if (show && sub === 'unread') show = !!it.querySelector('.cdot') || !!it.querySelector('.cunrd');
    if (show && sub === 'fav') show = it.getAttribute('data-fav') === '1';

    it.style.display = show ? '' : 'none';
    if (show) anyVisible = true;
  });

  var empty = document.getElementById('chat-empty-section');
  if (empty) {
    empty.style.display = anyVisible ? 'none' : 'block';
    if (!anyVisible) {
      var _es = {
        matches: { ico: icon('heart',26), t: 'No matches yet', b: 'Like people in Crush and your matches land here.', cta: 'Open Crush', act: "sw('unicrush','Crush')" },
        friends: { ico: icon('handshake',26), t: 'No friend chats yet', b: 'Add friends on campus to start a chat.', cta: 'Find people', act: "sw('unicrush','Crush')" },
        events:  { ico: icon('balloon',26), t: 'No event chats yet', b: 'Join a hangout to unlock its group chat.', cta: 'Explore hangouts', act: "sw('hangouts','Hangouts')" },
        all:     { ico: icon('message',26), t: 'No conversations yet', b: 'Match with someone or join a hangout to start chatting.', cta: 'Explore', act: "sw('hangouts','Hangouts')" }
      };
      var _e = _es[sec] || _es.all;
      empty.innerHTML =
        '<div style="width:70px;height:70px;border-radius:50%;background:color-mix(in srgb, var(--p) 14%, transparent);border:1px solid color-mix(in srgb, var(--p) 35%, transparent);display:flex;align-items:center;justify-content:center;font-size:30px;margin:0 auto 12px;">' + _e.ico + '</div>' +
        '<div style="font-size:var(--fs-md);font-weight:700;color:#fff;margin-bottom:4px;">' + _e.t + '</div>' +
        '<div style="font-size:var(--fs-sm);color:var(--fg2);line-height:1.5;max-width:240px;margin:0 auto 14px;">' + _e.b + '</div>' +
        '<button class="gbtn" onclick="' + _e.act + '" style="background:var(--p);width:auto;padding:9px 22px;display:inline-block;">' + _e.cta + '</button>';
    }
  }

  var searchWrap = document.getElementById('chat-search');
  if (searchWrap && searchWrap.parentElement) searchWrap.parentElement.style.display = '';

  _syncMatchBanner();
}
// Build a consistent empty state. `ico` is an ICONS key; `cta`/`onCta` optional.
function emptyState(o){
  o=o||{};
  return '<div class="empty-state">'+
    '<div class="es-ico">'+((typeof icon==='function')?icon(o.ico||'sparkles',28):'')+'</div>'+
    '<div class="es-title">'+(o.title||'Nothing here yet')+'</div>'+
    (o.body?'<div class="es-body">'+o.body+'</div>':'')+
    (o.cta?'<button class="es-cta" onclick="'+(o.onCta||'')+'">'+o.cta+'</button>':'')+
  '</div>';
}

// ── CREATE CHAT ──
// Pick 1–15 friends and start a chat. One friend = a DM, two or more = a group.
// Either way it's tagged 'individuals', so it lands in All + Friends only.
var CREATE_CHAT_MAX=15;

// Friends come from the API cache when we have it, otherwise from the seeded rows.
function _friendsForPicker(){
  var cache=window._myFriendsCache;
  if(Array.isArray(cache)&&cache.length){
    return cache.map(function(f){
      var nm=((f.firstName||'')+' '+(f.lastName||'')).trim()||f.handle||'Friend';
      return {
        name:nm,
        init:nm.charAt(0).toUpperCase(),
        color:(f.profile&&f.profile.customization&&f.profile.customization.badgeColor)||'#2b5fd9',
        photo:(f.photos&&f.photos[0]&&f.photos[0].url)||'',
        handle:'@'+String(f.handle||nm.toLowerCase().replace(/[^a-z0-9]/g,'')).replace(/^@/,''),
        sub:(f.profile&&f.profile.major)||_uniAcronymOf(f)
      };
    });
  }
  return Array.prototype.map.call(document.querySelectorAll('#fr-rows .frr'),function(r){
    var av=r.querySelector('div[style*="border-radius:50%"]');
    var sub=r.querySelector('div[style*="color:var(--fg2)"]');
    var nm2=r.getAttribute('data-nm')||'Friend';
    return {
      name:nm2,
      init:(av&&av.textContent.trim())||'?',
      color:(av&&av.style.background)||'#2b5fd9',
      photo:'',
      handle:'@'+nm2.toLowerCase().replace(/[^a-z0-9]/g,''),
      sub:(sub&&sub.textContent.trim())||_uniAcronymOf(null)
    };
  });
}

function _openChatCreateMenu(){
  var m=document.getElementById('chat-create-menu');if(m)m.remove();
  m=document.createElement('div');m.id='chat-create-menu';m.className='mov open';m.style.zIndex='10000';

  var friends=_friendsForPicker();
  window._createChatFriends=friends;

  var rows=friends.map(function(f,i){
    var av=f.photo
      ? '<div style="width:38px;height:38px;border-radius:50%;background:url(\''+f.photo+'\') center/cover;flex-shrink:0;"></div>'
      : '<div style="width:38px;height:38px;border-radius:50%;background:'+f.color+';display:flex;align-items:center;justify-content:center;font-weight:600;color:#fff;font-size:var(--fs-md);flex-shrink:0;">'+f.init+'</div>';
    return '<div class="ccf-row" data-idx="'+i+'" data-nm="'+f.name.replace(/"/g,'')+'" onclick="_toggleCreateChatFriend(this)" style="--cc:'+f.color+';display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:var(--rad-md);border:1.5px solid transparent;background:linear-gradient(150deg, color-mix(in srgb,'+f.color+' 12%,#0a0a12), #0a0a12) padding-box, linear-gradient(150deg, '+f.color+', color-mix(in srgb,'+f.color+' 32%,transparent) 60%) border-box;margin-bottom:9px;cursor:pointer;transition:all var(--dur) ease;">'+
      '<div class="ccf-chk" style="width:22px;height:22px;border-radius:50%;border:1.5px solid rgba(255,255,255,0.3);display:flex;align-items:center;justify-content:center;font-size:var(--fs-sm);font-weight:700;color:transparent;flex-shrink:0;">✓</div>'+
      av+
      '<div style="flex:1;min-width:0;">'+
        '<div style="font-size:var(--fs-base);font-weight:700;color:#fff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+f.name+'</div>'+
        '<div style="font-size:var(--fs-xs);font-weight:600;color:color-mix(in srgb,'+f.color+' 55%,#ffffff);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+(f.handle||'')+'</div>'+
      '</div>'+
    '</div>';
  }).join('');

  if(!rows){
    rows='<div style="text-align:center;padding:28px 0;font-size:var(--fs-base);color:var(--fg2);">No friends added yet.<br><span style="font-size:var(--fs-xs);">Add friends to start a chat.</span></div>';
  }

  m.innerHTML='<div class="msheet ccf-sheet" style="position:absolute;inset:0;max-width:none;width:100%;height:100%;max-height:100%;border-radius:0;display:flex;flex-direction:column;padding-top:calc(env(safe-area-inset-top) + 14px);"><div class="mhnd"></div><div class="mtitle">Create Chat</div>'+
    '<div style="font-size:var(--fs-xs);color:var(--fg2);margin:-6px 0 12px;">Pick 1 to '+CREATE_CHAT_MAX+' friends.</div>'+
    // Buscador de amigos primero (lo primero que buscas al crear un chat).
    '<input id="ccf-search" oninput="_filterCreateChatFriends(this.value)" placeholder="Search friends" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.05);border:1px solid var(--gbdl);border-radius:var(--rad-xl);color:#fff;font-size:var(--fs-base);padding:10px 15px;margin-bottom:10px;"/>'+
    // Nombre del grupo — solo aparece con 2+ seleccionados. El nombre es
    // opcional pero no lo decimos en el placeholder.
    '<div id="ccf-group-meta" style="display:none;align-items:center;gap:12px;margin-bottom:12px;">'+
      '<div id="ccf-photo" onclick="_ccfPickPhoto()" title="Chat photo" style="width:52px;height:52px;border-radius:50%;flex-shrink:0;cursor:pointer;background:rgba(255,255,255,0.05);border:1.5px dashed rgba(255,255,255,0.3);display:flex;align-items:center;justify-content:center;font-size:var(--fs-lg);background-size:cover;background-position:center;">'+icon('camera',18)+'</div>'+
      '<input id="ccf-title" maxlength="40" placeholder="Chat name" style="flex:1;min-width:0;box-sizing:border-box;background:rgba(255,255,255,0.05);border:1px solid var(--gbdl);border-radius:var(--rad-xl);color:#fff;font-size:var(--fs-base);padding:10px 15px;"/>'+
    '</div>'+
    '<div id="ccf-rows" style="flex:1;min-height:0;overflow-y:auto;-webkit-overflow-scrolling:touch;">'+rows+'</div>'+
    '<div style="display:flex;align-items:center;justify-content:space-between;margin:12px 0 10px;font-size:var(--fs-xs);font-weight:600;color:var(--fg2);">'+
      '<span><span id="ccf-count" style="color:#fff;">0</span> of '+CREATE_CHAT_MAX+' selected</span>'+
      '<div style="width:70px;height:5px;border-radius:3px;background:rgba(255,255,255,0.1);overflow:hidden;"><div id="ccf-bar" style="height:100%;width:0%;background:linear-gradient(90deg,#2b5fd9,#3d7bff);transition:width 0.2s;"></div></div>'+
    '</div>'+
    '<div style="display:flex;gap:10px;padding-bottom:calc(env(safe-area-inset-bottom));">'+
      '<button class="gbtn-ghost" style="flex:1;margin:0;" onclick="window.NavigationManager ? window.NavigationManager.goBack() : document.getElementById(\'chat-create-menu\').remove()">Cancel</button>'+
      '<button class="gbtn" id="ccf-create" disabled style="flex:2;margin:0;background:linear-gradient(135deg,var(--accent),var(--accent-deep));opacity:0.45;" onclick="_createChatFromPicker()">'+icon('chat',16)+' Create Chat</button>'+
    '</div>'+
  '</div>';
  document.body.appendChild(m);
}

function _createChatSelected(){
  return Array.prototype.slice.call(document.querySelectorAll('#ccf-rows .ccf-row.sel'));
}

function _toggleCreateChatFriend(el){
  var willSelect=!el.classList.contains('sel');
  if(willSelect&&_createChatSelected().length>=CREATE_CHAT_MAX){
    if(typeof ugzAlert==='function')ugzAlert('You can pick up to '+CREATE_CHAT_MAX+' friends.');
    return;
  }
  el.classList.toggle('sel');
  var on=el.classList.contains('sel');
  var chk=el.querySelector('.ccf-chk');
  el.style.borderColor=on?'#3d7bff':'rgba(255,255,255,0.08)';
  el.style.background=on?'rgba(61,123,255,0.14)':'rgba(255,255,255,0.03)';
  el.style.boxShadow=on?'0 0 14px rgba(61,123,255,0.3)':'none';
  if(chk){
    chk.style.background=on?'#3d7bff':'transparent';
    chk.style.borderColor=on?'#3d7bff':'rgba(255,255,255,0.25)';
    chk.style.color=on?'#fff':'transparent';
  }
  _syncCreateChatFooter();
}

// Chat photo chosen in the picker. Local blob URL — see _ccfPickPhoto.
window._ccfPhoto = '';
function _ccfPickPhoto(){
  var inp=document.createElement('input');inp.type='file';inp.accept='image/*';
  inp.onchange=function(){
    if(!inp.files||!inp.files[0])return;
    var url=URL.createObjectURL(inp.files[0]);
    var apply=function(u){
      window._ccfPhoto=u;
      var box=document.getElementById('ccf-photo');
      if(box){box.style.backgroundImage='url('+u+')';box.textContent='';box.style.border='1.5px solid var(--p)';}
    };
    // Reuse the app's existing cropper when available, same as pickPic/cgChangePic.
    if(typeof openImagePositioner==='function'){openImagePositioner(url,'profile',function(u){apply(u);});}
    else apply(url);
  };
  inp.click();
}

function _syncCreateChatFooter(){
  var n=_createChatSelected().length;
  var c=document.getElementById('ccf-count');if(c)c.textContent=n;
  var bar=document.getElementById('ccf-bar');if(bar)bar.style.width=Math.round(n/CREATE_CHAT_MAX*100)+'%';
  // Name + photo only apply to a group; a single pick is a DM with that person.
  var gm=document.getElementById('ccf-group-meta');if(gm)gm.style.display=(n>1?'flex':'none');
  var btn=document.getElementById('ccf-create');
  if(btn){btn.disabled=(n===0);btn.style.opacity=n?'1':'0.45';btn.style.cursor=n?'pointer':'default';
    btn.textContent=(n>1?('💬 Create Group ('+n+')'):'💬 Create Chat');}
}

function _filterCreateChatFriends(q){
  q=(q||'').toLowerCase();
  document.querySelectorAll('#ccf-rows .ccf-row').forEach(function(r){
    var nm=(r.getAttribute('data-nm')||'').toLowerCase();
    r.style.display=(!q||nm.indexOf(q)>-1)?'flex':'none';
  });
}

function _createChatFromPicker(){
  var sel=_createChatSelected();
  if(!sel.length)return;
  var all=window._createChatFriends||[];
  var picked=sel.map(function(r){return all[parseInt(r.getAttribute('data-idx'),10)];}).filter(Boolean);
  if(!picked.length)return;

  var isGroup=picked.length>1;
  var first=picked[0];
  // A typed name wins over the auto "Ana, Miguel +2" one.
  var titleEl=document.getElementById('ccf-title');
  var typedTitle=(isGroup&&titleEl)?String(titleEl.value||'').trim():'';
  var chatPhoto=isGroup?(window._ccfPhoto||''):'';
  var name=typedTitle || (isGroup
    ? picked.slice(0,3).map(function(f){return f.name.split(' ')[0];}).join(', ')+(picked.length>3?(' +'+(picked.length-3)):'')
    : first.name);
  var color=isGroup?(uni?uni.p:'#2b5fd9'):first.color;
  var init=isGroup?'👥':first.init;
  var chatId=(isGroup?'grp_':'dm_')+Date.now();

  var menu=document.getElementById('chat-create-menu');if(menu)menu.remove();

  // Seed the group meta up front so the settings sheet and the chat header read
  // the chosen name/photo instead of deriving a name from the DOM later.
  if(isGroup){
    window.groupChatMeta=window.groupChatMeta||{};
    var myH=(userPro&&userPro.handle)?userPro.handle.replace('@',''):'me';
    window.groupChatMeta[chatId]={
      name:name, adminHandle:myH, adminName:(userPro&&userPro.name)||'Admin',
      bannerUrl:'', avatarUrl:chatPhoto, isEvent:false, nicknames:{},
      members:[{id:(userPro&&userPro.id)||'me',name:(userPro&&userPro.name)||'You',handle:myH,photo:(userPro&&userPro.photos&&userPro.photos[0])||'',isAdmin:true}]
        .concat(picked.map(function(f,i){
          return {id:'f_'+i, name:f.name, handle:String(f.name).toLowerCase().replace(/\s+/g,''), photo:f.photo||'', isAdmin:false};
        }))
    };
    if(typeof _saveGroupMeta==='function')try{_saveGroupMeta();}catch(e){}
  }
  window._ccfPhoto='';

  var container=document.getElementById('chat-dm-container')||document.getElementById('chat-list');
  if(container){
    var item=document.createElement('div');
    item.className='citem';
    item.id='chatrow_'+chatId;
    // 'individuals' → category 'friends' → shows under All and Friends, never Matches
    item.setAttribute('data-csec','individuals');
    item.onclick=function(){openChat(chatId,name,color,init,isGroup,[],false);};
    item.innerHTML=(isGroup
        ? (chatPhoto
            ? '<div class="cav grp" id="cav-'+chatId+'" style="background:url(\''+chatPhoto+'\') center/cover;"></div>'
            : '<div class="cav grp" id="cav-'+chatId+'" style="background:'+color+';"><span style="display:inline-flex;">'+icon('users',18)+'</span></div>')
        : (first.photo
            ? '<div class="cav" style="background:'+color+';"><img src="'+first.photo+'" style="width:100%;height:100%;border-radius:50%;object-fit:cover;"/></div>'
            : '<div class="cav" style="background:'+color+';"><span>'+init+'</span></div>'))+
      '<div class="cmeta"><div class="cnm">'+name+(isGroup?' 👥':'')+'</div><div class="cpre">'+(isGroup?(picked.length+' members · group created'):'Chat created · say hi 👋')+'</div></div>'+
      '<div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;"><div class="ctm">Now</div></div>';
    container.insertBefore(item,container.firstChild);
  }

  if(typeof filterChatBySection==='function')filterChatBySection();
  openChat(chatId,name,color,init,isGroup,
    isGroup?['🎉 Group created with '+picked.length+' friends. Say hi! 👋']:[],false);
}
function addEventGroupChat(eventName,section,emoji){
  var list=document.getElementById('chat-list');if(!list)return;
  var id='evgrp_'+Date.now();
  var color=section==='nightlife'?'#3d7bff':section==='study'?'#3b82f6':section==='dorm'?'#10b981':section==='sports'?'#f59e0b':section==='exclusive'?'#dc2626':'#3d7bff';
  var d=document.createElement('div');
  d.className='citem';
  d.setAttribute('data-csec',section);
  d.id='chatrow_'+id;d.setAttribute('onclick',"openChat('"+id+"','"+eventName.replace(/'/g,"\\'")+"','"+color+"','"+emoji+"',true,['\uD83C\uDF89 Group chat for everyone going. Say hi \uD83D\uDC4B'],true)");
  d.innerHTML='<div class="cav grp" style="background:'+color+';"><span>'+emoji+'</span></div>'+
    '<div class="cmeta"><div class="cnm">'+eventName+'</div><div class="cpre">New group · joined just now</div></div>'+
    '<div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;"><div class="ctm">Now</div></div>';
  list.insertBefore(d,list.firstChild);
  filterChatBySection();
  return id;
}
function computeCompat(ev){
  var score=0,total=0;
  // language overlap
  total+=20;
  if(ev.langs&&ev.langs.length){
    var mine=(userPro.langs||[]);
    var overlap=ev.langs.filter(function(l){return mine.indexOf(l)>-1;}).length;
    if(overlap)score+=Math.min(20,20*overlap/ev.langs.length);
  }else{score+=10;}
  // org / Greek
  total+=20;
  if(ev.org){if(userPro.org&&userPro.org===ev.org)score+=20;}else{score+=10;}
  // major
  total+=20;
  if(ev.major){if(userPro.major&&userPro.major===ev.major)score+=20;}else{score+=10;}
  // gender restriction match
  total+=15;
  if(ev.restriction==='all'||ev.restriction===userGender)score+=15;
  // hobbies / interest tag (use emoji match fallback)
  total+=15;
  if(selectedHobbies&&selectedHobbies.length){
    var hit=selectedHobbies.some(function(h){return ev.name.toLowerCase().indexOf(h.toLowerCase())>-1;});
    score+=hit?15:7;
  }else{score+=7;}
  // country flag
  total+=10;
  if(ev.country==='international'&&(userPro.hometown||'').toLowerCase().indexOf('united states')===-1)score+=10;
  else if(!ev.country)score+=5;
  return Math.round(score/total*100);
}
// View YOUR own created event — full details + Edit (no Join, since it's yours)
