function _deleteMyEvent(el){
  var modal=el.closest('.mov');var btn=modal&&modal._evBtn;
  if(btn){var card=btn.closest('.gc');if(card)card.remove();}
  var myEl=document.getElementById('evp-my');var emptyEl=document.getElementById('my-events-empty');
  if(myEl&&!myEl.querySelector('.gc')&&emptyEl)emptyEl.style.display='block';
  if(modal)modal.remove();
  setTimeout(function(){alert('🗑 Event deleted.');},120);
}
// Countdown for an event — uses a real date if present, else parses the weekday/time from e.time.
// Returns 'ENDED', or "N days/hours to join".
function _evCountdown(e){
  try{
    var now=new Date();var target;
    if(e&&e._dateMs){target=new Date(e._dateMs);}
    else{
      var tm=((e&&e.time)||'').toLowerCase();
      var days=['sun','mon','tue','wed','thu','fri','sat'];var wd=-1;
      days.forEach(function(d,i){if(tm.indexOf(d)>-1)wd=i;});
      if(wd<0)return '';
      target=new Date(now);var add=(wd-now.getDay()+7)%7;if(add===0)add=7;target.setDate(now.getDate()+add);
      var hm=tm.match(/(\d{1,2})\s*(am|pm)/);var hr=20;
      if(hm){hr=(parseInt(hm[1])%12)+(hm[2]==='pm'?12:0);}
      target.setHours(hr,0,0,0);
    }
    var diff=target-now;if(diff<=0)return 'ENDED';
    var hrs=diff/3600000;
    if(hrs>=24){var d=Math.ceil(hrs/24);return d+' day'+(d>1?'s':'')+' to join';}
    var h=Math.max(1,Math.ceil(hrs));return h+' hour'+(h>1?'s':'')+' to join';
  }catch(_){return '';}
}
var _FRIEND_POOL=[{n:'Ana M.',i:'A',c:'#e91e63'},{n:'Miguel R.',i:'M',c:'#3b82f6'},{n:'Sofía T.',i:'S',c:'#3d7bff'},{n:'Carlos M.',i:'C',c:'#f59e0b'},{n:'Jessica M.',i:'J',c:'#dc2626'},{n:'Daniel P.',i:'D',c:'#0ea5e9'},{n:'Laura V.',i:'L',c:'#16a34a'}];
function _strHash(s){var h=0;s=String(s);for(var i=0;i<s.length;i++){h=(h*31+s.charCodeAt(i))>>>0;}return h;}
function _evFriendsGoing(e){var h=_strHash(e.name);var n=h%4;var out=[];for(var i=0;i<n;i++){out.push(_FRIEND_POOL[(h+i)%_FRIEND_POOL.length]);}return out;}
function _evFriendsGoingHtml(e){
  if (e.attendees && e.attendees.length > 0) {
    var realGoing = e.attendees.map(function(att) {
      var photoUrl = att.photos && att.photos[0] ? att.photos[0].url : '';
      return {
        id: att.id,
        n: att.firstName,
        i: att.firstName.charAt(0).toUpperCase(),
        avatar: photoUrl
      };
    });
    var avs = realGoing.slice(0, 3).map(function(f, i) {
      if (f.avatar) {
        return '<div style="width:24px;height:24px;border-radius:50%;background:url(\''+f.avatar+'\') center/cover;border:2px solid #0b0b0e;margin-left:'+(i?-8:0)+'px;"></div>';
      } else {
        return '<div style="width:24px;height:24px;border-radius:50%;background:#7aa5ff;display:flex;align-items:center;justify-content:center;font-size:var(--fs-xs);font-weight:600;color:#fff;border:2px solid #0b0b0e;margin-left:'+(i?-8:0)+'px;">'+f.i+'</div>';
      }
    }).join('');
    var label = realGoing[0].n + (realGoing.length > 1 ? ' + ' + (realGoing.length - 1) + ' ' + (realGoing.length - 1 === 1 ? 'person' : 'people') : '') + ' going';
    return '<div style="display:flex;align-items:center;gap:7px;margin-bottom:9px;">'+avs+'<span style="font-size:var(--fs-xs);color:#4ade80;font-weight:500;">'+icon('flame',13)+' '+label+'</span></div>';
  }
  var fg=_evFriendsGoing(e);if(!fg.length)return '';
  var avs=fg.slice(0,3).map(function(f,i){return '<div style="width:24px;height:24px;border-radius:50%;background:'+f.c+';display:flex;align-items:center;justify-content:center;font-size:var(--fs-xs);font-weight:600;color:#fff;border:2px solid #0b0b0e;margin-left:'+(i?-8:0)+'px;">'+f.i+'</div>';}).join('');
  var label=fg[0].n+(fg.length>1?' + '+(fg.length-1)+' '+(fg.length-1===1?'friend':'friends'):'')+' going';
  return '<div style="display:flex;align-items:center;gap:7px;margin-bottom:9px;">'+avs+'<span style="font-size:var(--fs-xs);color:#4ade80;font-weight:500;">'+icon('flame',13)+' '+label+'</span></div>';
}
function _happeningTonightHtml(){
  var tonight=HANGOUT_EVENTS.filter(function(e){var c=_evCountdown(e);return c&&c.indexOf('hour')>-1&&e.spots<e.cap;});
  if(window._userCreatedEvents)tonight=tonight.concat(window._userCreatedEvents.filter(function(e){var c=_evCountdown(e);return c&&c.indexOf('hour')>-1;}));
  if(!tonight.length)return '';
  var cards=tonight.slice(0,8).map(function(e){
    var cd=_evCountdown(e);var pct=Math.round((e.spots/e.cap)*100);
    return '<div onclick="setHangoutSection(\''+e.section+'\')" style="flex:0 0 210px;scroll-snap-align:start;border-radius:var(--rad-md);overflow:hidden;border:1px solid rgba(251,191,36,0.3);background:rgba(251,191,36,0.06);cursor:pointer;">'+
      '<div style="padding:11px;">'+
        '<div style="display:flex;justify-content:space-between;align-items:flex-start;"><div style="font-size:var(--fs-base);font-weight:600;color:#fff;line-height:1.25;">'+e.name+'</div><span style="font-size:var(--fs-xl);">'+e.emoji+'</span></div>'+
        '<div style="font-size:var(--fs-xs);color:#fbbf24;font-weight:600;margin:5px 0 7px;">'+icon('hourglass',16)+' '+cd+'</div>'+
        '<div style="display:flex;justify-content:space-between;font-size:var(--fs-2xs);font-weight:600;color:var(--fg2);margin-bottom:3px;"><span>'+e.spots+'/'+e.cap+' spots</span><span style="color:'+(pct>=80?'#dc2626':'#4ade80')+';">'+(e.cap-e.spots)+' left</span></div>'+
        '<div class="bar-t"><div class="bar-f" style="background:#fbbf24;width:'+pct+'%"></div></div>'+
      '</div>'+
    '</div>';
  }).join('');
  return '<div style="margin-bottom:10px;"><div style="font-size:var(--fs-base);font-weight:700;color:#fff;padding:2px var(--s) 8px;">🔥 Happening Tonight</div>'+
    '<div style="display:flex;gap:10px;overflow-x:auto;scroll-snap-type:x mandatory;padding:0 var(--s) 6px;-webkit-overflow-scrolling:touch;">'+cards+'</div></div>';
}
