// ── NEW MULTI-GENDER ALLOW SYSTEM ──
var evGenderAllowed={female:true,male:true,other:true};
var evGenderPct={female:34,male:33,other:33};
function toggleGenderAllow(g){
  // Allow 1, 2, or all 3 — just don't allow zero
  var on=Object.keys(evGenderAllowed).filter(function(k){return evGenderAllowed[k];});
  if(evGenderAllowed[g]&&on.length<=1){alert('Pick at least 1 gender.');return;}
  evGenderAllowed[g]=!evGenderAllowed[g];
  // Only the .on class now: the look comes from CSS (the _gradSkin recipe with a
  // --g-hue per data-g). Repainting background/color/borderColor inline here
  // would beat that stylesheet, since inline always wins over a class.
  document.querySelectorAll('#ev-gender-allow-row .gallow').forEach(function(btn){
    btn.classList.toggle('on',!!evGenderAllowed[btn.getAttribute('data-g')]);
  });
  // Distribute equal % among newly active genders
  var active=Object.keys(evGenderAllowed).filter(function(k){return evGenderAllowed[k];});
  var even=Math.floor(100/active.length);
  active.forEach(function(k,i){evGenderPct[k]=(i===active.length-1)?(100-even*(active.length-1)):even;});
  Object.keys(evGenderAllowed).forEach(function(k){if(!evGenderAllowed[k])evGenderPct[k]=0;});
  renderEvGenderRatio();
  // Update hidden restrict field
  var restrict=active.length>=3?'all':active.sort().join('+');
  var gr=document.getElementById('ev-gender-restrict');if(gr)gr.value=restrict;
}
// `c` is mirrored by the .gallow[data-g=…] --g-hue rules in styles.css (the
// allowed-gender pills). Change one, change the other, or the pill and its
// ratio slider stop agreeing on what colour that gender is.
var _evMeta={female:{l:'♀ Female',c:'#ec4899',cdim:'rgba(236,72,153,0.18)',emoji:'♀'},male:{l:'♂ Male',c:'#2563eb',cdim:'rgba(37,99,235,0.18)',emoji:'♂'},other:{l:'⚧ Other',c:'#8b5cf6',cdim:'rgba(139,92,246,0.18)',emoji:'⚧'}};
var evGenderLock={female:false,male:false,other:false};
function _evCapacity(){var el=document.getElementById('ev-cap');return Math.max(1,Math.min(100,parseInt(el&&el.value)||10));}
// Collapse/expand a Hangouts event-creation filter section (University / Major / Ethnicity / Politics)
function _evFiltToggle(h){var s=(h&&h.closest)?h.closest('.evfilt'):null;if(s)s.classList.toggle('collapsed');}
// Collapse/expand one of the 8 Create Event step cards. Same recipe as
// _evFiltToggle: a class on the container, with CSS hiding everything but the
// header. Deliberately NOT the Settings accordion's max-height + overflow:hidden
// — that caps at 1000px (card 6 is taller) and would clip the date picker popup
// in card 2, which is absolutely positioned to escape its card.
// The handler lives on .ehsec rather than being delegated on #evp-create: the
// .evfilt rows in card 6 are siblings of .ehsec, so their clicks never reach it.
function _ehCardToggle(h){
  var c=(h&&h.closest)?h.closest('.ehcard'):null;if(!c)return;
  var opening=c.classList.contains('collapsed');
  // El paso 8 (Review & Publish) queda BLOQUEADO hasta terminar los 7 anteriores.
  if(opening && c.getAttribute('data-step')==='8'){
    // Marcar como done el paso abierto actual (si es válido) antes de contar.
    document.querySelectorAll('#evp-create .ehcard[data-step]').forEach(function(o){
      var ds=parseInt(o.getAttribute('data-step'),10);
      if(ds>=1&&ds<=7&&!o.classList.contains('collapsed')&&_ehStepValid(o))o.classList.add('done');
    });
    var d17=0;for(var s=1;s<=7;s++){var st=document.querySelector('#evp-create .ehcard[data-step="'+s+'"]');if(st&&st.classList.contains('done'))d17++;}
    if(d17<7){
      _ehUpdateProgress();
      if(typeof ugzAlert==='function')ugzAlert('Completa los 7 pasos anteriores antes de revisar y publicar.');
      else alert('Completa los 7 pasos anteriores primero.');
      return;
    }
  }
  if(opening){
    // Accordion: only one step open at a time. Collapsing the others marks the
    // valid ones as done, so progress advances as you move down the flow.
    document.querySelectorAll('#evp-create .ehcard').forEach(function(o){
      if(o!==c&&!o.classList.contains('collapsed')){
        o.classList.add('collapsed');
        if(_ehStepValid(o))o.classList.add('done');
      }
    });
    c.classList.remove('collapsed');
    c.classList.remove('done'); // it's the step you're on now
  }else{
    c.classList.add('collapsed');
    if(_ehStepValid(c))c.classList.add('done');
  }
  _ehUpdateProgress();
}
function _ehStepValid(c){
  var step=c.getAttribute('data-step');
  if(step==='1'){var n=document.getElementById('ev-nm');return !!(n&&n.value.trim());}
  if(step==='2'){
    var mo=document.getElementById('ev-month'),dy=document.getElementById('ev-day'),yr=document.getElementById('ev-year');
    var hh=document.getElementById('ev-hour'),mm=document.getElementById('ev-min');
    return !!(mo&&mo.value&&dy&&dy.value&&yr&&yr.value&&hh&&hh.value.trim()&&mm&&mm.value.trim());
  }
  if(step==='3'){var a=document.getElementById('ev-addr');return !!(a&&a.value.trim());}
  // Step 4 (Max Spots/Age Restriction/Join Mode) always carries valid hardcoded
  // defaults the instant the DOM renders — nothing a user can leave unset.
  if(step==='4'){return true;}
  // Step 5 (Who Can Join?): toggleGenderAllow() already refuses to let the last
  // remaining gender be deselected, so "at least one gender" is unreachable-false.
  if(step==='5'){return true;}
  // Step 6 (Additional Filters) is genuinely all-optional refinement filters.
  if(step==='6'){return true;}
  // Step 7 requires an actual pick (stock tile, custom upload, or re-selecting the
  // custom photo) — not just the silent auto-default renderEventStockPickerGrid()
  // falls back to before the user has ever touched the grid.
  if(step==='7'){return !!window._evCoverPicked;}
  if(step==='8'){return false;} // el paso 8 solo se completa al picar Publish
  return true;
}
function _ehUpdateProgress(){
  var cards=document.querySelectorAll('#evp-create .ehcard');
  var total=Math.max(1,cards.length);
  var done=document.querySelectorAll('#evp-create .ehcard.done').length;
  var fill=document.getElementById('eh-progress-fill');
  var lbl=document.getElementById('eh-progress-lbl');
  if(fill)fill.style.width=Math.min(100,Math.round(done/total*100))+'%';
  if(lbl)lbl.textContent=done+' of '+total+' done';
  // Bloqueo visual del paso 8 hasta que los 7 anteriores estén completos.
  var step8=document.querySelector('#evp-create .ehcard[data-step="8"]');
  if(step8){
    var d17=0;for(var s=1;s<=7;s++){var st=document.querySelector('#evp-create .ehcard[data-step="'+s+'"]');if(st&&st.classList.contains('done'))d17++;}
    step8.classList.toggle('eh-locked', d17<7);
  }
}
// Open a step card by number and bring it into view. Used by anything that has
// to reach content which may be collapsed.
function _ehOpenStep(n){
  var c=document.querySelector('#evp-create .ehcard[data-step="'+n+'"]');
  if(!c)return null;
  c.classList.remove('collapsed');
  try{c.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){}
  return c;
}
function renderEvGenderRatio(){
  var box=document.getElementById('ev-ratio-rows');if(!box)return;
  var allowed=Object.keys(evGenderAllowed).filter(function(k){return evGenderAllowed[k];});
  if(!allowed.length)return;
  // Normalize percentages so the allowed genders sum to 100
  Object.keys(evGenderAllowed).forEach(function(k){if(!evGenderAllowed[k]){evGenderPct[k]=0;evGenderLock[k]=false;}});
  var sum=allowed.reduce(function(s,k){return s+(parseInt(evGenderPct[k])||0);},0);
  if(!sum||isNaN(sum)){var even=Math.floor(100/allowed.length);allowed.forEach(function(k,i){evGenderPct[k]=(i===allowed.length-1)?(100-even*(allowed.length-1)):even;});}
  // Pins are only offered when all three genders are allowed (see the row below).
  // Any stale lock from a 3-gender state has to be cleared, or an invisible pin
  // would keep capping the sliders with no way to release it.
  var showPins=allowed.length>=3;
  if(!showPins)Object.keys(evGenderLock).forEach(function(k){evGenderLock[k]=false;});
  // Sum of pinned (locked) percentages — unlocked sliders can't push the total past 100
  var lockedSum=allowed.filter(function(a){return evGenderLock[a];}).reduce(function(s,a){return s+(evGenderPct[a]||0);},0);
  // Stacked bar
  var barSegs=allowed.map(function(k){var m=_evMeta[k];return '<div id="seg-'+k+'" style="width:'+(evGenderPct[k]||0)+'%;background:'+m.c+';height:100%;transition:width var(--dur);"></div>';}).join('');
  // One control row per gender: label · slider · % · pin
  var rows=allowed.map(function(k){
    var m=_evMeta[k];var locked=!!evGenderLock[k];var lbl=m.l.split(' ').slice(1).join(' ');
    // An unlocked slider can range only over what the pins leave free
    var slMax=locked?100:Math.max(0,100-lockedSum);
    return '<div style="display:flex;align-items:center;gap:9px;margin-bottom:9px;">'+
      '<div style="display:flex;align-items:center;gap:5px;min-width:82px;"><span style="font-size:var(--fs-sm);font-weight:600;color:'+m.c+';">'+lbl+'</span></div>'+
      '<input type="range" min="0" max="'+slMax+'" step="10" value="'+(evGenderPct[k]||0)+'" id="sl-'+k+'" '+(locked?'disabled':'')+' oninput="evSetGenderPct(\''+k+'\',this.value)" style="flex:1;accent-color:'+m.c+';'+(locked?'opacity:0.45;':'')+'"/>'+
      '<span id="pctlbl-'+k+'" style="font-size:var(--fs-sm);font-weight:600;color:#fff;min-width:38px;text-align:right;">'+(evGenderPct[k]||0)+'%</span>'+
      // Pins only make sense with all three genders in play: with two, pinning
      // one fixes the other by arithmetic, and with one it is always 100%. So
      // below three the button is not rendered at all.
      (showPins?'<button type="button" id="lockbtn-'+k+'" onclick="evToggleLock(\''+k+'\')" title="'+(locked?'Unlock':'Lock this percentage')+'" style="background:transparent;border:none;width:30px;height:30px;cursor:pointer;flex-shrink:0;color:'+(locked?m.c:'rgba(255,255,255,0.45)')+';display:inline-flex;align-items:center;justify-content:center;opacity:'+(locked?'1':'0.7')+';">'+icon('thumbtack',15)+'</button>':'')+
    '</div>';
  }).join('');
  box.innerHTML=
    '<div style="height:14px;border-radius:var(--rad-xs);overflow:hidden;display:flex;background:rgba(255,255,255,0.06);margin-bottom:12px;border:1px solid var(--gbdl);">'+barSegs+'</div>'+
    rows+
    '<div style="font-size:var(--fs-2xs);color:var(--fg3);margin-top:2px;">Drag to set each ratio. Tap the pin to lock a percentage so it stays put while you adjust the others.</div>';
  if(typeof updateInviteFriends==='function'&&_evFriendsOn)updateInviteFriends(_evFriendsPct);
}
function evSetGenderPct(k,val){
  val=parseInt(val);if(isNaN(val))val=0;val=Math.round(val/10)*10;val=Math.max(0,Math.min(100,val));
  var allowed=Object.keys(evGenderAllowed).filter(function(a){return evGenderAllowed[a];});
  if(allowed.length===1){evGenderPct[k]=100;_evApplyRatioUI(k);return;}
  var lockedSum=allowed.filter(function(a){return a!==k&&evGenderLock[a];}).reduce(function(s,a){return s+(evGenderPct[a]||0);},0);
  var unlocked=allowed.filter(function(a){return a!==k&&!evGenderLock[a];});
  if(!unlocked.length){evGenderPct[k]=Math.max(0,100-lockedSum);_evApplyRatioUI(k);return;}
  var maxK=100-lockedSum;if(val>maxK)val=maxK;
  evGenderPct[k]=val;
  var remain=100-val-lockedSum;
  var curSum=unlocked.reduce(function(s,a){return s+(evGenderPct[a]||0);},0);
  var acc=0;
  unlocked.forEach(function(a,i){
    var v;
    if(i===unlocked.length-1)v=remain-acc;
    else if(curSum<=0)v=Math.floor(remain/unlocked.length);
    else v=Math.round(remain*(evGenderPct[a]||0)/curSum);
    v=Math.max(0,v);evGenderPct[a]=v;acc+=v;
  });
  _evApplyRatioUI(k);
}
function _evApplyRatioUI(activeKey){
  Object.keys(evGenderAllowed).filter(function(a){return evGenderAllowed[a];}).forEach(function(k){
    var seg=document.getElementById('seg-'+k);if(seg)seg.style.width=(evGenderPct[k]||0)+'%';
    var lbl=document.getElementById('pctlbl-'+k);if(lbl)lbl.textContent=(evGenderPct[k]||0)+'%';
    var sl=document.getElementById('sl-'+k);if(sl&&k!==activeKey)sl.value=evGenderPct[k]||0;
  });
}
// ── INVITE FRIENDS PORTION (yellow slider, 0–40% in 10% steps) ──
var _evFriendsOn=false,_evFriendsPct=40;
function toggleInviteFriends(){
  _evFriendsOn=!_evFriendsOn;
  var sw=document.getElementById('ev-friends-sw');if(sw)sw.classList.toggle('on',_evFriendsOn);
  var p=document.getElementById('ev-friends-portion');if(p)p.style.display=_evFriendsOn?'block':'none';
  if(_evFriendsOn)updateInviteFriends(_evFriendsPct);
}
function updateInviteFriends(v){
  v=parseInt(v);if(isNaN(v))v=0;v=Math.round(v/10)*10;v=Math.max(0,Math.min(40,v));
  _evFriendsPct=v;
  var cap=(typeof _evCapacity==='function')?_evCapacity():10;
  var count=Math.round(cap*v/100);
  var set=function(id,t){var el=document.getElementById(id);if(el)el.textContent=t;};
  set('ev-friends-pct',v);set('ev-friends-echo',v+'%');set('ev-friends-cap',cap);set('ev-friends-count',count);
  var sl=document.getElementById('ev-friends-sl');if(sl&&parseInt(sl.value)!==v)sl.value=v;
}
function evToggleLock(k){
  var allowed=Object.keys(evGenderAllowed).filter(function(a){return evGenderAllowed[a];});
  if(!evGenderLock[k]){
    var lockedCount=allowed.filter(function(a){return evGenderLock[a];}).length;
    if(lockedCount+1>=allowed.length){alert('Keep at least one gender unlocked so the ratio can still be adjusted.');return;}
  }
  evGenderLock[k]=!evGenderLock[k];
  renderEvGenderRatio();
}
// Backwards-compat stubs (legacy hooks)
function handleInviteChip(chip){
  var chips=document.querySelectorAll('#ev-invite-chips .yr-chip');
  var isAll=chip.getAttribute('data-inv')==='all';
  if(isAll){
    chip.classList.add('on');
    chips.forEach(function(c){if(c!==chip)c.classList.remove('on');});
  }else{
    chip.classList.toggle('on');
    // Deselect All Students when any class year is selected
    var allChip=document.querySelector('#ev-invite-chips .yr-chip[data-inv="all"]');if(allChip)allChip.classList.remove('on');
    // If no year chips on, fall back to All Students
    var anyYearOn=Array.from(chips).some(function(c){return c.getAttribute('data-inv')!=='all'&&c.classList.contains('on');});
    if(!anyYearOn&&allChip)allChip.classList.add('on');
  }
}

