function _campusPillBtnHtml(t, isSelected) {
  var col = t.col;
  var style;
  if (isSelected) {
    style = 'background:rgba(255,255,255,0.06);color:#fff;text-shadow:0 0 8px #fff, 0 0 12px ' + col + ';border:1.5px solid ' + col + ';' + col + '66, inset 0 0 8px ' + col + '33;';
  } else {
    style = 'background:transparent;color:' + col + ';text-shadow:0 0 8px ' + col + 'b3;border:1px solid rgba(255,255,255,0.08);box-shadow:none;';
  }
  return '<button type="button" class="campus-cat-pill ' + (isSelected ? 'active' : '') + '" data-catid="' + t.id + '" onclick="filterCampusCategory(\'' + t.id + '\')" style="' + style + 'padding:8px 14px;border-radius:var(--rad-lg);font-family:var(--font);font-size:var(--fs-sm);font-weight:600;cursor:pointer;white-space:nowrap;display:inline-flex;align-items:center;gap:7px;transition:all 0.2s ease;">' +
    '<span style="display:inline-flex;align-items:center;justify-content:center;color:' + col + ';">' + t.svg + '</span>' +
    '<span>' + t.lbl + '</span>' +
  '</button>';
}

function filterCampusCategory(cat){
  window._campusCurrentCat=cat;
  var bar=document.getElementById('campus-cat-bar');
  if(bar){
    var uAcr=(typeof uni!=='undefined'&&uni&&uni.acronym)?uni.acronym:((typeof userPro!=='undefined'&&userPro&&userPro.uni)?userPro.uni:'UTNC');
    if(!uAcr||uAcr==='University')uAcr='UTNC';
    _CAMPUS_TABS_CFG[3].lbl = uAcr;
    var btns=bar.querySelectorAll('.campus-cat-pill');
    btns.forEach(function(btn){
      var cid=btn.getAttribute('data-catid');
      var isTarget=(cid===cat);
      var cfg=_CAMPUS_TABS_CFG.find(function(c){return c.id===cid;});
      if(cfg){
        btn.classList.toggle('active',isTarget);
        var col=cfg.col;
        if(isTarget){
          btn.style.cssText='background:rgba(255,255,255,0.06);color:#fff;text-shadow:0 0 8px #fff, 0 0 12px '+col+';border:1.5px solid '+col+';'+col+'66, inset 0 0 8px '+col+'33;padding:8px 14px;border-radius:var(--rad-lg);font-family:var(--font);font-size:var(--fs-sm);font-weight:800;cursor:pointer;white-space:nowrap;display:inline-flex;align-items:center;gap:7px;transition:all 0.2s ease;';
        } else {
          btn.style.cssText='background:transparent;color:'+col+';text-shadow:0 0 8px '+col+'b3;border:1px solid rgba(255,255,255,0.08);box-shadow:none;padding:8px 14px;border-radius:var(--rad-lg);font-family:var(--font);font-size:var(--fs-sm);font-weight:800;cursor:pointer;white-space:nowrap;display:inline-flex;align-items:center;gap:7px;transition:all 0.2s ease;';
        }
      }
    });
  }
  var blocks=['events','marketplace','myu','trending'];
  blocks.forEach(function(b){
    var el=document.getElementById('campus-block-'+b);
    if(el){
      if(cat==='all'){
        el.style.display='block';
      } else if(b===cat){
        el.style.display='block';
      } else {
        el.style.display='none';
      }
    }
  });
}

