/* ── STUBHUB & MARKETPLACE HELPER METHODS ── */
function _renderMkSubpill(catId, label, col, isDefault) {
  var isSel = (window._activeMarketplaceSubcat === catId);
  var style = isSel ?
    'background:rgba(255,255,255,0.08);color:#fff;border:1.5px solid '+col+';'+col+'55;' :
    'background:rgba(255,255,255,0.04);color:var(--fg2);border:1px solid rgba(255,255,255,0.1);';
  return '<button type="button" class="mk-subpill" onclick="filterMarketplaceSubcat(\''+catId+'\')" style="'+style+'">'+label+'</button>';
}

function filterMarketplaceSubcat(subcat) {
  window._activeMarketplaceSubcat = subcat;
  var wrap = document.getElementById('fb-marketplace-grid-wrap');
  if (wrap) wrap.innerHTML = renderCampusMarketplaceGrid();
  // Also refresh subpill styles
  var block = document.getElementById('campus-block-marketplace');
  if (block) {
    var subpills = block.querySelectorAll('.mk-subpill');
    subpills.forEach(function(pill) {
      var txt = pill.textContent.trim();
      var isTarget = (subcat === 'All' && txt.includes('Todos')) || txt.includes(subcat);
      if (isTarget) {
        pill.style.cssText = 'background:rgba(255,255,255,0.08);color:#fff;border:1.5px solid #22c55e;padding:7px 13px;border-radius:var(--rad-md);font-size:var(--fs-xs);font-weight:800;cursor:pointer;white-space:nowrap;display:inline-flex;align-items:center;gap:6px;transition:all 0.2s ease;flex-shrink:0;';
      } else {
        pill.style.cssText = 'background:rgba(255,255,255,0.04);color:var(--fg2);border:1px solid rgba(255,255,255,0.1);padding:7px 13px;border-radius:var(--rad-md);font-size:var(--fs-xs);font-weight:800;cursor:pointer;white-space:nowrap;display:inline-flex;align-items:center;gap:6px;transition:all 0.2s ease;flex-shrink:0;';
      }
    });
  }
}

