function submitCreateTicket(e) {
  e.preventDefault();
  var title = document.getElementById('tkt-inp-title').value.trim();
  var date = document.getElementById('tkt-inp-date').value.trim();
  var venue = document.getElementById('tkt-inp-venue').value.trim();
  var count = parseInt(document.getElementById('tkt-inp-count').value) || 1;
  var row = document.getElementById('tkt-inp-row').value.trim() || 'Fila 1';
  var price = parseInt(document.getElementById('tkt-inp-price').value) || 350;
  var section = document.getElementById('tkt-inp-section').value.trim() || 'Zona General';
  var notes = document.getElementById('tkt-inp-notes').value.trim() || 'Boletos disponibles para entrega en campus.';

  var uName = (typeof userPro !== 'undefined' && userPro.name) ? userPro.name : 'Tu Usuario';
  var uHandle = (typeof userPro !== 'undefined' && userPro.handle) ? userPro.handle : '@usuario';
  var uAcr = (typeof uni !== 'undefined' && uni && uni.acronym) ? uni.acronym : 'UTNC';

  var newEvt = {
    id: 'evt-' + Date.now(),
    title: title,
    date: date,
    venue: venue,
    img: 'images/unidad-deportiva-uadec.jpg',
    badge: 'NUEVA PUBLICACIÓN',
    price: price,
    seller: {
      name: uName,
      handle: uHandle,
      avatar: uName.charAt(0).toUpperCase(),
      uni: uAcr,
      verified: true,
      rating: '5.0 ★ (Nueva publicación)',
      ticketsCount: count,
      section: section,
      row: row,
      seats: 'Asientos ' + count,
      notes: notes
    }
  };

  window._campusEvents.unshift(newEvt);
  document.getElementById('create-ticket-modal').classList.remove('open');
  e.target.reset();

  var container = document.getElementById('stubhub-events-container');
  if (container) container.innerHTML = renderCampusEventsList();

  if (typeof showToast === 'function') {
    showToast('🎉 ¡Boletos publicados en StubHub Campus exitosamente!');
  } else {
    alert('¡Boletos publicados exitosamente!');
  }
}

