// Admirers (people who liked you) + Secret Admirers (people who viewed your
// profile) are two different tables, so neither is a superset of the other.
// Concatenate and dedupe by user id, tagging where each person came from.
// NOTE: profileView rows carry no `gender`, so the crushGenderPref filter that
// the likes list uses can't be applied evenly here — it is deliberately not
// applied to the merged pool rather than inventing a value the backend never
// sent.
function _mergedAdmirersPool(){
  var likes = window._admirersData || [];
  var views = window._profileViewsData || [];
  var byId = {}, out = [];
  var push = function(p, src){
    if(!p) return;
    var k = String(p.id || p.handle || p.name || '').toLowerCase();
    if(!k) return;
    if(byId[k]){ byId[k]._src = 'both'; return; }
    var copy = {}; for(var f in p){ if(p.hasOwnProperty(f)) copy[f] = p[f]; }
    copy._src = src;
    byId[k] = copy; out.push(copy);
  };
  likes.forEach(function(p){ push(p, 'like'); });
  views.forEach(function(p){ push(p, 'view'); });
  return out;
}

// Small badge telling you why this person is on the list.
function _admirerSrcTag(src){
  if(src === 'both') return '';
  if(src === 'like') return '<span style="font-size:var(--fs-2xs);font-weight:700;color:#ec4899;">te dio like</span>';
  return '<span style="font-size:var(--fs-2xs);font-weight:700;color:#fb923c;">vio tu perfil</span>';
}

// Admirers unlock by inviting real friends (server-verified referredCount —
// see _refLoad() below), not by an A+ subscription. Front-loaded ladder: easy
// at first, gradually more friends needed per extra admirer, then a flat +5
// per unlock forever after so there's always a next goal.
var _ADMIRER_UNLOCK_LADDER=[3,5,8,12,17];
function _admirerInvitedCount(){
  return (typeof _userReferralData!=='undefined'&&_userReferralData&&typeof _userReferralData.referredCount!=='undefined')?_userReferralData.referredCount:0;
}
function _admirerUnlockedCount(poolLen){
  var invited=_admirerInvitedCount();
  var n=0;
  for(var i=0;i<_ADMIRER_UNLOCK_LADDER.length;i++){ if(invited>=_ADMIRER_UNLOCK_LADDER[i]) n=i+1; }
  var last=_ADMIRER_UNLOCK_LADDER[_ADMIRER_UNLOCK_LADDER.length-1];
  if(invited>last) n+=Math.floor((invited-last)/5);
  return Math.min(n,poolLen);
}
function _admirerNextThreshold(){
  var invited=_admirerInvitedCount();
  for(var i=0;i<_ADMIRER_UNLOCK_LADDER.length;i++){ if(invited<_ADMIRER_UNLOCK_LADDER[i]) return _ADMIRER_UNLOCK_LADDER[i]; }
  var last=_ADMIRER_UNLOCK_LADDER[_ADMIRER_UNLOCK_LADDER.length-1];
  var over=invited-last;
  return last+(Math.floor(over/5)+1)*5;
}
// Tapping a locked admirer opens the invite prompt below instead of a paywall.
function _admirerPaywall(){
  if(typeof _refLoad==='function')try{_refLoad();}catch(e){}
  _openAdmirerInviteModal();
}
function _openAdmirerInviteModal(){
  var isEs=window.currentLang==='es';
  var invited=_admirerInvitedCount();
  var next=_admirerNextThreshold();
  var toGo=Math.max(0,next-invited);
  var pct=Math.min(100,Math.max(0,Math.round(invited/next*100)));
  var m=document.getElementById('admirer-invite-modal');if(m)m.remove();
  m=document.createElement('div');m.id='admirer-invite-modal';m.className='mov open';m.style.zIndex='9999';
  m.innerHTML='<div class="msheet" style="max-width:370px;"><div class="mhnd"></div>'+
    '<div style="text-align:center;margin-bottom:12px;">'+
      '<div style="font-size:38px;">🔒</div>'+
      '<div style="font-size:var(--fs-xl);font-weight:900;color:#fff;">'+(isEs?'Invita amigos para desbloquear':'Invite friends to unlock')+'</div>'+
      '<div class="t-sub">'+(isEs?'Cada amigo real que se una con tu link desbloquea admiradores nuevos.':'Every real friend who joins with your link unlocks more admirers.')+'</div>'+
    '</div>'+
    '<div style="background:rgba(255,255,255,0.04);border:1px solid var(--gbdl);border-radius:var(--rad-sm);padding:13px;margin-bottom:14px;">'+
      '<div style="display:flex;justify-content:space-between;font-size:var(--fs-xs);font-weight:600;color:var(--fg2);margin-bottom:5px;"><span>'+invited+'/'+next+' '+(isEs?'invitados':'invited')+'</span><span style="color:#4ade80;">'+(isEs?(toGo+' más para desbloquear'):(toGo+' more to unlock'))+'</span></div>'+
      '<div class="bar-t"><div class="bar-f" style="background:var(--p);width:'+pct+'%"></div></div>'+
    '</div>'+
    '<button class="gbtn" style="background:var(--p);margin-bottom:8px;" onclick="_inviteShare()">📲 '+(isEs?'Compartir mi link':'Share invite link')+'</button>'+
    '<button class="gbtn-ghost" onclick="document.getElementById(\'admirer-invite-modal\').remove()">'+(isEs?'Cerrar':'Close')+'</button>'+
  '</div>';
  document.body.appendChild(m);
}

function _likedSawHtml(pool,unlockedN){
  var n = pool.length;
  unlockedN = Math.max(0, Math.min(n, unlockedN||0));
  var unlimited = unlockedN >= n && n > 0;
  var hatGlassesSvg = '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" class="lucide lucide-hat-glasses-icon lucide-hat-glasses" style="display:inline-block;vertical-align:middle;"><path d="M14 18a2 2 0 0 0-4 0"/><path d="m19 11-2.11-6.657a2 2 0 0 0-2.752-1.148l-1.276.61A2 2 0 0 1 12 4H8.5a2 2 0 0 0-1.925 1.456L5 11"/><path d="M2 11h20"/><circle cx="17" cy="18" r="3"/><circle cx="7" cy="18" r="3"/></svg>';

  // Split the count by where each person came from. _mergedAdmirersPool already
  // tags every row with _src ('like' | 'view' | 'both'), so this is free.
  var nLikes=0,nViews=0;
  pool.forEach(function(p){
    if(p._src==='both'){nLikes++;nViews++;}
    else if(p._src==='like')nLikes++;
    else nViews++;
  });

  // Redrawn: the old banner was a solid maroon slab with an orange button, the
  // last block in the app still built that way. Now it follows the house
  // language — black card, the wine hue carried by a lit underline, the count as
  // the loud element, and one full-width CTA on the shared _gradSkin recipe.
  var isEs = window.currentLang === 'es';
  var _cs = getComputedStyle(document.documentElement);
  var _uc = ((_cs.getPropertyValue('--uni-accent')||'').trim()) || ((_cs.getPropertyValue('--p')||'').trim()) || '#dc2626';
  var _uc2 = ((_cs.getPropertyValue('--p2')||'').trim()) || '#3d7bff';
  var _wine = _uc; // accent now follows the university, not a fixed red
  var _cta = (typeof _gradSkin === 'function')
    ? _gradSkin(_uc, true, { radius: 'var(--rad-pill)', dim: 82 })
    : 'background:linear-gradient(135deg,'+_uc+','+_uc2+');border:none;border-radius:var(--rad-pill);color:#fff;';
  var sub = unlimited
    ? (isEs?'Estas son las personas que te tienen en la mira.':'These are the people who have their eye on you.')
    : (isEs?'Descubre quién te está observando en secreto.':'See who\'s secretly checking you out.');
  var breakdown = '';
  var banner='<div style="position:relative;overflow:hidden;background:#000;border:1.5px solid color-mix(in srgb, var(--uni-accent,var(--p)) 40%, transparent);border-radius:var(--rad-xl);padding:16px 18px 18px;margin:0 var(--s) 14px;">'+
    // The lit 2px line every other section in the app uses to carry its hue
    '<div style="position:absolute;left:0;right:0;bottom:0;height:2px;background:linear-gradient(90deg,'+_uc+','+_uc2+');box-shadow:0 0 10px color-mix(in srgb, var(--uni-accent,var(--p)) 80%, transparent);"></div>'+
    '<div style="display:flex;align-items:center;gap:13px;">'+
      '<span style="color:'+_wine+';flex-shrink:0;display:flex;">'+hatGlassesSvg+'</span>'+
      '<div style="flex:1;min-width:0;">'+
        '<div style="display:flex;align-items:baseline;gap:7px;">'+
          '<span style="font-size:var(--fs-2xl);font-weight:900;color:'+_wine+';line-height:1;letter-spacing:-1.2px;">'+(n>0?n:'?')+'</span>'+
          '<span style="font-size:var(--fs-base);font-weight:800;color:#fff;letter-spacing:-0.2px;">Secret Admirers</span>'+
        '</div>'+
        '<div style="font-size:var(--fs-xs);color:var(--fg2);margin-top:5px;font-weight:500;line-height:1.4;">'+sub+'</div>'+
      '</div>'+
    '</div>'+
    breakdown+
    // Once every card is unlocked (enough friends invited) there's nothing
    // left to invite for here, so the CTA disappears.
    (unlimited?'':'<button onclick="_admirerPaywall()" style="'+_cta+'width:100%;margin-top:14px;padding:12px 14px;font-family:var(--font);font-size:var(--fs-sm);font-weight:800;letter-spacing:0.2px;cursor:pointer;">'+(isEs?'Invita amigos para ver quién es':'Invite friends to see who it is')+'</button>')+
  '</div>';

  if(!pool.length){
    var _emptyMsg='<div style="text-align:center;padding:14px var(--s) 6px;color:var(--fg2);font-size:var(--fs-sm);font-weight:500;">'+(isEs?'Aún nadie… por ahora':'No one yet… for now')+'<br><span style="font-size:var(--fs-xs);color:color-mix(in srgb, var(--uni-accent,var(--p)) 45%, #fff);">'+(isEs?'Mantén tu perfil activo para atraer miradas':'Keep your profile fresh to draw more eyes')+'</span></div>';
    return banner+_emptyMsg;
  }

  // How many cards are unlocked, per the invite ladder computed by the caller.
  var freeReveals = unlockedN;
  var uniObjs=Object.keys(UNI).map(function(d){return UNI[d];}).filter(function(u){return u&&u.name;});

  var cards=pool.map(function(p, idx){
    var unlocked = idx < freeReveals;
    var photoUrl = _getPhotoUrl(p.photos ? p.photos[0] : null);
    var cover = photoUrl ? 'background-image:url('+photoUrl+');background-size:cover;background-position:center;' : 'background:linear-gradient(160deg,'+(p.bg||'#4d84ff')+',rgba(0,0,0,0.55));';
    var safe=p.name.replace(/'/g,"");
    var timeText = p.timeAgo || (typeof _agoEs==='function' ? _agoEs(p.createdAt) : '') || 'hace 5m';
    var handleArg = p.handle ? '\'' + p.handle + '\'' : 'null';

    if(unlocked){
      var h=_strHash((p.name||'')+'saw');
      var unRaw=(p.uni&&(p.uni.acronym||p.uni.name||p.uni))||(uniObjs.length?(uniObjs[h%uniObjs.length].acronym||uniObjs[h%uniObjs.length].name):'UANE');
      var un=_getUniAcronym(unRaw);
      return '<div onclick="viewUserUnicrush('+handleArg+',\''+safe+'\',\''+(p.bg||'')+'\',\'\')" style="cursor:pointer;border-radius:var(--rad-lg);overflow:hidden;border:1.5px solid rgba(61,123,255,0.5);position:relative;height:216px;'+cover+';">'+
        '<div style="position:absolute;top:8px;right:8px;font-size:var(--fs-2xs);font-weight:700;color:#a5f3fc;padding:3px 7px;border-radius:var(--rad-sm);background:rgba(0,0,0,0.85);border:1px solid rgba(6,182,212,0.5);z-index:2;">'+timeText+'</div>'+
        '<div style="position:absolute;left:0;right:0;bottom:0;padding:44px 10px 11px;background:linear-gradient(to top, rgba(0,0,0,0.98) 0%, rgba(0,0,0,0.72) 62%, transparent 100%);">'+
          '<div style="font-size:var(--fs-base);font-weight:900;color:#fff;line-height:1.15;letter-spacing:-0.2px;text-shadow:0 2px 8px rgba(0,0,0,0.9);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+p.name+' '+(p.age||'')+'</div>'+
          '<div style="display:flex;align-items:center;gap:4px;margin-top:5px;flex-wrap:wrap;">'+
            '<span style="font-size:var(--fs-2xs);font-weight:700;color:#d6e4ff;background:rgba(61,123,255,0.28);border:1px solid rgba(61,123,255,0.65);border-radius:var(--rad-xs);padding:2px 6px;letter-spacing:0.4px;">🏛️ '+un+'</span>'+
            (p.major?'<span style="font-size:var(--fs-2xs);font-weight:700;color:#fde68a;background:rgba(245,158,11,0.22);border:1px solid rgba(245,158,11,0.6);border-radius:var(--rad-xs);padding:2px 6px;letter-spacing:0.4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;">🎓 '+p.major+'</span>':'')+
          '</div>'+
          '<div style="margin-top:5px;">'+_admirerSrcTag(p._src)+'</div>'+
        '</div>'+
      '</div>';
    }

    // The tap opens the invite-to-unlock modal, so the card says so.
    return '<div onclick="_admirerPaywall()" class="fomo-locked-card" style="cursor:pointer;border-radius:var(--rad-lg);overflow:hidden;border:1.5px solid color-mix(in srgb, var(--uni-accent,var(--p)) 65%, transparent);background:#0b0b0e;position:relative;height:216px;transition:transform var(--dur) ease, box-shadow var(--dur) ease;">'+
      '<div style="position:absolute;top:8px;right:8px;font-size:var(--fs-2xs);font-weight:700;color:color-mix(in srgb, var(--uni-accent,var(--p)) 45%, #fff);padding:3px 7px;border-radius:var(--rad-sm);background:rgba(0,0,0,0.85);border:1px solid color-mix(in srgb, var(--uni-accent,var(--p)) 55%, transparent);z-index:2;">'+timeText+'</div>'+
      // 14px, not 18px: at 18px the photo is a flat smear and the card stops
      // suggesting there is a real person behind it.
      '<div style="height:100%;'+cover+'filter:blur(14px) saturate(170%);transform:scale(1.15);"></div>'+
      '<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(circle at center, color-mix(in srgb, var(--uni-accent,var(--p)) 22%, transparent) 0%, rgba(0,0,0,0.82) 100%);z-index:2;">'+
        '<div style="width:48px;height:48px;border-radius:50%;background:var(--uni-accent,var(--p));display:flex;align-items:center;justify-content:center;color:#fff;border:2px solid #ffffff;box-shadow:0 0 18px color-mix(in srgb, var(--uni-accent,var(--p)) 60%, transparent);animation:fomoPulse 2s infinite ease-in-out;">'+icon('lock',22)+'</div>'+
      '</div>'+
      '<div style="position:absolute;left:0;right:0;bottom:0;padding:26px 10px 10px;background:linear-gradient(to top, rgba(0,0,0,0.98) 0%, rgba(0,0,0,0.7) 70%, transparent 100%);z-index:3;">'+
        '<div style="background:linear-gradient(135deg,'+_uc+','+_uc2+');border:none;color:#ffffff;font-size:var(--fs-2xs);font-weight:700;text-align:center;padding:6px;border-radius:var(--rad-sm);letter-spacing:0.4px;">'+icon('lock',14)+' '+(isEs?'Invitar para ver':'Invite to unlock')+'</div>'+
      '</div>'+
    '</div>';
  }).join('');
  return banner+'<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:0 var(--s) 14px;">'+cards+'</div>';
}

// No callers since the Global/University/Country rank cards were removed. Kept
// alongside loadUserStats for the same reason.
function _getUniCountryFlagInfo(uniObj) {
  var u = uniObj || (typeof _getCurrentUni === 'function' ? _getCurrentUni() : null) || (typeof uni !== 'undefined' ? uni : null);
  var domain = (u && u.domain) ? u.domain : '';

  if (!domain && u && (u.name || u.acronym) && typeof UNI !== 'undefined') {
    for (var d in UNI) {
      if (UNI[d] && (UNI[d].name === u.name || UNI[d].acronym === u.acronym || UNI[d].name === u.acronym)) {
        domain = d;
        break;
      }
    }
  }

  if (!domain && typeof userPro !== 'undefined' && userPro && userPro.email) {
    domain = userPro.email.split('@')[1] || '';
  }
  if (!domain && typeof _ob4State !== 'undefined' && _ob4State && _ob4State.email) {
    domain = _ob4State.email.split('@')[1] || '';
  }
  if (!domain && typeof _selectedUniDomain !== 'undefined' && _selectedUniDomain) {
    domain = _selectedUniDomain;
  }

  var cCode = 'US';
  domain = domain.toLowerCase();

  if (/\.mx$/.test(domain)) cCode = 'MX';
  else if (/\.ca$/.test(domain)) cCode = 'CA';
  else if (/\.co$/.test(domain)) cCode = 'CO';
  else if (/\.es$/.test(domain)) cCode = 'ES';
  else if (/\.ar$/.test(domain)) cCode = 'AR';
  else if (/\.cl$/.test(domain)) cCode = 'CL';
  else if (/\.pe$/.test(domain)) cCode = 'PE';
  else if (domain) cCode = 'US';
  else if (u) {
    var uStr = String(u.country || u.countryCode || u.name || u.acronym || '').toLowerCase();
    if (uStr.indexOf('uane') !== -1 || uStr.indexOf('utnc') !== -1 || uStr.indexOf('uanl') !== -1 || uStr.indexOf('unam') !== -1 || uStr.indexOf('tec') !== -1 || uStr.indexOf('itesm') !== -1 || uStr.indexOf('mexico') !== -1 || uStr.indexOf('méxico') !== -1) {
      cCode = 'MX';
    } else if (uStr.indexOf('canada') !== -1 || uStr.indexOf('canadá') !== -1) {
      cCode = 'CA';
    } else {
      cCode = 'US';
    }
  }

  var code = 'us';
  var countryName = 'USA';

  if (cCode === 'MX') { code = 'mx'; countryName = 'México'; }
  else if (cCode === 'CA') { code = 'ca'; countryName = 'Canadá'; }
  else if (cCode === 'CO') { code = 'co'; countryName = 'Colombia'; }
  else if (cCode === 'ES') { code = 'es'; countryName = 'España'; }
  else if (cCode === 'AR') { code = 'ar'; countryName = 'Argentina'; }
  else if (cCode === 'CL') { code = 'cl'; countryName = 'Chile'; }
  else if (cCode === 'PE') { code = 'pe'; countryName = 'Perú'; }

  var flagHtml = '<img src="https://flagcdn.com/w40/' + code + '.png" alt="' + countryName + '" style="width:18px;height:13px;border-radius:3px;object-fit:cover;display:inline-block;vertical-align:middle;box-shadow:var(--el-1);margin-right:2px;" />';

  return { code: code, flagHtml: flagHtml, name: countryName };
}

// No callers since the Discover stats bar was removed. Kept on purpose: this is
// the only place the /stats endpoint and its response shape are still recorded.
async function loadUserStats() {
  if (typeof apiClient === 'undefined') return;
  try {
    const stats = await apiClient.getStats();
    if (stats) {
      window.userStatsData = stats;
      var panel = document.getElementById('cpanel-liked');
      if (panel && (panel.classList.contains('active') || panel.style.display !== 'none') && typeof _renderLikedYouReveal === 'function') {
        _renderLikedYouReveal(typeof curPlan !== 'undefined' && curPlan === 'aplus');
      }
    }
  } catch (err) {
    console.warn("Could not fetch user stats from DB:", err);
  }
}


// Detach #cpanel-foryou from wherever it is and hand it back to
// #discover-panels, hidden. Returns the element so the caller can re-attach it.
// Without this, overwriting #cpanel-liked's innerHTML while For you is showing
// would delete the node for good, and switching back would render into nothing.
function _discoverParkForYou(){
  var fy=document.getElementById('cpanel-foryou');
  if(!fy)return null;
  var home=document.getElementById('discover-panels');
  if(home&&fy.parentElement!==home)home.appendChild(fy);
  fy.classList.remove('active');
  fy.style.display='none';
  return fy;
}
function _renderLikedYouReveal(unlimited){
  var panel=document.getElementById('cpanel-liked');if(!panel)return;
  var subTab=window._likedSubTab || localStorage.getItem('ugz_last_liked_subtab') || sessionStorage.getItem('ugz_last_liked_subtab') || 'foryou';
  if(subTab==='liked'||subTab==='admirers')subTab='saw'; // merged
  window._likedSubTab = subTab;

  // The For you sub-tab reuses the whole #cpanel-foryou element (season banner,
  // Campus Wrapped, senior send-off, Best Picks / New Picks) rather than
  // duplicating its markup, so every existing render function keeps working.
  // It is parked back in #discover-panels first, without exception: while it sits
  // inside this panel, the `panel.innerHTML = …` below would destroy it and the
  // node could never come back.
  var _fy=_discoverParkForYou();
  var subRow=_likedSubRow();
  if(subTab==='foryou'){
    panel.innerHTML=subRow;
    if(_fy){_fy.style.display='block';_fy.classList.add('active');panel.appendChild(_fy);}
    // Exactly the two the old top-level 'foryou' hook ran. Campus Wrapped and
    // the senior send-off are left alone on purpose: renderDiscover() blanks
    // them on entering Campus, so rendering them here would quietly switch on a
    // banner that was deliberately suppressed.
    ['renderSeasonBanner','renderSpotlight'].forEach(function(fn){
      try{if(typeof window[fn]==='function')window[fn]();}catch(e){}
    });
    return;
  }

  if(subTab==='likes'){
    if (typeof apiClient !== 'undefined' && (!window._sentLikesData || Date.now() - (window._lastSentLikesFetch || 0) > 5000)) {
      window._lastSentLikesFetch = Date.now();
      loadSentLikes();
    }
    var likesPool = window._sentLikesData;
    panel.innerHTML = subRow + _getSentLikesHtml(likesPool);
    return;
  }

  // 'saw' (Admirers), and the fallback for any other value: an unrecognised
  // sub-tab left in localStorage used to fall through to a dead branch below and
  // paint an empty panel.
  // Merged tab: people who liked you (swipe table) AND people who opened your
  // profile (profileView table). Two different endpoints, so both are loaded
  // and the results are concatenated + deduped by user id.
  if (typeof apiClient !== 'undefined' && (!window._profileViewsData || Date.now() - (window._lastViewsFetch || 0) > 5000)) {
    window._lastViewsFetch = Date.now();
    loadProfileViews();
  }
  if (typeof apiClient !== 'undefined' && (!window._admirersData || Date.now() - (window._lastAdmirersFetch || 0) > 5000)) {
    window._lastAdmirersFetch = Date.now();
    loadAdmirers();
  }
  if(typeof _refLoad==='function')try{_refLoad();}catch(e){}
  var _pool=_mergedAdmirersPool();
  panel.innerHTML = subRow + _likedSawHtml(_pool, (typeof _admirerUnlockedCount==='function')?_admirerUnlockedCount(_pool.length):0);
}
function swipe(dir){
  var card=document.getElementById('crush-card');if(!card||card.style.display==='none')return;
  // Free users get a limited number of likes per day
  if((dir==='like'||dir==='maybe')&&typeof _consumeLike==='function'&&!_consumeLike()){
    var cap=(typeof _effLikeCap==='function')?_effLikeCap():MAX_FREE_LIKES;
    var likeCapMsg=window.PLANS_ENABLED?('You\'ve used your '+cap+' likes for today!\n\nInvite friends for +3 likes/day each, or upgrade to A+ Student for unlimited. Open invite menu?\n\n(Cancel = see Plans)'):('You\'ve used your '+cap+' likes for today!\n\nInvite friends for +3 likes/day each. Open invite menu?');
    if(confirm(likeCapMsg)){if(typeof openReferral==='function')openReferral();}else{sw('premium','Plans');}
    return;
  }
  
  // Trigger Swipe Engine V2 programmatic animation
  SwipeEngineV2.swipe(dir);
}
var goBackUsedThisWeek=0;
var _goBackWeekStart=Date.now();
var _leftSwipeStack=[];
