    if(goBackUsedThisWeek>=2){alert(window.PLANS_ENABLED?'You\'ve used your 2 free go-backs this week.\n\nUpgrade to A+ Student for unlimited!':'You\'ve used your 2 free go-backs this week.');sw('premium','Plans');return;}
    goBackUsedThisWeek++;
