// ── Quick like / pass for the For-You cards (Today's Picks, Most Compatible) ──
function _findProfileByName(name){if(typeof crushDataAll==='undefined'||!crushDataAll)return null;for(var i=0;i<crushDataAll.length;i++){if(crushDataAll[i].name===name)return crushDataAll[i];}return null;}
function _addSentLikeCard(p){
  if(!p||typeof crushData==='undefined')return;
  var idx=crushData.indexOf(p);if(idx<0)return;// only profiles in the active deck can be reopened
  var sl=document.getElementById('sent-likes-list');if(!sl)return;
  if(sl.querySelector('[data-profile-idx="'+idx+'"]'))return;
  var empt=sl.querySelector('[data-empty="1"]');if(empt)empt.remove();
  var likeId='sl_'+Date.now()+'_'+Math.random().toString(36).slice(2,6);
  var d=document.createElement('div');d.id=likeId;d.dataset.profileIdx=idx;
  d.style.cssText='border-radius:var(--rad-md);overflow:hidden;background:rgba(255,255,255,0.06);border:1px solid var(--gbdl);cursor:pointer;transition:transform var(--dur), background var(--dur);';
  d.onmouseenter=function(){this.style.background='rgba(255,255,255,0.1)';this.style.transform='translateY(-2px)';};
  d.onmouseleave=function(){this.style.background='rgba(255,255,255,0.06)';this.style.transform='';};
  d.onclick=function(){openSentLikeProfile(likeId);};
  var cover=(p.photos&&p.photos[0])?'<div style="height:200px;background-image:url('+p.photos[0]+');background-size:cover;background-position:center;"></div>':'<div style="height:200px;background:linear-gradient(160deg,'+p.bg+'55,'+p.bg+'22);display:flex;align-items:center;justify-content:center;font-size:48px;font-weight:900;color:#fff;">'+p.init+'</div>';
  d.innerHTML=cover+'<div style="padding:8px 10px;"><div style="font-size:var(--fs-base);font-weight:600;color:#fff;display:flex;align-items:center;gap:4px;">'+p.name+' 💘</div><div style="font-size:var(--fs-xs);color:var(--fg2);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+(p.major||'')+'</div></div>';
  sl.insertBefore(d,sl.firstChild);
}
function quickLikeProfile(name,bg,cardEl){
  if(typeof _consumeLike==='function'&&!_consumeLike()){
    var cap=(typeof _effLikeCap==='function')?_effLikeCap():15;
    var likeCapMsg2=window.PLANS_ENABLED?('You\'ve used your '+cap+' likes for today!\n\nInvite friends for +3 likes/day each, or upgrade to A+ Student for unlimited. Open invite menu?\n\n(Cancel = see Plans)'):('You\'ve used your '+cap+' likes for today!\n\nInvite friends for +3 likes/day each. Open invite menu?');
    if(confirm(likeCapMsg2)){if(typeof openReferral==='function')openReferral();}else if(typeof sw==='function'){sw('premium','Plans');}
    return;
  }
  var p=_findProfileByName(name);
  _addSentLikeCard(p);
  if(cardEl){cardEl.style.transition='transform 0.32s,opacity 0.32s';cardEl.style.transform='translateX(120%) rotate(12deg)';cardEl.style.opacity='0';setTimeout(function(){cardEl.remove();},320);}
  
  var targetId = (p && p.id) || (p && p.handle) || name;
  if (typeof apiClient !== 'undefined' && apiClient.getAccessToken()) {
    apiClient.registerSwipe(targetId, 'LIKE')
      .then(function(res) {
        console.log("Quick like registered on backend:", res);
        if (res && res.isMatch) {
          var partnerData = (res && res.partner) || p;
          setTimeout(function(){ _showMatchOverlay({ matchId: res.match ? res.match.id : '', partner: partnerData }); }, 200);
        }
      })
      .catch(function(err) {
        console.error("Failed to register quick like on backend:", err.message);
      });
  } else {
    if(p&&Math.random()>0.45)setTimeout(function(){if(typeof showMatch==='function')showMatch(p);},340);
  }
}
// year-in-school label for a profile (self honors yearStyle; others show full word)
function _profileYearLabel(p){if(!p)return '';var yis=_yearInSchoolFromGrad(p.grad);if(!yis)return '';return (p===userPro||p.isSelf)?_yearDisplay(yis):yis;}
var _crushLocationOn=false;
var _crushMiles=10;
var _crushCoords=null;
function _setLocStatus(text,color){var el=document.getElementById('uc-loc-status');if(el){el.textContent=text;el.style.color=color||'';}}
function requestCrushLocation(){
  var sw=document.getElementById('uc-loc-sw');
  if(_crushLocationOn){
    _crushLocationOn=false;_crushCoords=null;
    if(sw)sw.classList.remove('on');
    var det=document.getElementById('uc-loc-detail');if(det)det.style.display='none';
    _setLocStatus('Tap to grant real-time location access','');
    return;
  }
  if(!navigator.geolocation){alert('Geolocation is not supported on this device.');return;}
  _setLocStatus('Requesting permission…','#fbbf24');
  navigator.geolocation.getCurrentPosition(function(pos){
    _crushCoords={lat:pos.coords.latitude,lng:pos.coords.longitude};_crushLocationOn=true;
    if(sw)sw.classList.add('on');
    var det=document.getElementById('uc-loc-detail');if(det)det.style.display='block';
    _setLocStatus('✓ Real-time location enabled','#4ade80');
    var w=document.getElementById('uc-loc-where');
    if(w){
      var here=[(userPro&&userPro.city)||'',(userPro&&userPro.state)||''].filter(Boolean).join(', ')
        ||(userPro&&userPro.hometown)
        ||'your location';
      w.textContent=here;
    }
    onUcMilesChange(_crushMiles);
  },function(err){
    _setLocStatus('Permission denied · '+(err.message||'unable to access location'),'#dc2626');
  },{enableHighAccuracy:true,maximumAge:60000,timeout:10000});
}
var _gpsCityName='';
function _resolveCurrentCity(coords,cb){
  if(_gpsCityName){cb(_gpsCityName);return;}
  if(!coords||!coords.lat){cb('');return;}
  try{
    fetch('https://nominatim.openstreetmap.org/reverse?format=json&zoom=10&lat='+coords.lat+'&lon='+coords.lng,{headers:{'Accept':'application/json'}})
      .then(function(r){return r.json();})
      .then(function(d){
        var a=d&&d.address||{};
        var city=a.city||a.town||a.village||a.hamlet||a.county||'';
        var state=a.state||a.region||'';
        var country=a.country_code?a.country_code.toUpperCase():(a.country||'');
        var label=[city,state].filter(Boolean).join(', ')+(country?' ('+country+')':'');
        _gpsCityName=label.trim();
        cb(_gpsCityName||'your current location');
      })
      .catch(function(){cb('your current location');});
  }catch(e){cb('your current location');}
}
function onUcMilesChange(v){
  _crushMiles=parseInt(v)||10;
  var lbl=document.getElementById('uc-mile-val');if(lbl)lbl.textContent=_crushMiles;
  var ec=document.getElementById('uc-mile-echo');if(ec)ec.textContent=_crushMiles;
  var sl=document.getElementById('uc-mile-sl');if(sl&&parseInt(sl.value)!==_crushMiles)sl.value=_crushMiles;
  var w=document.getElementById('uc-loc-where');
  if(!w)return;
  // Prefer the real-time GPS location over signup city/state. Reverse-geocode to a readable city.
  var coords=(typeof _crushCoords!=='undefined'&&_crushCoords)||(typeof _obLocationCoords!=='undefined'&&_obLocationCoords)||null;
  if(coords&&coords.lat){
    if(_gpsCityName){w.textContent=_gpsCityName;}
    else{w.textContent='your current location';_resolveCurrentCity(coords,function(name){var wn=document.getElementById('uc-loc-where');if(wn)wn.textContent=name;});}
  }else{
    var here=[(userPro&&userPro.city)||'',(userPro&&userPro.state)||''].filter(Boolean).join(', ')||(userPro&&userPro.hometown)||'your location';
    w.textContent=here;
  }
}
// Legacy compat — toggleCrushLocation routes to new flow if old button still exists
function toggleCrushLocation(){requestCrushLocation();}
var _matchProfiles={};
function showMatch(p,isRose){
  if (!p) return;
  var chatId='match_'+Date.now();
  _matchProfiles[chatId]=p;
  var partnerObj = {
    id: p.id || '',
    firstName: p.name ? p.name.split(' ')[0] : (p.firstName || 'Partner'),
    name: p.name || p.firstName || 'Partner',
    handle: p.handle || '',
    photo: (p.photos && p.photos[0]) ? (p.photos[0].url || p.photos[0]) : (p.photo || ''),
    prompts: p.prompts || [],
    ints: p.ints || [],
    major: p.major || '',
    hometown: p.hometown || ''
  };
  _showMatchOverlay({ matchId: chatId, partner: partnerObj });
  // Pre-create chat
  chatHistory[chatId]=chatHistory[chatId]||[];chatHistory[chatId]._expires=Date.now()+86400000;chatHistory[chatId]._matched=p.name;
  // Add to the Matches side of the chat list
  _addMatchChatRow(chatId, p);
  var badge=document.getElementById('uc-badge')||document.getElementById('nbadge-chats');if(badge){badge.style.display='flex'; badge.textContent='1';}
}
function matchDoOpen(chatId,name,color,init){
  var ov=document.getElementById('match-overlay');if(ov)ov.remove();
  var clean=name.replace(' 💘','');
  var pr=_pendingReplies[clean];
  if(pr){
    chatHistory[chatId]=chatHistory[chatId]||[];
    if(chatHistory[chatId].length===0){
      // Photo first (if any), then the section + message underneath, then their welcome
      if(pr.photo)chatHistory[chatId].push({img:pr.photo,out:true});
      var head='💬 You replied to '+clean+'\'s '+pr.section;
      chatHistory[chatId].push({txt:pr.msg?(head+': "'+pr.msg+'"'):head,out:true});
      chatHistory[chatId].push({txt:'You matched! Reply back to keep it going 😊',out:false});
    }
    delete _pendingReplies[clean];
    openChat(chatId,name+' 💘',color,init,false,[],false);
  }else{
    openChat(chatId,name+' 💘',color,init,false,['Hey! We matched! 😊'],false);
  }
}
function matchDoWait(chatId,name,color,init){
  var ov=document.getElementById('match-overlay');if(ov)ov.remove();
}

// ══════════ ICEBREAKERS FOR MATCHES ══════════
// Tailored, non-corny openers. Tone: casual, curious, a little playful — and
// specific to THIS person (their prompts, interests, major, hometown).
function _stripEmoji(s){return (s||'').replace(/^[^A-Za-z0-9]+/,'').trim();}
function _genIcebreakers(p){
  if(!p)return[];
  var out=[];
  // 1) React to one of their prompts (strongest — references what they actually wrote)
  if(p.prompts&&p.prompts.length){
    var pr=p.prompts[_strHash((p.name||'')+'p')%p.prompts.length];
    var q=(pr.q||'').replace(/[…\.]+$/,'').trim();
    var promptLines=[
      'Your take on "'+q+'" — I have follow-up questions.',
      'Read your "'+q+'" answer twice. Need the backstory.',
      'Okay "'+q+'" — defend it.'
    ];
    out.push(promptLines[_strHash(p.name+'pl')%promptLines.length]);
  }
  // 2) Poke at an interest (playful, low-pressure)
  if(p.ints&&p.ints.length){
    var it=_stripEmoji(p.ints[_strHash((p.name||'')+'i')%p.ints.length]);
    if(it)out.push(it+' — casual hobby or full personality trait? Need to know what I\'m dealing with.');
  }
  // 3) Curious about major / hometown
  if(p.major)out.push(p.major+' — did you actually choose it, or is it a long story?');
  if(p.hometown)out.push(p.hometown+' to here — upgrade or downgrade? Be honest.');
  // 4) Solid non-corny fallbacks (always available)
  var fallbacks=[
    'Give me a strong opinion. Doesn\'t matter what about.',
    'Coffee-between-classes or nap-between-classes person? Important data.',
    'What\'s something you\'d actually want to do this week — not the vague "we should hang out" someday.',
    'Best food spot near campus, go. I\'ll judge accordingly.'
  ];
  // ensure we always return 3, padding with fallbacks (no repeats)
  var i=0;while(out.length<3&&i<fallbacks.length){if(out.indexOf(fallbacks[i])===-1)out.push(fallbacks[i]);i++;}
  return out.slice(0,3);
}
function renderIcebreakers(chatId){
  var bar=document.getElementById('icebreaker-bar');if(!bar)return;
  var p=_matchProfiles[chatId];
  var hist=chatHistory[chatId]||[];
  var alreadySent=hist.some(function(m){return m.out&&m.txt;});
  if(!p||alreadySent){bar.style.display='none';bar.innerHTML='';return;}
  var ideas=_genIcebreakers(p);
  if(!ideas.length){bar.style.display='none';return;}
  bar.style.display='block';
  bar.style.cssText='display:block;padding:8px 10px;border-top:1px solid var(--gbdl);background:rgba(0,0,0,0.15);';
  bar.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px;"><span style="font-size:var(--fs-2xs);font-weight:600;color:var(--fg2);text-transform:uppercase;letter-spacing:0.6px;">💡 Breakers — tap to use, then make it yours</span><button onclick="document.getElementById(\'icebreaker-bar\').style.display=\'none\'" style="background:none;border:none;color:var(--fg3);font-size:var(--fs-base);cursor:pointer;">✕</button></div>'+
    '<div style="display:flex;flex-direction:column;gap:6px;">'+ideas.map(function(t){var safe=t.replace(/'/g,"\\'").replace(/"/g,'&quot;');
      return '<div onclick="useIcebreaker(this)" data-txt="'+t.replace(/"/g,'&quot;')+'" style="font-size:var(--fs-sm);color:#fff;background:rgba(255,255,255,0.06);border:1px solid var(--gbdl);border-radius:var(--rad-sm);padding:9px 11px;cursor:pointer;line-height:1.4;">'+t+'</div>';
    }).join('')+'</div>';
}
function useIcebreaker(el){
  var txt=el.getAttribute('data-txt');var inp=document.getElementById('cinp');
  if(inp){inp.value=txt;inp.focus();}
  var bar=document.getElementById('icebreaker-bar');if(bar)bar.style.display='none';
}
// 📅 DATE PLANNER — commuter / off-campus aware
