// 🎮 ICE-BREAKER GAMES — mini-games inside a match chat
function openChatGame(){
  if(typeof curChatId==='undefined'||!curChatId){alert('Open a chat first to play.');return;}
  var games=[
    {e:'🎭',t:'Two Truths & a Lie',m:function(){return '🎭 Two truths and a lie — I\'ll guess yours if you guess mine. You go first!';}},
    {e:'🔥',t:'Hot Take',m:function(){var hot=['pineapple on pizza — yes or crime?','cereal before milk or after?','is a hotdog a sandwich?','beach trip > mountain trip — defend or deny.','texting "k" — rude or efficient?'];return 'Hot take: '+hot[Math.floor(Math.random()*hot.length)];}},
    {e:'🌶️',t:'Rapid Fire',m:function(){var rf=['texter or caller?','morning or night person?','coffee or energy drink?','concerts or festivals?','dogs or cats?'];return '🌶️ Rapid fire, first thing that comes to mind: '+rf[Math.floor(Math.random()*rf.length)];}}
  ];
  window._chatGames=games;
  var m=document.getElementById('chatgame-modal');if(m)m.remove();
  m=document.createElement('div');m.id='chatgame-modal';m.className='mov open';m.style.zIndex='10001';
  m.innerHTML='<div class="msheet" style="max-width:360px;"><div class="mhnd"></div><div style="text-align:center;margin-bottom:14px;"><div style="font-size:30px;">🎮</div><div class="t-title">Ice-breaker games</div><div class="t-sub">Beat the dry opener — tap one to start.</div></div>'+
    games.map(function(g,i){return '<button onclick="_playChatGame('+i+')" style="display:flex;align-items:center;gap:11px;width:100%;text-align:left;margin-bottom:8px;padding:13px;border-radius:var(--rad-sm);border:1px solid var(--gbdl);background:rgba(255,255,255,0.04);color:#fff;cursor:pointer;"><span style="font-size:var(--fs-xl);">'+g.e+'</span><span style="font-size:var(--fs-base);font-weight:600;">'+g.t+'</span></button>';}).join('')+
    '<button class="gbtn-ghost" onclick="document.getElementById(\'chatgame-modal\').remove()">Close</button></div>';
  document.body.appendChild(m);
}
function _playChatGame(i){
  var g=window._chatGames&&window._chatGames[i];if(!g||!curChatId)return;
  if(!chatHistory[curChatId])chatHistory[curChatId]=[];
  var gameMsg = g.m();
  chatHistory[curChatId].push({txt:gameMsg,out:true});
  if(typeof renderMsgs==='function')renderMsgs();
  var isDbMatch = (typeof apiClient !== 'undefined' && apiClient.getAccessToken() && !curChatId.startsWith('biz_') && !curChatId.startsWith('net_') && !curChatId.startsWith('clist-') && !curChatId.includes('moment'));
  if (isDbMatch) {
    apiClient.sendChatMessage(curChatId, gameMsg, 'GAME');
  }
  var mm=document.getElementById('chatgame-modal');if(mm)mm.remove();
}

// ── CHATS ──
function updateChatWindowBubbleColors(style, partnerUni) {
  var win = document.getElementById('cwin');
  if (!win) return;
  
  // Resolve primary color c1
  var c1 = '';
  if (partnerUni) {
    c1 = partnerUni.p || '';
  } else if (typeof uni !== 'undefined' && uni) {
    c1 = uni._schoolP || uni.p || '';
  }
  // If we didn't get a concrete hex (empty, or a 'var(--p)'/gradient string), read
  // the live computed --p so the sent bubble tracks the university colour instead
  // of silently falling back to the old hardcoded pink.
  if (!c1 || c1.charAt(0) !== '#') {
    try {
      var _pc = getComputedStyle(document.documentElement).getPropertyValue('--p').trim();
      if (_pc && _pc.charAt(0) === '#') c1 = _pc;
    } catch (e) {}
  }
  if (!c1 || c1.charAt(0) !== '#') c1 = '#3d7bff';

  // Parse hex to rgb (defaults to the blue fallback, never pink)
  var r = 61, g = 123, b = 255;
  if (c1.startsWith('#')) {
    var hex = c1.substring(1);
    if (hex.length === 3) {
      hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
    }
    if (hex.length === 6) {
      r = parseInt(hex.substring(0, 2), 16);
      g = parseInt(hex.substring(2, 4), 16);
      b = parseInt(hex.substring(4, 6), 16);
    }
  }

  if (style === '#050505') {
    // Deep Black - elegant translucent white glass
    win.style.setProperty('--chat-out-bg', 'rgba(255, 255, 255, 0.16)');
    win.style.setProperty('--chat-in-bg', 'rgba(24, 30, 52, 0.92)');
    win.style.setProperty('--chat-out-shadow', 'none');
    win.style.setProperty('--chat-send-btn-bg', 'rgba(255, 255, 255, 0.25)');
  } else if (style && style !== 'linear-gradient(135deg,#1a0a2e,#0d1a3a)') {
    // Custom background
    win.style.setProperty('--chat-out-bg', 'rgba(' + r + ',' + g + ',' + b + ',0.9)');
    win.style.setProperty('--chat-in-bg', 'rgba(24, 30, 52, 0.92)');
    win.style.setProperty('--chat-out-shadow', 'none');
    win.style.setProperty('--chat-send-btn-bg', 'rgb(' + r + ',' + g + ',' + b + ')');
  } else {
    // Default background, but themed with university color!
    win.style.setProperty('--chat-out-bg', 'rgba(' + r + ',' + g + ',' + b + ',0.9)');
    win.style.setProperty('--chat-in-bg', 'rgba(24, 30, 52, 0.92)');
    win.style.setProperty('--chat-out-shadow', 'none');
    win.style.setProperty('--chat-send-btn-bg', 'rgb(' + r + ',' + g + ',' + b + ')');
  }
}

function _getCurrentUserId() {
  if (typeof userPro !== 'undefined' && userPro && userPro.id) return userPro.id;
  if (typeof window._currentUserId !== 'undefined' && window._currentUserId) return window._currentUserId;
  if (typeof apiClient !== 'undefined' && apiClient.getAccessToken()) {
    try {
      var token = apiClient.getAccessToken();
      var parts = token.split('.');
      if (parts.length === 3) {
        var payload = JSON.parse(atob(parts[1]));
        var uid = payload.userId || payload.id || null;
        if (uid) {
          window._currentUserId = uid;
          if (typeof userPro !== 'undefined' && userPro) userPro.id = uid;
          return uid;
        }
      }
    } catch(e) {}
  }
  return null;
}
window._getCurrentUserId = _getCurrentUserId;

function debugChatState(label, matchId) {
  var target = matchId || (typeof curChatId !== 'undefined' ? curChatId : null);
  var arr = (typeof chatHistory !== 'undefined' && target) ? chatHistory[target] : null;
  console.log('[CHAT STATE]', label, {
    matchId: target,
    curChatId: (typeof curChatId !== 'undefined' ? curChatId : null),
    count: Array.isArray(arr) ? arr.length : 'NOT_ARRAY',
    messages: Array.isArray(arr)
      ? arr.map(function(m) {
          return {
            id: m.id,
            text: m.txt || m.text || m.content,
            senderId: m.senderId,
            out: m.out
          };
        })
      : arr
  });
}
window.debugChatState = debugChatState;

function normalizeChatMessage(m) {
  if (!m) return null;
  var curUserId = _getCurrentUserId();
  var senderId = m.senderId || (m.sender ? m.sender.id : null);
  
  var isOut = false;
  if (typeof m.out === 'boolean') {
    isOut = m.out;
  } else if (senderId && curUserId) {
    isOut = (senderId === curUserId);
  }

  var txtContent = m.content || m.txt || m.text || '';
  
  return {
    id: m.id || ('msg_loc_' + Math.random().toString(36).substring(2, 9)),
    txt: txtContent,
    content: txtContent,
    type: (m.type || 'TEXT').toUpperCase(),
    mediaUrl: m.mediaUrl || m.img || m.audio || null,
    duration: m.duration || null,
    out: isOut,
    senderId: senderId,
    isRead: !!m.isRead,
    readAt: m.readAt || null,
    from: (m.sender && m.sender.firstName) ? m.sender.firstName : (m.from || ''),
    seeOnce: !!m.seeOnce,
    opened: !!m.opened,
    expired: !!m.expired,
    isVideo: !!m.isVideo,
    createdAt: m.createdAt || new Date().toISOString()
  };
}
window.normalizeChatMessage = normalizeChatMessage;

function _updateUnreadBadgeForChat(matchId) {
  window._unreadMessageCounts = window._unreadMessageCounts || {};
  var count = window._unreadMessageCounts[matchId] || 0;

  // Per-row unread state is shown by .cdot alone (see fetchAndRenderChats /
  // onMessageReceived / openChat) — this function only owns the aggregate
  // nav/tab badges below. It used to also inject a numeric .cunrd badge into
  // the same row, which duplicated .cdot and collided with .cright's other
  // elements (status text, presence dot).
  var targets = ['dm-match-' + matchId, 'uc-match-' + matchId];
  if (count === 0) {
    targets.forEach(function(rowId) {
      var item = document.getElementById(rowId);
      var existingBadge = item && item.querySelector('.cunrd');
      if (existingBadge) existingBadge.remove();
    });
  }

  var totalUnread = 0;
  for (var mId in window._unreadMessageCounts) {
    totalUnread += window._unreadMessageCounts[mId] || 0;
  }
  var chatsBadge = document.getElementById('nbadge-chats');
  if (chatsBadge) {
    if (totalUnread > 0) {
      chatsBadge.style.display = 'flex';
      chatsBadge.textContent = totalUnread > 9 ? '+9' : totalUnread;
    } else {
      chatsBadge.style.display = 'none';
    }
  }
  var navBadge = document.querySelector('.nav-btn[data-tab="chats"] .nav-badge') || document.querySelector('#nav-chats .nav-badge');
  if (navBadge) {
    if (totalUnread > 0) {
      navBadge.style.display = 'flex';
      navBadge.textContent = totalUnread > 9 ? '+9' : totalUnread;
    } else {
      navBadge.style.display = 'none';
    }
  }
}
window._updateUnreadBadgeForChat = _updateUnreadBadgeForChat;

// On-demand presence lookup (no proactive broadcast) — queried once per chat open.
// Bails out quietly if the chat was closed/switched by the time the response arrives.
function _applyPresenceToHeader(matchId, csubEl) {
  if (typeof apiClient === 'undefined' || !apiClient.getAccessToken()) return;
  apiClient.getUserPresence(matchId).then(function(presence) {
    if (curChatId !== matchId || !csubEl) return;
    if (presence && presence.online) {
      csubEl.textContent = 'Online';
    } else if (presence && presence.lastActive) {
      var ago = (typeof _timeAgo === 'function') ? _timeAgo(presence.lastActive) : 'recently';
      csubEl.textContent = 'Last seen ' + (ago === 'now' ? 'just now' : ago);
    } else {
      csubEl.textContent = 'Last seen recently';
    }
  }).catch(function(err) {
    console.warn('[CHAT] Failed to load presence for', matchId, err);
  });
}

function openChat(id,nm,color,av,isGrp,msgs,online){
  if(window.NavigationManager) window.NavigationManager.setActiveChat(id);
  var inpBefore = document.getElementById('cinp') ? document.getElementById('cinp').value : '';
  console.log('[CHAT DUPLICATE DEBUG] openChat() START | timestamp: ' + new Date().toISOString() + ' | id: ' + id + ' | input value BEFORE loading chat: "' + inpBefore + '"');
  debugChatState('openChat START', id);
  console.log('[CHAT DEBUG] OPEN CHAT START | openChat ARGUMENT id:', id, '| name:', nm);
  console.log('[CHAT DEBUG] current user ID:', _getCurrentUserId());

  if (id && typeof id === 'string' && (id.startsWith('friend_') || id.startsWith('user_') || (!id.startsWith('cm') && !id.startsWith('grp_') && !id.startsWith('biz_') && !id.startsWith('net_') && !id.startsWith('clist-') && !id.includes('moment')))) {
    var partnerRef = id.replace(/^(friend_|user_)/, '');
    console.log('[CHAT DEBUG] Non-Match ID detected, resolving partnerRef:', partnerRef);
    if (typeof apiClient !== 'undefined' && apiClient.getAccessToken()) {
      apiClient.createConversation(partnerRef).then(function(result) {
        if (result && result.matchId) {
          console.log('[CHAT DEBUG] Resolved partnerRef ' + partnerRef + ' to matchId:', result.matchId);
          openChat(result.matchId, nm, color, av, isGrp, msgs, online);
          if (typeof fetchAndRenderChats === 'function') fetchAndRenderChats();
        }
      }).catch(function(err) {
        console.error("[CHAT DEBUG ERROR] Failed to resolve conversation ID in openChat:", err);
      });
    }
    return;
  }
  var isDbMatch = (typeof apiClient !== 'undefined' && apiClient.getAccessToken() && !id.startsWith('biz_') && !id.startsWith('net_') && !id.startsWith('clist-') && !id.includes('moment'));
  
  if (window._unreadMessageCounts) {
    window._unreadMessageCounts[id] = 0;
  }
  _updateUnreadBadgeForChat(id);
  // Clear the row's own unread dot right away instead of waiting on the next
  // full fetchAndRenderChats() — that wait is what let a stale re-render (or
  // a poll landing before the backend's read-mark resolved) bring the dot
  // back after the user had already read the message.
  ['dm-match-' + id, 'uc-match-' + id].forEach(function(rid) {
    var item = document.getElementById(rid);
    if (!item) return;
    var pre = item.querySelector('.cpre');
    if (pre) pre.classList.remove('cpre-unrd');
    var dotEl = item.querySelector('.cright .cdot');
    if (dotEl) dotEl.remove();
    var badgeEl = item.querySelector('.cunrd');
    if (badgeEl) badgeEl.remove();
  });
  if (isDbMatch && typeof apiClient !== 'undefined' && typeof apiClient.markChatRead === 'function') {
    apiClient.markChatRead(id);
  }

  var conv = (typeof _chatPartnerCache !== 'undefined') ? _chatPartnerCache[id] : null;
  var partner = conv ? conv.partner : null;
  var displayName = nm;
  if (isDbMatch && partner && partner.handle) {
    var rawHandle = partner.handle.replace('@', '');
    displayName = rawHandle + (conv.streamChannelId ? ' 💘' : '');
  }
  
  var chatBgStyle = '';
  if (typeof userPro !== 'undefined' && userPro) {
    if (userPro.customization && userPro.customization.chatBackgrounds) {
      chatBgStyle = userPro.customization.chatBackgrounds[id] || '';
    }
    if (!chatBgStyle && userPro.chatBackgrounds) {
      chatBgStyle = userPro.chatBackgrounds[id] || '';
    }
  }
  var partnerUni = null;
  if (partner && partner.profile && partner.profile.university && typeof UNI !== 'undefined') {
    for (var d in UNI) {
      if (UNI[d] && UNI[d].name === partner.profile.university) {
        partnerUni = UNI[d];
        break;
      }
    }
  }
  var bgContainer = document.getElementById('cwbg');
  if (bgContainer) {
    if (chatBgStyle) {
      renderChatBackground(chatBgStyle);
    } else {
      renderChatBackground('default');
      if (partnerUni) {
        bgContainer.style.background = 'linear-gradient(135deg, ' + partnerUni.p + '33, ' + (partnerUni.p2 || partnerUni.p) + '18, var(--bg, #000000))';
      } else {
        bgContainer.style.background = 'var(--bg, #000000)';
      }
    }
  }
  
  updateChatWindowBubbleColors(chatBgStyle, partnerUni);

  curChatId=id;_curChatUser={name:displayName,color:color||'#3d7bff',init:av,isGrp:!!isGrp};var win=document.getElementById('cwin');if(win)win.classList.add('open');var cnm=document.getElementById('cwnm');if(cnm)cnm.textContent=displayName;var csub=document.getElementById('cwsub');if(csub){var _cst=null;if(!isGrp&&typeof crushDataAll!=='undefined'&&crushDataAll){var _cp=crushDataAll.filter(function(x){return x.name===nm;})[0];if(_cp&&typeof _profileStatus==='function')_cst=_profileStatus(_cp);}csub.textContent=_cst&&_cst.text?(_cst.emoji+' '+_cst.text):(online?'Online':'Last seen recently');}
  var avDiv=document.getElementById('cwav');
  if(avDiv){
    var photoUrl = (partner && partner.photos && partner.photos[0] && partner.photos[0].url) || '';
    if (isDbMatch && photoUrl) {
      avDiv.innerHTML = '<img src="' + photoUrl + '" style="width:100%;height:100%;border-radius:50%;object-fit:cover;display:block;"/>';
    } else {
      avDiv.innerHTML = '<span id="cwav-txt">' + av + '</span>';
      var avEl = document.getElementById('cwav-txt');
      if (avEl) avEl.textContent = av;
      if (color) avDiv.style.background = color;
    }
  }
  if (!chatHistory[id]) chatHistory[id] = [];
  if (!isDbMatch && msgs && chatHistory[id].length === 0) {
    chatHistory[id] = msgs.map(function(m){ return normalizeChatMessage({ txt: m, out: isGrp?false:true }); });
  }
  if (typeof _cwApplyChatHead === 'function') _cwApplyChatHead(id, displayName, color, !!isGrp);
  
  console.log('[CHAT DEBUG] curChatId set to:', curChatId);
  console.log('[CHAT DEBUG] Initial chatHistory[' + id + '] count:', chatHistory[id].length, chatHistory[id]);
  
  renderMsgs();
  if (typeof renderIcebreakers === 'function') renderIcebreakers(id);

  if (isDbMatch) {
    window._currentChatRequestId = (window._currentChatRequestId || 0) + 1;
    var requestId = window._currentChatRequestId;

    console.log('[CHAT DEBUG] Requesting DB messages for matchId:', id, '| requestId:', requestId);
    if (csub && !isGrp) csub.textContent = 'Loading messages...';
    debugChatState('openChat BEFORE GET RESOLVE', id);
    apiClient.getChatMessages(id).then(function(dbMsgs) {
      if (window._currentChatRequestId !== requestId || curChatId !== id) {
        console.log('[CHAT DEBUG] Ignoring stale GET response for requestId ' + requestId);
        return;
      }
      console.log('[CHAT DEBUG] GET RETURNED:', (dbMsgs ? dbMsgs.length : 0), 'messages from server for matchId:', id);
      
      debugChatState('openChat BEFORE ASSIGNING GET RESULT', id);
      chatHistory[id] = (dbMsgs || []).map(function(m) {
        return normalizeChatMessage(m);
      });
      debugChatState('openChat AFTER ASSIGNING GET RESULT', id);
      
      console.log('[CHAT DEBUG] NORMALIZED & UPDATED chatHistory[' + id + ']:', chatHistory[id].length, 'messages');
      renderMsgs();
      debugChatState('openChat AFTER renderMsgs FOR GET', id);
      if (csub && !isGrp) csub.textContent = online ? 'Online' : 'Last seen recently';
      if (!isGrp) _applyPresenceToHeader(id, csub);
    }).catch(function(err) {
      console.error("[CHAT DEBUG ERROR] Failed to load chat history:", err);
      if (csub && !isGrp) csub.textContent = 'Error loading history';
    });
    apiClient.joinChatRoom(id);
  }
}
function closeChat(){
  if(window.NavigationManager) window.NavigationManager.setActiveChat(null);
  debugChatState('closeChat START', curChatId);
  console.log('[CHAT DEBUG] CHAT CLOSE');
  console.log('[CHAT DEBUG] curChatId BEFORE CLOSE:', curChatId);
  if (curChatId && chatHistory[curChatId]) {
    console.log('[CHAT DEBUG] chatHistory BEFORE CLOSE for ' + curChatId + ' count:', chatHistory[curChatId].length, chatHistory[curChatId]);
  }
  var win=document.getElementById('cwin');
  if(win)win.classList.remove('open');
  if (typeof curChatId !== 'undefined' && curChatId) {
    if (typeof apiClient !== 'undefined' && typeof apiClient.leaveChatRoom === 'function') {
      apiClient.leaveChatRoom(curChatId);
    }
    curChatId = null;
  }
  debugChatState('closeChat END', curChatId);
}
function _e(t){return String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
window.groupChatMeta = window.groupChatMeta || {};

// Group chats do not exist on the backend — they are DOM rows plus this in-memory
// map, so without this everything (banner, title, nicknames, who is admin) is
// lost on every reload. Persist to the device for now; when group endpoints
// exist, swap these two bodies for the API calls and nothing else changes.
var _GROUP_META_KEY = 'ugz_groupmeta';

function _saveGroupMeta() {
  try {
    localStorage.setItem(_GROUP_META_KEY, JSON.stringify(window.groupChatMeta || {}));
  } catch (e) {}
}

function _loadGroupMeta() {
  try {
    var raw = localStorage.getItem(_GROUP_META_KEY);
    if (!raw) return;
    var saved = JSON.parse(raw);
    if (saved && typeof saved === 'object') {
      window.groupChatMeta = window.groupChatMeta || {};
      for (var k in saved) {
        if (saved.hasOwnProperty(k) && !window.groupChatMeta[k]) window.groupChatMeta[k] = saved[k];
      }
    }
  } catch (e) {}
}
try { _loadGroupMeta(); } catch (e) {}

function _getGroupMeta(chatId) {
  window.groupChatMeta = window.groupChatMeta || {};
  if (window.groupChatMeta[chatId]) {
    var cached = window.groupChatMeta[chatId];
    // Older saved entries predate these fields.
    if (!cached.nicknames) cached.nicknames = {};
    if (typeof cached.avatarUrl === 'undefined') cached.avatarUrl = '';
    if (typeof cached.isEvent === 'undefined') {
      cached.isEvent = /^evgrp_/.test(chatId || '');
    }
    return cached;
  }

  var ev = (typeof HANGOUT_EVENTS !== 'undefined' ? HANGOUT_EVENTS : []).find(function(e) {
    var key = (e.section || '') + '|' + (e.name || '');
    return (typeof _hangoutChatIds !== 'undefined' && _hangoutChatIds[key] === chatId) || ('evgrp_' + e.id) === chatId || e.name === chatId;
  });

  var adminHandle = (userPro && userPro.handle) ? userPro.handle.replace('@','') : 'admin';
  var adminName = (userPro && userPro.name) || 'Admin';
  var banner = '';
  var members = [];

  if (ev) {
    adminHandle = (ev.host || (ev.creator && ev.creator.handle) || adminHandle).replace('@','');
    adminName = (ev.creator ? (ev.creator.firstName + ' ' + (ev.creator.lastName || '')) : adminHandle);
    banner = ev.cover || '';
    if (ev.attendees && ev.attendees.length) {
      members = ev.attendees.map(function(att) {
        var isAdm = (att.id === ev.creatorId || att.handle === adminHandle);
        return {
          id: att.id,
          name: att.firstName ? (att.firstName + ' ' + (att.lastName || '')) : (att.handle || 'Member'),
          handle: (att.handle || att.firstName || 'user').replace('@',''),
          photo: (att.photos && att.photos[0] && att.photos[0].url) || '',
          isAdmin: isAdm
        };
      });
    }
  }

  var myHandle = (userPro && userPro.handle ? userPro.handle.replace('@','') : 'me');
  if (!members.some(function(m) { return m.handle === myHandle; })) {
    members.unshift({
      id: userPro ? (userPro.id || 'me') : 'me',
      name: (userPro && userPro.name) ? userPro.name : 'You',
      handle: myHandle,
      photo: (userPro && userPro.photos && userPro.photos[0]) || '',
      isAdmin: true
    });
  }

  if (!members.some(function(m) { return m.isAdmin; })) {
    members[0].isAdmin = true;
  }

  var meta = {
    name: ev ? ev.name : (document.getElementById('cwnm') ? document.getElementById('cwnm').textContent : 'Group Chat'),
    adminHandle: adminHandle,
    adminName: adminName,
    bannerUrl: banner,
    members: members,
    // Event groups cannot be renamed — the title belongs to the event. The ev
    // lookup above (via _hangoutChatIds / the evgrp_ prefix) is the only
    // reliable "came from an event" signal in the codebase.
    isEvent: !!ev || /^evgrp_/.test(chatId || ''),
    nicknames: {},
    // Chat profile photo, distinct from bannerUrl (the wide cover strip).
    avatarUrl: ''
  };

  window.groupChatMeta[chatId] = meta;
  _saveGroupMeta();
  return meta;
}

// Nickname wins over the real name once set, for everyone looking at this group.
function _gsDisplayName(meta, m) {
  var nick = meta && meta.nicknames ? meta.nicknames[m.handle] : '';
  return nick ? nick : m.name;
}

function _cwApplyGroupAvatar(meta){
  var av=document.getElementById('cwav');
  if(!av)return;
  var txt=document.getElementById('cwav-txt');
  if(meta&&meta.avatarUrl){
    av.style.backgroundImage='url('+meta.avatarUrl+')';
    av.style.backgroundSize='cover';
    av.style.backgroundPosition='center';
    if(txt)txt.style.display='none';
  }else{
    av.style.backgroundImage='';
    if(txt)txt.style.display='';
  }
}

// Admin-only: replace the group's profile photo. Local blob URL, same approach
// as cgChangePic — there is no upload endpoint for group avatars yet.
function groupChangePhoto(chatId){
  var meta=_getGroupMeta(chatId);
  var inp=document.createElement('input');inp.type='file';inp.accept='image/*';
  inp.onchange=function(){
    if(!inp.files||!inp.files[0])return;
    var url=URL.createObjectURL(inp.files[0]);
    var apply=function(u){
      meta.avatarUrl=u;
      if(typeof _saveGroupMeta==='function')try{_saveGroupMeta();}catch(e){}
      _cwApplyGroupAvatar(meta);
      // Chat-list row too, so the change is visible without reopening.
      var row=document.getElementById('cav-'+chatId)||document.querySelector('#chatrow_'+chatId+' .cav');
      if(row){row.style.background='url('+u+') center/cover';row.innerHTML='';}
      var img=document.getElementById('gsx-avatar');
      if(img){img.style.backgroundImage='url('+u+')';img.textContent='';}
    };
    if(typeof openImagePositioner==='function')openImagePositioner(url,'profile',function(u){apply(u);});
    else apply(url);
  };
  inp.click();
}

function _cwApplyChatHead(id,nm,color,isGrp){
  var head=document.getElementById('cw-eventhead');var sub=document.getElementById('cwsub');
  if(!isGrp){if(head)head.style.display='none';return;}

  var meta = _getGroupMeta(id);
  var members = meta.members || [];
  var memberCount = members.length || 8;
  // Instagram-style subtitle: the members' first names (never "Error loading").
  if(sub){
    var _gnames=members.map(function(m){return (m.name||'').split(' ')[0];}).filter(Boolean);
    sub.textContent=_gnames.length?_gnames.join(', '):(memberCount+' participants');
  }

  // Group photo in the chat header. openChat() treats its `av` argument as text
  // (it writes textContent), so a group avatar has to be applied here instead.
  _cwApplyGroupAvatar(meta);

  // Group banner (purple cover + member-avatar row) removed per design.
  if(head){
    head.style.display='none';return;
    var cov=document.getElementById('cw-eventcover');
    if(cov){
      if(meta.bannerUrl){
        cov.style.background='url("'+meta.bannerUrl+'") center/cover no-repeat';
      }else{
        cov.style.background='linear-gradient(150deg,'+(color||'#2b5fd9')+',rgba(0,0,0,0.68))';
      }
    }
    var avs=document.getElementById('cw-eventavs');
    if(avs){
      var displayAvatars = members.slice(0, 5);
      var overflowCount = Math.max(0, members.length - 5);
      var avsHtml = displayAvatars.map(function(m, i) {
        var photo = m.photo || ('https://randomuser.me/api/portraits/' + (i % 2 === 0 ? 'women' : 'men') + '/' + (i * 11 + 10) + '.jpg');
        return '<img src="' + photo + '" title="' + m.name + (m.isAdmin ? ' (Admin)' : '') + '" style="width:30px;height:30px;border-radius:50%;border:2px solid #0b0b0e;margin-left:' + (i ? '-9px' : '0') + ';object-fit:cover;"/>';
      }).join('');
      if (overflowCount > 0) {
        avsHtml += '<span style="margin-left:8px;font-size:var(--fs-sm);font-weight:600;color:#fff;background:rgba(0,0,0,0.55);border-radius:var(--rad-sm);padding:3px 9px;">+' + overflowCount + '</span>';
      }
      avs.innerHTML = avsHtml;
    }
  }
}

// NOTE on prompt/confirm in this file: app.js:1020-1043 replaces the native
// window.prompt/confirm/alert with ugzModal, which returns a PROMISE. Calling
// them synchronously silently misbehaves (a Promise is always truthy, and
// .trim() on one throws), so every group action below goes through
// ugzPrompt(...).then(...) / ugzConfirm({onConfirm}).
function groupChangeBanner(chatId) {
  var meta = _getGroupMeta(chatId);
  ugzPrompt('Ingresa la URL de la imagen para el Banner Superior del Chat:', meta.bannerUrl || '').then(function(newUrl) {
    if (newUrl === null || typeof newUrl === 'undefined') return;
    meta.bannerUrl = String(newUrl).trim();
    _saveGroupMeta();

    var ev = (typeof HANGOUT_EVENTS !== 'undefined' ? HANGOUT_EVENTS : []).find(function(e) {
      var key = (e.section || '') + '|' + (e.name || '');
      return (typeof _hangoutChatIds !== 'undefined' && _hangoutChatIds[key] === chatId) || ('evgrp_' + e.id) === chatId || e.name === chatId;
    });
    if (ev) {
      ev.cover = meta.bannerUrl;
      if (typeof fetchAndRenderHangouts === 'function') fetchAndRenderHangouts();
    }

    if (typeof _cwApplyChatHead === 'function') {
      _cwApplyChatHead(chatId, meta.name, 'var(--p)', true);
    }
    _gsRefreshBanner(chatId);
  });
}

// Only for groups made from friends: an event group's title belongs to the event.
function groupChangeTitle(chatId) {
  var meta = _getGroupMeta(chatId);
  if (meta.isEvent) {
    if (typeof ugzAlert === 'function') ugzAlert('El título de un grupo de evento no se puede cambiar.');
    return;
  }
  ugzPrompt('Nuevo título del grupo:', meta.name || '').then(function(val) {
    if (val === null || typeof val === 'undefined') return;
    var nm = String(val).trim();
    if (!nm) return;
    meta.name = nm;
    _saveGroupMeta();

    var cwnm = document.getElementById('cwnm');
    if (cwnm) cwnm.textContent = nm;
    if (typeof _curChatUser !== 'undefined' && _curChatUser) _curChatUser.name = nm;
    // Keep the chat-list row label in sync too.
    var rowNm = document.querySelector('#chatrow_' + chatId + ' .cnm');
    if (rowNm) rowNm.textContent = nm;
    if (typeof _cwApplyChatHead === 'function') _cwApplyChatHead(chatId, nm, 'var(--p)', true);
    _gsRefreshBanner(chatId);
  });
}

// Any member can set a nickname; it replaces the name for everyone viewing this
// group (device-local until group chats exist on the backend).
function groupSetMemberNickname(chatId, handle) {
  var meta = _getGroupMeta(chatId);
  meta.nicknames = meta.nicknames || {};
  var current = meta.nicknames[handle] || '';
  ugzPrompt('Nickname para @' + handle + ' (vacío para quitarlo):', current).then(function(val) {
    if (val === null || typeof val === 'undefined') return;
    var nn = String(val).trim();
    if (nn) meta.nicknames[handle] = nn;
    else delete meta.nicknames[handle];
    _saveGroupMeta();
    if (typeof _cwApplyChatHead === 'function') _cwApplyChatHead(chatId, meta.name, 'var(--p)', true);
    _gsRenderMembers(chatId, handle);
  });
}

function groupInviteMembers(chatId) {
  var meta = _getGroupMeta(chatId);
  var friends = (typeof _friendsForPicker === 'function') ? _friendsForPicker() : [
    { name: 'Ana Garcia', sub: _uniAcronymOf(null), color: '#e91e63', init: 'A' },
    { name: 'Carlos Mendez', sub: _uniAcronymOf(null), color: '#3b82f6', init: 'C' },
    { name: 'Sofia Torres', sub: _uniAcronymOf(null), color: '#10b981', init: 'S' }
  ];

  var m = document.getElementById('group-invite-modal');
  if (m) m.remove();
  m = document.createElement('div');
  m.id = 'group-invite-modal';
  m.className = 'mov open';
  m.style.zIndex = '10010';

  var rows = friends.map(function(f) {
    var alreadyIn = meta.members.some(function(mem) {
      return mem.name.toLowerCase() === f.name.toLowerCase() || mem.handle.toLowerCase() === (f.name.split(' ')[0]).toLowerCase();
    });
    var av = f.photo
      ? '<img src="' + f.photo + '" style="width:36px;height:36px;border-radius:50%;object-fit:cover;"/>'
      : '<div style="width:36px;height:36px;border-radius:50%;background:' + (f.color || 'var(--p)') + ';display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;">' + (f.init || f.name.charAt(0)) + '</div>';

    return '<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 12px;background:rgba(255,255,255,0.04);border-radius:var(--rad-md);margin-bottom:6px;">' +
      '<div style="display:flex;align-items:center;gap:10px;flex:1;">' + av +
        '<div><div style="font-weight:600;color:#fff;font-size:var(--fs-base);">' + f.name + '</div><div style="font-size:var(--fs-xs);color:var(--fg2);">' + (f.sub || 'Friend') + '</div></div>' +
      '</div>' +
      (alreadyIn
        ? '<span style="font-size:var(--fs-xs);color:var(--fg3);">En el grupo</span>'
        : '<button class="jbtn" style="padding:6px 14px;font-size:var(--fs-xs);background:var(--p) !important;border:none!important;" onclick="_addFriendToGroup(\'' + chatId + '\',\'' + f.name.replace(/'/g, "\\'") + '\')">Invitar</button>') +
    '</div>';
  }).join('');

  m.innerHTML = '<div class="msheet" style="max-height:80vh;overflow-y:auto;"><div class="mhnd"></div>' +
    '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;">' +
      '<div style="font-size:var(--fs-lg);font-weight:800;color:#fff;">Invitar Integrantes</div>' +
      '<div onclick="document.getElementById(\'group-invite-modal\').remove()" style="cursor:pointer;color:#fff;font-size:var(--fs-md);">✕</div>' +
    '</div>' +
    '<div>' + (rows || '<div style="color:var(--fg2);padding:12px;text-align:center;">No hay integrantes disponibles para invitar.</div>') + '</div>' +
  '</div>';
  document.body.appendChild(m);
}

function _addFriendToGroup(chatId, friendName) {
  var meta = _getGroupMeta(chatId);
  meta.members.push({
    id: 'f_' + Date.now(),
    name: friendName,
    handle: friendName.toLowerCase().replace(/\s+/g, ''),
    photo: '',
    isAdmin: false
  });
  if (typeof _cwApplyChatHead === 'function') {
    _cwApplyChatHead(chatId, meta.name, 'var(--p)', true);
  }
  var m = document.getElementById('group-invite-modal');
  if (m) m.remove();
  var sm = document.getElementById('chat-settings-modal');
  if (sm) sm.remove();
  openChatSettings();
}

function groupRemoveMember(chatId, handle) {
  var meta = _getGroupMeta(chatId);
  ugzConfirm({
    type: 'warning',
    title: 'Desinvitar integrante',
    message: '¿Sacar a @' + handle + ' del grupo?',
    confirmText: 'Desinvitar',
    cancelText: 'Cancelar',
    onConfirm: function() {
      meta.members = meta.members.filter(function(m) { return m.handle !== handle; });
      if (meta.nicknames) delete meta.nicknames[handle];
      _saveGroupMeta();
      if (typeof _cwApplyChatHead === 'function') {
        _cwApplyChatHead(chatId, meta.name, 'var(--p)', true);
      }
      _gsRenderMembers(chatId);
    }
  });
}

function groupPromoteAdmin(chatId, handle) {
  var meta = _getGroupMeta(chatId);
  ugzConfirm({
    type: 'confirm',
    title: 'Hacer administrador',
    message: '¿Nombrar a @' + handle + ' administrador del grupo?',
    confirmText: 'Hacer Admin',
    cancelText: 'Cancelar',
    onConfirm: function() {
      meta.adminHandle = handle;
      meta.members.forEach(function(m) {
        if (m.handle === handle) m.isAdmin = true;
      });
      _saveGroupMeta();
      _gsRenderMembers(chatId, handle);
    }
  });
}

function groupDeleteChatCompletely(chatId) {
  ugzConfirm({
    type: 'warning',
    title: '🗑️ Borrar chat',
    message: '¿Borrar este grupo por completo? Esta acción no se puede deshacer.',
    confirmText: 'Borrar',
    cancelText: 'Cancelar',
    onConfirm: function() {
      delete window.groupChatMeta[chatId];
      _saveGroupMeta();
      if (typeof chatHistory !== 'undefined') delete chatHistory[chatId];
      if (typeof _deleteChatRow === 'function') _deleteChatRow(chatId);
      var row = document.getElementById('chatrow_' + chatId) || document.getElementById('clist-' + chatId) || document.getElementById('uc-match-' + chatId) || document.getElementById('dm-match-' + chatId);
      if (row) row.remove();

      var sm = document.getElementById('chat-settings-modal');
      if (sm) sm.remove();
      closeChat();
    }
  });
}

function groupExitGroup(chatId) {
  ugzConfirm({
    type: 'warning',
    title: 'Salir del grupo',
    message: '¿Salir de este grupo?',
    confirmText: 'Salir',
    cancelText: 'Cancelar',
    onConfirm: function() {
      if (typeof _deleteChatRow === 'function') _deleteChatRow(chatId);
      var sm = document.getElementById('chat-settings-modal');
      if (sm) sm.remove();
      closeChat();
    }
  });
}

// ¿Este chat es un match de Crush? (para el recordatorio de expiración de 24h)
function _isCrushMatchChat(cid){
  if(!cid)return false;
  try{ var conv=(window._chatPartnerCache||{})[cid]; if(conv&&conv.streamChannelId)return true; }catch(e){}
  var it=document.getElementById('dm-match-'+cid)||document.getElementById('uc-match-'+cid);
  if(it&&it.getAttribute('data-csec')==='matches')return true;
  return false;
}
function renderMsgs(){
  var box=document.getElementById('cmsgs');if(!box||!curChatId)return;
  var isGrp=!!(typeof _curChatUser!=='undefined'&&_curChatUser&&_curChatUser.isGrp);
  var hist=chatHistory[curChatId]||[];
  console.log('[CHAT DEBUG] renderMsgs() executing for curChatId:', curChatId, '| messages count in chatHistory:', hist.length, hist);
  box.innerHTML='';
  // Empty thread → an inviting prompt instead of a black void (worst moment for a
  // fresh match). Auto-surface the icebreakers too.
  if(!hist.length){
    var _enm=(_curChatUser&&_curChatUser.name)||'them';
    var _eic=(_curChatUser&&_curChatUser.init)||_enm.charAt(0).toUpperCase();
    var _ecl=(_curChatUser&&_curChatUser.color)||'var(--p)';
    // Solo en matches/crush: recordar que el chat se borra en 24h si no respondes.
    var _isMatch=(typeof _isCrushMatchChat==='function')&&_isCrushMatchChat(curChatId);
    var _sub=(!isGrp&&_isMatch)
      ? '<div style="font-size:var(--fs-sm);color:#fbbf24;font-weight:600;display:inline-flex;align-items:center;gap:6px;background:rgba(245,158,11,0.1);border:1px solid rgba(245,158,11,0.35);border-radius:var(--rad-pill);padding:7px 14px;">'+icon('hourglass',15)+' Reply within 24h or this match disappears</div>'
      : '<div style="font-size:var(--fs-sm);color:var(--fg2);">Say something</div>';
    box.innerHTML='<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:24px 20px;gap:12px;">'+
      '<div style="width:64px;height:64px;border-radius:50%;background:'+_ecl+';display:flex;align-items:center;justify-content:center;font-size:26px;font-weight:800;color:#fff;box-shadow:0 6px 20px rgba(0,0,0,0.45);">'+_e(_eic)+'</div>'+
      '<div style="font-size:var(--fs-md);font-weight:800;color:#fff;">'+(isGrp?_e(_enm):('You matched with '+_e(_enm)))+'</div>'+
      _sub+
    '</div>';
    try{ if(typeof renderIcebreakers==='function')renderIcebreakers(curChatId); var _ib0=document.getElementById('icebreaker-bar'); if(_ib0)_ib0.style.display=''; }catch(e){}
    return;
  }
  var RX=['❤️','🔥','👍'];var COLS=['#e91e63','#3b82f6','#3d7bff','#f59e0b','#22c55e','#0ea5e9'];
  var _lastDay=null;
  hist.forEach(function(m){
    // Real date separator — only when a message actually carries a timestamp, so
    // we never print a fake "Today" over undated demo history.
    if(m.at){
      var _dayKey=new Date(m.at).toDateString();
      if(_dayKey!==_lastDay){_lastDay=_dayKey;var _dc=document.createElement('div');_dc.className='msg-datesep';_dc.textContent=(typeof _ugzDayLabel==='function'?_ugzDayLabel(m.at):'');box.appendChild(_dc);}
    }
    var div=document.createElement('div');div.className='msg '+(m.out?'out':'in');

    // 1. See-Once media handling
    if(m.seeOnce&&!m.opened&&!m.expired){
      div.style.cssText+='cursor:pointer;background:rgba(180,83,9,0.3);border:1px dashed rgba(251,191,36,0.4);';
      div.innerHTML='<div style="text-align:center;padding:4px 8px;"><div style="font-size:var(--fs-xl);margin-bottom:4px;">'+(m.isVideo?'🎬':'👁')+'</div><div style="font-size:var(--fs-sm);font-weight:500;">View Once '+(m.isVideo?'Video':'Photo')+'</div><div style="font-size:var(--fs-2xs);color:var(--fg2);">Tap to open — disappears after viewing</div></div>';
      div.onclick=function(){
        m.opened=true;div.onclick=null;
        div.style.cssText='';div.className='msg '+(m.out?'out':'in');div.style.padding='4px';div.style.background='transparent';
        if(m.isVideo){
          div.innerHTML='<video src="'+m.img+'" controls autoplay playsinline style="width:180px;border-radius:var(--rad-sm);display:block;max-height:240px;"></video><div style="font-size:var(--fs-2xs);color:var(--fg3);margin-top:4px;">👁 Viewed · expires soon</div>';
        }else{
          div.innerHTML='<img src="'+m.img+'" onclick="openImageViewer(this.src)" style="width:180px;border-radius:var(--rad-sm);display:block;object-fit:cover;cursor:zoom-in;"/><div style="font-size:var(--fs-2xs);color:var(--fg3);margin-top:4px;">👁 Viewed · expires soon</div>';
        }
        setTimeout(function(){m.expired=true;m.img=null;renderMsgs();},8000);
      };
      box.appendChild(div);return;
    }else if(m.seeOnce&&m.expired){
      div.innerHTML='<div style="font-size:var(--fs-sm);color:var(--fg3);font-style:italic;">'+(m.isVideo?'🎬':'👁')+' Media expired</div>';
      box.appendChild(div);return;
    }else if(m.seeOnce&&m.opened&&m.img){
      div.style.padding='4px';div.style.background='transparent';
      if(m.isVideo){div.innerHTML='<video src="'+m.img+'" controls style="width:180px;border-radius:var(--rad-sm);display:block;max-height:240px;"></video><div style="font-size:var(--fs-2xs);color:var(--fg3);margin-top:4px;">👁 Viewed</div>';}
      else{div.innerHTML='<img src="'+m.img+'" onclick="openImageViewer(this.src)" style="width:180px;border-radius:var(--rad-sm);display:block;cursor:zoom-in;"/><div style="font-size:var(--fs-2xs);color:var(--fg3);margin-top:4px;">👁 Viewed</div>';}
      box.appendChild(div);return;
    }

    // 2. Audio message rendering
    var isAudio = (m.type === 'AUDIO' || m.audio || (m.mediaUrl && (m.mediaUrl.includes('audio') || m.mediaUrl.includes('.webm') || m.mediaUrl.includes('.m4a') || m.mediaUrl.includes('.ogg') || m.mediaUrl.includes('.mp3') || m.mediaUrl.includes('.wav') || m.mediaUrl.includes('/audios/'))) || (m.txt && m.txt.includes('Mensaje de voz')));
    if (isAudio) {
      var audioUrl = m.mediaUrl || m.audio;
      if (!audioUrl && m.txt && m.txt.includes('http')) {
        var matchUrl = m.txt.match(/https?:\/\/[^\s]+/);
        if (matchUrl) audioUrl = matchUrl[0];
      }
      var durSecs = m.duration || 0;
      var durLabel = typeof _formatAudioTime === 'function' ? _formatAudioTime(durSecs) : (durSecs > 0 ? (durSecs + 's') : 'Audio');

      div.style.background = 'transparent';
      div.style.padding = '2px';

      var playerWrap = document.createElement('div');
      playerWrap.className = 'msg-audio-player-wrapper';
      playerWrap.innerHTML = `
        <button type="button" class="msg-audio-play-btn">▶</button>
        <div class="msg-audio-body">
          <div class="msg-audio-track">
            <div class="msg-audio-fill"></div>
          </div>
          <div class="msg-audio-meta">
            <span>🎤 Audio</span>
            <span class="dur-txt">${durLabel}</span>
          </div>
        </div>
      `;

      var playBtn = playerWrap.querySelector('.msg-audio-play-btn');
      var fill = playerWrap.querySelector('.msg-audio-fill');
      var durTxt = playerWrap.querySelector('.dur-txt');
      var track = playerWrap.querySelector('.msg-audio-track');

      var audioInst = null;

      playBtn.onclick = function() {
        if (!audioUrl) {
          alert('⚠️ Archivo de audio no disponible.');
          return;
        }
        if (audioInst && !audioInst.paused) {
          audioInst.pause();
          playBtn.textContent = '▶';
          return;
        }

        if (!audioInst) {
          audioInst = new Audio(audioUrl);
          audioInst.onloadedmetadata = function() {
            if (audioInst.duration && isFinite(audioInst.duration)) {
              var realDur = Math.round(audioInst.duration);
              if (typeof _formatAudioTime === 'function') durTxt.textContent = _formatAudioTime(realDur);
            }
          };
          audioInst.onended = function() {
            playBtn.textContent = '▶';
            fill.style.width = '0%';
            if (durSecs > 0 && typeof _formatAudioTime === 'function') durTxt.textContent = _formatAudioTime(durSecs);
          };
          audioInst.ontimeupdate = function() {
            if (audioInst && audioInst.duration) {
              var pct = (audioInst.currentTime / audioInst.duration) * 100;
              fill.style.width = pct + '%';
              if (typeof _formatAudioTime === 'function') durTxt.textContent = _formatAudioTime(audioInst.currentTime);
            }
          };
        }

        if (typeof window._currentlyPlayingAudio !== 'undefined' && window._currentlyPlayingAudio && window._currentlyPlayingAudio !== audioInst) {
          window._currentlyPlayingAudio.pause();
        }
        window._currentlyPlayingAudio = audioInst;

        audioInst.play().then(function() {
          playBtn.textContent = '⏸';
        }).catch(function(e) {
          console.error("Playback failed:", e);
        });
      };

      track.onclick = function(e) {
        if (!audioInst) return;
        var rect = track.getBoundingClientRect();
        var pct = (e.clientX - rect.left) / rect.width;
        if (audioInst.duration) {
          audioInst.currentTime = pct * audioInst.duration;
        }
      };

      div.appendChild(playerWrap);
      box.appendChild(div);
      return;
    }

    // 3. Image / Video message handling
    if(m.img || m.type === 'IMAGE' || m.isVideo || (m.mediaUrl && (m.mediaUrl.includes('.jpg') || m.mediaUrl.includes('.png') || m.mediaUrl.includes('.jpeg') || m.mediaUrl.includes('.webp')))){
      var imgUrl = m.img || m.mediaUrl;
      div.style.padding='4px';div.style.background='transparent';
      if (m.isVideo) {
        div.innerHTML='<video src="'+imgUrl+'" controls style="width:180px;border-radius:var(--rad-sm);display:block;max-height:240px;"></video>';
      } else {
        div.innerHTML='<img src="'+imgUrl+'" onclick="openImageViewer(this.src)" style="width:160px;max-height:160px;border-radius:var(--rad-sm);object-fit:cover;display:block;cursor:zoom-in;"/>';
      }
      box.appendChild(div);return;
    }

    // 4. File attachment handling
    if (m.type === 'FILE' || (m.mediaUrl && !isAudio)) {
      var fileUrl = m.mediaUrl;
      div.style.padding = '8px 12px';
      div.innerHTML = '<div style="display:flex;align-items:center;gap:8px;"><span style="font-size:20px;">'+icon('link',18)+'</span><div><a href="' + fileUrl + '" target="_blank" style="color:#fff;text-decoration:underline;font-weight:600;font-size:var(--fs-sm);">' + (m.txt || 'Attachment') + '</a></div></div>';
      box.appendChild(div);return;
    }

    // 5. Game card handling
    if (m.type === 'GAME' || (m.txt && (m.txt.includes('This or That') || m.txt.includes('Truth or Dare') || m.txt.includes('2 Truths') || m.txt.includes('Would You Rather')))) {
      div.style.background = 'transparent';
      div.style.padding = '0';
      div.innerHTML = '<div class="msg-game-card"><div class="msg-game-badge">'+icon('dice',13)+' Icebreaker Game</div><div class="msg-game-title">' + _e(m.txt) + '</div></div>';
      box.appendChild(div);return;
    }

    // 6. Group message formatting
    if(!m.out&&isGrp){
      var txt=m.txt||'';var from=m.from||'';var body=txt;
      if(!from){var mt=txt.match(/^([^:@]{1,22}):\s+(.+)$/);if(mt){from=mt[1];body=mt[2];}}
      if(from){
        var h=_strHash(from+body);var col=COLS[_strHash(from)%COLS.length];
        var react='';if(h%2===0){react='<div style="display:inline-flex;align-items:center;gap:3px;background:rgba(255,255,255,0.12);border:1px solid var(--gbdl);border-radius:var(--rad-sm);padding:2px 7px;font-size:var(--fs-xs);font-weight:500;color:#fff;margin-top:4px;">'+RX[h%3]+' '+(2+(h%5))+'</div>';}
        var row=document.createElement('div');row.style.cssText='display:flex;gap:8px;align-items:flex-end;align-self:flex-start;max-width:84%;';
        row.innerHTML='<div style="width:28px;height:28px;border-radius:50%;background:'+col+';display:flex;align-items:center;justify-content:center;font-size:var(--fs-sm);font-weight:600;color:#fff;flex-shrink:0;">'+from.charAt(0).toUpperCase()+'</div><div><div class="msnd">'+_e(from)+'</div><div class="msg in" style="max-width:100%;">'+_e(body)+'</div>'+react+'</div>';
        box.appendChild(row);return;
      }
    }

    // 7. Plain text fallback
    div.textContent=m.txt||'';
    box.appendChild(div);
  });
  // Read receipt: "Sent" / "Seen · HH:MM" under YOUR last message, driven by the
  // real isRead/readAt from the backend — only shown while your message is the
  // newest thing in the thread.
  if(!isGrp && hist.length && hist[hist.length-1] && hist[hist.length-1].out){
    var _lastOut=hist[hist.length-1];
    var _outs=box.querySelectorAll('.msg.out');
    if(_outs.length){
      var _sn=document.createElement('div');
      _sn.className='msg-seen';
      if(_lastOut.isRead){
        var _seenTime=_lastOut.readAt?(new Date(_lastOut.readAt)).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'';
        _sn.innerHTML='<div style="font-size:var(--fs-2xs);color:var(--fg3);">Seen'+(_seenTime?(' · '+_seenTime):'')+'</div>';
      }else{
        _sn.innerHTML='<div style="font-size:var(--fs-2xs);color:var(--fg3);">Sent</div>';
      }
      box.appendChild(_sn);
    }
  }
  box.scrollTop=box.scrollHeight;
  console.log('[CHAT DEBUG] renderMsgs() finished, DOM children count in #cmsgs:', box.children.length);
}

// Fullscreen image viewer with zoom: wheel/pinch to zoom, drag/one-finger-pan
// when zoomed, click backdrop / Escape / × to close. Single shared overlay,
// reused across chat image taps and the shared-photos gallery.
function openImageViewer(url){
  if(!url) return;
  var old=document.getElementById('img-viewer-ov');
  if(old) old.remove();

  var ov=document.createElement('div');
  ov.id='img-viewer-ov';
  ov.style.cssText='position:fixed;inset:0;z-index:999999;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.92);overflow:hidden;touch-action:none;';
  ov.innerHTML='<div id="iv-close" style="position:absolute;top:calc(env(safe-area-inset-top) + 14px);right:16px;width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,0.12);display:flex;align-items:center;justify-content:center;cursor:pointer;color:#fff;font-size:20px;z-index:2;">✕</div>'+
    '<img id="iv-img" src="'+url+'" style="max-width:92vw;max-height:92vh;object-fit:contain;user-select:none;-webkit-user-drag:none;transform:translate(0px,0px) scale(1);transition:transform 0.15s ease-out;cursor:zoom-in;"/>';
  document.body.appendChild(ov);

  var img=document.getElementById('iv-img');
  var scale=1, panX=0, panY=0;
  var MIN=1, MAX=5;

  function apply(withTransition){
    img.style.transition=withTransition?'transform 0.15s ease-out':'none';
    img.style.transform='translate('+panX+'px,'+panY+'px) scale('+scale+')';
    img.style.cursor=scale>1?'grab':'zoom-in';
  }

  function close(){
    window.removeEventListener('keydown', onKey);
    ov.remove();
  }
  function onKey(e){ if(e.key==='Escape') close(); }
  window.addEventListener('keydown', onKey);

  document.getElementById('iv-close').onclick=close;
  ov.onclick=function(e){ if(e.target===ov) close(); };

  // Desktop: wheel to zoom around cursor, click-drag to pan once zoomed
  ov.addEventListener('wheel', function(e){
    e.preventDefault();
    var next=scale + (e.deltaY<0?0.25:-0.25);
    scale=Math.min(MAX, Math.max(MIN, next));
    if(scale===MIN){panX=0;panY=0;}
    apply(true);
  }, { passive:false });

  var dragging=false, dragStartX=0, dragStartY=0, panStartX=0, panStartY=0;
  img.addEventListener('mousedown', function(e){
    if(scale<=1) return;
    dragging=true; dragStartX=e.clientX; dragStartY=e.clientY; panStartX=panX; panStartY=panY;
    img.style.cursor='grabbing';
  });
  window.addEventListener('mousemove', function(e){
    if(!dragging) return;
    panX=panStartX+(e.clientX-dragStartX);
    panY=panStartY+(e.clientY-dragStartY);
    apply(false);
  });
  window.addEventListener('mouseup', function(){
    if(dragging){ dragging=false; apply(true); }
  });
  img.addEventListener('dblclick', function(){
    scale = scale>1 ? 1 : 2.5;
    if(scale===1){panX=0;panY=0;}
    apply(true);
  });

  // Mobile: pinch-to-zoom with two touches, one-finger pan when zoomed
  var touchMode=null, startDist=0, startScale=1, touchPanStartX=0, touchPanStartY=0, touchStartX=0, touchStartY=0;
  function touchDist(t){ return Math.hypot(t[0].clientX-t[1].clientX, t[0].clientY-t[1].clientY); }
  ov.addEventListener('touchstart', function(e){
    if(e.touches.length===2){
      touchMode='pinch';
      startDist=touchDist(e.touches);
      startScale=scale;
    } else if(e.touches.length===1 && scale>1){
      touchMode='pan';
      touchStartX=e.touches[0].clientX; touchStartY=e.touches[0].clientY;
      touchPanStartX=panX; touchPanStartY=panY;
    }
  }, { passive:true });
  ov.addEventListener('touchmove', function(e){
    if(touchMode==='pinch' && e.touches.length===2){
      e.preventDefault();
      var ratio=touchDist(e.touches)/startDist;
      scale=Math.min(MAX, Math.max(MIN, startScale*ratio));
      if(scale===MIN){panX=0;panY=0;}
      apply(false);
    } else if(touchMode==='pan' && e.touches.length===1){
      e.preventDefault();
      panX=touchPanStartX+(e.touches[0].clientX-touchStartX);
      panY=touchPanStartY+(e.touches[0].clientY-touchStartY);
      apply(false);
    }
  }, { passive:false });
  ov.addEventListener('touchend', function(e){
    if(e.touches.length===0){ touchMode=null; apply(true); }
  });
}

// Typing indicator: a dots bubble in-thread + restore the REAL subtitle (member
// names for groups) instead of clobbering it with a hardcoded "Online".
function _cwSetTyping(on){
  var sub=document.getElementById('cwsub');
  if(sub){
    if(on){ if(sub.dataset.base==null)sub.dataset.base=sub.textContent; sub.textContent='typing…'; }
    else if(sub.dataset.base!=null){ sub.textContent=sub.dataset.base; delete sub.dataset.base; }
  }
  var box=document.getElementById('cmsgs');if(!box)return;
  var ex=document.getElementById('cw-typing');
  if(on){
    if(!ex){var t=document.createElement('div');t.id='cw-typing';t.className='msg in typing-bubble';t.innerHTML='<span class="tdot"></span><span class="tdot"></span><span class="tdot"></span>';box.appendChild(t);box.scrollTop=box.scrollHeight;}
  }else if(ex){ex.remove();}
}
// "Today" / "Yesterday" / "Mon, 3 Jun" for date separators.
function _ugzDayLabel(ts){
  var d=new Date(ts), now=new Date();
  var a=new Date(d.getFullYear(),d.getMonth(),d.getDate());
  var b=new Date(now.getFullYear(),now.getMonth(),now.getDate());
  var diff=Math.round((b-a)/86400000);
  if(diff===0)return 'Today';
  if(diff===1)return 'Yesterday';
  return d.toLocaleDateString([],{weekday:'short',day:'numeric',month:'short'});
}
function sendMsg(){
  var rawInpValue = document.getElementById('cinp') ? document.getElementById('cinp').value : '';
  console.log('[CHAT DUPLICATE DEBUG] sendMsg() CALLED', {
    timestamp: new Date().toISOString(),
    curChatId: curChatId,
    inputValue: rawInpValue
  });
  try { console.trace('[CHAT DUPLICATE DEBUG] sendMsg() CALLED'); } catch(e) {}

  if (window._isSendingMsg) {
    console.warn('⚠️ sendMsg blocked: message sending already in progress');
    return;
  }
  window._isSendingMsg = true;
  setTimeout(function() { window._isSendingMsg = false; }, 600);

  var inp=document.getElementById('cinp');if(!inp||!inp.value.trim()){ window._isSendingMsg = false; return; }
  var txt=inp.value.trim();
  var txtLow=txt.toLowerCase();
  if(BANNED.some(function(w){return txtLow.includes(w);})){alert('Message contains restricted content.');inp.value=txt; window._isSendingMsg = false; return;}
  inp.value='';
  if (typeof _handleCinpInput==='function') _handleCinpInput();

  console.log('[CHAT DEBUG] SEND START');
  console.log('[CHAT DEBUG] current user ID:', _getCurrentUserId());
  console.log('[CHAT DEBUG] curChatId:', curChatId);
  console.log('[CHAT DEBUG] message content:', txt);

  if(!curChatId)return;
  if(!chatHistory[curChatId])chatHistory[curChatId]=[];
  
  var isDbMatch = (typeof apiClient !== 'undefined' && apiClient.getAccessToken() && !curChatId.startsWith('biz_') && !curChatId.startsWith('net_') && !curChatId.startsWith('clist-') && !curChatId.includes('moment'));
  
  debugChatState('sendMsg BEFORE PUSH', curChatId);
  chatHistory[curChatId].push({txt:txt,out:true,at:Date.now()});
  debugChatState('sendMsg AFTER PUSH', curChatId);
  console.log('[CHAT DEBUG] LOCAL MESSAGE INSERTED, local count in chatHistory[' + curChatId + ']:', chatHistory[curChatId].length);
  
  var _ib=document.getElementById('icebreaker-bar');if(_ib)_ib.style.display='none';
  
  if(typeof _bumpKindness==='function')_bumpKindness(1);
  if(typeof _blindMatchChats!=='undefined'&&curChatId in _blindMatchChats){
    _blindMatchChats[curChatId]++;
    if(_blindMatchChats[curChatId]>=3){
      var _cid=curChatId;
      delete _blindMatchChats[_cid];
      chatHistory[_cid].push({txt:'📸 Photos unlocked! You\'ve both opened up.',out:false});
      setTimeout(function(){if(typeof _blindRevealPrompt==='function')_blindRevealPrompt(_cid);},700);
    }
  }
  if(chatHistory[curChatId]._expires)delete chatHistory[curChatId]._expires;
  var _matchItem=document.getElementById('uc-match-'+curChatId) || document.getElementById('dm-match-'+curChatId);
  if(_matchItem){
    // Antes ponía "✅ Replied · ongoing chat" en TODOS los chats (glitch).
    // Ahora refleja el mensaje que acabas de mandar, estilo Instagram, y quita
    // el punto de no-leído.
    var _pre=_matchItem.querySelector('.cpre');
    if(_pre){_pre.classList.remove('cpre-unrd');_pre.innerHTML=(typeof _e==='function'?_e(txt):txt)+' <span class="cago">· now</span>';}
    var _dot=_matchItem.querySelector('.cdot');if(_dot)_dot.remove();
  }
  
  renderMsgs();
  
  if (isDbMatch) {
    apiClient.sendChatMessage(curChatId, txt).then(function(savedMsg) {
      console.log("[CHAT DEBUG] SERVER CONFIRMED MESSAGE, DB ID:", savedMsg ? savedMsg.id : 'N/A', savedMsg);
      if (savedMsg && savedMsg.id) {
        var local = chatHistory[curChatId] ? chatHistory[curChatId].find(function(m) { return !m.id && m.txt === txt && m.out; }) : null;
        if (local) local.id = savedMsg.id;
      }
    }).catch(function(err) {
      console.error("[CHAT DEBUG] SERVER REJECTED MESSAGE:", err);
      if (chatHistory[curChatId]) {
        debugChatState('sendMsg BEFORE REJECT FILTER', curChatId);
        chatHistory[curChatId] = chatHistory[curChatId].filter(function(m) { return m.txt !== txt || !m.out || m.id; });
        debugChatState('sendMsg AFTER REJECT FILTER', curChatId);
        renderMsgs();
      }
      if (typeof showToast === 'function') showToast('❌ Error al guardar el mensaje');
    });
    window._lastTypingState = false;
    apiClient.sendTypingStatus(curChatId, false);
  } else {
    setTimeout(function(){
      chatHistory[curChatId].push({txt:'Got it! 👍',out:false,at:Date.now()});
      renderMsgs();
    },1200);
  }
}
function _initCitemSwipeGestures() {
  var chatItems = document.querySelectorAll('.citem');
  chatItems.forEach(function(item) {
    if (item.dataset.swipeInitialized) return;
    item.dataset.swipeInitialized = 'true';

    var oldActions = item.querySelectorAll('.citem-actions');
    oldActions.forEach(function(el) { el.remove(); });

    var actionsWrap = document.createElement('div');
    actionsWrap.className = 'citem-actions';

    var btnPin = document.createElement('div');
    btnPin.className = 'citem-act-btn citem-act-pin';
    btnPin.innerHTML = icon('thumbtack',16);
    btnPin.title = 'Fijar';
    btnPin.onclick = function(e) { e.stopPropagation(); alert('📌 Chat fijado'); };

    var btnMute = document.createElement('div');
    btnMute.className = 'citem-act-btn citem-act-mute';
    btnMute.innerHTML = icon('ban',16);
    btnMute.title = 'Silenciar';
    btnMute.onclick = function(e) { e.stopPropagation(); alert('Chat silenciado'); };

    var btnFlag = document.createElement('div');
    btnFlag.className = 'citem-act-btn citem-act-flag';
    btnFlag.innerHTML = icon('flag',16);
    btnFlag.title = 'Reportar';
    btnFlag.onclick = function(e) { e.stopPropagation(); alert('🚩 Chat reportado'); };

    var btnClose = document.createElement('div');
    btnClose.className = 'citem-act-btn citem-act-close';
    btnClose.innerHTML = icon('x',16);
    btnClose.title = 'Cerrar';
    btnClose.onclick = function(e) {
      e.stopPropagation();
      item.style.transition = 'all 0.25s ease';
      item.style.height = item.offsetHeight + 'px';
      item.style.opacity = '0';
      item.style.transform = 'translateX(-100%)';
      setTimeout(function() { item.remove(); }, 250);
    };

    actionsWrap.appendChild(btnPin);
    actionsWrap.appendChild(btnMute);
    actionsWrap.appendChild(btnFlag);
    actionsWrap.appendChild(btnClose);
    item.appendChild(actionsWrap);

    var startX = 0, startY = 0, currentDx = 0, isDragging = false, isHorizontal = false, isOpen = false;
    var maxDx = 180;

    function getInnerElements() {
      return Array.from(item.children).filter(function(child) {
        return !child.classList.contains('citem-actions');
      });
    }

    function applyDragState(dx) {
      currentDx = Math.max(0, Math.min(maxDx, dx));
      actionsWrap.style.width = currentDx + 'px';
      if (currentDx > 5) {
        actionsWrap.classList.add('active');
      } else {
        actionsWrap.classList.remove('active');
      }

      var innerEls = getInnerElements();
      innerEls.forEach(function(el) {
        el.style.transform = 'translateX(' + (-currentDx) + 'px)';
      });
    }

    function setTransitions(on) {
      actionsWrap.style.transition = on ? 'width 0.25s cubic-bezier(0.16, 1, 0.3, 1)' : 'none';
      var innerEls = getInnerElements();
      innerEls.forEach(function(el) {
        el.style.transition = on ? 'transform 0.25s cubic-bezier(0.16, 1, 0.3, 1)' : 'none';
      });
    }

    function onStart(e) {
      isDragging = true;
      isHorizontal = false;
      var pt = e.touches ? e.touches[0] : e;
      startX = pt.clientX;
      startY = pt.clientY;
      setTransitions(false);
    }

    function onMove(e) {
      if (!isDragging) return;
      var pt = e.touches ? e.touches[0] : e;
      var diffX = startX - pt.clientX;
      var diffY = Math.abs(startY - pt.clientY);

      if (!isHorizontal) {
        if (Math.abs(diffX) > 6 && Math.abs(diffX) > diffY) {
          isHorizontal = true;
        } else if (diffY > 10) {
          isDragging = false;
          return;
        }
      }

      if (isHorizontal) {
        if (e.cancelable) e.preventDefault();
        var totalDiff = diffX + (isOpen ? maxDx : 0);
        applyDragState(totalDiff);
      }
    }

    function onEnd() {
      if (!isDragging && !isHorizontal) return;
      isDragging = false;
      setTransitions(true);

      if (currentDx > 85) {
        isOpen = true;
        applyDragState(maxDx);
      } else {
        isOpen = false;
        applyDragState(0);
      }
    }

    item.addEventListener('touchstart', onStart, { passive: true });
    item.addEventListener('touchmove', onMove, { passive: false });
    item.addEventListener('touchend', onEnd, { passive: true });
    item.addEventListener('mousedown', onStart);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onEnd);
  });
}

document.addEventListener('DOMContentLoaded', function() {
  setTimeout(_initCitemSwipeGestures, 500);
});
setInterval(_initCitemSwipeGestures, 1500);

