// ── DAILY UNICRUSH PICKS (a fresh curated set each day; resets at midnight) ──
// 🎯 LOOKING FOR — deterministic intent set per profile (dating/friends/study/events)
var _LF_KEYS=['dating','friends','study','events'];
function _profileLookingFor(p){
  if(p.lookingFor)return p.lookingFor;// user-chosen (self)
  if(p._lf)return p._lf;
  var h=_strHash((p.name||'')+'lf');
  var primary=_LF_KEYS[h%4];var set=[primary];
  var sec=_LF_KEYS[Math.floor(h/4)%4];if(sec!==primary&&h%3===0)set.push(sec);
  if(set.indexOf('dating')===-1&&set.indexOf('friends')===-1&&h%2===0)set.push('friends');
  p._lf=set;return set;
}
// ♌ Zodiac for a profile (sample profiles get a deterministic sign)
function _profileZodiac(p){
  if(p.zodiac)return {s:p.zodiac,e:p.zodiacEmoji||''};
  if(p._z)return p._z;
  var sign=ZODIAC_SIGNS[_strHash((p.name||'')+'z')%12];
  p._z={s:sign[0],e:sign[1]};return p._z;
}
// 🟢 Green flags
var GREEN_FLAGS=['💬 Communicates','👂 Good listener','🤝 Loyal','🚀 Ambitious','😂 Actually funny','❤️ Emotionally available','🧭 Adventurous','🙏 Kind to staff','⏱️ Texts back','🌱 Plant/pet parent','🥡 Labels the leftovers','🙏 Low drama'];
function _profileGreenFlags(p){
  if(p.greenFlags)return p.greenFlags;
  if(p._gf)return p._gf;
  var h=_strHash((p.name||'')+'gf');var out=[];var n=2+(h%2);// 2-3 flags
  for(var i=0;i<n;i++){var f=GREEN_FLAGS[(h+i*5)%GREEN_FLAGS.length];if(out.indexOf(f)===-1)out.push(f);}
  p._gf=out;return out;
}
// ⚔️ This-or-that picks (uses the campus-poll tot items). Returns [{id,q,opt:{l,e},idx}]
function _totPolls(){return (typeof POLLS!=='undefined'?POLLS:[]).filter(function(p){return p.type==='tot';});}
function _profileTOT(p){
  if(p.tot)return p.tot;// the signed-in user's own picks
  if(p._tot)return p._tot;
  var out={};
  _totPolls().forEach(function(poll){out[poll.id]=_strHash((p.name||'')+poll.id)%poll.opts.length;});
  p._tot=out;return out;
}
function _myTOT(){return (userPro&&userPro.tot)||{};}
// shared this-or-that picks between me and a profile → array of labels
function _sharedTOT(p){
  var mine=_myTOT(),theirs=_profileTOT(p),shared=[];
  _totPolls().forEach(function(poll){if(mine[poll.id]!=null&&mine[poll.id]===theirs[poll.id]){var o=poll.opts[theirs[poll.id]];shared.push(o.e+' '+o.l);}});
  return shared;
}
// ── LOVE LANGUAGE / WORKOUT / DIET / ANTHEM / FREE-WEEKEND ──
var LOVE_LANGS=['💬 Words of affirmation','Quality time','🎁 Gifts','🤝 Acts of service','🤗 Physical touch'];
var WORKOUTS=['🏋️ Gym rat','🏃 Runner','⚽ Sports','🙏 Yoga/Pilates','🚶 Casual mover','🛋️ Not my thing'];
var POLITICS_OPTS=['Liberal','Moderate','Conservative','Apolitical'];
var DRINK_OPTS=['Non-drinker','Social drinker','Regular drinker'];
var SMOKE_OPTS=['Non-smoker','Socially','Regularly','Vape'];
function _profileWorkoutDisplay(p,isSelf){var w=isSelf?p.workout:_profileWorkout(p);if(Array.isArray(w))return w.join(', ');return w;}
var DIETS=['🍽️ Anything','🥗 Vegetarian','🌱 Vegan','☪️ Halal','✡️ Kosher','🌾 Gluten-free'];
// small stand-in catalog for the "anthem" picker (real app: Spotify Search API)
function _profileLoveLang(p){if(p.loveLanguage)return p.loveLanguage;if(p._ll)return p._ll;p._ll=LOVE_LANGS[_strHash((p.name||'')+'ll')%LOVE_LANGS.length];return p._ll;}
