// 📸 Photo verification — selfie-pose verified badge
function _profilePhotoVerified(p){if(p===userPro||p&&p.isSelf)return !!userPro.photoVerified;if(typeof p.photoVerified==='boolean')return p.photoVerified;return (_strHash((p.name||'')+'pv')%2===0);}
// 🌙 Out right now — live "let's link up tonight" status
