// 💞 ONE compatibility number per card, fusing interests + zodiac + love language + this-or-that
function _megaCompat(p){
  var score=0,maxw=0;
  var ic=(typeof _personalityCompat==='function')?_personalityCompat(p):null;
  if(ic&&ic.pct!=null){score+=(ic.pct/100)*35;maxw+=35;}
  var myZ=userPro&&userPro.zodiac;var tz=_profileZodiac(p);var zc=myZ?_zodiacCompat(myZ,tz.s):null;
  if(zc!=null){score+=zc*20;maxw+=20;}
  var myLL=userPro&&userPro.loveLanguage;
  if(myLL){score+=(myLL===_profileLoveLang(p)?1:0.45)*20;maxw+=20;}
  var st=_sharedTOT(p).length;var totN=Math.min(4,_totPolls().length||1);
  score+=Math.min(1,st/totN)*25;maxw+=25;
  var qm=_quizMatchCount(p);if(qm){score+=(qm.hits/qm.tot)*30;maxw+=30;}
  var myFa=userPro&&userPro.faith;
  if(myFa){var ti=FAITH_LEVELS.indexOf(_profileFaith(p)),mi=FAITH_LEVELS.indexOf(myFa);if(mi>-1&&ti>-1){var fd=Math.abs(mi-ti);score+=(fd===0?1:fd===1?0.6:0.25)*15;maxw+=15;}}
  var myHT=userPro&&userPro.hotTakes;
  if(myHT){var hk=0,htot=0;Object.keys(myHT).forEach(function(idx){htot++;if(_profileHotTake(p,parseInt(idx))===myHT[idx])hk++;});if(htot){score+=(hk/htot)*20;maxw+=20;}}
  var detBase=72+(_strHash((p.name||'')+'mc')%20);// believable 72–91 baseline
  var pct=maxw?Math.round(0.55*(score/maxw*100)+0.45*detBase):detBase;
  return {pct:Math.max(50,Math.min(99,pct))};
}
