function selectPayMethod(type, el) {
  var row = document.getElementById('pay-method-row');
  if (row) {
    var items = row.querySelectorAll('.pay-method');
    items.forEach(function(item) { item.classList.remove('sel'); });
  }
  if (el) el.classList.add('sel');
  
  var fieldsWrap = document.getElementById('pay-card-fields-wrap');
  var ctaBtn = document.getElementById('pay-cta');
  
  if (type === 'apple' || type === 'google') {
    if (fieldsWrap) fieldsWrap.style.display = 'none';
    if (ctaBtn) {
      if (type === 'apple') {
        ctaBtn.innerHTML = '<i class="fa-brands fa-apple-pay" style="font-size:var(--fs-xl);vertical-align:middle;margin-right:6px;"></i> Pay with Apple Pay';
        ctaBtn.style.background = '#000';
      } else {
        ctaBtn.innerHTML = '<i class="fa-brands fa-google-pay" style="font-size:var(--fs-xl);vertical-align:middle;margin-right:6px;"></i> Pay with Google Pay';
        ctaBtn.style.background = '#000';
      }
    }
  } else {
    if (fieldsWrap) fieldsWrap.style.display = 'block';
    if (ctaBtn) {
      ctaBtn.innerHTML = '🔒 Unlock A+ Now';
      ctaBtn.style.background = 'linear-gradient(90deg,#9e1b1b,#791515 55%,#fb923c)';
    }
  }
}

function formatPayExpInput(el) {
  if (!el) return;
  var raw = el.value;
  var digits = raw.replace(/\D/g, '').slice(0, 4);
  if (digits.length === 0) {
    el.value = '';
    return;
  }
  if (digits.length === 1) {
    if (parseInt(digits, 10) > 1) {
      el.value = '0' + digits + ' / ';
    } else {
      el.value = digits;
    }
    return;
  }
  var month = parseInt(digits.slice(0, 2), 10);
  if (month > 12) month = 12;
  if (month === 0) month = 1;
  var monthStr = (month < 10 ? '0' : '') + month;

  if (digits.length >= 2) {
    el.value = monthStr + ' / ' + digits.slice(2);
  }
}

function selectCardType(type) {
  var targetId = 'pct-' + type;
  var el = document.getElementById(targetId);
  if (el) selectPayMethod(type, el);
}

function processPayment() {
  var selectedMethod = document.querySelector('#pay-method-row .pay-method.sel');
  var isDigitalPay = selectedMethod && (selectedMethod.id === 'pct-apple' || selectedMethod.id === 'pct-google');
  var m = document.getElementById('payment-modal');
  var isBiz = m && m.dataset.bizLaunch === '1';

  if (!isDigitalPay) {
    var nameEl = document.getElementById('pay-name');
    var numEl = document.getElementById('pay-num');
    var expEl = document.getElementById('pay-exp');
    var cvvEl = document.getElementById('pay-cvv');

    var name = nameEl ? nameEl.value.trim() : '';
    var num = numEl ? numEl.value.replace(/\s/g, '') : '';
    var exp = expEl ? expEl.value.trim() : '';
    var cvv = cvvEl ? cvvEl.value.trim() : '';

    if (!name || !num || !exp || !cvv) {
      alert('⚠️ Por favor completa todos los campos del pago.');
      return;
    }

    if (num.length < 15 || num.length > 16) {
      alert('⚠️ Ingresa un número de tarjeta válido de 16 dígitos.');
      if (numEl) numEl.focus();
      return;
    }

    var expParts = exp.split('/');
    if (expParts.length < 2 || !expParts[1].trim()) {
      alert('⚠️ Ingresa una fecha de expiración válida (MM / YY).');
      if (expEl) expEl.focus();
      return;
    }
    var month = parseInt(expParts[0].trim(), 10);
    var year = parseInt(expParts[1].trim(), 10);

    if (isNaN(month) || month < 1 || month > 12) {
      alert('⚠️ El mes de expiración debe estar entre 01 y 12.');
      if (expEl) expEl.focus();
      return;
    }

    if (year < 100) year += 2000;
    var now = new Date();
    var curYear = now.getFullYear();
    var curMonth = now.getMonth() + 1;

    if (year < curYear || (year === curYear && month < curMonth)) {
      alert('⚠️ La tarjeta ingresada ha expirado.');
      if (expEl) expEl.focus();
      return;
    }

    if (cvv.length < 3 || cvv.length > 4) {
      alert('⚠️ Ingresa un CVV válido (3 o 4 dígitos).');
      if (cvvEl) cvvEl.focus();
      return;
    }

    if (name.length < 3) {
      alert('⚠️ Ingresa el nombre completo del titular de la tarjeta.');
      if (nameEl) nameEl.focus();
      return;
    }
  }

  if (m) {
    m.classList.remove('open');
    m.dataset.bizLaunch = '';
  }
  if (curPayPlan === 'cheat') {
    alert('Purchase complete! Your boost is now active.');
    return;
  }
  // Remember the state to roll back to: the purchase is applied locally first so
  // the UI reacts immediately, but the server can still refuse it (a downgrade
  // while a longer plan is running comes back as 409).
  var _prevPlan = curPlan, _prevPeriod = curPlanPeriod, _prevEnds = curPlanEnds;
  curPlan = curPayPlan;
  if (curPayPlan === 'aplus') curPlanPeriod = _aplusBillSel;
  if (typeof _applyPlanLocks === 'function') _applyPlanLocks();
  if (curPayPlan === 'silver' || curPayPlan === 'gold' || curPayPlan === 'aplus') userDatingTier = curPayPlan;
  if (isBiz) {
    alert('Business account activated!\n\nWelcome to Undrgradz.');
    if (typeof launch === 'function') launch();
    return;
  }
  var sp = document.getElementById('settings-plan');
  if (sp) sp.textContent = curPlan;

  // The celebration modal fires only once the server actually confirms the
  // purchase — showing it right away (as this used to) meant a 409 rejection
  // (e.g. trying to downgrade mid-term) landed a contradicting error alert
  // right after "you're now subscribed!".
  function _celebrateSubscription() {
    var planLabel = (curPayPlan === 'aplus' && typeof _APLUS_BILL !== 'undefined' && _APLUS_BILL[curPlanPeriod])
      ? _APLUS_BILL[curPlanPeriod].name
      : (curPayPlan ? curPayPlan.charAt(0).toUpperCase() + curPayPlan.slice(1) : 'Premium');
    var renewsLabel = (typeof _planEndsLabel === 'function') ? _planEndsLabel() : '';
    var isEs = window.currentLang === 'es';
    var title = isEs ? '¡Ya eres ' + planLabel + '!' : "You're " + planLabel + ' now!';
    var message = renewsLabel
      ? (isEs ? 'Tu membresía está activa y se renueva el ' + renewsLabel + '.\n\nDisfruta tus nuevas funciones.'
              : 'Your membership is active and renews on ' + renewsLabel + '.\n\nEnjoy your new features.')
      : (isEs ? 'Tu membresía ya está activa. Disfruta tus nuevas funciones.'
              : 'Your membership is now active. Enjoy your new features.');
    if (window.ugzModal && typeof window.ugzModal.subscribed === 'function') {
      window.ugzModal.subscribed({ title: title, message: message });
    } else {
      alert(title + '\n\n' + message);
    }
  }

  if (curPayPlan !== 'cheat' && typeof apiClient !== 'undefined') {
    var _period = (curPayPlan === 'aplus') ? _aplusBillSel : null;
    apiClient.purchasePremium(curPayPlan.toUpperCase(), _period).then(function(data) {
      // Take the expiry and period from the server rather than recomputing them
      // here — it owns the duration table.
      if (data) {
        if (data.subscriptionPeriod) curPlanPeriod = data.subscriptionPeriod;
        if (data.subscriptionEnds) curPlanEnds = new Date(data.subscriptionEnds);
      }
      if (typeof showPlansForGender === 'function') showPlansForGender();
      if (typeof loadCrushFeed === 'function') loadCrushFeed();
      if (typeof fetchAndRenderHangouts === 'function') fetchAndRenderHangouts();
      _celebrateSubscription();
    }).catch(function(e) {
      console.error("DB update failed", e);
      curPlan = _prevPlan; curPlanPeriod = _prevPeriod; curPlanEnds = _prevEnds;
      if (typeof _applyPlanLocks === 'function') _applyPlanLocks();
      if (typeof showPlansForGender === 'function') showPlansForGender();
      if (typeof ugzAlert === 'function') {
        ugzAlert(e && e.status === 409
          ? 'No se pudo cambiar de plan: ' + e.message
          : 'No se pudo completar la compra: ' + ((e && e.message) ? e.message : 'error'));
      }
    });
  } else {
    // No network path available (e.g. apiClient not loaded) — fall back to an
    // immediate celebration rather than silently doing nothing.
    _celebrateSubscription();
  }
}

function showPremiumForMode(){var sec=document.getElementById('sec-premium');if(!sec)return;var mode=obMode||userMode||'student';
  // Update hero subtitle for alumni
  if(mode==='alumni'){var ph=sec.querySelector('.pp2');if(ph)ph.textContent='One plan. All alumni filters. $29.99/yr.';}
  if(mode==='business'){sec.innerHTML='<div style="padding:20px var(--s);"><div class="phero" style="background:linear-gradient(135deg,#b45309,#92400e);margin:0 0 14px;"><div class="ph2">Upgrade Your Plan</div><div class="pp2">Reach more students across campus.</div></div><div class="plan-tabs" id="biz-plan-tabs"><button class="plan-tab on" id="bptab-mo" onclick="setBizPlanTab(\'mo\')" style="background:var(--p);">Monthly</button><button class="plan-tab" id="bptab-yr" onclick="setBizPlanTab(\'yr\')">Yearly</button></div><div style="background:rgba(255,255,255,0.07);border:1px solid var(--gbdl);border-radius:var(--r);padding:16px;margin-bottom:11px;"><div style="font-size:var(--fs-lg);font-weight:900;color:#fff;margin-bottom:4px;">Starter</div><div style="font-size:var(--fs-2xl);font-weight:900;color:#fff;margin-bottom:10px;" id="biz-starter-price">$49<span class="t-body">/mo</span></div><div class="plf hi">1 event/mo</div><div class="plf hi">1 university</div><button class="gbtn" style="background:var(--p);margin-top:10px;" onclick="openPayment(\'biz_starter\',\'$49\',\'Starter\')">Upgrade to Starter</button></div><div style="border:1.5px solid var(--p);border-radius:var(--r);padding:16px;background:rgba(61,123,255,0.06);"><div style="font-size:var(--fs-lg);font-weight:900;color:#fff;margin-bottom:4px;">Campus Pack</div><div style="font-size:var(--fs-2xl);font-weight:900;color:#fff;margin-bottom:10px;" id="biz-campus-price">$149<span class="t-body">/mo</span></div><div class="plf hi">Unlimited events</div><div class="plf hi">All universities</div><div class="plf hi">Analytics</div><button class="gbtn" style="background:var(--p);margin-top:10px;" onclick="openPayment(\'biz_campus\',\'$149\',\'Campus Pack\')">Upgrade to Campus Pack</button></div></div>';}}

