// ── USER POPUP ──
function openUserPopup(user){
  popupCurrentUser=user;
  var m=document.getElementById('user-profile-modal');
  if(m)m.classList.add('open');
  
  if (typeof apiClient !== 'undefined' && user) {
    var targetId = user.id || user.handle || user.name;
    if (targetId) {
      apiClient.recordProfileView(targetId);
    }
  }
  
  // Resolve viewed user's university colors
  var targetUni = null;
  var foundUser = null;
  if (typeof crushDataAll !== 'undefined' && crushDataAll) {
    foundUser = crushDataAll.find(function(x) {
      return x.handle === user.handle || x.name === user.name;
    });
  }
  if (foundUser && foundUser.uni) {
    targetUni = foundUser.uni;
  }
  if (!targetUni && typeof UNI !== 'undefined' && user.university) {
    for (var d in UNI) {
      if (UNI[d] && UNI[d].name === user.university) {
        targetUni = UNI[d];
        break;
      }
    }
  }
  
  var pCol = targetUni ? targetUni.p : (uni ? uni.p : '#3d7bff');
  var pCol2 = targetUni ? (targetUni.p2 || targetUni.p) : (uni ? uni.p2 : '#3d7bff');
  
  var avEl=document.getElementById('popup-av');
  if(avEl){
    var uPhoto = (user.photos && user.photos[0] && (user.photos[0].url || user.photos[0])) || user.photo || user.avatarUrl || (foundUser && foundUser.photos && foundUser.photos[0]);
    if(uPhoto) {
      avEl.textContent='';
      avEl.style.backgroundImage='url('+uPhoto+')';
      avEl.style.backgroundSize='cover';
      avEl.style.backgroundPosition='center';
    } else {
      avEl.textContent=(user.name||'U').charAt(0);
      avEl.style.backgroundImage='';
      avEl.style.background=pCol;
    }
  }
  var bBg=document.getElementById('popup-banner-bg');
  if(bBg) {
    bBg.style.background='linear-gradient(135deg,'+pCol+','+pCol2+')';
  }
  var hEl=document.getElementById('popup-handle');
  if(hEl)hEl.textContent=user.handle||'@user';
  var nEl=document.getElementById('popup-fullname');
  if(nEl)nEl.textContent=user.name||'';
  var dEl=document.getElementById('popup-details');
  if(dEl)dEl.textContent=[user.major,user.grad].filter(Boolean).join(' · ');
  var bioEl=document.getElementById('popup-bio');
  if(bioEl)bioEl.textContent=user.bio||'';
  var chips=document.getElementById('popup-chips');
  if(chips){
    chips.innerHTML='';
    if(user.major)chips.innerHTML+='<span class="tag">'+user.major+'</span>';
    if(user.org)chips.innerHTML+='<span class="tag hi">🔱 '+user.org+'</span>';
  }
  var intEl=document.getElementById('popup-interests');
  if(intEl)intEl.innerHTML=(user.interests||[]).slice(0,8).map(function(i){return '<div class="cpill on">'+i+'</div>';}).join('');
  var fbtn=document.getElementById('popup-friend-btn');
  if(fbtn){
    fbtn.textContent='Add Friend +';
    fbtn.style.background=pCol;
    fbtn.disabled=false;
  }
}
function addFriendPopup(){
  // Close user popup and open friend request modal
  var um=document.getElementById('user-profile-modal');if(um)um.classList.remove('open');
  var toHandle=popupCurrentUser?(popupCurrentUser.handle||'@user'):'@user';
  // Populate modal with current user's pic and target
  var myAv=document.getElementById('freq-my-av');
  if(myAv){
    myAv.textContent=(userPro.name||'U').charAt(0);
    myAv.style.background=uni?uni.p:'#3d7bff';
    if(_profilePicUrl){myAv.style.backgroundImage='url('+_profilePicUrl+')';myAv.style.backgroundSize='cover';myAv.style.backgroundPosition='center';myAv.textContent='';}
    else{myAv.style.backgroundImage='';}
  }
  var myH=document.getElementById('freq-my-handle');if(myH)myH.textContent=userPro.handle||'@you';
  var toEl=document.getElementById('friend-req-to');if(toEl)toEl.textContent=toHandle;
  var msgEl=document.getElementById('friend-req-msg');if(msgEl)msgEl.value='';
  var modal=document.getElementById('friend-req-modal');if(modal)modal.classList.add('open');
}
function sendFriendRequest(){
  var toEl=document.getElementById('friend-req-to');var to=toEl?toEl.textContent:'@user';
  var modal=document.getElementById('friend-req-modal');if(modal)modal.classList.remove('open');
  var fbtn=document.getElementById('popup-friend-btn');if(fbtn){fbtn.textContent='✅ Request Sent';fbtn.disabled=true;fbtn.style.background='#16a34a';}
  setTimeout(function(){alert('Friend request sent to '+to+'!');},150);
}
async function msgPopup() {
  var m = document.getElementById('user-profile-modal');
  if (m) m.classList.remove('open');
  var u = popupCurrentUser;
  if (!u) return;
  
  if (u.id) {
    try {
      const result = await apiClient.createConversation(u.id);
      const matchId = result.matchId;
      var bg = (u.profile && u.profile.customization && u.profile.customization.badgeColor) || (uni ? uni.p : '#3d7bff');
      var init = (u.name || 'U').charAt(0).toUpperCase();
      openChat(matchId, u.name || '@user', bg, init, false, ['Say hi! 👋'], false);
      if (typeof fetchAndRenderChats === 'function') fetchAndRenderChats();
    } catch (err) {
      console.error("Failed to start conversation via profile popup:", err);
      openChat((u.handle || 'user').replace('@', ''), u.handle || '@user', uni ? uni.p : '#3d7bff', (u.name || 'U').charAt(0), false, ['Say hi! 👋'], false);
    }
  } else {
    openChat((u.handle || 'user').replace('@', ''), u.handle || '@user', uni ? uni.p : '#3d7bff', (u.name || 'U').charAt(0), false, ['Say hi! 👋'], false);
  }
}
var _curChatUser=null;
// ── Relationship actions on someone else's profile ────────────────────────
// Which bar shows depends on WHERE the profile was opened from:
//   'deck' (default) → the swipe bar (pass / super like / like), unchanged
//   'search' | 'chat' → relationship actions, because you looked this person up
//                       on purpose; judging them like a candidate makes no sense.
// The origin travels on window._ucViewUser.origin.

function _ensureFriendsCache() {
  if (window._myFriendsCache || window._friendsCacheLoading) return;
  if (typeof apiClient === 'undefined' || !apiClient.getAccessToken()) return;
  window._friendsCacheLoading = true;
  apiClient.getFriends().then(function (fr) {
    window._myFriendsCache = fr;
    window._friendsCacheLoading = false;
    // The bar may already be on screen — repaint it now that we know.
    if (document.getElementById('uc-relation-bar')) _applyUcActionBar();
  }).catch(function () { window._friendsCacheLoading = false; });
}

// The friends cache ships in two different shapes depending on which endpoint
// filled it ({...} vs {friend:{...}}), so unwrap defensively.
function _isFriend(name) {
  if (!name) return false;
  var c = window._myFriendsCache;
  if (!c || !c.length) return false;
  var target = String(name).trim().toLowerCase().replace('@', '');
  for (var i = 0; i < c.length; i++) {
    var o = (c[i] && c[i].friend) ? c[i].friend : c[i];
    if (!o) continue;
    var full = ((o.firstName || '') + ' ' + (o.lastName || '')).trim().toLowerCase();
    var h = String(o.handle || '').replace('@', '').toLowerCase();
    var nm = String(o.name || '').trim().toLowerCase();
    if ((full && full === target) || (h && h === target) || (nm && nm === target)) return true;
  }
  return false;
}

// ══ Shared "coloured gradient" button skin ══
// The A+ / Cheats / Invite tab recipe, factored out so the relationship bar and
// the university scope buttons use the exact same look instead of three copies.
//   on  → bright hue→dark fill, a lighter gradient on the edge, halo, white label
//   off → the same gradient dimmed nearly to black, hue label, no halo
// Rounded corners rule out border-image, so the edge is a second background
// painted on the border box while the fill sits on the padding box.
// The glow uses color-mix rather than appending '66' to the hex, because `color`
// may arrive as var(--p) (the university colour), and var()+'66' is not a colour.
// opts.dim (0-100) tones the selected fill down without touching the edge or the
// halo, so a button can read calmer while keeping its neon outline. 100 is the
// full-strength default: color-mix(C 100%, #000) is C, so nothing changes.
function _gradSkin(color, on, opts) {
  opts = opts || {};
  var radius = opts.radius || 'var(--rad-md)';
  if (on) {
    var dim = opts.dim == null ? 100 : opts.dim;
    var fill = opts.grad || ('linear-gradient(135deg,'
      + ' color-mix(in srgb, ' + color + ' ' + dim + '%, #000) 0%,'
      + ' color-mix(in srgb, ' + color + ' ' + Math.round(dim * 0.4) + '%, #000) 100%)');
    // Solo el relleno. El estado seleccionado llevaba encima un borde pintado
    // con border-box que terminaba en color-mix(hue 35%, #fff): a tamaño de
    // botón eso no se lee como brillo sino como un filo claro alrededor. Se
    // pidió quitarlo cuatro veces seguidas sobre elementos distintos (VER TODOS,
    // las subpestañas, los chips de género, los de año), así que deja de ser una
    // excepción y pasa a ser la norma. Se van con él el halo y el text-shadow.
    //
    // El borde se queda declarado en transparent: mantenerlo significa que un
    // botón que alterna entre los dos estados nunca cambia de tamaño.
    return 'border-radius:' + radius + ';border:1.5px solid transparent;'
      + 'background:' + fill + ';color:#fff;box-shadow:none;text-shadow:none;';
  }
  return 'border-radius:' + radius + ';'
    + 'background:linear-gradient(135deg, color-mix(in srgb, ' + color + ' 22%, #000) 0%, #000 100%);'
    + 'border:1px solid color-mix(in srgb, ' + color + ' 40%, transparent);'
    + 'color:' + color + ';';
}

// Drawn in the unselected state — dark fill, hue on the outline and on the label
// — because none of these is a "current" choice; they are three actions offered
// side by side. Keeps the pill radius asked for earlier.
function _relBtn(label, hue, onclick) {
  return '<button onclick="' + onclick + '" style="flex:1;min-width:0;padding:12px 8px;' +
    _gradSkin(hue, false, { radius: 'var(--rad-pill)' }) +
    'font-family:var(--font);font-size:var(--fs-sm);font-weight:700;cursor:pointer;white-space:nowrap;">' + label + '</button>';
}

// Blocked people are remembered by name so the button can show the inverse
// action. No backend endpoint exists for blocking yet, so this is device-local.
window._blockedProfiles = window._blockedProfiles || {};
function _isBlockedProfile(name) {
  return !!(name && window._blockedProfiles[String(name).trim().toLowerCase()]);
}

function _relationBarHtml(name) {
  _ensureFriendsCache();
  var safe = String(name || '').replace(/'/g, "\\'");
  var friend = _isFriend(name);
  // A friendly PRIMARY action (Message if you're friends, Add Friend if not),
  // with the destructive/safety actions tucked behind a "•••" menu — instead of
  // a bar made only of red buttons.
  var primary = friend
    ? '<button onclick="_msgFromProfile(\''+safe+'\')" style="flex:2;min-width:0;padding:14px 10px;border-radius:var(--rad-pill);border:none;background:linear-gradient(135deg,var(--uni-accent,#22c55e),color-mix(in srgb, var(--uni-accent,#22c55e) 55%, #000));color:#fff;font-family:var(--font);font-size:var(--fs-base);font-weight:800;cursor:pointer;box-shadow:0 4px 18px color-mix(in srgb, var(--uni-accent,#22c55e) 40%, transparent);display:flex;align-items:center;justify-content:center;gap:7px;">💬 Message</button>'
    : '<button onclick="_addFriendProfile(\''+safe+'\')" style="flex:2;min-width:0;padding:14px 10px;border-radius:var(--rad-pill);border:none;background:linear-gradient(135deg,#22c55e,#16a34a);color:#fff;font-family:var(--font);font-size:var(--fs-base);font-weight:800;cursor:pointer;box-shadow:0 4px 18px rgba(34,197,94,0.35);display:flex;align-items:center;justify-content:center;gap:7px;">＋ Add Friend</button>';
  var more = '<button onclick="_profileMoreSheet(\''+safe+'\')" aria-label="More options" style="flex:0 0 auto;width:52px;padding:14px 0;border-radius:var(--rad-pill);background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.16);color:#fff;font-size:var(--fs-lg);font-weight:800;cursor:pointer;display:flex;align-items:center;justify-content:center;">•••</button>';
  return '<div id="uc-relation-bar" style="display:flex;gap:10px;padding:16px var(--s) calc(14px + env(safe-area-inset-bottom));border-top:none;background:linear-gradient(180deg, transparent, rgba(0,0,0,0.9) 40%);flex-shrink:0;">' + primary + more + '</div>';
}
function _msgFromProfile(name){
  try{ if(window.NavigationManager && typeof window.NavigationManager.goBack==='function') window.NavigationManager.goBack(); }catch(e){}
  if(typeof sw==='function') sw('chats','Chats');
}
// The "•••" overflow: Report / Block / Unfriend, in an iOS-style action sheet.
function _profileMoreSheet(name){
  var safe=String(name||'').replace(/'/g,"\\'");
  var friend=(typeof _isFriend==='function')&&_isFriend(name);
  var blocked=(typeof _isBlockedProfile==='function')&&_isBlockedProfile(name);
  var m=document.createElement('div');m.id='profile-actions-sheet';m.className='mov open';m.style.zIndex='10000';m.onclick=function(){_closeProfileActions();};
  m.innerHTML='<div class="ig-sheet" onclick="event.stopPropagation();">'+
    '<div class="ig-sheet-grp">'+
      (friend?'<button class="ig-act" onclick="_closeProfileActions();_unfriendProfile(\''+safe+'\')">Unfriend</button>':'')+
      '<button class="ig-act" onclick="_closeProfileActions();_toggleBlockProfile(\''+safe+'\')">'+(blocked?'Unblock':'Block')+'</button>'+
      '<button class="ig-act" style="color:#dc2626;" onclick="_reportProfile(\''+safe+'\')">Report</button>'+
    '</div>'+
    '<div class="ig-sheet-grp"><button class="ig-act bold" onclick="_closeProfileActions()">Cancel</button></div>'+
  '</div>';
  document.body.appendChild(m);
}

// Block/unblock toggle. Blocking still runs the existing _blockProfile() side
// effects (dropping them from the decks); unblocking only clears the flag,
// since those decks refill on their own.
function _toggleBlockProfile(name) {
  var k = String(name || '').trim().toLowerCase();
  if (_isBlockedProfile(name)) {
    delete window._blockedProfiles[k];
    if (typeof ugzAlert === 'function') ugzAlert(name + ' ya no está bloqueado.');
  } else {
    window._blockedProfiles[k] = true;
    if (typeof _blockProfile === 'function') { try { _blockProfile(name); } catch (e) {} }
  }
  _refreshRelationBars(name);
}

// Both places the bar can live: the full-screen card and the details sheet.
function _refreshRelationBars(name) {
  if (document.getElementById('uc-action-bar')) _applyUcActionBar();
  var det = document.getElementById('crush-details-relbar');
  if (det) det.innerHTML = _relationBarHtml(name);
}

// Bottom strip for a profile opened from Likes Sent. The like / super-like /
// pass buttons make no sense there — the like is already sent — so this states
// where things stand and offers the one action that is still available.
// It deliberately reuses id="uc-relation-bar": _applyUcActionBar() removes that
// id before rendering, so any other id would stack up a new strip per repaint.
function _sentStatusBarHtml(u) {
  var kind = _sentLikeKind(u && u.sentType);
  var label = (kind.lbl === 'LIKE') ? 'Ya le diste like' : 'Ya le enviaste un ' + kind.lbl.toLowerCase();
  return '<div id="uc-relation-bar" style="padding:14px var(--s) calc(14px + env(safe-area-inset-bottom));border-top:none;background:linear-gradient(180deg, transparent, rgba(0,0,0,0.9) 42%);flex-shrink:0;">' +
    '<div style="display:flex;align-items:center;gap:12px;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.12);border-radius:var(--rad-lg);padding:10px 12px;-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);box-shadow:0 6px 20px -6px rgba(0,0,0,0.6);">' +
      '<div style="width:40px;height:40px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:var(--fs-lg);background:color-mix(in srgb, ' + kind.hue + ' 18%, #000);border:1.5px solid ' + kind.hue + ';box-shadow:0 0 12px color-mix(in srgb, ' + kind.hue + ' 45%, transparent);">' + kind.ico + '</div>' +
      '<div style="flex:1;min-width:0;">' +
        '<div style="font-size:var(--fs-sm);font-weight:800;color:#fff;letter-spacing:-0.1px;">' + label + '</div>' +
        '<div style="font-size:var(--fs-2xs);color:var(--fg2);font-weight:500;margin-top:2px;">Esperando su respuesta</div>' +
      '</div>' +
      '<button onclick="_unsendSentLike()" style="flex-shrink:0;padding:10px 16px;' +
        _gradSkin('var(--wine)', false, { radius: 'var(--rad-pill)' }) +
        'font-family:var(--font);font-size:var(--fs-sm);font-weight:700;cursor:pointer;white-space:nowrap;">Quitar like</button>' +
    '</div>' +
  '</div>';
}

// "Quitar like" — retracts the swipe so the person leaves Likes Sent for good.
function _unsendSentLike() {
  var u = window._ucViewUser || {};
  var name = u.name || 'esta persona';
  var id = u.sentTargetId;

  ugzConfirm({
    type: 'warning',
    title: 'Quitar like',
    message: '¿Quitar tu like a ' + name + '? Dejará de aparecer en Likes Sent y no sabrá que le diste like.',
    confirmText: 'Quitar like',
    cancelText: 'Cancelar',
    onConfirm: function () {
      function done() {
        // Drop them from the cached list so the grid repaints without them
        // instead of waiting out the 5s refetch window in _renderLikedYouReveal.
        if (window._sentLikesData) {
          window._sentLikesData = window._sentLikesData.filter(function (x) {
            return id ? x.id !== id : x.name !== u.name;
          });
        }
        var m = document.getElementById('user-crush-modal');
        if (m) m.classList.remove('open');
        if (typeof _renderLikedYouReveal === 'function') _renderLikedYouReveal(curPlan === 'aplus');
        if (typeof ugzAlert === 'function') ugzAlert('Quitaste tu like a ' + name + '.');
      }

      // No id means a demo/seeded profile that was never persisted — there is
      // nothing on the backend to delete, so just drop it locally.
      if (!id || typeof apiClient === 'undefined' || !apiClient.getAccessToken()) { done(); return; }

      apiClient.unsendLike(id).then(done).catch(function (err) {
        if (err && err.status === 409) {
          if (typeof ugzAlert === 'function') ugzAlert('Ya hicieron match — el like no se puede retirar.');
        } else if (err && err.status === 404) {
          // Already gone on the backend; the local list is what is stale.
          done();
        } else if (typeof ugzAlert === 'function') {
          ugzAlert('No se pudo quitar el like: ' + ((err && err.message) ? err.message : 'error'));
        }
      });
    }
  });
}

// Swaps the swipe bar for the relationship bar inside #user-crush-modal.
function _applyUcActionBar() {
  var bar = document.getElementById('uc-action-bar');
  if (!bar) return;
  var prev = document.getElementById('uc-relation-bar');
  if (prev) prev.remove();
  var u = window._ucViewUser || {};
  if (u.origin === 'sent') {
    // Same cascade problem as below: .crush-actions carries display:flex !important.
    bar.style.setProperty('display', 'none', 'important');
    bar.insertAdjacentHTML('afterend', _sentStatusBarHtml(u));
  } else if (u.origin === 'search' || u.origin === 'chat') {
    // .crush-actions carries display:flex !important, so a plain style.display
    // assignment loses the cascade.
    bar.style.setProperty('display', 'none', 'important');
    bar.insertAdjacentHTML('afterend', _relationBarHtml(u.name));
  } else {
    bar.style.removeProperty('display');
  }
}

function _addFriendProfile(name) {
  var u = window._ucViewUser || {};
  var id = (u.p && u.p.id) ? u.p.id : null;
  if (id && typeof apiClient !== 'undefined' && apiClient.getAccessToken() && typeof apiClient.sendFriendRequest === 'function') {
    apiClient.sendFriendRequest(id).then(function () {
      if (typeof ugzAlert === 'function') ugzAlert('🤝 Solicitud enviada a ' + name);
    }).catch(function (err) {
      if (typeof ugzAlert === 'function') ugzAlert('No se pudo enviar la solicitud: ' + (err && err.message ? err.message : 'error'));
    });
  } else if (typeof ugzAlert === 'function') {
    // No resolvable user id (demo/seeded profile) — nothing to send to.
    ugzAlert('🤝 Solicitud enviada a ' + name);
  }
  var bar = document.getElementById('uc-relation-bar');
  if (bar) {
    var b = bar.querySelector('button');
    if (b) { b.textContent = '✓ Enviada'; b.disabled = true; b.style.background = 'rgba(255,255,255,0.10)'; b.style.color = 'var(--fg2)'; }
  }
}

function _unfriendProfile(name) {
  ugzConfirm({
    type: 'warning',
    title: 'Eliminar amigo',
    message: '¿Eliminar a ' + name + ' de tus amigos?',
    confirmText: 'Eliminar',
    cancelText: 'Cancelar',
    onConfirm: function () {
      // Local only: there is no unfriend endpoint on the backend yet, so this
      // drops them from the cached list and repaints. Add the apiClient call
      // here when the endpoint lands.
      var c = window._myFriendsCache;
      if (c && c.length) {
        var t = String(name).trim().toLowerCase();
        window._myFriendsCache = c.filter(function (x) {
          var o = (x && x.friend) ? x.friend : x;
          if (!o) return true;
          var full = ((o.firstName || '') + ' ' + (o.lastName || '')).trim().toLowerCase();
          return full !== t && String(o.name || '').trim().toLowerCase() !== t;
        });
      }
      _refreshRelationBars(name);
      if (typeof ugzAlert === 'function') ugzAlert(name + ' ya no está en tus amigos.');
    }
  });
}

// Open the current 1:1 chat partner's Crush card from the chat header
function openCurChatUnicrush(){
  if(!_curChatUser||_curChatUser.isGrp)return;// groups don't have a Crush card
  viewUserUnicrush(null,_curChatUser.name,_curChatUser.color,'','chat');
}
// View another user's Crush card (from search results, profile popup, or a chat)
function viewUserUnicrush(handle,name,bg,uniName,origin){
  // Respect the other user's privacy setting if present (demo users are public)
  var found=(typeof crushDataAll!=='undefined'&&crushDataAll)?crushDataAll.filter(function(x){return x.name===name;})[0]:null;
  if(found&&found.unicrushPublic===false){alert(name+' keeps their Crush profile private.');return;}
  var p=null;
  if(typeof crushDataAll!=='undefined'&&crushDataAll){p=crushDataAll.filter(function(x){return x.name===name;})[0];}
  if(!p){
    // Synthesize a minimal card for users that aren't in the demo crush pool
    p={name:name||'User',init:(name||'?').charAt(0).toUpperCase(),bg:bg||(uni&&uni.p)||'#3d7bff',age:'',major:'',minor:'',grad:'',bio:'',ints:[],flags:[],photos:[],verified:false,prompts:[]};
  }
  // Cross-university view ("Around other universities"): show this profile under that school, not the viewer's
  var _crossLocked=false;
  if(uniName){
    var ouni=null;for(var _d in UNI){if(UNI[_d].name===uniName){ouni=UNI[_d];break;}}
    if(ouni){p=Object.assign({},p);p.uni=ouni;
      // Free users can't like / super-like / add a Spotlight person from ANOTHER university — A+ only
      _crossLocked=(!uni||ouni.name!==uni.name)&&(typeof curPlan==='undefined'||curPlan!=='aplus');}
  }
  
  // Set modal-specific colors to match target university
  var modal=document.getElementById('user-crush-modal');
  if(modal){
    var uCol = (p && p.uni) ? p.uni.p : (uni ? uni.p : '#3d7bff');
    var uCol2 = (p && p.uni) ? (p.uni.p2 || p.uni.p) : (uni ? uni.p2 : '#3d7bff');
    modal.style.setProperty('--p', uCol);
    modal.style.setProperty('--p2', uCol2);
  }
  
  window._ucViewUser={p:p,handle:handle,name:name,bg:bg,crossLocked:_crossLocked,origin:origin||'deck'};
  if (typeof apiClient !== 'undefined') {
    var targetId = (p && p.id) ? p.id : (handle || name);
    if (targetId) {
      apiClient.recordProfileView(targetId);
    }
  }
  var title=document.getElementById('user-crush-title');if(title)title.textContent=(name||'User');
  var fbtn=document.getElementById('uc-addfriend');if(fbtn){fbtn.textContent='➕ Add';fbtn.disabled=false;fbtn.style.background='var(--p)';}
  switchUserCrushTab('crush');
  var pop=document.getElementById('user-profile-modal');if(pop)pop.classList.remove('open');
  modal=document.getElementById('user-crush-modal');if(modal)modal.classList.add('open');
  if(typeof _applyUcActionBar==='function')_applyUcActionBar();
  if(typeof _ucEnableSwipeClose==='function')_ucEnableSwipeClose(modal);
}
// Swipe DOWN (when the card is scrolled to the top) closes View Profile — the
// standard iOS sheet dismiss — in addition to the ‹ button.
function _ucEnableSwipeClose(m){
  if(!m||m.__swipeClose)return;m.__swipeClose=1;
  var sy=0,sx=0,active=false;
  // El scroller real es .crush-scroll (o #user-crush-body), NO .msheet — se
  // re-renderiza al cambiar de tab, así que lo re-consultamos en cada touchstart.
  m.addEventListener('touchstart',function(e){if(e.touches.length!==1){active=false;return;}var sheet=m.querySelector('.crush-scroll')||m.querySelector('#user-crush-body')||m.querySelector('.msheet');sy=e.touches[0].clientY;sx=e.touches[0].clientX;active=(!sheet||sheet.scrollTop<=2);},{passive:true});
  m.addEventListener('touchmove',function(e){if(!active||e.touches.length!==1)return;var dy=e.touches[0].clientY-sy,dx=e.touches[0].clientX-sx;if(dy>75&&Math.abs(dy)>Math.abs(dx)*1.4){m.classList.remove('open');active=false;}},{passive:true});
  m.addEventListener('touchend',function(){active=false;},{passive:true});
}
// Mark a profile as acted-on so Today's Picks drops it and refreshes with new faces
function _markPickActed(name){if(!name)return;window._pickActed=window._pickActed||{};window._pickActed[name]=1;if(typeof renderDailyPicks==='function')try{renderDailyPicks();}catch(e){}}
// Like / pass / super-like from the opened profile card
