var _chatAudioRec = null;
var _chatAudioChunks = [];
var _chatAudioStream = null;
var _chatAudioTimer = null;
var _chatAudioSecs = 0;
var _chatAudioBlob = null;
var _chatAudioMimeType = 'audio/webm';
var _chatAudioState = 'idle'; // 'idle', 'recording', 'preview', 'uploading'
var _chatAudioPreviewEl = null;
var _currentlyPlayingAudio = null;

function _formatAudioTime(sec) {
  var s = Math.floor(sec || 0);
  var m = Math.floor(s / 60);
  var rs = s % 60;
  return String(m).padStart(2, '0') + ':' + String(rs).padStart(2, '0');
}

function _triggerVoiceMsg() {
  console.log('[AUDIO] _triggerVoiceMsg invoked, current state:', _chatAudioState);
  if (_chatAudioState === 'recording') {
    _stopChatAudioRecording(false);
    return;
  }
  if (_chatAudioState === 'preview' || _chatAudioState === 'uploading') {
    return;
  }
  _startChatAudioRecording();
}

function _createAndStartMediaRecorder(stream) {
  var tracks = stream ? stream.getAudioTracks() : [];
  console.log('[AUDIO] Audio tracks:', tracks.map(function(t) {
    return { label: t.label, readyState: t.readyState, enabled: t.enabled, muted: t.muted };
  }));

  if (!tracks.length || tracks[0].readyState !== 'live') {
    throw new Error('No live audio track available in MediaStream');
  }

  // Candidate MIME types to try in order of preference
  var candidates = [];
  var testTypes = [
    'audio/webm;codecs=opus',
    'audio/webm',
    'audio/mp4;codecs=mp4a.40.2',
    'audio/mp4',
    'audio/aac',
    'audio/ogg;codecs=opus',
    'audio/wav',
    '' // browser default
  ];

  for (var i = 0; i < testTypes.length; i++) {
    var t = testTypes[i];
    if (!t || (typeof MediaRecorder !== 'undefined' && MediaRecorder.isTypeSupported && MediaRecorder.isTypeSupported(t))) {
      candidates.push(t);
    }
  }

  if (candidates.indexOf('') === -1) candidates.push('');

  var recorder = null;
  var selectedType = '';
  var startErr = null;

  for (var j = 0; j < candidates.length; j++) {
    var mime = candidates[j];
    try {
      console.log('[AUDIO] Trying to instantiate & start MediaRecorder with mimeType:', mime || '(default)');
      var opts = mime ? { mimeType: mime } : undefined;
      var rec = new MediaRecorder(stream, opts);
      
      // Test starting recording synchronously
      rec.start(100);
      
      recorder = rec;
      selectedType = rec.mimeType || mime || 'audio/webm';
      console.log('[AUDIO] Successfully started MediaRecorder with MIME type:', selectedType);
      break;
    } catch(err) {
      console.warn('[AUDIO] Failed MediaRecorder start with mimeType:', mime, err);
      startErr = err;
    }
  }

  if (!recorder) {
    throw startErr || new Error('Failed to start MediaRecorder with any candidate MIME type');
  }

  return { recorder: recorder, mimeType: selectedType };
}

function _startChatAudioRecording() {
  console.log('[AUDIO] Requesting microphone permission');
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    console.error('[AUDIO] navigator.mediaDevices.getUserMedia not supported');
    alert('🎤 El acceso al micrófono no está soportado en este navegador.');
    return;
  }

  navigator.mediaDevices.getUserMedia({ audio: true }).then(function(stream) {
    console.log('[AUDIO] Microphone permission granted');
    console.log('[AUDIO] getUserMedia success');

    _chatAudioStream = stream;
    _chatAudioChunks = [];

    try {
      var recRes = _createAndStartMediaRecorder(stream);
      _chatAudioRec = recRes.recorder;
      _chatAudioMimeType = recRes.mimeType;

      console.log('[AUDIO] MediaRecorder created and started with selected MIME type:', _chatAudioMimeType);

      _chatAudioRec.onstart = function() {
        console.log('[AUDIO] Recording started event fired');
      };

      _chatAudioRec.ondataavailable = function(e) {
        if (e.data && e.data.size > 0) {
          console.log('[AUDIO] Data received:', e.data.size, 'bytes');
          _chatAudioChunks.push(e.data);
        }
      };

      _chatAudioRec.onstop = function() {
        console.log('[AUDIO] Recording stopped event fired, total chunks:', _chatAudioChunks.length);
        _chatAudioBlob = new Blob(_chatAudioChunks, { type: _chatAudioMimeType });
        console.log('[AUDIO] Audio blob created, size:', _chatAudioBlob.size, 'bytes, type:', _chatAudioBlob.type);
        if (_chatAudioState === 'recording') {
          _showChatAudioPreview();
        }
      };

      _chatAudioRec.onerror = function(err) {
        console.error('[AUDIO] Recording error:', err);
      };

      _chatAudioState = 'recording';
      _chatAudioSecs = 0;

      console.log('[AUDIO] Recording started');
      _renderChatAudioRecordingUI();

      if (_chatAudioTimer) clearInterval(_chatAudioTimer);
      _chatAudioTimer = setInterval(function() {
        _chatAudioSecs++;
        var timerEl = document.getElementById('chat-rec-timer-txt');
        if (timerEl) {
          timerEl.textContent = _formatAudioTime(_chatAudioSecs) + ' / 01:00';
        }

        // Enforce 60s limit (1 minute)
        if (_chatAudioSecs >= 60) {
          console.log('[AUDIO] 60s limit reached, auto-stopping recording');
          if (typeof showToast === 'function') {
            showToast('⏱️ Límite máximo de 1 minuto alcanzado');
          }
          _stopChatAudioRecording(true);
        }
      }, 1000);

    } catch(recErr) {
      console.error('[AUDIO] Error initializing MediaRecorder:', recErr);
      if (typeof showToast === 'function') {
        showToast('❌ Error al iniciar la grabación de audio');
      } else {
        alert('❌ Error al iniciar el grabador de voz.');
      }
      if (_chatAudioStream) {
        _chatAudioStream.getTracks().forEach(function(t) { t.stop(); });
        _chatAudioStream = null;
      }
    }

  }).catch(function(err) {
    console.error('[AUDIO] Error accessing microphone / getUserMedia rejected:', err);
    if (typeof showToast === 'function') {
      showToast('❌ Se requiere permiso de micrófono para grabar audio');
    } else {
      alert('❌ Permiso de micrófono denegado');
    }
  });
}

function _renderChatAudioRecordingUI() {
  console.log('[AUDIO] Rendering Chat Audio Recording UI');
  var cbar = document.getElementById('cbar') || document.querySelector('.cbar-capsule') || document.querySelector('.cbar');
  if (!cbar) {
    console.error('[AUDIO] Container .cbar or .cbar-capsule not found in DOM');
    return;
  }

  var inp = document.getElementById('cinp');
  if (inp) inp.style.display = 'none';

  Array.from(cbar.children).forEach(function(child) {
    if (child.id !== 'chat-audio-rec-bar') {
      child.style.display = 'none';
    }
  });

  var existing = document.getElementById('chat-audio-rec-bar');
  if (existing) existing.remove();

  var bar = document.createElement('div');
  bar.id = 'chat-audio-rec-bar';
  bar.className = 'chat-audio-rec-bar';
  bar.innerHTML = `
    <div class="chat-rec-dot"></div>
    <div id="chat-rec-timer-txt" class="chat-rec-timer">00:00 / 01:00</div>
    <div class="chat-rec-wave">
      <div class="chat-rec-wave-bar"></div>
      <div class="chat-rec-wave-bar"></div>
      <div class="chat-rec-wave-bar"></div>
      <div class="chat-rec-wave-bar"></div>
      <div class="chat-rec-wave-bar"></div>
      <div class="chat-rec-wave-bar"></div>
    </div>
    <button type="button" class="chat-audio-btn danger" onclick="_cancelChatAudioRecording()" title="Cancelar">🗑️</button>
    <button type="button" class="chat-audio-btn send-btn" onclick="_stopChatAudioRecording(false)" title="Previsualizar / Detener">⏹️</button>
  `;

  cbar.appendChild(bar);
}

function _stopChatAudioRecording(autoStopped) {
  console.log('[AUDIO] Stopping Chat Audio Recording, autoStopped:', autoStopped);
  if (_chatAudioTimer) {
    clearInterval(_chatAudioTimer);
    _chatAudioTimer = null;
  }

  if (_chatAudioRec && _chatAudioRec.state !== 'inactive') {
    try {
      _chatAudioRec.stop();
    } catch(e) {
      console.warn('[AUDIO] Error calling recorder.stop():', e);
    }
  }

  if (_chatAudioStream) {
    _chatAudioStream.getTracks().forEach(function(t) { t.stop(); });
    _chatAudioStream = null;
  }

  if (_chatAudioSecs <= 0) _chatAudioSecs = 1;

  if (autoStopped) {
    setTimeout(function() { _showChatAudioPreview(); }, 200);
  }
}

function _showChatAudioPreview() {
  console.log('[AUDIO] Showing Chat Audio Preview');
  _chatAudioState = 'preview';
  var bar = document.getElementById('chat-audio-rec-bar');
  if (!bar) return;

  var durTxt = _formatAudioTime(_chatAudioSecs);
  bar.innerHTML = `
    <button type="button" id="chat-audio-preview-play-btn" class="chat-audio-btn" onclick="_toggleChatAudioPreviewPlay()" style="background:rgba(255,255,255,0.15);color:#fff;width:32px;height:32px;" title="Escuchar audio">▶️</button>
    <div class="chat-rec-timer" style="font-size:13px;">${durTxt} 🎤</div>
    <div style="flex:1;height:4px;background:rgba(255,255,255,0.2);border-radius:2px;overflow:hidden;">
      <div id="chat-audio-preview-progress" style="width:0%;height:100%;background:#f03e5a;"></div>
    </div>
    <button type="button" class="chat-audio-btn danger" onclick="_cancelChatAudioRecording()" title="Descartar">🗑️</button>
    <button type="button" id="chat-audio-send-btn" class="chat-audio-btn send-btn" onclick="_sendChatAudioMessage()" title="Enviar audio">🚀</button>
  `;
}

function _toggleChatAudioPreviewPlay() {
  if (!_chatAudioBlob) return;

  var btn = document.getElementById('chat-audio-preview-play-btn');
  var progress = document.getElementById('chat-audio-preview-progress');

  if (_chatAudioPreviewEl && !_chatAudioPreviewEl.paused) {
    _chatAudioPreviewEl.pause();
    if (btn) btn.textContent = '▶️';
    return;
  }

  if (!_chatAudioPreviewEl) {
    var audioUrl = URL.createObjectURL(_chatAudioBlob);
    _chatAudioPreviewEl = new Audio(audioUrl);
    _chatAudioPreviewEl.onended = function() {
      if (btn) btn.textContent = '▶️';
      if (progress) progress.style.width = '0%';
    };
    _chatAudioPreviewEl.ontimeupdate = function() {
      if (_chatAudioPreviewEl && progress && _chatAudioPreviewEl.duration) {
        var pct = (_chatAudioPreviewEl.currentTime / _chatAudioPreviewEl.duration) * 100;
        progress.style.width = pct + '%';
      }
    };
  }

  if (_currentlyPlayingAudio && _currentlyPlayingAudio !== _chatAudioPreviewEl) {
    _currentlyPlayingAudio.pause();
  }
  _currentlyPlayingAudio = _chatAudioPreviewEl;

  _chatAudioPreviewEl.play().then(function() {
    if (btn) btn.textContent = '⏸️';
  }).catch(function(e) {
    console.error("[AUDIO] Error playing audio preview", e);
  });
}

function _cancelChatAudioRecording() {
  console.log('[AUDIO] Cancelling Chat Audio Recording');
  if (_chatAudioTimer) {
    clearInterval(_chatAudioTimer);
    _chatAudioTimer = null;
  }
  if (_chatAudioRec && _chatAudioRec.state !== 'inactive') {
    try { _chatAudioRec.stop(); } catch(e){}
  }
  if (_chatAudioStream) {
    _chatAudioStream.getTracks().forEach(function(t) { t.stop(); });
    _chatAudioStream = null;
  }
  if (_chatAudioPreviewEl) {
    _chatAudioPreviewEl.pause();
    _chatAudioPreviewEl = null;
  }

  _chatAudioState = 'idle';
  _chatAudioBlob = null;
  _chatAudioChunks = [];
  _chatAudioSecs = 0;

  var cbar = document.getElementById('cbar') || document.querySelector('.cbar-capsule') || document.querySelector('.cbar');
  if (cbar) {
    Array.from(cbar.children).forEach(function(child) {
      if (child.id === 'chat-audio-rec-bar') {
        child.remove();
      } else {
        child.style.display = '';
      }
    });
  }

  var inp = document.getElementById('cinp');
  if (inp) {
    inp.style.display = 'block';
    inp.focus();
  }
}

function _sendChatAudioMessage() {
  if (_chatAudioState === 'uploading' || !_chatAudioBlob || !curChatId) return;

  console.log('[AUDIO] Sending Chat Audio Message, size:', _chatAudioBlob.size, 'type:', _chatAudioBlob.type);
  _chatAudioState = 'uploading';

  var sendBtn = document.getElementById('chat-audio-send-btn');
  if (sendBtn) {
    sendBtn.disabled = true;
    sendBtn.innerHTML = '⏳';
    sendBtn.style.opacity = '0.7';
  }

  var durSecs = Math.min(60, Math.max(1, _chatAudioSecs));
  var isDbMatch = (typeof apiClient !== 'undefined' && apiClient.getAccessToken() && !curChatId.startsWith('biz_') && !curChatId.startsWith('net_') && !curChatId.startsWith('clist-') && !curChatId.includes('moment'));

  if (!isDbMatch) {
    var localDataUrl = URL.createObjectURL(_chatAudioBlob);
    if (!chatHistory[curChatId]) chatHistory[curChatId] = [];
    chatHistory[curChatId].push({
      txt: '🎤 Mensaje de voz',
      type: 'AUDIO',
      mediaUrl: localDataUrl,
      duration: durSecs,
      out: true
    });
    renderMsgs();
    _cancelChatAudioRecording();
    return;
  }

  // Real DB + Storage Flow
  apiClient.getChatAudioUploadUrl(curChatId, _chatAudioMimeType).then(function(res) {
    var data = res.data || res;
    var uploadUrl = data.uploadUrl;
    var publicUrl = data.publicUrl;

    return apiClient.uploadAudioToStorage(uploadUrl, _chatAudioBlob).then(function() {
      console.log('[AUDIO] Upload successful to:', publicUrl);
      if (!chatHistory[curChatId]) chatHistory[curChatId] = [];
      chatHistory[curChatId].push({
        txt: '🎤 Mensaje de voz',
        type: 'AUDIO',
        mediaUrl: publicUrl,
        duration: durSecs,
        out: true
      });
      renderMsgs();

      apiClient.sendChatMessage(curChatId, '🎤 Mensaje de voz', 'AUDIO', publicUrl, durSecs);
      window._lastTypingState = false;
      apiClient.sendTypingStatus(curChatId, false);

      _cancelChatAudioRecording();
    });
  }).catch(function(err) {
    console.error("❌ [AUDIO] Audio upload/send error:", err);
    if (typeof showToast === 'function') {
      showToast('❌ Error al subir el audio. Inténtalo de nuevo.');
    } else {
      alert('❌ Error al enviar mensaje de voz.');
    }
    _chatAudioState = 'preview';
    if (sendBtn) {
      sendBtn.disabled = false;
      sendBtn.innerHTML = '🚀';
      sendBtn.style.opacity = '1';
    }
  });
}

function _openChatAttachmentPicker() {
  var fileInp = document.createElement('input');
  fileInp.type = 'file';
  fileInp.accept = 'image/*,video/*,application/pdf';
  fileInp.onchange = function(e) {
    if (e.target.files && e.target.files[0]) {
      chatSendPhoto();
    }
  };
  fileInp.click();
}

// ── Shared match-celebration plumbing ──
// Both the 1:1 match overlay and the Double Date match overlay are full-screen
// modals that can appear asynchronously; they share the same backdrop-dismiss
// safety and the same "shrink to a floating badge if ignored" retention hook,
// so that plumbing lives here once instead of being duplicated per overlay.
function _attachMatchBackdropDismiss(overlay) {
  overlay.addEventListener('click', function(e) {
    if (e.target === overlay) overlay.remove();
  });
}

function _scheduleMatchRetentionBadge(overlay, opts) {
  opts = opts || {};
  var interacted = false;
  overlay.addEventListener('click', function(){ interacted = true; }, { once: true });
  setTimeout(function(){
    if (interacted || !overlay.parentNode) return;
    _shrinkMatchToBadge(overlay, opts);
  }, opts.delay || 4500);
}

function _shrinkMatchToBadge(overlay, opts) {
  overlay.style.transition = 'transform 0.4s ease, opacity 0.4s ease';
  overlay.style.transform = 'scale(0.85)';
  overlay.style.opacity = '0';
  setTimeout(function() {
    if (overlay.parentNode) overlay.remove();
    var old = document.getElementById('match-retention-badge');
    if (old) old.remove();
    var badge = document.createElement('div');
    badge.id = 'match-retention-badge';
    badge.style.cssText = 'position:fixed;right:16px;bottom:88px;z-index:99998;display:flex;align-items:center;gap:8px;background:linear-gradient(135deg,#1a0a38,#0d061f);border:1.5px solid rgba(255,62,166,0.5);border-radius:999px;padding:8px 14px 8px 8px;box-shadow:0 0 12px rgba(62,166,255,0.35),var(--el-3);cursor:pointer;animation:ugzBadgeIn 0.35s ease;';
    var photoHtml = opts.photoUrl
      ? '<img src="' + opts.photoUrl + '" style="width:36px;height:36px;border-radius:50%;object-fit:cover;box-shadow:0 0 8px rgba(255,62,166,0.6);"/>'
      : '<div style="width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,#3ea6ff,#ff3ea6);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;">' + (opts.name || '?').charAt(0) + '</div>';
    var label = window.currentLang === 'es' ? 'Nuevo match 💘' : 'New match 💘';
    badge.innerHTML = photoHtml + '<div style="font-size:var(--fs-sm);font-weight:600;color:#fff;">' + label + '</div><div data-badge-close="1" style="margin-left:2px;color:rgba(255,255,255,0.5);font-size:var(--fs-sm);padding:2px 4px;">✕</div>';
    badge.addEventListener('click', function(e) {
      if (e.target && e.target.getAttribute('data-badge-close')) { badge.remove(); return; }
      badge.remove();
      if (typeof opts.onReopen === 'function') opts.onReopen();
    });
    document.body.appendChild(badge);
  }, 400);
}

// Reuses the existing icebreaker generator (_genIcebreakers, used in chat) so the
// "break the ice" suggestion is driven by the same shared-interests/prompts logic
// already in the app, normalizing whichever partner-object shape the caller has
// (swipe-deck card vs. DB match partner with a nested `profile`).
function _matchIcebreakerText(partner) {
  try {
    var norm = {
      name: partner.firstName || partner.name || '',
      prompts: partner.prompts || (partner.profile && partner.profile.prompts) || [],
      ints: partner.ints || partner.interests || (partner.profile && partner.profile.interests) || [],
      major: partner.major || (partner.profile && partner.profile.major) || '',
      hometown: partner.hometown || (partner.profile && partner.profile.hometown) || ''
    };
    var ideas = _genIcebreakers(norm);
    if (ideas && ideas.length) return ideas[0];
  } catch(e) {}
  return window.currentLang === 'es' ? '¡Dile hola y pregúntale qué la trae por el campus! 👋' : 'Say hi and ask what brought them to campus! 👋';
}

// Spawns a one-shot burst of small spark nodes from the center of `container`,
// each animated purely by the CSS `matchSparkOut` keyframe (transform+opacity via
// per-node --tx/--ty custom props) — no rAF-per-particle, this is the only thing
// animating during the "explosion" phase (see the perf note above _showMatchOverlay).
function _spawnMatchSparks(container) {
  var COLORS = ['#3ea6ff', '#ff3ea6'];
  for (var i = 0; i < 12; i++) {
    var angle = (Math.PI * 2 * i / 12) + (Math.random() * 0.4 - 0.2);
    var dist = 70 + Math.random() * 50;
    var spark = document.createElement('div');
    var size = 4 + Math.random() * 3;
    spark.style.cssText = 'position:absolute;left:50%;top:50%;width:' + size + 'px;height:' + size + 'px;margin:-' + (size/2) + 'px 0 0 -' + (size/2) + 'px;border-radius:50%;background:' + COLORS[i % 2] + ';box-shadow:0 0 6px ' + COLORS[i % 2] + ';--tx:' + (Math.cos(angle) * dist).toFixed(1) + 'px;--ty:' + (Math.sin(angle) * dist).toFixed(1) + 'px;animation:matchSparkOut 0.6s ease-out forwards;pointer-events:none;';
    container.appendChild(spark);
  }
}

var _matchOverlayTimers = [];
var _activeMatchOverlayKey = null;
function _showMatchOverlay(data) {
  if (!data) return;
  var partner = data.partner || {};
  var matchId = data.matchId || '';
  // A single match reliably fires this 2-3 times (the 'newMatch' socket event,
  // the 'newMatch_broadcast' fallback, and the swiper's own HTTP isMatch:true
  // response all call this for the same match). The "Neon Energy" sequence takes
  // ~5s to play out, so a duplicate call arriving mid-animation used to wipe the
  // in-progress overlay and restart the whole thing from step 1 — visible as the
  // animation never finishing. Dedup by match identity instead: once an overlay
  // for this match is already up, later calls for the SAME match are no-ops.
  var overlayKey = matchId || partner.handle || partner.name || 'unknown';
  if (_activeMatchOverlayKey === overlayKey && document.getElementById('live-match-modal')) {
    return;
  }
  _activeMatchOverlayKey = overlayKey;
  _matchOverlayTimers.forEach(function(t){ clearTimeout(t); clearInterval(t); });
  _matchOverlayTimers = [];
  console.log("🎉 Displaying real-time match modal:", data);
  var partnerName = partner.firstName || partner.name || 'someone';
  var partnerPhoto = partner.photo || (partner.photos && partner.photos[0] && partner.photos[0].url) || 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=500';
  var userPhoto = (typeof userPro !== 'undefined' && userPro.photos && userPro.photos[0] && userPro.photos[0].url) || (typeof userPro !== 'undefined' && userPro.p && userPro.p.pic) || 'https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?w=500';
  var isEs = window.currentLang === 'es';
  var icebreakerText = _matchIcebreakerText(partner);

  if (typeof notifData !== 'undefined') {
    // Evita duplicar la notificación de match de la misma persona.
    notifData = notifData.filter(function(n){ return !(n.type==='match' && (n.from===partnerName || (partner.handle && n.handle===partner.handle))); });
    notifData.unshift({
      type: 'match',
      from: partnerName,
      handle: partner.handle || '',
      av: partnerPhoto ? '<img src="' + partnerPhoto + '" style="width:100%;height:100%;border-radius:50%;object-fit:cover;"/>' : partnerName.charAt(0),
      color: '#dc2626',
      msg: '¡Hicieron Match! 🎉 Di hola.',
      time: 'just now',
      id: 'match_' + Date.now()
    });
    if (typeof _updateNotifBadge === 'function') _updateNotifBadge();
  }

  var oldM = document.getElementById('live-match-modal');
  if (oldM) oldM.remove();
  var oldBadge = document.getElementById('match-retention-badge');
  if (oldBadge) oldBadge.remove();

  var overlay = document.createElement('div');
  overlay.id = 'live-match-modal';
  overlay.className = 'ugz-modal-overlay ugz-open open';
  // backdrop-filter blur is one of the priciest CSS effects to composite; 8px reads
  // just as "glassy" as 16px here but is noticeably cheaper per frame.
  overlay.style.cssText = 'position:fixed;inset:0;z-index:999999;display:flex;align-items:center;justify-content:center;background:rgba(10,5,22,0.88);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);opacity:1 !important;visibility:visible !important;pointer-events:auto !important;';
  // "Neon Energy" sequence (5 steps, ~5s total, one animated thing per phase —
  // see the perf note this replaced above _spawnMatchSparks): photos slide in →
  // two SVG neon strokes draw from each photo and cross at the center → they
  // fade into a halo burst + spark particles → the match text/heart/CTA fade in.
  overlay.innerHTML = `
    <div class="ugz-modal-card type-confirm" style="max-width:380px;text-align:center;padding:30px 22px;background:linear-gradient(145deg, #0d061f, #1a0a38);border:1.5px solid rgba(120,90,255,0.35);box-shadow:var(--el-3);animation:ugzPopIn 0.25s ease;">
      <div style="display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:14px;height:88px;position:relative;">
        <svg id="match-neon-svg" viewBox="0 0 336 88" style="position:absolute;left:50%;top:0;width:336px;height:88px;margin-left:-168px;overflow:visible;pointer-events:none;transition:opacity 0.25s ease;">
          <path id="match-neon-line-blue" class="match-neon-line" d="M120,44 Q168,64 216,20" fill="none" stroke="#3ea6ff" stroke-width="3" stroke-linecap="round" style="filter:drop-shadow(0 0 4px #3ea6ff);"/>
          <path id="match-neon-line-pink" class="match-neon-line" d="M216,44 Q168,24 120,20" fill="none" stroke="#ff3ea6" stroke-width="3" stroke-linecap="round" style="filter:drop-shadow(0 0 4px #ff3ea6);"/>
        </svg>
        <div id="match-halo" style="position:absolute;left:50%;top:50%;width:120px;height:120px;margin:-60px 0 0 -60px;border-radius:50%;background:radial-gradient(circle, rgba(255,255,255,0.9) 0%, rgba(62,166,255,0.55) 35%, rgba(255,62,166,0.35) 65%, rgba(255,62,166,0) 100%);opacity:0;pointer-events:none;"></div>
        <div id="match-sparks" style="position:absolute;left:50%;top:50%;width:0;height:0;pointer-events:none;"></div>
        <div id="match-photo-user" style="width:82px;height:82px;border-radius:50%;padding:3px;background:#3ea6ff;box-shadow:0 0 14px rgba(62,166,255,0.7);transform:translateX(-60px);opacity:0;transition:transform 0.35s cubic-bezier(.2,.8,.2,1),opacity 0.3s ease;will-change:transform,opacity;">
          <img src="${userPhoto}" style="width:100%;height:100%;border-radius:50%;object-fit:cover;display:block;"/>
        </div>
        <div id="match-photo-partner" style="width:82px;height:82px;border-radius:50%;padding:3px;background:#ff3ea6;box-shadow:0 0 14px rgba(255,62,166,0.7);transform:translateX(60px);opacity:0;transition:transform 0.35s cubic-bezier(.2,.8,.2,1),opacity 0.3s ease;will-change:transform,opacity;">
          <img src="${partnerPhoto}" style="width:100%;height:100%;border-radius:50%;object-fit:cover;display:block;"/>
        </div>
        <div id="match-mini-heart" style="position:absolute;left:50%;top:50%;width:26px;height:26px;margin:-13px 0 0 -13px;font-size:18px;line-height:26px;opacity:0;">❤️</div>
      </div>
      <div id="match-title" style="font-size:var(--fs-2xl);font-weight:900;background:linear-gradient(90deg,#3ea6ff,#ff3ea6);-webkit-background-clip:text;-webkit-text-fill-color:transparent;margin-bottom:6px;font-family:var(--font-serif);letter-spacing:0.5px;opacity:0;">${isEs ? '¡ES UN MATCH!' : "IT'S A MATCH"}</div>
      <div id="match-subtitle" style="font-size:var(--fs-sm);color:rgba(255,255,255,0.65);margin-bottom:22px;font-weight:600;opacity:0;">${isEs ? '¡Salúdala/o! 👋' : 'Now say hi 👋'}</div>

      <div id="match-actions" style="display:flex;flex-direction:column;gap:10px;opacity:0;">
        <button id="live-match-btn-chat" class="ugz-modal-btn ugz-modal-btn-confirm" style="background:linear-gradient(135deg,#3ea6ff,#ff3ea6);color:#fff;border:none;font-weight:600;padding:13px;border-radius:var(--rad-md);cursor:pointer;font-size:var(--fs-base);box-shadow:var(--el-2);">
          ${isEs ? 'Enviar mensaje' : 'Send Message'}
        </button>
        <button id="live-match-btn-close" class="ugz-modal-btn ugz-modal-btn-cancel" style="background:rgba(255,255,255,0.08);color:var(--fg2);border:1px solid rgba(255,255,255,0.14);font-weight:500;padding:11px;border-radius:var(--rad-md);cursor:pointer;font-size:var(--fs-base);">
          ${isEs ? 'Seguir viendo perfiles' : 'Keep Swiping'}
        </button>
      </div>
    </div>
  `;

  document.body.appendChild(overlay);

  // Safety: this overlay is triggered asynchronously by match/WebSocket
  // events and covers the whole screen at z-index:999999. Without a
  // backdrop-close it swallows every tap that misses its two buttons,
  // producing "random dead taps, must tap several times". Allow a tap
  // on the backdrop to dismiss it.
  _attachMatchBackdropDismiss(overlay);

  // Step 1 (0-350ms): photos slide in from the sides.
  requestAnimationFrame(function(){
    requestAnimationFrame(function(){
      var up = document.getElementById('match-photo-user');
      var pp = document.getElementById('match-photo-partner');
      if (up) { up.style.transform = 'translateX(0)'; up.style.opacity = '1'; }
      if (pp) { pp.style.transform = 'translateX(0)'; pp.style.opacity = '1'; }
    });
  });

  // Steps 2+3 (450-1350ms): the two neon strokes draw from each photo and cross
  // at the center, then fade out. getTotalLength() is measured once (not per
  // frame) and the draw is a plain stroke-dashoffset transition, same technique
  // as the existing .ring-fill progress rings elsewhere in the app.
  _matchOverlayTimers.push(setTimeout(function(){
    ['match-neon-line-blue', 'match-neon-line-pink'].forEach(function(id){
      var path = document.getElementById(id);
      if (!path) return;
      var len = path.getTotalLength();
      path.style.strokeDasharray = len;
      path.style.strokeDashoffset = len;
      requestAnimationFrame(function(){
        requestAnimationFrame(function(){
          path.style.strokeDashoffset = '0';
        });
      });
    });
  }, 450));

  // Step 4 (1350-1850ms): hide the lines, burst a halo + spark particles —
  // the only animated group running in this window.
  _matchOverlayTimers.push(setTimeout(function(){
    var svg = document.getElementById('match-neon-svg');
    if (svg) svg.style.opacity = '0';
    var halo = document.getElementById('match-halo');
    if (halo) halo.style.animation = 'matchHaloBurst 0.5s ease-out forwards';
    var sparks = document.getElementById('match-sparks');
    if (sparks) _spawnMatchSparks(sparks);
  }, 1350));

  // Step 5 (2000-2450ms): title, heart, subtitle and buttons fade in, staggered
  // so nothing else is animating alongside them. Title lands at ~2s total,
  // comfortably inside the 2-2.5s budget for "IT'S A MATCH" to appear.
  [
    ['match-title', 2000],
    ['match-mini-heart', 2150],
    ['match-subtitle', 2300],
    ['match-actions', 2450]
  ].forEach(function(pair){
    _matchOverlayTimers.push(setTimeout(function(){
      var el = document.getElementById(pair[0]);
      if (el) el.style.animation = 'matchStep5In 0.35s ease forwards';
    }, pair[1]));
  });

  var chatBtn = document.getElementById('live-match-btn-chat');
  if (chatBtn) {
    chatBtn.onclick = function() {
      overlay.remove();
      if (typeof sw === 'function') sw('chats', 'Chats');
      if (matchId && typeof openChat === 'function') {
        openChat(matchId, partnerName, '#dc2626', '❤️', false, [], false);
        setTimeout(function(){
          var inp = document.getElementById('cinp');
          if (inp) { inp.value = icebreakerText; inp.focus(); }
        }, 200);
      }
    };
  }

  var closeBtn = document.getElementById('live-match-btn-close');
  if (closeBtn) {
    closeBtn.onclick = function() {
      overlay.remove();
    };
  }

  // The "Neon Energy" sequence's buttons finish fading in around 2.8s — the
  // retention badge's default 4.5s delay is tuned for the old, even-shorter
  // animation and would shrink the overlay too soon after the buttons appear.
  // Give it a few seconds of visible, clickable time first.
  _scheduleMatchRetentionBadge(overlay, {
    photoUrl: partnerPhoto,
    name: partnerName,
    delay: 6000,
    onReopen: function() {
      if (typeof sw === 'function') sw('chats', 'Chats');
      if (matchId && typeof openChat === 'function') openChat(matchId, partnerName, '#dc2626', '❤️', false, [], false);
    }
  });

  if (typeof fetchAndRenderChats === 'function') {
    fetchAndRenderChats();
  }
}

function conectarChatEnVivo() {
  if (typeof apiClient === 'undefined' || !apiClient.getAccessToken()) return;
  console.log("🔌 Connecting to live chat WebSockets...");
  apiClient.connectSocket({
    onConnected: function() {
      console.log("✅ WebSocket connected!");
      if (curChatId && !curChatId.startsWith('biz_') && !curChatId.startsWith('net_') && !curChatId.startsWith('clist-') && !curChatId.includes('moment')) {
        apiClient.joinChatRoom(curChatId);
      }
    },
    onDisconnected: function() {
      console.warn("🔌 WebSocket disconnected.");
    },
    onForceLogout: function(data) {
      var msg = (data && data.message) || 'Tu cuenta ya no tiene acceso a la aplicación.';
      var isEs = window.currentLang === 'es';
      var userEmail = (typeof userPro !== 'undefined' && userPro && userPro.email) || '';
      var doLogout = function() { if (typeof _logOut === 'function') _logOut(true); };
      window.ugzModal.show({
        type: 'warning',
        message: msg,
        confirmText: isEs ? 'Apelar' : 'Appeal',
        cancelText: isEs ? 'Cerrar' : 'Close',
        onConfirm: function() { window.openAppealForm({ email: userEmail, onClose: doLogout }); },
        onCancel: doLogout
      });
    },
    onAppealResolved: function(data) {
      var isEs = window.currentLang === 'es';
      window.ugzModal.show({
        type: data && data.status === 'APPROVED' ? 'success' : 'warning',
        title: data && data.title,
        message: (data && data.message) || (isEs ? 'Tu apelación fue resuelta.' : 'Your appeal has been resolved.')
      });
    },
    onMatchCreated: function(data) {
      _showMatchOverlay(data);
    },
    onMessageReceived: function(msg) {
      console.log("✉️ Real-time message received:", msg);
      if (!msg || !msg.matchId) return;

      var targetId = msg.matchId;
      if (!chatHistory[targetId]) chatHistory[targetId] = [];

      var exists = chatHistory[targetId].some(function(m) {
        return m.id === msg.id;
      });

      var curUserId = _getCurrentUserId();
      var isOut = msg.senderId === curUserId;

      if (!exists) {
        var optMsg = null;
        if (isOut) {
          optMsg = chatHistory[targetId].find(function(m) {
            return !m.id && m.txt === msg.content && m.out;
          });
        }
        if (optMsg) {
          optMsg.id = msg.id;
          optMsg.type = msg.type || optMsg.type || 'TEXT';
          optMsg.mediaUrl = msg.mediaUrl || optMsg.mediaUrl || null;
          optMsg.duration = msg.duration || optMsg.duration || null;
          optMsg.isRead = !!msg.isRead;
          optMsg.readAt = msg.readAt || null;
        } else {
          chatHistory[targetId].push({
            id: msg.id,
            txt: msg.content,
            type: msg.type || 'TEXT',
            mediaUrl: msg.mediaUrl || null,
            duration: msg.duration || null,
            out: isOut,
            senderId: msg.senderId,
            isRead: !!msg.isRead,
            readAt: msg.readAt || null,
            from: msg.sender ? msg.sender.firstName : ''
          });
        }

        if (curChatId === targetId) {
          renderMsgs();
        }
      }
      
      var previewText = msg.content;
      if (msg.type === 'AUDIO') previewText = 'Mensaje de voz';
      else if (msg.type === 'GAME') previewText = 'Icebreaker Game';
      else if (msg.type === 'IMAGE') previewText = 'Foto';
      else if (msg.type === 'FILE') previewText = 'Archivo';

      // A chat can still be "open" as far as curChatId is concerned while the
      // tab/window isn't actually the one the user is looking at (e.g. two
      // accounts tested side by side in separate tabs) — document.hidden
      // catches that case so the bell still fires instead of assuming the
      // user has seen the message just because that chat's screen is loaded.
      var _isUnreadNow = ((curChatId !== targetId || document.hidden) && !isOut);
      ['dm-match-' + targetId, 'uc-match-' + targetId].forEach(function(rid){
        var item = document.getElementById(rid);
        if (!item) return;
        // Preview estilo Instagram: negrita blanco si no visto, gris si leído.
        var pre = item.querySelector('.cpre');
        if (pre) {
          pre.classList.toggle('cpre-unrd', _isUnreadNow);
          pre.innerHTML = (typeof _e==='function'?_e(previewText):previewText) + ' <span class="cago">· now</span>';
        }
        // Estado (Sent/Seen) y punto de no-leído, sin pisar el .online-d que ya
        // pueda estar puesto ahí por la presencia batch.
        var right = item.querySelector('.cright');
        if (right) {
          var statusEl = right.querySelector('.cstatus');
          if (isOut) {
            if (!statusEl) {
              statusEl = document.createElement('div');
              statusEl.className = 'cstatus';
              right.insertBefore(statusEl, right.firstChild);
            }
            statusEl.textContent = msg.isRead ? 'Seen' : 'Sent';
          } else if (statusEl) {
            statusEl.remove();
          }
          var dotEl = right.querySelector('.cdot');
          if (_isUnreadNow && !dotEl) {
            dotEl = document.createElement('div');
            dotEl.className = 'cdot';
            right.appendChild(dotEl);
          } else if (!_isUnreadNow && dotEl) {
            dotEl.remove();
          }
        }
        // Un mensaje nuevo sube la conversación al TOPE de su lista.
        var par = item.parentElement;
        if (par && par.firstElementChild !== item) par.insertBefore(item, par.firstElementChild);
      });

      if (_isUnreadNow) {
        window._unreadMessageCounts = window._unreadMessageCounts || {};
        window._unreadMessageCounts[targetId] = (window._unreadMessageCounts[targetId] || 0) + 1;
        _updateUnreadBadgeForChat(targetId);
        var count = window._unreadMessageCounts[targetId];
        
        var totalUnread = 0;
        for (var mId in window._unreadMessageCounts) {
          totalUnread += window._unreadMessageCounts[mId] || 0;
        }
        
        var ucBadge = document.getElementById('uc-badge') || document.getElementById('nbadge-chats');
        if (ucBadge) {
          if (totalUnread > 0) {
            ucBadge.style.display = 'flex';
            ucBadge.textContent = totalUnread > 9 ? '+9' : totalUnread;
          } else {
            ucBadge.style.display = 'none';
          }
        }
        
        var senderName = msg.senderName || (msg.sender && msg.sender.firstName) || 'Alguien';
        var senderInit = senderName.charAt(0).toUpperCase();
        var notifId = 'msg_' + msg.matchId;
        
        if (typeof notifData !== 'undefined') {
          notifData = notifData.filter(function(n) { return n.id !== notifId; });
          
          var funMsg = '';
          if (count === 1) {
            funMsg = 'te mandó un recadito... ¡no lo dejes en visto! 💬';
          } else if (count === 2) {
            funMsg = 'te está tirando la onda con 2 mensajes. 😏';
          } else if (count === 3) {
            funMsg = 'te mandó 3 mensajes... ¿te estás haciendo la difícil? 😜';
          } else {
            funMsg = 'te está bombardeando! Tiene +' + count + ' cosas urgentes que decirte. 💣🔥';
          }
          
          var partnerPhoto = (msg.sender && msg.sender.photos && msg.sender.photos[0] && msg.sender.photos[0].url) || '';
          var avHtml = partnerPhoto 
            ? '<img src="' + partnerPhoto + '" style="width:100%;height:100%;border-radius:50%;object-fit:cover;display:block;"/>'
            : senderInit;
          
          notifData.unshift({
            type: 'social',
            from: senderName,
            handle: '',
            av: avHtml,
            color: '#dc2626',
            msg: funMsg,
            time: 'just now',
            id: notifId,
            matchId: msg.matchId
          });
          
          if (typeof notifRead !== 'undefined') delete notifRead[notifId];
          if (typeof _updateNotifBadge === 'function') _updateNotifBadge();
        }
        // Per-row unread state (.cdot) was already set in the forEach above —
        // no separate .cunrd badge here, that duplicated it and collided with
        // .cright's other elements (status text, presence dot).
      }
    },
    onTypingStatus: function(data) {
      if (curChatId === data.matchId && data.userId !== userPro.id) {
        if (typeof _cwSetTyping === 'function') _cwSetTyping(!!data.isTyping);
      }
    },
    onMessageRead: function(data) {
      if (!data || !data.matchId) return;
      var hist = chatHistory[data.matchId];
      if (hist) {
        hist.forEach(function(m) {
          if (m.out) { m.isRead = true; m.readAt = data.readAt; }
        });
      }
      if (curChatId === data.matchId && typeof renderMsgs === 'function') renderMsgs();
      // Reflect "Seen" in the chat-list row too, if my last message there is what got read.
      ['dm-match-' + data.matchId, 'uc-match-' + data.matchId].forEach(function(rid) {
        var item = document.getElementById(rid);
        if (!item) return;
        var statusEl = item.querySelector('.cright .cstatus');
        if (statusEl) statusEl.textContent = 'Seen';
      });
    }
  });
}

// On-demand presence for every chat row visible in the list, batched into a
// single request instead of one per row. Applied after the list itself
// renders so a slow/offline presence check never blocks the chat list.
function _applyListPresence(matchIds) {
  if (typeof apiClient === 'undefined' || !apiClient.getAccessToken() || !matchIds.length) return;
  apiClient.getPresenceBatch(matchIds).then(function(map) {
    matchIds.forEach(function(mid) {
      var item = document.getElementById('dm-match-' + mid);
      if (!item) return;
      var dot = item.querySelector('.cav .online-d');
      if (!dot) return;
      var isOnline = !!(map[mid] && map[mid].online);
      dot.classList.toggle('offline', !isOnline);
    });
  }).catch(function(e) { console.warn('[CHAT] Presence batch fetch failed:', e); });
}

// Presence is only checked on-demand (no proactive server broadcast), so the
// dot on an already-rendered row would otherwise go stale until the next full
// fetchAndRenderChats() — re-check periodically for whatever rows are
// currently in the DOM so online/offline flips live without a reload.
setInterval(function() {
  if (!_isAppActive() || document.hidden) return;
  var dmContainer = document.getElementById('chat-dm-container');
  if (!dmContainer) return;
  var matchIds = Array.prototype.slice.call(dmContainer.querySelectorAll('.citem[id^="dm-match-"]'))
    .map(function(el) { return el.id.replace('dm-match-', ''); });
  if (matchIds.length) _applyListPresence(matchIds);
}, 15000);

async function fetchAndRenderChats() {
  if (typeof apiClient === 'undefined' || !apiClient.getAccessToken()) return;
  try {
    debugChatState('fetchAndRenderChats START', curChatId);
    const list = await apiClient.getConversations();
    console.log("Loaded conversations from database:", list);
    debugChatState('fetchAndRenderChats AFTER getConversations', curChatId);
    
    var dmContainer = document.getElementById('chat-dm-container');
    if (dmContainer) dmContainer.innerHTML = '';

    var chatList = document.getElementById('chat-list');
    if (chatList) {
      chatList.querySelectorAll('.citem[id^="dm-match-"], .citem[id^="uc-match-"]').forEach(function(el) {
        if (el.parentElement !== dmContainer) {
          el.remove();
        }
      });
    }

    if (list.length === 0) {
      // #chat-empty-section (driven by filterChatBySection) covers the empty case
      if (typeof filterChatBySection === 'function') filterChatBySection();
      return;
    }

    window._chatPartnerCache = window._chatPartnerCache || {};
    list.forEach(function(conv) {
      var partner = conv.partner;
      var matchId = conv.matchId;
      window._chatPartnerCache[matchId] = conv;
      var partnerName = partner.firstName + ' ' + (partner.lastName || '');
      var cleanName = partnerName.trim();
      var init = partner.firstName.charAt(0).toUpperCase();
      var bg = (partner.profile && partner.profile.customization && partner.profile.customization.badgeColor) || '#3d7bff';
      var photoUrl = (partner.photos && partner.photos[0] && partner.photos[0].url) || '';

      // Estilo Instagram: sin reloj fijo — tiempo RELATIVO ("3m", "1h") y el
      // preview del mensaje. El "cuándo" vive al final de la línea del mensaje.
      var lastMsgTxt = '⏳ Expires in 24h — say hi!';
      var lastMsgAgo = '';
      var statusHtml = '';
      if (conv.lastMessage) {
        lastMsgTxt = conv.lastMessage.content;
        lastMsgAgo = (typeof _timeAgo === 'function') ? _timeAgo(conv.lastMessage.createdAt) : '';
        var _isMine = conv.lastMessage.senderId === _getCurrentUserId();
        if (_isMine) {
          statusHtml = '<div class="cstatus">' + (conv.lastMessage.isRead ? 'Seen' : 'Sent') + '</div>';
        }
      }

      var avatarHtml = photoUrl
        ? '<div class="cav" style="background:'+bg+';"><img src="'+photoUrl+'" style="width:100%;height:100%;border-radius:50%;object-fit:cover;"/><div class="online-d offline"></div></div>'
        : '<div class="cav" style="background:'+bg+';"><span>'+init+'</span><div class="online-d offline"></div></div>';

      var isCrushMatch = !!conv.streamChannelId;
      var suffix = isCrushMatch ? ' 💘' : '';
      var rawHandle = (partner.handle || cleanName).replace('@', '');
      var nameToShow = rawHandle + suffix;

      window._unreadMessageCounts = window._unreadMessageCounts || {};
      window._unreadMessageCounts[matchId] = conv.unreadCount || 0;

      // Instagram-style: un PUNTO (no burbuja con número) cuando hay mensajes
      // sin leer; la segunda línea dice "N new messages · tiempo".
      // Instagram: siempre el mensaje real; en negrita blanco si NO lo has visto,
      // gris una vez leído. Mismo tamaño que el nombre. Punto a la derecha si hay
      // mensajes sin leer.
      var isUnrd = conv.unreadCount && conv.unreadCount > 0;
      var dotHtml = isUnrd ? '<div class="cdot"></div>' : '';
      var preHtml = '<div class="cpre' + (isUnrd ? ' cpre-unrd' : '') + '">' + lastMsgTxt + (lastMsgAgo ? ' <span class="cago">· ' + lastMsgAgo + '</span>' : '') + '</div>';

      if (dmContainer) {
        var existingItem = document.getElementById('dm-match-' + matchId);
        if (existingItem) existingItem.remove();

        var item = document.createElement('div');
        item.className = 'citem';
        item.id = 'dm-match-' + matchId;
        // Crush matches belong to Matches only; everyone else is a friend DM.
        // Keeping these apart is what stops friends showing up under Matches.
        item.setAttribute('data-csec', isCrushMatch ? 'matches' : 'individuals');
        item.onclick = function() {
          openChat(matchId, nameToShow, bg, init, false, [], false);
        };
        item.innerHTML = avatarHtml +
          '<div class="cmeta"><div class="cnm">'+nameToShow+'</div>'+preHtml+'</div>' +
          '<div class="cright">' + statusHtml + dotHtml + '</div>';
        dmContainer.appendChild(item);
      }

    });

    _applyListPresence(list.map(function(c) { return c.matchId; }));

    // One list, one render — the Matches chip filters #chat-list by data-csec.
    if (typeof filterChatBySection === 'function') filterChatBySection();

    var totalUnread = 0;
    if (window._unreadMessageCounts) {
      for (var mId in window._unreadMessageCounts) {
        totalUnread += window._unreadMessageCounts[mId] || 0;
      }
    }
    var chatsBadge = document.getElementById('nbadge-chats');
    if (chatsBadge) {
      if (totalUnread > 0) {
        chatsBadge.style.display = 'flex';
        chatsBadge.textContent = totalUnread > 9 ? '+9' : totalUnread;
      } else {
        chatsBadge.style.display = 'none';
      }
    }

  } catch(err) {
    console.error("Failed to fetch and render conversations:", err);
  }
}

function _logOut(force) {
  if (force === true) {
    _performLogoutExecution();
    return;
  }

  var isSpanish = (typeof window.currentLang !== 'undefined' && window.currentLang === 'es');

  var logoutTitle = isSpanish ? '¿Seguro que quieres cerrar sesión? 🎓' : 'Log out of UndrGradz? 🎓';
  var logoutMessage = isSpanish 
    ? 'No olvides regresar pronto para ver tus nuevos matches y eventos del campus.' 
    : 'Don\'t forget to check back soon for your new campus matches & events!';
  var confirmBtnText = isSpanish ? 'Cerrar Sesión' : 'Log Out';
  var cancelBtnText = isSpanish ? 'Quedarme en la App' : 'Stay Logged In';

  if (typeof ugzConfirm === 'function') {
    ugzConfirm({
      title: logoutTitle,
      message: logoutMessage,
      confirmText: confirmBtnText,
      cancelText: cancelBtnText,
      onConfirm: function() {
        _performLogoutExecution();
      }
    });
  } else {
    if (window.confirm(logoutMessage)) {
      _performLogoutExecution();
    }
  }
}

function _performLogoutExecution() {
  window._loggingOut = true;
  if (typeof apiClient !== 'undefined') {
    try { apiClient.logout(); } catch(e) {}
  }
  try {
    localStorage.removeItem('userPro');
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');
    localStorage.removeItem('token');
    localStorage.removeItem('ugz_token');
    localStorage.removeItem('ugz_snap_v3');
    localStorage.removeItem('ugz_last_screen');
    localStorage.removeItem('ugz_last_label');
  } catch(e) {}
  try {
    sessionStorage.removeItem('ugz_snap');
    sessionStorage.removeItem('ugz_last_screen');
    sessionStorage.removeItem('ugz_last_label');
  } catch(e) {}
  try {
    setActiveRootScreen('authscreen');
    document.querySelectorAll('.mov.open').forEach(function(m) {
      m.classList.remove('open');
    });
  } catch(e) {}
  try {
    var _u = location.href.split('#')[0];
    location.replace(_u);
  } catch(e) {
    try { location.reload(); } catch(e2) {}
  }
}
