function _gradApproaching(grad){if(!grad)return false;var mo=/May/i.test(grad)?5:(/Dec/i.test(grad)?12:6);var ym=(''+grad).match(/(\d{2})\s*$/);if(!ym)return false;var yr=2000+parseInt(ym[1]);var now=new Date();var months=(yr-now.getFullYear())*12+((mo-1)-now.getMonth());return months>=0&&months<=4;}
function _checkGradReminder(){try{if((obMode||userMode)!=='student')return;if(!_gradApproaching(userPro&&userPro.grad))return;if(typeof notifData==='undefined')return;for(var i=0;i<notifData.length;i++){if(notifData[i].id==='gradremind')return;}notifData.unshift({type:'grad',from:'Undrgradz',handle:'',av:'\U0001F393',color:'#fbbf24',msg:'Your graduation is approaching — make sure you transfer your info to Alumni so you keep everything. Settings → Graduating? → Switch.',time:'now',id:'gradremind'});if(typeof _updateNotifBadge==='function')_updateNotifBadge();}catch(e){}}
