function _usernameTaken(h){try{var _um=JSON.parse(localStorage.getItem('ugz_usernames')||'{}');var k=('@'+h.replace(/^@/,'')).toLowerCase();var mine=(userPro&&userPro.handle||'').toLowerCase();return _um[k]&&_um[k]!==((document.getElementById('ob-email')||{}).value||'').toLowerCase()&&k!==mine;}catch(e){return false;}}
function checkHandle(inp) {
  var v = inp.value.replace(/\s/g, '').toLowerCase();
  v = v.replace(/^@+/, '');
  if (v.length > 15) v = v.slice(0, 15);
  inp.value = v;
  
  var msg = document.getElementById('handle-msg');
  if (!msg) return;
  // Nothing to say until the user actually types — never a status on a blank
  // (or freshly pre-filled, untouched) field.
  if (!v.length) { msg.textContent = ''; msg.style.display = 'none'; inp.style.borderColor = ''; return; }
  msg.style.display = '';

  var regex = /^[a-zA-Z0-9](?:[a-zA-Z0-9]|(?:\.|_)(?![._])){2,13}[a-zA-Z0-9]$/;
  var isValidFormat = regex.test(v);
  var isBanned = BANNED.some(function(w) { return v.includes(w); });
  
  if (v.length < 4) {
    msg.textContent = 'Min. 4 characters';
    msg.style.color = '#dc2626';
    inp.style.borderColor = '#dc2626';
  } else if (!isValidFormat) {
    msg.textContent = '⚠️ Invalid format';
    msg.style.color = '#dc2626';
    inp.style.borderColor = '#dc2626';
  } else if (isBanned) {
    msg.textContent = '⚠️ Restricted word';
    msg.style.color = '#dc2626';
    inp.style.borderColor = '#dc2626';
  } else if (typeof _usernameTaken === 'function' && _usernameTaken(v)) {
    msg.textContent = '⚠️ Taken';
    msg.style.color = '#dc2626';
    inp.style.borderColor = '#dc2626';
  } else {
    msg.textContent = '✓ Available';
    msg.style.color = '#4ade80';
    inp.style.borderColor = '#4ade80';
  }
}
function toggleFlag(el,lang){el.classList.toggle('on');if(el.classList.contains('on'))selectedFlags.push(lang);else selectedFlags=selectedFlags.filter(function(l){return l!==lang;});}
