// ── PHONE + OTP ──
function sendOTP(inputId){var phone=document.getElementById(inputId);if(!phone||phone.value.length<7){alert('Enter a valid phone number.');return;}var row=document.getElementById(inputId.replace('phone','otp-row'));if(row)row.style.display='block';var msg=document.getElementById(inputId.replace('phone','otp-msg'));if(msg){msg.textContent='✓ OTP sent';msg.style.color='#4ade80';}setTimeout(function(){if(msg){msg.textContent='✓ Code verified';msg.style.color='#4ade80';}},3000);}
function otpNext(inp){if(inp.value.length===1){var next=inp.nextElementSibling;if(next&&next.tagName==='INPUT')next.focus();}}

// ── 21+ TOGGLE ──
function toggle21Plus(){var row=document.getElementById('ev-21-toggle');if(!row)return;var isOn=!(row.dataset.on==='1');row.dataset.on=isOn?'1':'0';var sw=document.getElementById('ev-21-sw');if(sw)sw.classList.toggle('on',isOn);row.style.borderColor=isOn?'#fbbf24':'transparent';var inp=document.getElementById('ev-age-restrict');if(inp)inp.value=isOn?'21plus':'all';}

// ── BIZ PLAN TAB (Upgrade page) ──
function setBizPlanTab(t){['mo','yr'].forEach(function(id){var el=document.getElementById('biz-tab-'+id);if(el)el.classList.toggle('on',id===t);});var pp=document.getElementById('ob-biz-plan-price');if(pp)pp.innerHTML=t==='yr'?'$249<span class="t-body">/yr</span>':'$49<span class="t-body">/mo</span>';var cp=document.getElementById('ob-biz-campus-price');if(cp)cp.innerHTML=t==='yr'?'$749<span class="t-body">/yr</span>':'$149<span class="t-body">/mo</span>';}

// ── FIXED ANON TOGGLE ──
toggleAnon=function(){anonMode=!anonMode;var btn=document.getElementById('anon-btn');if(btn){btn.classList.toggle('on',anonMode);btn.style.color=anonMode?'var(--p)':'';btn.style.borderColor='';btn.style.background='';}var tooltip=document.getElementById('anon-tooltip');if(tooltip)tooltip.style.display='block';setTimeout(function(){if(tooltip)tooltip.style.display='none';},2000);};

// ── VOTE POST (1 vote total, switchable) ──
function votePost(btn,dir){
  var pacts=btn.closest('.pacts');if(!pacts)return;
  var upBtn=pacts.querySelector('button:first-child');
  var downBtn=pacts.querySelectorAll('button')[1];
  if(!upBtn||!downBtn)return;
  var upNum=parseInt(upBtn.textContent.replace(/[^0-9]/g,''))||0;
  var downNum=parseInt(downBtn.textContent.replace(/[^0-9]/g,''))||0;
  var curVote=pacts.dataset.vote||'none';
  if(dir===1){
    if(curVote==='up')return;
    if(curVote==='down'){downNum=Math.max(0,downNum-1);downBtn.textContent='▼ '+downNum;downBtn.style.color='';}
    upBtn.textContent='▲ '+(upNum+1);upBtn.style.color='#4ade80';pacts.dataset.vote='up';
  }else{
    if(curVote==='down')return;
    if(curVote==='up'){upNum=Math.max(0,upNum-1);upBtn.textContent='▲ '+upNum;upBtn.style.color='';}
    downBtn.textContent='▼ '+(downNum+1);downBtn.style.color='#dc2626';pacts.dataset.vote='down';
  }
}

// ── FIXED SOCIAL LINKS ──
addLink=function(){var raw=prompt('Enter URL or @username (Instagram, YouTube, LinkedIn, TikTok, Snapchat, Twitter/X)');if(!raw)return;raw=raw.trim();var url=raw,display=raw,icon='🔗';
  if(raw.match(/^@/)){url='https://instagram.com/'+raw.replace('@','');display=raw;icon='📸';}
  else if(raw.includes('instagram')){icon='📸';if(!raw.startsWith('http'))url='https://'+raw;var m2=raw.match(/instagram\.com\/([^\/\s?]+)/);display=m2?'@'+m2[1]:raw;}
  else if(raw.includes('youtube')){icon='▶️';if(!raw.startsWith('http'))url='https://'+raw;display=url.replace('https://','').replace('www.','');}
  else if(raw.includes('linkedin')){icon='💼';if(!raw.startsWith('http'))url='https://'+raw;display=url.replace('https://','').replace('www.','');}
  else if(raw.includes('tiktok')){icon='🎵';if(!raw.startsWith('http'))url='https://'+raw;display=url.replace('https://','').replace('www.','');}
  else if(raw.includes('snapchat')){icon='👻';if(!raw.startsWith('http'))url='https://'+raw;display=url.replace('https://','').replace('www.','');}
  else{if(!raw.startsWith('http'))url='https://'+raw;display=url.replace('https://','').replace('www.','').split('/')[0];}
  var list=document.getElementById('links-list');if(!list)return;
  var d=document.createElement('div');d.style.cssText='display:flex;align-items:center;gap:8px;padding:8px var(--s);font-size:var(--fs-base);';
  d.innerHTML='<span style="font-size:var(--fs-md);">'+icon+'</span> <a href="'+url+'" target="_blank" style="color:var(--fg);text-decoration:none;font-weight:600;">'+display+'</a><button onclick="this.parentElement.remove()" style="margin-left:auto;background:none;border:none;color:var(--fg3);cursor:pointer;font-size:var(--fs-base);">✕</button>';
  list.appendChild(d);
};

// ── MAX SPOTS ENFORCEMENT ──
