// CHAT PHOTO/VIDEO SEND — See Once / Keep in Chat
// ══════════════════════════════════════════════════════
function chatSendPhoto(){
  var inp=document.createElement('input');inp.type='file';inp.accept='image/*,video/*';
  inp.onchange=function(){if(!inp.files[0])return;
    var file=inp.files[0];var url=URL.createObjectURL(file);var isVideo=file.type.startsWith('video/');
    // Ask see once or keep
    var modal=document.createElement('div');modal.id='photo-send-modal';modal.className='mov open';
    modal.innerHTML='<div class="msheet"><div class="mhnd"></div><div class="mtitle">Send '+(isVideo?'Video':'Photo')+'</div>'+
      '<div style="border-radius:var(--rad-md);overflow:hidden;margin-bottom:12px;max-height:240px;">'+
        (isVideo?'<video src="'+url+'" style="width:100%;max-height:240px;border-radius:var(--rad-md);" controls></video>':'<img src="'+url+'" style="width:100%;max-height:240px;object-fit:cover;border-radius:var(--rad-md);"/>')+
      '</div>'+
      '<div style="display:flex;gap:8px;">'+
        '<button class="gbtn" style="background:var(--p);flex:1;" onclick="chatDoSendPhoto(\''+url+'\',false,'+isVideo+')">📌 Keep in Chat</button>'+
        '<button class="gbtn" style="background:#b45309;flex:1;" onclick="chatDoSendPhoto(\''+url+'\',true,'+isVideo+')">👁 See Once</button>'+
      '</div>'+
      '<button class="gbtn-ghost" onclick="document.getElementById(\'photo-send-modal\').remove()">Cancel</button></div>';
    document.body.appendChild(modal);
  };inp.click();
}

function chatDoSendPhoto(url,seeOnce,isVideo){
  var modal=document.getElementById('photo-send-modal');if(modal)modal.remove();
  if(!curChatId)return;if(!chatHistory[curChatId])chatHistory[curChatId]=[];
  // For see once, we'll create a special message
  if(seeOnce){
    chatHistory[curChatId].push({txt:'[👁 View Once '+(isVideo?'Video':'Photo')+']',out:true,seeOnce:true,isVideo:isVideo,img:url});
  }else{
    chatHistory[curChatId].push({txt:'['+(isVideo?'Video':'Photo')+']',out:true,img:url});
    // Track shared photos
    if(!chatSharedPhotos[curChatId])chatSharedPhotos[curChatId]=[];
    chatSharedPhotos[curChatId].push(url);
  }
  renderMsgs();
}

// Attachment, Camera Photo, and Icebreaker Game Handlers
function _openChatAttachmentPicker() {
  if (!curChatId) return;
  var inp = document.createElement('input');
  inp.type = 'file';
  inp.accept = '*/*';
  inp.onchange = function() {
    if (!inp.files || !inp.files[0]) return;
    var file = inp.files[0];
    var isImage = file.type.startsWith('image/');
    var isAudio = file.type.startsWith('audio/');
    var isVideo = file.type.startsWith('video/');

    var reader = new FileReader();
    reader.onload = function(e) {
      var dataUrl = e.target.result;
      if (!chatHistory[curChatId]) chatHistory[curChatId] = [];
      if (isImage) {
        chatHistory[curChatId].push({ img: dataUrl, out: true });
      } else if (isAudio) {
        chatHistory[curChatId].push({ txt: '🎤 Mensaje de voz', type: 'AUDIO', mediaUrl: dataUrl, duration: 10, out: true });
      } else if (isVideo) {
        chatHistory[curChatId].push({ img: dataUrl, isVideo: true, out: true });
      } else {
        chatHistory[curChatId].push({ txt: file.name, type: 'FILE', mediaUrl: dataUrl, out: true });
      }
      renderMsgs();
    };
    reader.readAsDataURL(file);
  };
  inp.click();
}

function chatSendPhoto() {
  if (!curChatId) return;
  var inp = document.createElement('input');
  inp.type = 'file';
  inp.accept = 'image/*';
  inp.onchange = function() {
    if (!inp.files || !inp.files[0]) return;
    var reader = new FileReader();
    reader.onload = function(e) {
      var dataUrl = e.target.result;
      if (!chatHistory[curChatId]) chatHistory[curChatId] = [];
      chatHistory[curChatId].push({ img: dataUrl, out: true });
      renderMsgs();
      var isDbMatch = (typeof apiClient !== 'undefined' && apiClient.getAccessToken() && !curChatId.startsWith('biz_') && !curChatId.startsWith('net_') && !curChatId.startsWith('clist-') && !curChatId.includes('moment'));
      if (isDbMatch) {
        apiClient.sendChatMessage(curChatId, '📷 Foto', 'IMAGE', dataUrl);
      }
    };
    reader.readAsDataURL(inp.files[0]);
  };
  inp.click();
}

