var _datingPhotoIdx=0;
var _photoPermGranted=false,_photoPermCb=null;
function requestPhotoPermission(cb){
  _photoPermCb=cb;
  // No iOS-style "picture settings" sheet — notify the user once, then open the picker directly.
  if(!_photoPermGranted){
    _photoPermGranted=true;
    if(typeof notifData!=='undefined'){notifData.unshift({type:'info',from:'Undrgradz',handle:'',av:'📸',color:'#dc2626',msg:'Undrgradz will only use the photos you choose for your profile & Crush card.',time:'now',id:'photoperm_'+notifData.length});if(typeof _updateNotifBadge==='function')_updateNotifBadge();}
  }
  window._photoPermMode='all';window._photoWantCamera=false;
  var _cbf=_photoPermCb;_photoPermCb=null;if(_cbf)_cbf();
  return;
  var m=document.getElementById('photo-perm-modal');if(m)m.remove();
  m=document.createElement('div');m.id='photo-perm-modal';m.className='mov open';m.style.zIndex='9999';
  if(_photoPermGranted){
    // Permission already granted — just pick a source
    m.innerHTML='<div class="msheet" style="max-width:340px;text-align:center;"><div class="mhnd"></div>'+
      '<div class="mtitle" style="text-align:center;">Add a photo</div>'+
      '<button class="gbtn" style="background:var(--p);margin-bottom:8px;" onclick="grantPhotoPerm(\'camera\')">📷 Take Photo</button>'+
      '<button class="gbtn" style="background:rgba(255,255,255,0.12);color:#fff;margin-bottom:8px;" onclick="grantPhotoPerm(\'all\')">🖼️ Choose from Library</button>'+
      '<button class="gbtn-ghost" onclick="var p=document.getElementById(\'photo-perm-modal\');if(p)p.remove();_photoPermCb=null;">Cancel</button>'+
    '</div>';
  }else{
    m.innerHTML='<div class="msheet" style="max-width:340px;text-align:center;"><div class="mhnd"></div>'+
      '<div style="font-size:38px;margin:4px 0 8px;">🖼️</div>'+
      '<div class="mtitle" style="text-align:center;">Allow “Undrgradz” to access your photos?</div>'+
      '<div style="font-size:var(--fs-sm);color:var(--fg2);line-height:1.5;margin-bottom:14px;">Undrgradz will only use the photos you choose for your profile &amp; Crush card.</div>'+
      '<button class="gbtn" style="background:var(--p);margin-bottom:8px;" onclick="grantPhotoPerm(\'camera\')">📷 Take Photo</button>'+
      '<button class="gbtn" style="background:rgba(255,255,255,0.12);color:#fff;margin-bottom:8px;" onclick="grantPhotoPerm(\'all\')">Allow Access to All Photos</button>'+
      '<button class="gbtn" style="background:rgba(255,255,255,0.12);color:#fff;margin-bottom:8px;" onclick="grantPhotoPerm(\'limited\')">Select Photos…</button>'+
      '<button class="gbtn-ghost" onclick="var p=document.getElementById(\'photo-perm-modal\');if(p)p.remove();_photoPermCb=null;">Don’t Allow</button>'+
    '</div>';
  }
  document.body.appendChild(m);
}
function grantPhotoPerm(mode){
  if(mode==='camera'&&!confirm('📷 Allow “Undrgradz” to open your camera?')){return;}
  _photoPermGranted=true;window._photoPermMode=mode;window._photoWantCamera=(mode==='camera');
  var p=document.getElementById('photo-perm-modal');if(p)p.remove();
  if(_photoPermCb){var cb=_photoPermCb;_photoPermCb=null;cb();}
}
function uploadDatingPhoto(idx){
  _datingPhotoIdx=idx;
  var existing=userDatingPhotos[idx];
  if(!existing){requestPhotoPermission(function(){var f=document.getElementById('dating-photo-file');if(f){if(window._photoWantCamera){f.setAttribute('capture','user');}else{f.removeAttribute('capture');}window._photoWantCamera=false;f.click();}});return;}
  // Open an actions sheet for filled slots
  var modal=document.createElement('div');
  modal.className='mov open';modal.style.zIndex='9998';
  modal.innerHTML='<div class="msheet" style="max-width:340px;"><div class="mhnd"></div>'+
    '<div class="mtitle">Photo '+(idx+1)+(idx===0?' · Cover':'')+'</div>'+
    '<button class="gbtn" style="background:var(--p);margin-bottom:8px;" onclick="this.closest(\'.mov\').remove();_replaceDatingPhoto()">🔄 Replace photo</button>'+
    '<button class="gbtn-ghost" style="margin-bottom:8px;color:#dc2626;" onclick="this.closest(\'.mov\').remove();removeDatingPhoto('+idx+')">'+icon('trash',16)+' Remove photo</button>'+
    '<button class="gbtn-ghost" onclick="this.closest(\'.mov\').remove()">Cancel</button>'+
  '</div>';
  document.body.appendChild(modal);
}
function _replaceDatingPhoto(){document.getElementById('dating-photo-file').click();}
function removeDatingPhoto(idx){
  if(!confirm('Remove this photo?'))return;
  userDatingPhotos[idx]=null;
  if(userDatingPhotoPositions)userDatingPhotoPositions[idx]=null;
  if(userDatingPhotoCaptions)userDatingPhotoCaptions[idx]=null;
  renderDatingPhotoGrid();
  var count=userDatingPhotos.filter(Boolean).length;
  var msg=document.getElementById('photo-count-msg');if(msg)msg.textContent=count+'/6 photos'+(count<2?' · (optional)':' ✓');
  var btn=document.getElementById('dating-continue-btn');
  if(btn){if(true){btn.disabled=false;btn.style.opacity='1';btn.textContent='Enter Undrgradz 🚀';}else{btn.style.opacity='0.5';btn.textContent='Enter Undrgradz 🚀';}}
  renderObCrushPreview();
}
function handleDatingPhoto(inp){
  if(!inp.files[0])return;
  window._datingPhotoFiles = window._datingPhotoFiles || [];
  var file = inp.files[0];
  var url=URL.createObjectURL(file);
  var idx=_datingPhotoIdx;
  openImagePositioner(url,idx===0?'profile':'rect',function(u,pos){
    window._datingPhotoFiles[idx]=file;
    userDatingPhotos[idx]=u;userDatingPhotoPositions=userDatingPhotoPositions||[];userDatingPhotoPositions[idx]=pos;
    inp.value='';
    renderDatingPhotoGrid();
    var count=userDatingPhotos.filter(Boolean).length;
    var msg=document.getElementById('photo-count-msg');if(msg)msg.textContent=count+'/6 photos'+(count<2?' · (optional)':' ✓');
    var btn=document.getElementById('dating-continue-btn');
    if(btn){if(true){btn.disabled=false;btn.style.opacity='1';btn.textContent='Enter Undrgradz 🚀';}else{btn.style.opacity='0.5';btn.textContent='Enter Undrgradz 🚀';}}
    renderObCrushPreview();
  });
}
function finishOnboardingFromPhotos(){
  var count=userDatingPhotos.filter(Boolean).length;
  if(typeof _vibeSave==='function')try{_vibeSave();}catch(e){}
  // Sync dating photos → profile crush grid so launch() doesn't re-prompt
  var grid=document.getElementById('prof-photos');
  if(grid){
    userDatingPhotos.forEach(function(u,i){
      if(!u)return;
      var pos=(userDatingPhotoPositions&&userDatingPhotoPositions[i])||'center';
      var cap=(userDatingPhotoCaptions&&userDatingPhotoCaptions[i])||'';
      if(typeof crushPhotoCell==='function'){var d=crushPhotoCell(u,pos);if(cap)d.setAttribute('data-caption',cap);grid.insertBefore(d,grid.lastChild);}
      if(i===0){try{_profilePicUrl=u;if(typeof _syncFirstCrushPhoto==='function')_syncFirstCrushPhoto();}catch(e){}}
    });
    // Sync count label + preview now that all onboarding photos are in the grid
    if(typeof _syncFirstCrushPhoto==='function')try{_syncFirstCrushPhoto();}catch(e){}
  }
  launch();
  setTimeout(function(){if(typeof _showEntryPoll==="function")_showEntryPoll();},900);
}

