// selectSingleChip override — track crushGenderPref + show/hide DD panel
var _origSelectSingleChipDD=selectSingleChip;
selectSingleChip=function(el){
  _origSelectSingleChipDD(el);
  var section=el.closest('.love-filter-section');
  if(!section)return;
  var title=section.querySelector('.love-filter-title');
  if(!title||!title.textContent.includes('Interested'))return;
  var t=el.textContent.trim();
  var ddPanel=document.getElementById('dd-invite-panel');
  if(t.includes('Double Date')){
    crushGenderPref='any';
    if(ddPanel)ddPanel.style.display='block';
  } else {
    crushGenderPref=t.includes('Female')?'female':t.includes('Other')?'other':'male';
    if(ddPanel)ddPanel.style.display='none';
    // Cancel active double date if switching away
    if(crushDoubleDateMode){crushDoubleDateMode=false;crushDoubleDatePartner=null;}
  }
  // Keep the profile "Interested in" chips in sync
  document.querySelectorAll('#prof-interest-chips .yr-chip').forEach(function(c){
    var pt=c.textContent;
    var on=(crushGenderPref==='female'&&/Female/.test(pt))||(crushGenderPref==='male'&&/Male/.test(pt))||(crushGenderPref==='other'&&/Other/.test(pt))||(crushGenderPref==='any'&&/Double/.test(pt));
    c.classList.toggle('on',on);
  });
  // Sync the updated interestedIn preference to the database!
  if(typeof saveProfile==='function'){
    try {
      saveProfile();
    } catch(e) {
      console.error("Failed to save profile on filter change:", e);
    }
  }
  // Immediately reload the swipe deck from the database matching the new preference!
  if(typeof loadCrushFeed==='function'){
    loadCrushFeed();
  } else if(typeof crushDataAll!=='undefined'&&crushDataAll){
    crushData=crushDataAll.filter(function(p){return crushGenderPref==='any'?true:(!p.gender||p.gender===crushGenderPref);});
    crushIdx=0;
    if(typeof renderCrush==='function')renderCrush();
  }
};

