/* ══════════════════════════════════════════════════════════════════
   NEON PALETTE LOCK — remove university colors, force neon everywhere.
   School colors are NOT destroyed: originals stay in the UNI map and are
   stashed on the live uni object (uni._schoolP / uni._schoolP2) so they
   can be reintroduced in chosen spots later ("vamos a ver dónde").
   ══════════════════════════════════════════════════════════════════ */
(function(){
  var NP='#3d7bff', NP2='#3d7bff';
  function _neonizeUni(){
    try{
      if(typeof uni!=='undefined' && uni){
        uni.p = uni._schoolP || uni.p;
        uni.p2 = uni._schoolP2 || uni.p2;
      }
    }catch(e){}
  }
  function _paintNeon(){
    try{
      var de=document.documentElement;
      var primary = (typeof uni!=='undefined' && uni && uni.p) ? uni.p : NP;
      var secondary = (typeof uni!=='undefined' && uni && uni.p2) ? uni.p2 : NP2;
      var pPaint = (typeof _legiblePrimary === 'function') ? _legiblePrimary(primary) : primary;
      // El secundario también: es el que llevan halos, bordes y el degradado del
      // logo, y sin esto se quedaba en sRGB mientras el primario sí subía.
      var sPaint = (typeof _p3Boost === 'function') ? _p3Boost(secondary) : secondary;

      de.style.setProperty('--p', pPaint);
      de.style.setProperty('--p2', sPaint);
      // --cta-grad la escribía sólo _ob4UpdateUniTheme(), que vive en el
      // registro. Aquí también, porque el botón My University de Hangouts la usa
      // y fuera del registro no existía.
      if(typeof _ctaGradient === 'function'){
        de.style.setProperty('--cta-grad', _ctaGradient(primary, secondary, pPaint, sPaint) || 'none');
      }
      // Los dos en <body> también: un valor inline en body tapa el del root para
      // todo lo que cuelga de él, así que escribir solo arriba no llega a nada.
      if(document.body) {
        document.body.style.setProperty('--p', pPaint);
        document.body.style.setProperty('--p2', sPaint);
      }

      // Aquí había un _applyPrimaryContrast(primary). La línea de abajo reemplaza
      // esa función por una que vuelve a llamar a _paintNeon, así que era una
      // recursión mutua: se comía la pila en ~9.500 escrituras de estilo por cada
      // applyColors() y el catch de fuera se tragaba el desbordamiento en
      // silencio. En un teléfono eso es un tirón visible.
      // De lo que hacía solo sobrevive _applyAccentText(): las clases
      // dark-primary / light-primary que ponía las borra la línea siguiente de
      // todos modos, así que el resultado en pantalla es el mismo de siempre.
      if(typeof _applyAccentText === 'function') try{ _applyAccentText(); }catch(e){}

      de.classList.remove('dark-primary','light-primary','light-secondary');
      if (typeof _secDull === 'function' && secondary) {
        de.classList.toggle('light-secondary', _secDull(secondary));
      }
    }catch(e){}
  }
  // Override the theming funnels — every path now yields neon.
  window.applyColors=function(){ _neonizeUni(); _paintNeon(); try{var pun=document.getElementById('prof-uni-nm'); if(pun&&typeof uni!=='undefined'&&uni)pun.textContent=uni.name;}catch(e){} };
  window.setAccentColor=function(p,p2){ if(typeof uni==='undefined'||!uni){ uni={name:'My University',p:NP,p2:NP2}; } _neonizeUni(); _paintNeon(); };
  window.applySchoolTheme=function(){ _neonizeUni(); _paintNeon(); };
  window._applyPrimaryContrast=function(){ _paintNeon(); };
  // Apply now and again once the DOM is ready.
  _neonizeUni(); _paintNeon();
  document.addEventListener('DOMContentLoaded',function(){ _neonizeUni(); _paintNeon(); });
})();

let crushSearchTimeout = null;

function _renderSearchStudentCard(p) {
  var photoUrl = (p.photos && p.photos[0]) ? p.photos[0] : (p.photo || '');
  var init = (p.name || 'S').charAt(0).toUpperCase();
  var bg = p.bg || '#3d7bff';
  var acronym = (p.uni && p.uni.acronym) || _uniAcronymOf(p) || 'UTNC';
  var major = p.major || acronym;
  var handle = p.handle || (p.name || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  var fullName = p.name || 'Student';

  var avatarHtml = photoUrl
    ? '<img src="' + photoUrl + '" style="width:100%;height:100%;border-radius:50%;object-fit:cover;display:block;"/>'
    : '<div style="width:100%;height:100%;border-radius:50%;background:' + bg + ';display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;font-size:var(--fs-md);">' + init + '</div>';

  var safeName = fullName.replace(/'/g, "\\'");
  var cardIsVerified = p.isVerified || p.verified || ((userPro.isVerified || verified) && (fullName === userPro.name || handle === userPro.handle || '@' + handle === userPro.handle));

  return '<div class="search-student-card" onclick="openProfileCardByName(\'' + safeName + '\')">' +
    '<div style="position:relative;width:48px;height:48px;border-radius:50%;flex-shrink:0;">' +
      '<div style="width:100%;height:100%;border-radius:50%;overflow:hidden;">' + avatarHtml + '</div>' +
      '<div style="position:absolute;bottom:-1px;right:-1px;width:13px;height:13px;border-radius:50%;background:#4ade80;border:2px solid #0d0d12;"></div>' +
    '</div>' +
    '<div style="flex:1;min-width:0;">' +
      '<div style="font-size:var(--fs-base);font-weight:700;color:#ffffff;display:flex;align-items:center;gap:4px;">' +
        '<span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + fullName + '</span>' +
        _getVerifyBadgeHtml(cardIsVerified, 14) +
        (p.age ? '<span style="font-size:var(--fs-sm);color:#d6e4ff;font-weight:500;margin-left:2px;">' + p.age + '</span>' : '') +
      '</div>' +
      '<div style="font-size:var(--fs-sm);color:#9aa3af;font-weight:500;margin-top:2px;display:flex;align-items:center;gap:5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' +
        '@' + String(handle).replace(/^@+/, '') + ' <span style="opacity:.6;">·</span> ' + icon('landmark',12) + ' ' + acronym +
      '</div>' +
    '</div>' +
    '<button style="background:transparent;border:1.5px solid #22c55e;border-radius:999px;padding:7px 16px;color:#22c55e;font-family:var(--font);font-size:var(--fs-xs);font-weight:700;cursor:pointer;flex-shrink:0;" onclick="event.stopPropagation();openProfileCardByName(\'' + safeName + '\')">Ver Perfil</button>' +
  '</div>';
}

function openProfileCardByName(name) {
  // "Ver Perfil" should show the actual photo card with the relationship
  // actions underneath, not just the details sheet — so route through the
  // full-screen viewer with a 'search' origin, which swaps the swipe bar for
  // Add Friend / Report / Block.
  var pFull = null;
  if (typeof crushDataAll !== 'undefined' && crushDataAll) {
    pFull = crushDataAll.filter(function (x) { return x.name === name; })[0];
  }
  if (!pFull && typeof crushData !== 'undefined' && crushData) {
    pFull = crushData.filter(function (x) { return x.name === name; })[0];
  }
  if (pFull && typeof viewUserUnicrush === 'function') {
    viewUserUnicrush(pFull.handle || null, name, pFull.bg || '#3d7bff', '', 'search');
    return;
  }

  // Fallback: no card data for this person — show the details sheet instead.
  if (typeof crushData !== 'undefined' && crushData) {
    var idx = -1;
    for (var i = 0; i < crushData.length; i++) {
      if (crushData[i].name === name) { idx = i; break; }
    }
    if (idx >= 0) {
      crushIdx = idx;
      openCrushDetailsModal();
      _appendRelationBarToDetails(name);
      return;
    }
  }
  if (typeof crushDataAll !== 'undefined' && crushDataAll) {
    var p2 = crushDataAll.filter(function(x){ return x.name === name; })[0];
    if (p2) {
      var modal = document.getElementById('crush-details-modal');
      if (modal && typeof buildHingeStackHtml === 'function') {
        var _u2=(p2.uni&&p2.uni.name)?p2.uni.name:'';
        var title = document.getElementById('crush-details-title');
        if (title) title.innerHTML = (p2.name||'') + (_u2?'<div style="font-size:var(--fs-2xs);font-weight:600;color:var(--fg2);font-family:var(--font);margin-top:3px;">🎓 '+_u2+'</div>':'');
        var content = document.getElementById('crush-details-content');
        if (content) {
          content.innerHTML = buildHingeStackHtml(p2, {isSelf: false, onlyDetails: true});
        }
        modal.classList.add('open');
        _appendRelationBarToDetails(name);
      }
    }
  }
}

// This sheet is reached by looking someone up, so it gets the relationship
// actions too — never the swipe buttons.
function _appendRelationBarToDetails(name) {
  var content = document.getElementById('crush-details-content');
  if (!content) return;
  window._ucViewUser = window._ucViewUser || {};
  window._ucViewUser.name = name;
  window._ucViewUser.origin = 'search';
  var prev = document.getElementById('crush-details-relbar');
  if (prev) prev.remove();
  content.insertAdjacentHTML('beforeend',
    '<div id="crush-details-relbar" style="margin-top:16px;">' + _relationBarHtml(name) + '</div>');
}

function _getUniversityStudents(limit) {
  limit = limit || 8;
  var myUniName = (typeof uni !== 'undefined' && uni && uni.name) || (typeof userPro !== 'undefined' && userPro && userPro.uni) || 'Universidad Tecnológica del Norte de Coahuila';
  var pool = [];
  if (typeof crushDataAll !== 'undefined' && crushDataAll && crushDataAll.length) {
    pool = crushDataAll.filter(function(p) {
      return !p.uni || !p.uni.name || p.uni.name === myUniName || p.uni.name.indexOf('Tecnológica') > -1;
    });
    if (pool.length < 4) pool = crushDataAll.slice();
  }
  var shuffled = pool.slice().sort(function() { return 0.5 - Math.random(); });
  return shuffled.slice(0, limit);
}

async function handleCrushSearch(query) {
  if (crushSearchTimeout) clearTimeout(crushSearchTimeout);
  
  const container = document.getElementById('crush-search-results');
  if (!container) return;
  
  const myUniAcronym = (typeof uni !== 'undefined' && uni && uni.acronym) || 'UTNC';
  const myUniName = (typeof uni !== 'undefined' && uni && uni.name) || 'UTNC';

  const sInput = document.getElementById('crush-search-input');
  if (sInput && !sInput.placeholder.includes(myUniAcronym)) {
    sInput.placeholder = 'Search students at ' + myUniAcronym + '...';
  }

  const q = (query || '').trim();
  if (!q) {
    var students = _getUniversityStudents(8);
    // El label "ESTUDIANTES DE …" y el botón Mezclar suelto se quitaron: Mezclar
    // ahora vive DENTRO de la barra de búsqueda (index.html #crush-search-shuffle).
    var cardsHtml = students.map(_renderSearchStudentCard).join('');
    container.innerHTML = cardsHtml;
    return;
  }
  
  crushSearchTimeout = setTimeout(async () => {
    try {
      var matches = [];
      if (typeof crushDataAll !== 'undefined' && crushDataAll) {
        var lowerQ = q.toLowerCase();
        matches = crushDataAll.filter(function(u) {
          return (u.name && u.name.toLowerCase().includes(lowerQ)) ||
                 (u.handle && u.handle.toLowerCase().includes(lowerQ)) ||
                 (u.major && u.major.toLowerCase().includes(lowerQ));
        });
      }
      
      if (matches.length === 0 && typeof apiClient !== 'undefined' && apiClient.getAccessToken()) {
        let users = await apiClient.searchUsers(q);
        matches = users.map(function(u) {
          return {
            name: u.firstName + ' ' + (u.lastName || ''),
            handle: u.handle,
            major: (u.profile && u.profile.major) || _uniAcronymOf(u),
            age: u.age,
            isVerified: !!u.isVerified,
            photo: (u.photos && u.photos[0] && u.photos[0].url) || null,
            photos: (u.photos && u.photos.map(function(p){ return p.url; })) || [],
            uni: { name: (u.profile && u.profile.university) || myUniName, acronym: myUniAcronym }
          };
        });
      }

      if (matches.length === 0) {
        container.innerHTML = '<div style="text-align:center;padding:36px 0;font-size:var(--fs-base);color:rgba(255,255,255,0.6);">No students found matching "' + q + '" '+icon('search',16)+'</div>';
        return;
      }
      
      var headerHtml = '<div style="font-size:var(--fs-sm);font-weight:700;color:#a9c4ff;text-transform:uppercase;letter-spacing:0.8px;margin-bottom:14px;">'+icon('search',16)+' RESULTADOS PARA "' + q.toUpperCase() + '"</div>';
      container.innerHTML = headerHtml + matches.map(_renderSearchStudentCard).join('');
    } catch (e) {
      console.error("Search error:", e);
    }
  }, 100);
}

async function sendCrushFriendRequest(userId, btn) {
  btn.disabled = true;
  btn.style.background = 'rgba(255,255,255,0.08)';
  btn.style.color = 'var(--fg3)';
  btn.textContent = 'Sending...';
  
  try {
    await apiClient.sendFriendRequest(userId);
    btn.textContent = '✓ Sent';
    if (typeof addToActivity === 'function') {
      addToActivity("Sent a friend request to a student.");
    }
  } catch (e) {
    console.error("Friend request error:", e);
    btn.disabled = false;
    btn.style.background = 'var(--p)';
    btn.style.color = '#fff';
    btn.textContent = 'Add +';
    alert(e.message || "Failed to send friend request. They might already be your friend or have a pending request!");
  }
}

// Spanish sibling of _timeAgo, for the Discover sections — their copy is in
// Spanish, and _timeAgo's "3d ago" reads as a leftover next to it.
function _agoEs(dateStr) {
  if (!dateStr) return '';
  var seconds = Math.floor((new Date() - new Date(dateStr)) / 1000);
  if (isNaN(seconds)) return '';
  if (seconds < 60) return 'ahora';
  var minutes = Math.floor(seconds / 60);
  if (minutes < 60) return 'hace ' + minutes + 'm';
  var hours = Math.floor(minutes / 60);
  if (hours < 24) return 'hace ' + hours + 'h';
  var days = Math.floor(hours / 24);
  if (days < 7) return 'hace ' + days + 'd';
  var weeks = Math.floor(days / 7);
  if (weeks < 5) return 'hace ' + weeks + 'sem';
  return 'hace ' + Math.floor(days / 30) + 'mes';
}

function _timeAgo(dateStr) {
  if (!dateStr) return 'now';
  const seconds = Math.floor((new Date() - new Date(dateStr)) / 1000);
  if (seconds < 60) return 'now';
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return minutes + 'm ago';
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return hours + 'h ago';
  const days = Math.floor(hours / 24);
  return days + 'd ago';
}

function openChatFromNotif(matchId) {
  if (window._unreadMessageCounts) {
    window._unreadMessageCounts[matchId] = 0;
  }
  if (typeof notifData !== 'undefined') {
    notifData = notifData.filter(function(n) { return n.id !== 'msg_' + matchId; });
  }
  if (typeof _updateNotifBadge === 'function') _updateNotifBadge();
  
  if (typeof sw === 'function') sw('chats', 'Chats');
  
  var conv = (typeof _chatPartnerCache !== 'undefined') ? _chatPartnerCache[matchId] : null;
  if (conv) {
    var partner = conv.partner;
    var name = partner.firstName + ' ' + (partner.lastName || '');
    var bg = (partner.profile && partner.profile.customization && partner.profile.customization.badgeColor) || '#3d7bff';
    var photoUrl = (partner.photos && partner.photos[0] && partner.photos[0].url) || '';
    if (typeof openChat === 'function') {
      openChat(matchId, name, bg, photoUrl ? '' : name.charAt(0), false);
    }
  }
}

async function liveChatSearch(q) {
  var d = document.getElementById('chat-search-results-drop');
  if (!d) return;
  
  q = q.replace('@', '').toLowerCase().trim();
  if (!q) {
    d.style.display = 'none';
    d.innerHTML = '';
    return;
  }
  
  var domChats = [];
  var seenIds = new Set();
  
  document.querySelectorAll('#chat-list .citem, #uc-chat-list .citem, #chat-dm-container .citem').forEach(function(item) {
    if (seenIds.has(item.id)) return;
    seenIds.add(item.id);
    
    var nameEl = item.querySelector('.cnm');
    var previewEl = item.querySelector('.cpre');
    var avatarEl = item.querySelector('.cav');
    
    if (nameEl) {
      var nameText = nameEl.textContent;
      var previewText = previewEl ? previewEl.textContent : '';
      var avatarHtml = avatarEl ? avatarEl.outerHTML : '';
      
      domChats.push({
        id: item.id,
        name: nameText,
        preview: previewText,
        avatarHtml: avatarHtml
      });
    }
  });
  
  var matchedChats = domChats.filter(function(c) {
    return c.name.toLowerCase().indexOf(q) > -1 || c.preview.toLowerCase().indexOf(q) > -1;
  });
  
  var matchedFriends = [];
  if (window._myFriendsCache) {
    matchedFriends = window._myFriendsCache.filter(function(entry) {
      var f = entry.friend;
      var handle = (f.handle || '').toLowerCase();
      var firstName = (f.firstName || '').toLowerCase();
      var lastName = (f.lastName || '').toLowerCase();
      var fullName = firstName + ' ' + lastName;
      
      var hasActiveChat = matchedChats.some(function(c) {
        return c.name.toLowerCase().indexOf(firstName) > -1 || c.name.toLowerCase().indexOf(lastName) > -1;
      });
      if (hasActiveChat) return false;
      
      return handle.indexOf(q) > -1 || firstName.indexOf(q) > -1 || lastName.indexOf(q) > -1 || fullName.indexOf(q) > -1;
    });
  }
  
  if (matchedChats.length === 0 && matchedFriends.length === 0) {
    d.style.display = 'block';
    d.innerHTML = '<div style="padding:14px;text-align:center;font-size:var(--fs-sm);color:var(--fg3);">No matching chats or friends found</div>';
    return;
  }
  
  d.style.display = 'block';
  var h = '';
  
  if (matchedChats.length > 0) {
    h += '<div style="font-size:var(--fs-2xs);font-weight:700;color:var(--fg3);letter-spacing:.7px;padding:8px 14px 4px;">ACTIVE CHATS & EVENTS</div>';
    h += matchedChats.map(function(c) {
      return '<div onpointerdown="event.preventDefault(); _clickChatRow(\'' + c.id + '\')" style="display:flex;align-items:center;gap:11px;padding:9px 14px;cursor:pointer;border-bottom:1px solid var(--gbdl);touch-action:manipulation;">' +
        '<div style="width:38px;height:38px;border-radius:50%;flex-shrink:0;overflow:hidden;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,0.02);">' + c.avatarHtml + '</div>' +
        '<div style="flex:1;min-width:0;">' +
          '<div style="font-size:var(--fs-base);font-weight:600;color:#fff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + c.name + '</div>' +
          '<div style="font-size:var(--fs-xs);color:var(--fg2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + c.preview + '</div>' +
        '</div>' +
      '</div>';
    }).join('');
  }
  
  if (matchedFriends.length > 0) {
    h += '<div style="font-size:var(--fs-2xs);font-weight:700;color:var(--fg3);letter-spacing:.7px;padding:12px 14px 4px;border-top:1px solid var(--gbdl);">FRIENDS (START A CHAT)</div>';
    h += matchedFriends.map(function(entry) {
      var f = entry.friend;
      var photoUrl = (f.photos && f.photos[0] && f.photos[0].url) || '';
      var init = f.firstName.charAt(0).toUpperCase();
      var customization = (f.profile && f.profile.customization) || {};
      var badgeColor = customization.badgeColor || '#3d7bff';
      var handle = f.handle || '';
      var fullName = f.firstName + ' ' + (f.lastName || '');
      
      var avatar = photoUrl
        ? '<img src="' + photoUrl + '" style="width:100%;height:100%;border-radius:50%;object-fit:cover;display:block;"/>'
        : '<div style="width:100%;height:100%;border-radius:50%;background:' + badgeColor + ';display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;font-size:var(--fs-base);">' + init + '</div>';
        
      var safeName = fullName.replace(/'/g, "\\'");
      return '<div onpointerdown="event.preventDefault(); _startFriendChat(\'' + f.id + '\',\'' + safeName + '\',\'' + badgeColor + '\',\'' + init + '\')" style="display:flex;align-items:center;gap:11px;padding:9px 14px;cursor:pointer;border-bottom:1px solid var(--gbdl);touch-action:manipulation;">' +
        '<div style="width:38px;height:38px;border-radius:50%;flex-shrink:0;overflow:hidden;background:rgba(255,255,255,0.02);display:flex;align-items:center;justify-content:center;">' + avatar + '</div>' +
        '<div style="flex:1;min-width:0;">' +
          '<div style="font-size:var(--fs-base);font-weight:600;color:#fff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + fullName + '</div>' +
          '<div class="t-meta">@' + handle + '</div>' +
        '</div>' +
      '</div>';
    }).join('');
  }
  
  d.innerHTML = h;
}

function _clickChatRow(id) {
  var d = document.getElementById('chat-search-results-drop');
  if (d) d.style.display = 'none';
  var inp = document.getElementById('chat-search');
  if (inp) { inp.value = ''; inp.blur(); }
  
  var el = document.getElementById(id);
  if (el) el.click();
}

async function _startFriendChat(friendId, fullName, badgeColor, init) {
  var d = document.getElementById('chat-search-results-drop');
  if (d) d.style.display = 'none';
  var inp = document.getElementById('chat-search');
  if (inp) { inp.value = ''; inp.blur(); }
  
  try {
    const result = await apiClient.createConversation(friendId);
    const matchId = result.matchId;
    if (typeof openChat === 'function') {
      openChat(matchId, fullName, badgeColor, init, false, ['Say hi! 👋'], false);
    }
    if (typeof fetchAndRenderChats === 'function') fetchAndRenderChats();
  } catch (err) {
    console.error("Failed to start conversation with friend:", err);
    alert("Could not start conversation with friend. Please try again later.");
  }
}

