function sendVerificationCode() {
  var emailVal = (document.getElementById('ob-email') || {}).value || '';
  if (!/^\S+@\S+\.\S+/.test(emailVal)) {
    alert('Please enter a valid email address first.');
    return;
  }
  var d = (emailVal.split('@')[1] || '').toLowerCase();
  var u = d ? UNI[_resolveUniDomain(d)] : null;
  if (!u) {
    alert('This email domain does not belong to a supported university.');
    return;
  }
  var container = document.getElementById('email-code-container');
  if (container) {
    container.style.display = 'block';
  }
  alert('Verification code sent to ' + emailVal);
}

function verifyCodeInput(inp) {
  inp.value = inp.value.replace(/[^0-9]/g, '');
  var successCheck = document.getElementById('code-success-check');
  if (inp.value.length === 6) {
    inp.style.borderColor = '#4ade80';
    inp.style.background = 'rgba(74, 222, 128, 0.08)';
    if (successCheck) successCheck.style.display = 'block';
    _ob4State.emailVerified = true;
  } else {
    inp.style.borderColor = '';
    inp.style.background = '';
    if (successCheck) successCheck.style.display = 'none';
    _ob4State.emailVerified = false;
  }
  _ob4Strength();
  _ob4ValidateAll();
}

function checkPasswordStrength(val) {
  if (suData) suData.pass = val;
  val = val || '';
  // Live 4-segment meter + checklist, so the rules are visible AS you type
  // instead of hidden behind a submit-time alert.
  var rules = {
    len: val.length >= 8,
    case: /[a-z]/.test(val) && /[A-Z]/.test(val),
    num: /\d/.test(val),
    spec: /[@$!%*?&._\-]/.test(val)
  };
  var met = (rules.len?1:0) + (rules.case?1:0) + (rules.num?1:0) + (rules.spec?1:0);
  var meter = document.getElementById('pass-meter');
  if (meter) {
    meter.style.display = val ? 'block' : 'none';
    var cols = ['#dc2626', '#f59e0b', '#eab308', '#22c55e'];
    var bars = meter.querySelectorAll('.pw-bar');
    for (var i = 0; i < bars.length; i++) {
      bars[i].style.background = (i < met) ? cols[Math.max(0, met - 1)] : 'rgba(255,255,255,0.12)';
    }
    Object.keys(rules).forEach(function (k) {
      var el = meter.querySelector('[data-rule="' + k + '"]');
      if (el) { el.style.color = rules[k] ? '#4ade80' : 'var(--fg3)'; el.style.fontWeight = rules[k] ? '700' : '500'; }
    });
  }
  // The old single red line is now redundant — the meter says it all.
  var msg = document.getElementById('pass-msg');
  if (msg) msg.style.display = 'none';
  _ob4Strength();
  _ob4ValidateAll();
}

function togglePhoneCodeDropdown(e) {
  e.stopPropagation();
  var dropdown = document.getElementById('ob-phone-flag-dropdown');
  if (dropdown) {
    dropdown.style.display = dropdown.style.display === 'none' ? 'block' : 'none';
  }
}

function selectPhoneCountry(code, prefix) {
  var flagImg = document.getElementById('selected-flag-img');
  if (flagImg) flagImg.src = 'https://flagcdn.com/w40/' + code + '.png';
  if (code === 'ca') {
    _ob4State.country = 'ca';
  } else {
    _ob4State.country = 'us';
  }
  var phoneInput = document.getElementById('ob-phone');
  _ob4State.phoneCode = prefix;
  if (phoneInput) {
    var currentVal = phoneInput.value;
    currentVal = currentVal.replace(/^\+\d+\s*/, '');
    phoneInput.value = prefix + ' ' + currentVal;
    formatPhoneNumber(phoneInput);
  }
  var dropdown = document.getElementById('ob-phone-flag-dropdown');
  if (dropdown) dropdown.style.display = 'none';
}

function formatPhoneNumber(inp) {
  var prefix = _ob4State.phoneCode || '+1';
  var v = inp.value;
  if (!v.startsWith(prefix)) {
    v = prefix + ' ' + v.replace(/[^\d]/g, '');
  }
  var digits = v.slice(prefix.length).replace(/[^\d]/g, '');
  if (digits.length > 10) digits = digits.slice(0, 10);
  
  var formatted = '';
  if (digits.length > 0) {
    formatted += '(' + digits.slice(0, 3);
    if (digits.length > 3) {
      formatted += ') ' + digits.slice(3, 6);
      if (digits.length > 6) {
        formatted += '-' + digits.slice(6, 10);
      }
    }
  }
  inp.value = prefix + ' ' + formatted;
  _ob4State.phone = inp.value;
  _ob4Strength();
  _ob4ValidateAll();
}

function _ob4ValidateAll() {
  var btn = document.getElementById('ob4-continue-btn');
  if (!btn) return;
  
  var fn = ((document.getElementById('ob4-fn') || {}).value || '').trim();
  var ln = ((document.getElementById('ob4-ln') || {}).value || '').trim();
  var h = ((document.getElementById('ob-handle') || {}).value || '').trim();
  
  var dobM = parseInt((document.getElementById('ob4-dm') || {}).value) || 0;
  var dobD = parseInt((document.getElementById('ob4-dd') || {}).value) || 0;
  var dobY = parseInt((document.getElementById('ob4-dy') || {}).value) || 0;
  
  var email = ((document.getElementById('ob-email') || {}).value || '').trim();
  var pass = ((document.getElementById('ob-pass') || {}).value || '').trim();
  var phone = ((document.getElementById('ob-phone') || {}).value || '').trim();
  var refCodeVal = ((document.getElementById('ob-refcode') || {}).value || '').trim();
  _ob4State.referralCode = refCodeVal.toUpperCase();
  
  var nameRegex = /^[A-Za-zÀ-ÿ\s'-]+$/;
  var fnOk = fn.length > 0 && nameRegex.test(fn);
  var lnOk = ln.length > 0 && nameRegex.test(ln);
  
  var handleRegex = /^[a-zA-Z0-9](?:[a-zA-Z0-9]|(?:\.|_)(?![._])){2,13}[a-zA-Z0-9]$/;
  var usernameOk = handleRegex.test(h) && (typeof _usernameTaken !== 'function' || !_usernameTaken(h));
  
  var ageOk = false;
  if (dobM && dobD && dobY) {
    var now = new Date();
    var age = now.getFullYear() - dobY - ((now.getMonth() + 1 > dobM || (now.getMonth() + 1 === dobM && now.getDate() >= dobD)) ? 0 : 1);
    ageOk = age >= 17;
  }
  
  var emailOk = /^\S+@\S+\.\S+/.test(email);
  var uniOk = typeof uni !== 'undefined' && uni !== null;
  var emailVerifiedOk = !!_ob4State.emailVerified;
  
  var passRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&._-])[A-Za-z\d@$!%*?&._-]{8,}$/;
  var passOk = passRegex.test(pass);
  
  var prefix = _ob4State.phoneCode || '+1';
  var digitsAfterPrefix = phone.slice(prefix.length).replace(/[^\d]/g, '');
  var phoneOk = digitsAfterPrefix.length === 10;
  
  var allOk = fnOk && lnOk && usernameOk && ageOk && emailOk && uniOk && emailVerifiedOk && passOk && phoneOk;
  btn.disabled = !allOk;
  btn.style.opacity = allOk ? '1' : '0.45';
}

